#include <stdio.h>
#include <stdlib.h>
#include <openssl/conf.h>
#include <openssl/evp.h>
#include <openssl/err.h>

void* LoadDynOpenSSL(const char* modules) {
    // Create the OpenSSL context
    SSL_library_init();
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();

    // Initialize the configured OpenSSL context
    EVP_cleanup();

    // Load specified modules, if provided
    if (modules) {
        char* err;
        int ret = EVP_load_crypto_strings(NULL, modules, &err);
        if (!ret) {
            fprintf(stderr, "Failed to load OpenSSL crypto strings: %s\n", err);
            ERR_print_errors_fp(stderr);
        }
    }

    // Perform any additional resource management and error handling here

    return EVP_cleanup();
}
