asyncReduce([1, 2, 3, 4], null, (acc, val) => acc + val); // Returns Promise resolving with 10

asyncReduce([1, '2', 3, 4], 0, (acc, val) => acc + val); // Rejects with an Error

asyncReduce([], null, (acc, val) => acc + val); // Rejects with an Error

asyncReduce(Array.from({ length: 1_000_000 }), 0, (acc, val) => acc + val); // Returns a Promise resolving with the sum of all numbers in the array
