<?php
class PasswordManager {
    private $hashedPassword;
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()';
    private $saltRounds = 12;

    public function generateRandomString($length) {
        $randomString = '';
        $charSetLength = strlen($this->characterSet);

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->characterSet[rand(0, $charSetLength - 1)];
        }

        return $randomString;
    }

    public function hashPassword($password) {
        if (!ctype_alnum($password)) {
            throw new InvalidArgumentException("Password must contain only alphanumeric characters.");
        }

        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['rounds' => $this->saltRounds]);
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        $uppercaseCount = substr_count($characterSet, strtoupper(substr($characterSet[0], 0, 1)));
        $lowercaseCount = substr_count($characterSet, substr($characterSet[0], 0, 1));
        $digitCount = substr_count($characterSet, '0');
        $specialCharCount = substr_count($characterSet, '!') + substr_count($characterSet, '@') + substr_count($characterSet, '#') + substr_count($characterSet, '$') + substr_count($characterSet, '%') + substr_count($characterSet, '^') + substr_count($characterSet, '&') + substr_count($characterSet, '*') + substr_count($characterSet, '(') + substr_count($characterSet, ')');

        if ($uppercaseCount <= 0 || $lowercaseCount <= 0 || $digitCount <= 0 || $specialCharCount <= 0) {
            throw new InvalidArgumentException("Character set must contain at least one uppercase letter, one lowercase letter, one digit, and one special character.");
        }
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12) {
            throw new InvalidArgumentException("Salt round count must be at least 12.");
        }

        $this->saltRounds = $rounds;
    }

    public function resetPassword() {
        $this->hashPassword($this->generateRandomString(60)); // You can adjust the length of the random string according to your needs
    }
}
