```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

typedef struct Semaphore {
    char name[256];
    sem_t sem;
    pid_t creator_pid;
    pthread_mutex_t lock;
} Semaphore;

Semaphore* create_semaphore(const char *name) {
    Semaphore *semaphore = malloc(sizeof(Semaphore));
    strcpy(semaphore->name, name);
    semaphore->creator_pid = getpid();
    pthread_mutex_init(&semaphore->lock, NULL);
    sem_init(&semaphore->sem, 0, 0);
    return semaphore;
}

void delete_semaphore(Semaphore *semaphore) {
    pthread_mutex_destroy(&semaphore->lock);
    sem_destroy(&semaphore->sem);
    free(semaphore);
}

int sem_value(const Semaphore *semaphore) {
    int value;
    sem_getvalue(&semaphore->sem, &value);
    return value;
}

void sem_inc(Semaphore *semaphore) {
    pthread_mutex_lock(&semaphore->lock);
    while (sem_value(semaphore) >= SEMLIMIT) {
        pthread_mutex_unlock(&semaphore->lock);
        usleep(1000);
        pthread_mutex_lock(&semaphore->lock);
    }
    sem_post(&semaphore->sem);
    log_message("Semaphore %s incremented by process %d", semaphore->name, getpid());
    pthread_mutex_unlock(&semaphore->lock);
}

void sem_dec(Semaphore *semaphore) {
    pthread_mutex_lock(&semaphore->lock);
    while (sem_value(semaphore) <= 0) {
        pthread_mutex_unlock(&semaphore->lock);
        usleep(1000);
        pthread_mutex_lock(&semaphore->lock);
    }
    sem_wait(&semaphore->sem);
    log_message("Semaphore %s decremented by process %d", semaphore->name, getpid());
    pthread_mutex_unlock(&semaphore->lock);
}

void log_message(const char *format, ...) {
    va_list args;
    openlog("Semaphore Log", LOG_PID | LOG_CONS | LOG_NDELAY, LOG_INFO);
    vsyslog(LOG_INFO, format, args);
    closelog();
}
```
This code defines a `Semaphore` structure that includes the semaphore name, the underlying semaphore, its creator PID, and a mutex for thread-safety. The provided functions allow creating, deleting, and operating on semaphores (increment, decrement). It also includes an external logging mechanism to record semaphore operations and errors. The system can coexist with other system libraries or tools by using standard POSIX functions. The semaphore values are non-negative since the semaphore is initialized with 0 and incremented only when required.

