from Crypto.Cipher import AES

def read_file(filename):
    data = []
    try:
        with open(filename) as f:
            for line in f:
                line = line.strip()
                if line:
                    data.append((line, None))
    except Exception as e:
        print(f"Error reading file: {e}")
        return []

    data.sort()
    return data

def get_sequence_number(line):
    match = re.search(r'\d+', line)
    if match:
        return int(match.group(0))
    return None

class HashFunction:
    def __init__(self, name, function):
        self.name = name
        self.function = function

class BlockCipher:
    def __init__(self, name, function, params=None):
        self.name = name
        self.function = function
        self.params = params or {}

def hash_available(hash_name):
    try:
        hash_obj = getattr(hashlib, hash_name)
        return True
    except AttributeError:
        return False

def cipher_available(cipher_name):
    try:
        CipherClass = getattr(AES, cipher_name)
        return True
    except AttributeError:
        return False

