import java.util.*;
import java.util.concurrent.TimeUnit;
import okhttp3.*;

public class DisjointPairCounter {
    private static final String API_URL = "YOUR_API_URL"; // Replace with your API URL

    public static long countDisjointPairs(int[] arr) {
        UnionFind disjointSet = new UnionFind(arr.length);
        long pairsCount = 0;
        long totalTime = 0;

        for (int i = 0; i < arr.length; ++i) {
            for (int j = i + 1; j < arr.length; ++j) {
                long startTime = System.nanoTime();
                if (!disjointSet.isConnected(arr[i], arr[j])) {
                    disjointSet.union(arr[i], arr[j]);
                    pairsCount++;
                }
                totalTime += (System.nanoTime() - startTime);
            }
        }

        System.out.println("Total time taken: " + TimeUnit.NANOSECONDS.toMillis(totalTime) + " ms");

        verifyWithAPI(pairsCount);

        return pairsCount;
    }

    private static void verifyWithAPI(long pairsCount) {
        OkHttpClient client = new OkHttpClient();

