#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    size_t capacity;
    size_t length;
    char *data;
} String;

String* dynamicTrimAndCapitalize(const char *input) {
    static sem_t mutex = SEM_INITIALIZER_NP;
    static int server_socket = -1;

    // Initialize required variables
    size_t word_list_size = 0;
    char **word_list = NULL;
    size_t average_word_length = 0;
    size_t adjusted_capacity = 0;
    String *result = NULL;

    // Fetch the word list from the external data source (assuming a simple UDP server)
    struct sockaddr_in server_address;
    char buffer[1024];
    ssize_t bytes_received;

    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(54321);
    inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr);

    if ((server_socket = socket(AF_INET, SOCK_DGRAM, 0)) == -1) {
        perror("socket creation error");
        return NULL;
    }

    // Send request for word list size and average word length
    char request[64] = "WORD_LIST_SIZE\0";
    if (sendto(server_socket, request, strlen(request), 0, (struct sockaddr *)&server_address, sizeof(server_address)) == -1) {
        perror("sendto error");
        close(server_socket);
        return NULL;
    }

    // Receive word list size and average word length from the server
    if ((bytes_received = recvfrom(server_socket, buffer, sizeof(buffer), 0, (struct sockaddr *)&server_address, NULL)) <= 0) {
        perror("recvfrom error");
        close(server_socket);
        return NULL;
    }

    sscanf(buffer, "%zu", &word_list_size);
    average_word_length = atoi(buffer + strlen("WORD_LIST_SIZE\0") + 1);

    // Allocate memory for the word list and copy fetched words into it
    word_list = malloc(word_list_size * sizeof(char*));
    if (!word_list) {
        perror("malloc error");
        close(server_socket);
        return NULL;
    }

    for (size_t i = 0; i < word_list_size; ++i) {
        if ((bytes_received = recvfrom(server_socket, buffer, sizeof(buffer), 0, (struct sockaddr *)&server_address, NULL)) <= 0) {
            perror("recvfrom error");
            close(server_socket);
            free(word_list);
            return NULL;
        }

        word_list[i] = malloc(strlen(buffer) + 1);
        if (!word_list[i]) {
            perror("malloc error");
            close(server_socket);
            for (size_t j = 0; j < i; ++j) free(word_list[j]);
            free(word_list);
            return NULL;
        }

        strcpy(word_list[i], buffer);
    }

    // Adjust the capacity based on the length of the fetched word list and average word length
    adjusted_capacity = (word_list_size + 1) * average_word_length;

    // Allocate memory for the resulting string and trim the specified words from the input
    result = malloc(adjusted_capacity);
    if (!result) {
        perror("malloc error");
        for (size_t i = 0; i < word_list_size; ++i) free(word_list[i]);
        free(word_list);
        close(server_socket);
        return NULL;
    }

    sem_wait(&mutex);
    char *ptr = result->data;
    size_t input_length = strlen(input);
    for (char *word : word_list) {
        if (strncmp(word, input, strlen(word)) == 0) {
            size_t word_length = strlen(word);
            if (ptr - result->data + word_length > result->capacity) {
                sem_post(&mutex);
                free(result);
                for (size_t i = 0; i < word_list_size; ++i) free(word_list[i]);
                free(word_list);
                close(server_socket);
                return NULL;
            }

            memmove(ptr + word_length, ptr, input_length - word_length + 1);
            input_length -= word_length;
            continue;
        }
    }
    sem_post(&mutex);

    // Capitalize the first letter of each remaining word and ensure the total length does not exceed the adjusted capacity
    for (size_t i = 0; i < input_length; ++i) {
        if (input[i] >= 'a' && input[i] <= 'z') {
            ptr[i] -= 32;
        } else {
            ptr[i] = input[i];
        }
    }

    // Trim any leading or trailing whitespace from the resulting string
    char *begin = ptr;
    while (isspace(*ptr)) ++ptr;
    result->data = begin;
    char *end = ptr + input_length - 1;
    while (end > begin && isspace(*end)) --end;
    result->data += (ptr - begin);
    result->length = end - ptr + 1;

    // Free allocated resources and close the server socket
    for (size_t i = 0; i < word_list_size; ++i) free(word_list[i]);
    free(word_list);
    close(server_socket);

    return result;
}
```
