```c
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <errno.h>
#include <sys/wait.h>
#include <pthread.h>

pid_t fork_process();
void exec_jpeg_to_pdf(char *input, char *output);
sem_t *create_semaphore(unsigned int value);
void delete_semaphore(sem_t *sem);

int main(int argc, char **argv) {
    if (argc != 3) {
        printf("Usage: ./convert input_file output_file\n");
        return 1;
    }

    sem_t *semaphore = create_semaphore(1);
    pid_t child_pid = fork_process();

    if (child_pid == 0) { // Child process
        exec_jpeg_to_pdf(argv[1], argv[2]);
        _exit(0);
    } else { // Parent process
        sem_wait(semaphore);
        waitpid(child_pid, NULL, 0);
        delete_semaphore(semaphore);
    }

    return 0;
}

sem_t *create_semaphore(unsigned int value) {
    sem_t *sem = malloc(sizeof(sem_t));
    if (sem == NULL) {
        perror("Memory allocation error\n");
        exit(EXIT_FAILURE);
    }

    if (sem_init(sem, 1, value)) {
        perror("Semaphore creation error\n");
        free(sem);
        exit(EXIT_FAILURE);
    }

    return sem;
}

void delete_semaphore(sem_t *sem) {
    if (sem_destroy(sem)) {
        perror("Semaphore destruction error\n");
    }
    free(sem);
}

pid_t fork_process() {
    return fork();
}

void exec_jpeg_to_pdf(char *input, char *output) {
    char command[256];
    sprintf(command, "convert %s %s.pdf", input, output);

    pid_t pid = fork();
    if (pid < 0) {
        perror("Fork failed\n");
        return;
    } else if (pid == 0) { // Child process
        execl("/usr/bin/convert", "convert", input, output, NULL);
        _exit(1);
    } else { // Parent process
        waitpid(pid, NULL, 0);
    }
}
```

This code creates a semaphore with an initial value of 1 using the `create_semaphore()` function and deletes it after use with the `delete_semaphore()` function. The main function forks a child process to execute the `exec_jpeg_to_pdf()` function, which uses ImageMagick's "convert" command-line tool to convert JPEG files to PDF. If there is an error during execution, it will be ignored by simply returning from the function without setting an error code. The parent process waits for the child process to complete before deleting the semaphore and returning 0 if successful or 1 otherwise.

