}

// Get a signed URL to access an object in Amazon S3
function getSignedUrl(Bucket, Key, UserId) {
  return new Promise((resolve, reject) => {
    const expiration = 60 * 5; // 5 minutes expiration time for the url
    const params = {
      Bucket: BUCKET,
      Key: KEY + '/' + UserId,
      Expires: expiration
    };
    s3.getSignedUrl('getObject', params, (err, url) => {
      if (err) reject(err);
      else resolve(url);
    });
  });
}

// Start the Express server
app.listen(3000, () => console.log('Server listening on port 3000'));
