```python
import json
import os
import hashlib
from fastapi import FastAPI, HTTPException, UploadFile, File

app = FastAPI()

# Define a dictionary to store resources
resources = {}

def get_resource(id):
    if id not in resources:
        raise HTTPException(status_code=404, detail="Resource not found")
    return resources[id]

@app.put("/resources/{id}")
async def update_resource(id: str, resource_data: dict):
    if id not in resources:
        resources[id] = {}
    for key, value in resource_data.items():
        resources[id][key] = value
    return resources[id]

def calculate_md5(file_path):
    hash_object = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(8192)
            if not data:
                break
            hash_object.update(data)
    return hash_object.hexdigest()

@app.post("/upload-file/{id}", response_model=str)
async def upload_file(id: str, file: UploadFile = File(...)):
    if id not in resources:
        raise HTTPException(status_code=404, detail="Resource not found")
    hash_value = calculate_md5(os.path.join('/temp', file.filename))
    resources[id]['hash'] = hash_value
    return hash_value
```

