    private static Map<String, JsonFactoryFunction> factories = new HashMap<>();

    public static void addFactory(String id, JsonFactoryFunction factory) {
        factories.put(id, factory);
    }

    public static JsonElement toJson(Object obj, Type typeOfSrc) {
        return gson.toJsonTree(obj, typeOfSrc);
    }

    public static <T> T fromJson(String json, Type typeOfDest) {
        return gson.fromJson(json, typeOfDest);
    }

    private interface JsonFactoryFunction<T extends JsonBase> {
        T createInstance();
    }

    public static <T extends JsonBase> T createFromFactory(String id, Class<T> clazz) {
        return factories.getOrDefault(id, () -> clazz.newInstance()).createInstance();
    }

    public static class JsonBase {
        private String id;

        protected JsonBase() {}

        public String getId() {
            return id;
        }

        public void setId(String id) {
            this.id = id;
        }
    }

    // Service class implementation
    public static class Service {
        private boolean isRunning = false;
        private final String serviceId;
        private final Random random = new Random();

        public Service(String serviceId) {
            this.serviceId = serviceId;
        }

        public void start() {
            if (isRunning) return;
            isRunning = true;
            try {
                Thread.sleep(random.nextInt(5000)); // Random delay between starts
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
            System.out.println("Service " + serviceId + " started");
            sendStopMessage(); // Assume a messaging system is already set up and this method sends the stop message
        }

        public void stop() {
            if (!isRunning) return;
            isRunning = false;
            System.out.println("Service " + serviceId + " stopped");
            sendStopMessage(); // Assume a messaging system is already set up and this method sends the stop message
        }
    }
}
