#include <string.h>
#include <limits.h>
#include <ctype.h>
#include <openssl/md5.h>

typedef struct {
    int value;
} record;

void parseRange(char *range, int *min, int *max) {
    char *ptr = range;
    *min = strtol(ptr, &ptr, 10);
    if (*ptr == '-') ptr++;
    *max = strtol(ptr, NULL, 10);
}

int main() {
    char range[256], keys[256];
    scanf("%s %s", range, keys);

    int min, max;
    parseRange(range, &min, &max);

    int numKeys = 0;
    for (char *ptr = keys; *ptr != '\0'; ptr += strcspn(ptr, ", ") + 1) {
        ++numKeys;
    }

    int *offsets = malloc((max - min + 1) * sizeof(int));
    int *keysArr = malloc(numKeys * sizeof(int));
    for (int i = 0; i < numKeys; ++i) {
        scanf("%d", keysArr + i);
    }

    record *records = malloc((max - min + 1) * sizeof(record));

    int seed = time(NULL);
    srand(seed);

    for (int i = 0; i < max - min + 1; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    for (int i = 0; i < numKeys; ++i) {
        char keyStr[256];
        sprintf(keyStr, "%d", keysArr[i]);
        MD5_Update(&ctx, keyStr, strlen(keyStr));
    }
    MD5_Final(digest, &ctx);

    // Print the resulting array of records for debugging purposes.
    printf("Generated Records:\n");
    for (int i = 0; i < max - min + 1; ++i) {
        printf("%d ", records[i].value);
    }
    printf("\n");

    return 0;
}
