#include <stdarg.h>
#include <stdio.h>
#include <time.h>
#include <unistd.h>
#include <syslog.h>

static FILE *logFile = NULL;

void openLogFile() {
    char *logPath = "/path/to/your/error_log";
    logFile = fopen(logPath, "a");
    if (!logFile) {
        syslog(LOG_ERR, "Error opening error log file: %s", strerror(errno));
    }
}

void closeLogFile() {
    if (logFile) {
        fclose(logFile);
        logFile = NULL;
    }
}

int logCondition(const char *condition, int severity, const char *format, ...) {
    va_list args;
    char buffer[4096];
    time_t now;
    struct tm *tm_now;

    if (!logFile) openLogFile();

    if (logFile) {
        va_start(args, format);
        snprintf(buffer, sizeof(buffer), "%s %ld: [%d] ", ctime(&now), getuid(), severity);
        vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), format, args);
        va_end(args);

        if (fprintf(logFile, "%s", buffer) < 0) {
            syslog(LOG_ERR, "Error writing to error log file: %s", strerror(errno));
        }
    }

    closeLogFile();
    return !strcmp(condition, "true");
}
