#include <iostream>
#include <string>
#include <stdexcept>
#include <magick/Magick++.h>

enum class ConversionStatus { Success, Failure };

class ImageConverter {
public:
    ImageConverter(const std::string& inputPath, const std::string& outputPath, const std::string& format)
        : m_inputImage(inputPath), m_outputImage(outputPath), m_format(format) {}

    void convertAndSave() {
        try {
            Magick::Image inImage(m_inputImage.c_str());
            Magick::Image outImage;

            if (inImage.density() <= 0) {
                inImage.density(72);
            }

            if (format == "PNG") {
                outImage = inImage;
            } else if (format == "SVG") {
                outImage = inImage.autoOrient();
                outImage.setFormat("SVG");
            } else if (format == "JPEG") {
                outImage = inImage.quality(90);
            } else {
                throw std::runtime_error("Unsupported format: " + format);
            }

            outImage.write(m_outputImage);
        } catch (const Magick::Exception& e) {
            m_conversionStatus = ConversionStatus::Failure;
            std::cerr << "Error during image conversion: " << e.what() << std::endl;
        }
    }

    ConversionStatus getConversionStatus() const { return m_conversionStatus; }

private:
    Magick::Image m_inputImage;
    Magick::Image m_outputImage;
    std::string m_format;
    ConversionStatus m_conversionStatus = ConversionStatus::Success;
};

int main(int argc, char* argv[]) {
    if (argc != 4) {
        std::cerr << "Usage: ImageConverter <input_image> <output_image> <format>" << std::endl;
        return -1;
    }

    const std::string inputPath(argv[1]);
    const std::string outputPath(argv[2]);
    const std::string format(argv[3]);

    ImageConverter converter(inputPath, outputPath, format);
    converter.convertAndSave();

    if (converter.getConversionStatus() == ConversionStatus::Failure) {
        return -1;
    }

    return 0;
}
```

