namespace HashGenerator
{
    public interface IHashAlgorithm
    {
        byte[] ComputeHash(byte[] data);
    }

    public class Md5 : IHashAlgorithm
    {
        public byte[] ComputeHash(byte[] data) => MD5.Create().ComputeHash(data);
    }

    public class Sha1 : IHashAlgorithm
    {
        public byte[] ComputeHash(byte[] data) => SHA1.Create().ComputeHash(data);
    }

    public class Sha256 : IHashAlgorithm
    {
        public byte[] ComputeHash(byte[] data) => SHA256.Create().ComputeHash(data);
    }

    public class HashGenerator
    {
        private readonly Dictionary<string, IHashAlgorithm> _algorithms;
        private readonly ILogger<HashGenerator> _logger;

        public HashGenerator(ILogger<HashGenerator> logger)
        {
            _algorithms = new Dictionary<string, IHashAlgorithm>
            {
                { "md5", new Md5() },
                { "sha1", new Sha1() },
                { "sha256", new Sha256() }
            };
            _logger = logger;
        }

        public string GenerateHash(string input, string algorithm)
        {
            if (!_algorithms.ContainsKey(algorithm))
            {
                throw new ArgumentException($"Invalid hash algorithm: '{algorithm}'");
            }

            using var hasher = _algorithms[algorithm];
            var bytes = Encoding.UTF8.GetBytes(input);
            return BitConverter.ToString(hasher.ComputeHash(bytes)).Replace("-", string.Empty).ToLowerInvariant();
        }

        public string GenerateHash(byte[] input, string algorithm)
        {
            if (!_algorithms.ContainsKey(algorithm))
            {
                throw new ArgumentException($"Invalid hash algorithm: '{algorithm}'");
            }

            using var hasher = _algorithms[algorithm];
            return BitConverter.ToString(hasher.ComputeHash(input)).Replace("-", string.Empty).ToLowerInvariant();
        }
    }

    public class Program
    {
        static void Main()
        {
            var loggerFactory = LoggerFactory.Create(builder => builder.AddConsole());
            using var logger = loggerFactory.CreateLogger<HashGenerator>();
            using var hashGenerator = new HashGenerator(logger);

            // Testing with strings
            foreach (var algorithm in new[] { "md5", "sha1", "sha256" })
            {
                var input = "Hello, World!";
                Console.WriteLine($"\n{algorithm}: {input}");
                Console.WriteLine(hashGenerator.GenerateHash(input, algorithm));
            }

            // Testing with byte arrays
            var bytes = new byte[] { 123, 456, 789 };
            Console.WriteLine("\nByte array:");
            foreach (var algorithm in new[] { "md5", "sha1", "sha256" })
            {
                Console.WriteLine(hashGenerator.GenerateHash(bytes, algorithm));
            }
        }
    }
}
