// Function to dynamically load and execute tests
async function runTests(moduleLabel, testSuite) {
  console.log(`Starting tests for ${chalk.blue(moduleLabel)}...`);

  // Establish database connection before starting the tests
  try {
    await db.connect();
  } catch (error) {
    console.error(`Error connecting to database: ${error}`);
    process.exit(1);
  }

  // Reset mocking library after each test
  for (const test of testSuite) {
    console.log(`Running test case: ${chalk.cyan(test.name)}`);

    // Mock the required modules and dependencies
    Blueslip.reset();
    testRunner(moduleLabel)(...Object.values(require(`./${moduleLabel}`).default));

    try {
      await test();
    } catch (error) {
      console.error(`Test case ${chalk.cyan(test.name)} failed with error:`, error);
    }
  }

  // Disconnect from the database after all tests have been executed
  try {
    await db.disconnect();
  } catch (error) {
    console.error(`Error disconnecting from database: ${error}`);
  }
}

