public:
    explicit NetworkResolver(const std::vector<std::string>& dnsServers) {
        updateDNSServers(dnsServers);
    }

    void updateDNSServers(const std::vector<std::string>& newDNSServers) {
        for (const auto& ip : newDNSServers) {
            if (!isValidIP(ip)) {
                throw std::invalid_argument("Invalid IP address provided: " + ip);
            }
        }

        pthread_mutex_lock(&dns_servers_mutex_);
        dns_servers_ = newDNSServers;
        pthread_mutex_unlock(&dns_servers_mutex_);
    }

    std::string resolveHostname(const std::string& hostname, int timeout) {
        // Implement concurrency management here...

        bl::scope exit_scope = bl::add_file_logger("networkResolver.log").auto_flush();

        for (size_t i = 0; i < dns_servers_.size() || i < retries_; ++i) {
            auto it = std::find_if(dns_servers_.cbegin(), dns_servers_.cend(), [&](const auto& server) {
                return isValidIP(server);
            });

            if (it != dns_servers_.cend()) {
                try {
                    boost::asio::io_service io_service;
                    boost::asio::ip::tcp::resolver resolver(io_service);
                    auto results = resolver.resolve(hostname, "");

                    if (results.empty()) {
                        throw std::runtime_error("DNS resolution failed.");
                    }

                    boost::asio::ip::tcp::socket socket(io_service);
                    boost::asio::connect(socket, results.begin()->endpoint());
                    bl::get<0>(socket.lowest_layer().get_executor())->post([&]() {
                        socket.close();
                    });

                    return (*results.begin()).address().to_string();
                } catch (const std::exception& e) {
                    bl::error("Error resolving hostname '{0}': {1}", hostname, e.what());
                }
            } else {
                break;
            }
        }

        throw boost::system_error(boost::errc::not_connected, "networkResolver");
    }

private:
    static bool isValidIP(const std::string& ip) {
        // Implement IP validation here...
        return false;
    }

    mutable pthread_mutex_t dns_servers_mutex_;
    std::vector<std::string> dns_servers_;
    size_t retries_ = 3;
};
```
