Here's the code for loading the resource bundle from a file:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef enum { KEY, VALUE } ResourceItemType;

struct ResourceItem {
    char key[256];
    union {
        int integer;
        float floatValue;
        char *string;
    } value;
    ResourceItemType type;
};

typedef struct ResourceBundle ResourceBundle;
struct ResourceBundle {
    unsigned int size;
    struct ResourceItem *items;
};

ResourceBundle *loadResourceBundle(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Could not open file %s.\n", filename);
        return NULL;
    }

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fprintf(stderr, "Error: Out of memory.\n");
        fclose(file);
        return NULL;
    }

    bundle->size = 0;
    size_t capacity = 1;
    bundle->items = malloc(capacity * sizeof(struct ResourceItem));

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        if (bundle->size == capacity) {
            capacity *= 2;
            bundle->items = realloc(bundle->items, capacity * sizeof(struct ResourceItem));
        }

        char *key_start = line;
        char *key_end = key_start;
        while (*key_end && isalnum(*key_end) || *key_end == '_') ++key_end;
        size_t key_length = key_end - key_start;
        memcpy(bundle->items[bundle->size].key, key_start, key_length);
        bundle->items[bundle->size].key[key_length] = '\0';
        ++bundle->size;

        char *value_start = NULL;
        for (char *i = key_end; *i != '\n' && *i != '\r'; ++i) {
            if (*i == '=') value_start = i + 1;
        }
        if (!value_start) continue;

        char *value_end = strchr(value_start, '\n');
        if (!value_end) value_end = line + sizeof(line);

        size_t value_length = value_end - value_start;
        bundle->items[bundle->size - 1].type = STRING;
        bundle->items[bundle->size - 1].value.string = malloc(value_length + 1);
        memcpy(bundle->items[bundle->size - 1].value.string, value_start, value_length);
        bundle->items[bundle->size - 1].value.string[value_length] = '\0';
    }

    fclose(file);
    return bundle;
}
```

This code defines a `ResourceItem` struct to represent key-value pairs in the resource bundle, and a `ResourceBundle` struct to manage the entire bundle. The `loadResourceBundle()` function opens a file given its path, validates each line according to the specific format, allocates memory for the bundle and its items using dynamic memory allocation, and returns a pointer to the loaded bundle.

