namespace XmlParser
{
    public class XPathQuery
    {
        private string _xpathQuery;
        private XNamespace _ns;

        public XPathQuery(string xpath, XNamespace ns)
        {
            _xpathQuery = xpath;
            _ns = ns;
        }

        public XElement GetFirstMatchingElement()
        {
            if (!Cache.TryGetValue(_xpathQuery, out var cachedXml))
            {
                var config = new ConfigurationBuilder()
                    .SetBasePath(AppDomain.CurrentDomain.BaseDirectory)
                    .AddJsonFile("appsettings.json")
                    .Build();

                string xmlFilePath = config.GetValue<string>("XmlDocument:Path");
                cachedXml = LoadXmlDocument(xmlFilePath);
                Cache.Set(new MemoryCacheEntryOptions().ExpireAfter(TimeSpan.FromMinutes(5)), _xpathQuery, cachedXml);
            }

            var xdoc = cachedXml as XmlDocument;
            if (xdoc == null) throw new InvalidOperationException("Loaded data is not an XML document.");

            XPathNavigator navigator = xdoc.CreateNavigator();
            var query = navigator.Compile(_xpathQuery + "/", XPathResultType.Element);

            if (query.MoveNext() && query.Current.NodeType == XmlNodeType.Element)
                return (XElement)query.Current.ReadOut();

            throw new MultipleElementsException($"Multiple elements found with XPath '{_xpathQuery}'.");
        }

        private static XmlDocument LoadXmlDocument(string filePath)
        {
            using var reader = XmlReader.Create(filePath);
            return new XmlDocument();
        }
    }

    public class MemoryCacheEntryOptions : MemoryCacheEntryOptions<object>
    {
        // Override to set expiration time or other cache options as needed.
    }

    public class MultipleElementsException : Exception
    {
        public MultipleElementsException(string message) : base(message) {}
    }

    public static class Cache
    {
        private static IMemoryCache _cache;

        public static void SetUp(IMemoryCache memoryCache) => _cache = memoryCache;

        // Cache methods go here...
    }
}
