```javascript
const { Stream } = require('stream');
const { RWLock } = require('rwlock-js'); // Import a read-write lock library if not already available in your project

let dataArray = [];
let rwlock = new RWLock();
let pauseRequested = false;
let paused = false;

function collectAndHandleStream(stream) {
    return new Promise((resolve, reject) => {
        const reader = stream.pipe(new Stream.PassThrough({ objectMode: true }));

        function handleData(data) {
            rwlock.wrlock(() => {
                dataArray.push(data);
            }, () => {});
        }

        reader.on('data', handleData);
        reader.on('error', reject);
        reader.on('end', () => {
            rwlock.rlock(() => {
                paused = false;
                resolve(dataArray);
            }, () => {});
        });

        function pause() {
            rwlock.wrlock(() => {
                if (!paused) {
                    pauseRequested = true;
                    paused = true;
                }
            }, () => {});
        }

        function resume() {
            rwlock.rlock(() => {
                if (pauseRequested) {
                    pauseRequested = false;
                    paused = false;
                }
            }, () => {});
        }

        this.pause = pause;
        this.resume = resume;
    });
}
```

