char *expandStringWithSlash(const char *input, size_t limit) {
    if (!input || !limit) return NULL;

    size_t inputLength = strlen(input);
    if (inputLength >= limit) return NULL;

    char *newStr = malloc(inputLength + 2); // Allocate enough space for the string and a trailing slash

    strcpy(newStr, input);
    newStr[inputLength] = '/';
    newStr[inputLength + 1] = '\0';

    return newStr;
}
