from zipfile import ZIP_DEFLATED, ZipFile

def convert_images_to_pdf(directory, output_file):
    try:
        pdf_path = f"{output_file}.pdf"
        images = [f for f in os.listdir(directory) if f.lower().endswith(('.png', '.jpeg', '.jpg', '.gif'))]

        with ZipFile(pdf_path, mode='w', compression=ZIP_DEFLATED) as z:
            for image in images:
                try:
                    img = Image.open(os.path.join(directory, image))
                    z.writestr(img.filename, img.tobytes())
                except Exception as e:
                    print(f"Error processing {image}: {e}")

        if os.path.exists(pdf_path):
            return pdf_path
        else:
            return ""
    except Exception as e:
        print(f"Error converting images to PDF: {e}")
        return ""
