```java
package com.example;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;
import java.util.stream.IntStream;

public class UnionFindDisjointPairs {
    private final static Logger LOGGER = Logger.getLogger(UnionFindDisjointPairs.class.getName());

    // Class for union-find data structure with dynamic updates
    public static class UF {
        private int[] parent;
        private int[] rank;
        private int count;

        public UF(int size) {
            this.parent = new int[size];
            this.rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
            this.count = size;
        }

        public void union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);
            if (rootP == rootQ) return;

            // Path compression by making root of rootQ as root of rootP
            parent[rootQ] = rootP;
            rank[rootP]++;   // Update the rank of the new root
        }

        public int find(int x) {
            if (parent[x] != x)
                parent[x] = find(parent[x]);   // Path compression by recursively calling find on parent until it finds the root
            return parent[x];
        }

        public boolean isConnected(int p, int q) {
            return find(p) == find(q);
        }

        public int size() {
            return count;
        }
    }

    private final UF uf;
    private final Map<Integer, Integer> numMap;  // Map to store the occurrence of each unique element
    private int[] array;

    public UnionFindDisjointPairs(int[] inputArray) {
        if (inputArray == null || inputArray.length == 0)
            throw new IllegalArgumentException("Input array cannot be null or empty.");

        for (int i : inputArray) {
            if (numMap.containsKey(i))
                throw new IllegalArgumentException("Duplicate elements found in the input array.");
        }

        this.array = inputArray;
        this.uf = new UF(this.array.length);
        this.numMap = new HashMap<>();

        for (int i : inputArray) {
            numMap.put(i, numMap.getOrDefault(i, 0) + 1);
            uf.union(this.array[i], i);
        }
    }

    public void addNewElement(int element) {
        if (numMap.containsKey(element))
            throw new IllegalArgumentException("Element already exists in the array.");

        numMap.put(element, 1);
        uf.union(array.length, element); // Add a new set for the new element
    }

    /**
     * This method should be called after all elements have been added to the data structure.
     */
    public int countDisjointPairs() {
        long startTime = System.currentTimeMillis();
        int pairs = 0;

        for (int i = 0; i < array.length; ++i) {
            if (!uf.isConnected(array[i], i)) {
                pairs++;
            }
        }

        long endTime = System.currentTimeMillis();
        LOGGER.info("Number of disjoint pairs: " + pairs + ", Time taken: " + (endTime - startTime) + " ms");

        return pairs;
    }
}
