    int success = 1;
    for (int i = 0; i < num_files; ++i) {
        pthread_create(&threads[i], NULL, convert_jpeg_to_pdf, &jpeg_files[i], args->output_dir);
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
        if (errno != EINTR && errno != 0) {
            fprintf(stderr, "Error converting file: %s\n", strerror(errno));
            success = 0;
        }
    }

    free(jpeg_files);

    return success ? 0 : 1;
}

void *convert_jpeg_to_pdf(void *jpeg_path, void *output_dir) {
