```javascript
const express = require('express');
const redis = require('redis');
const mongoose = require('mongoose');

// Schema and model for Old Testament books
const BookSchema = new mongoose.Schema({
  name: String,
});
const Book = mongoose.model('Book', BookSchema);

// Regular expression for Old Testament book names
const bookPattern = /([Gg][e|o]|[Ee][x|o]|[Jj][o|u]|[Ll][e|u]|[Nn][a|u]|[Ss][amuel]|[Kk][ings]|[Ii][saiah]|[Jj][eremiah]|[Ee][zekiel]|[Dd][aniel]|[Hh][osea]|[Oo][badiah]|[Jj][onah]|[Aa][mos]|[Nn][ahum]|[Hh][abakkuk])/i;

const app = express();
const redisClient = redis.createClient();

app.use(express.json());

// Middleware for caching book patterns in Redis
function cacheMiddleware(req, res, next) {
  // Check if book pattern is in cache
  redisClient.get('bookPatterns', (err, patternJSON) => {
    if (patternJSON) {
      const patterns = JSON.parse(patternJSON);
      req.booksPatterns = patterns;
      next();
    } else {
      // Fetch books from database and update cache
      Book.find({}, (err, books) => {
        if (err) return next(err);
        redisClient.setex('bookPatterns', 60 * 60, JSON.stringify(books.map(b => b.name))); // Cache for 1 hour
        req.booksPatterns = books.map(b => new RegExp(b.name, 'i'));
        next();
      });
    }
  });
}

// Main endpoint to process incoming data streams
app.post('/process', cacheMiddleware, async (req, res) => {
  try {
    const total = req.body.split(/\s+/).reduce((count, text) => {
      for (const pattern of req.booksPatterns) {
        if (pattern.test(text)) count[pattern]++;
      }
      return count;
    }, {});
    res.status(200).json({ books: total });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Initialize and start the server
const PORT = process.env.PORT || 3000;
mongoose.connect('mongodb://localhost/test', { useNewUrlParser: true, useUnifiedTopology: true })
  .then(() => app.listen(PORT))
  .catch((error) => console.error(`Error initializing the server: ${error}`));
```

