Here's a simplified example using Android's Glide library for image loading, OkHttp for network requests, Java Concurrent (Executors) for concurrency, and an in-memory cache (LruCache). Note that this is a basic implementation and might require adjustments based on your specific project requirements.

```java
import android.content.Context;
import androidx.annotation.NonNull;
import com.bumptech.glide.Glide;
import com.bumptech.glide.request.RequestOptions;
import com.squareup.okhttp.OkHttpClient;
import com.squareup.okhttp.Request;
import com.squareup.okhttp.Response;
import okio.BufferedSource;
import okio.Okio;

import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ThemeBitmapCache {
    private static final int CACHE_SIZE = 10 * 1024 * 1024; // 10 MB cache size
    private Context context;
    private ExecutorService executor;
    private LruCache<String, Bitmap> bitmapCache;
    private String defaultThemeDirectory;

    public ThemeBitmapCache(Context context) {
        this.context = context;
        this.executor = Executors.newFixedThreadPool(5); // 5 threads for concurrency
        this.bitmapCache = new LruCache<String, Bitmap>(CACHE_SIZE);
        defaultThemeDirectory = context.getFilesDir().getAbsolutePath() + "/themes/";
    }

    public void loadBitmap(@NonNull final String key, @NonNull final String url, RequestOptions requestOptions) {
        // Check cache first
        Bitmap bitmap = bitmapCache.get(key);
        if (bitmap != null) {
            return;
        }

        Runnable task = new Runnable() {
            @Override
            public void run() {
                try {
                    OkHttpClient client = new OkHttpClient();
                    Request request = new Request.Builder().url(url).build();
                    Response response = client.newCall(request).execute();
                    if (!response.isSuccessful()) {
                        // Handle error here, for example: throw new IOException("Unable to load image from URL.");
                        return;
                    }

                    InputStream inputStream = response.body().byteStream();
                    Bitmap bitmap = Glide.with(context).load(inputStream).apply(requestOptions).submit().get();

                    // Cache the bitmap and save it to disk
                    cacheBitmap(key, bitmap);
                } catch (IOException e) {
                    // Handle error here, for example: Log.e("Error", e.getMessage());
                }
            }
        };

        executor.execute(task);
    }

    private void cacheBitmap(String key, Bitmap bitmap) {
        String hashKey = calculateMd5(bitmap);
        File file = new File(defaultThemeDirectory + hashKey + ".png");
        try {
            BufferedSink sink = Okio.buffer(Okio.sink(file));
            bitmap.compress(Bitmap.CompressFormat.PNG, 100, sink);
            sink.close();
        } catch (IOException e) {
            // Handle error here, for example: Log.e("Error", e.getMessage());
        }

        bitmapCache.put(key, bitmap);
    }

    private String calculateMd5(Bitmap bitmap) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            ByteArrayOutputStream stream = new ByteArrayOutputStream();
            bitmap.compress(Bitmap.CompressFormat.PNG, 100, stream);
            byte[] bytes = stream.toByteArray();
            digest.update(bytes);
            byte[] md5Hash = digest.digest();

            StringBuilder sb = new StringBuilder();
            for (byte b : md5Hash) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            // Handle error here, for example: Log.e("Error", e.getMessage());
            return "";
        }
    }
}
```

