```javascript
const blueslip = require('blueslip'); // Mocking library
const log = require('my-logging-framework'); // Logging framework
const _ = require('lodash'); // Utility functions for handling arrays and objects
const yargs = require('yargs'); // For parsing command-line arguments
const chokidar = require('chokidar'); // File watcher to detect changes in the codebase

// Configuration options, can be overridden via command-line arguments or environment variables
const config = {
  concurrency: 4, // Maximum number of test suites that can run concurrently
  timeout: 60000, // Timeout for each test suite in milliseconds
  resourceLimit: {}, // Resource limits specific to the system (e.g., database connections or API calls)
};

function runTests(moduleLabel, testSuites, options = {}) {
  const { concurrency, timeout, resourceLimit } = _.merge({}, config, options);

  // Initialize the watcher for automatically running tests when changes are detected
  const watcher = chokidar.watch([`src/${moduleLabel}*`, `tests/${moduleLabel}*`], { persistent: true });

  watcher.on('add', (path) => {
    log(`Added file: ${path}`);
    runTests(moduleLabel, testSuites, options);
  });

  watcher.on('change', (path) => {
    log(`Changed file: ${path}`);
    runSingleTestSuite(path.split('/')[2], testSuites[0]); // Run the first suite in the array for the changed file
  });

  // Run a single test suite, managing resources and executing tests sequentially or concurrently based on the provided configuration
  function runSingleTestSuite(suiteName, testFunctions) {
    const testFunctionIndex = 0;
    const testSuiteStartTime = Date.now();

    log(`Running test suite: ${suiteName}`);

    // Initialize the resource manager and acquire necessary resources
    const resourceManager = new ResourceManager(resourceLimit);

    function nextTest() {
      if (testFunctionIndex < testFunctions.length) {
        const currentTest = testFunctions[testFunctionIndex];
        let testStartTime;

        // Acquire resources before running the test to ensure they are available
        resourceManager.acquireResources(currentTest.resources, () => {
          if (resourceManager.isAllAcquired()) {
            // Reset the mocking library before each test to avoid side effects
            blueslip.reset();

            // Execute the test function with custom assertions and error handling
            try {
              testStartTime = Date.now();
              currentTest(assert, expect); // Replace 'assert' and 'expect' with actual assertion functions if needed
              log(`Test case "${testFunctionIndex}": Passed`);
            } catch (error) {
              const duration = Date.now() - testStartTime;
              log(`Test case "${testFunctionIndex}": Failed, Error: ${error.message}, Duration: ${duration}ms`);
            }
          }

          // Release resources after the test to make them available for other tests
          resourceManager.releaseResources();

          // Increase the index for the next test function and check if we have reached the end of the suite
          testFunctionIndex++;
          if (testFunctionIndex < testFunctions.length) {
            setTimeout(nextTest, 0);
          } else {
            const duration = Date.now() - testSuiteStartTime;
            log(`Test suite "${suiteName}": Completed in ${duration}ms`);
          }
        });
      }
    }

    nextTest();
  }

  // Start the function execution by running the first test suite in the array
  runSingleTestSuite(testSuites[0][0], testSuites[0]);
}

// Customize this function to provide a user-friendly interface for debugging and monitoring test progress
function startTests() {
  const args = yargs.option('concurrency', {
    alias: 'c',
    description: 'Maximum number of test suites that can run concurrently',
    type: 'number',
  }).option('timeout', {
    alias: 't',
    description: 'Timeout for each test suite in milliseconds',
    type: 'number',
  }).option('resourceLimit', {
    alias: 'r',
    description: 'Resource limits specific to the system (e.g., database connections or API calls)',
    type: 'object',
  }).argv;

  if (!args._ || !Array.isArray(args._)) {
    log('Usage: node run-tests.js [moduleLabel] [testSuite...]');
    return;
  }

  const moduleLabel = args._[0];
  const testSuites = args._.slice(1).map((suite) => _.compact(_.map(_(suite.split(',')).trim().value(), (str) => str ? str.split(' ').slice(1) : [])));

  runTests(moduleLabel, testSuites, args);
}

// Add the command to execute the tests directly from the command line
startTests();
```

