<?php

class ClinicOperations {
    private $db;
    private $weatherApi;
    private $patientScheduler;
    private $rateLimiter;

    public function __construct(PDO $db, WeatherAPI $weatherApi, PatientScheduler $patientScheduler, RateLimiter $rateLimiter) {
        $this->db = $db;
        $this->weatherApi = $weatherApi;
        $this->patientScheduler = $patientScheduler;
        $this->rateLimiter = $rateLimiter;
    }

    public function createClinic($initial_status, $location, $capacity) {
        // Implement rate limiting here
        // Start transaction to ensure atomicity of the operation
        try {
            $this->db->beginTransaction();

            // Insert the new clinic record into the database
            $stmt = $this->db->prepare("INSERT INTO clinics (status, location, capacity) VALUES (?, ?, ?)");
            $stmt->execute([$initial_status, $location, $capacity]);

            $this->db->commit(); // Commit the transaction if no errors occurred
        } catch (\PDOException $e) {
            $this->db->rollback(); // Rollback the transaction in case of an error
            throw new \Exception("Error creating clinic", 500);
        }
    }

    public function updateClinic($clinic_id, $status, $last_modified_ip) {
        // Implement rate limiting here
        // Start transaction to ensure atomicity of the operation
        try {
            $this->db->beginTransaction();

            // Update the clinic record in the database
            $stmt = $this->db->prepare("UPDATE clinics SET status=?, last_modified_ip=? WHERE id=?"));
            $stmt->execute([$status, $last_modified_ip, $clinic_id]);

            // Check if the status is changed to "closed" or "emergency" and perform additional actions
            if (in_array($status, ['closed', 'emergency'])) {
                $weatherData = $this->weatherApi->getWeatherData();
                if ($weatherData['condition'] === 'extreme') {
                    // Notify the external API service and hospital's emergency response team via email
                    // ...
                }
            }

            $this->db->commit(); // Commit the transaction if no errors occurred
        } catch (\PDOException $e) {
            $this->db->rollback(); // Rollback the transaction in case of an error
            throw new \Exception("Error updating clinic", 500);
        }
    }

    public function deleteClinic($clinic_id) {
        // Implement rate limiting here
        // Start transaction to ensure atomicity of the operation
        try {
            $this->db->beginTransaction();

            // Check if there are any overlapping appointments before deleting the clinic record
            if (!$this->patientScheduler->checkAvailability($clinic_id)) {
                throw new \Exception("Clinic is currently in use", 409);
            }

            // Delete the clinic record from the database
            $stmt = $this->db->prepare("DELETE FROM clinics WHERE id=?");
            $stmt->execute([$clinic_id]);

            $this->db->commit(); // Commit the transaction if no errors occurred
        } catch (\PDOException $e) {
            $this->db->rollback(); // Rollback the transaction in case of an error
            throw new \Exception("Error deleting clinic", 500);
        }
    }
}
```
