    if (!logFile) {
        fprintf(stderr, "Error: Unable to open the log file.\n");
        return NULL;
    }
    return logFile;
}

// Write a log entry to the given FILE* stream with the specified severity level and metadata.
void writeLogEntry(FILE* stream, const char* severity, const char* message) {
    time_t rawtime;
    struct tm* timeinfo;
    char timeString[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timeString, sizeof(timeString), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stream, "[%s] [%s]: %s\n", timeString, severity, message);
}

// Close the log file, if it is open.
void closeLogFile(FILE* stream) {
    if (stream) fclose(stream);
}

// AsyncLogCondition function
void asyncLogCondition(const char* condition, const char* format, ...) {
    FILE* logFile = openLogFile();

    if (!logFile) return;

    bool failedCondition = strcmp(condition, "true") != 0;

    if (failedCondition) {
        va_list args;
        char* message = formatMessage(format, args);
        writeLogEntry(logFile, "ERROR", message);
        free(message);
    }

