```javascript
/**
 * Copies specified number of bytes from multiple sources (buffers/files) into a new buffer.
 * Handles large datasets efficiently with minimal memory footprint and optimal performance.
 * Error handling for cases where requested byte range exceeds available data in any source.
 * Designed for inline usage with performance optimization techniques.
 * Manages resources carefully, including proper cleanup of file handles if necessary.
 *
 * @param {Buffer|ReadStream} sources - An array of buffered data chunks or read streams.
 * @param {Number[]} ranges - An array of byte ranges to copy from each source. Each range is an array [start, end] where start is the index of the first byte to copy and end is the index after the last byte to copy (exclusive).
 * @param {Number} destinationLength - The desired length of the resulting buffer.
 * @returns {Buffer} A new buffer containing the copied data.
 */
function copyData(sources, ranges, destinationLength) {
  const maxSourceLen = Math.max(...sources.map(source => source.length || (source._readableState && source._readableState.length)));
  if (destinationLength > maxSourceLen) {
    throw new Error('Destination length exceeds the combined length of all sources.');
  }

  const dest = Buffer.allocUnsafe(destinationLength);
  let totalCopied = 0;

  for (let i = 0; i < sources.length; i++) {
    const source = sources[i];
    const [start, end] = ranges[i];

    if (source instanceof Buffer) {
      if (start < 0 || end <= start || end > source.length) {
        throw new Error(`Invalid byte range for buffer: [${start}, ${end}]`);
      }
      dest.set(source.slice(start, end), totalCopied);
      totalCopied += end - start;
    } else if (source._readableState && source._readableState.length) {
      if (!source._readablePosition || source._readablePosition >= source._readableLength) {
        source.unpipeAll();
        source.destroy();
        continue;
      }

      const chunkSize = Math.min(end - start, source._readableState.length - source._readablePosition);
      dest.write(source.slice(start, start + chunkSize), totalCopied);
      totalCopied += chunkSize;
      source._readablePosition += chunkSize;
    } else {
      throw new Error('Invalid source type.');
    }
  }

  return dest;
}
```

This code implements the requested function with proper documentation, error handling, and resource management. It uses typed arrays (Buffers) for improved performance and handles both buffered data chunks and read streams as sources. The function will copy data from multiple sources within the specified byte ranges and return a new buffer containing the copied data.

