import logging
from functools import lru_cache
from itertools import groupby

# Set up logging for errors and stats
logging.basicConfig(filename='error_log.txt', level=logging.ERROR, format='%(asctime)s - %(message)s')

def parse_line(line):
    match = re.match(r'^(\S+) (\S+) "\S+" \S+ \S+:(\d{2}:\d{2}:\d{2},\d{3}) "(\S+) \S+ \S+ HTTP/\d.\d" (\d{3})', line)
    if match:
        ip, _, request_time, method_, path, status = match.groups()
        return ip, request_time, int(status)
    return None, None, None

def read_file_chunked(file, chunksize=100000):
    while True:
        data = file.read(chunksize)
        if not data:
            break
        lines = [line.strip() for line in data.splitlines()]
        for line in lines:
            yield from parse_each_line(line)

def parse_each_line(iterable):
    try:
        for ip, request_time, status in iterable:
            yield (ip, request_time), (status, 1)
    except Exception as e:
        logging.error(f'Error parsing line: {e}')

def aggregate_data(iterable):
    return dict((k, v) for k, v in groupby(sorted(iterable), key=lambda x: x[0][0]))

@lru_cache(maxsize=128)
def get_stats():
    # Replace this with your actual API URL and parameters.
    response = requests.get('https://example-realtime-reporting-api.com/aggregate', params={...})
    return response.json()

def main(log_file, api_url):
    stats = {}
    start_time = time.monotonic()
    with open(log_file, 'r') as f:
        for data in read_file_chunked(f):
            for k, v in data:
                key, value = v
                stats[key] = (stats.get(key, (0, 0)) + value)
    response_times = {k: v[0]/len(v[1]) for k, v in stats.items() if len(v[1]) > 0}
    aggregate_data_and_report(response_times, api_url)
    print(f'Processing completed in {time.monotonic() - start_time:.2f} seconds')

def aggregate_data_and_report(stats, api_url):
    current_stats = get_stats()
