const readFile = util.promisify(fs.readFile);
const writeLog = (msg) => console.log(`[${new Date().toISOString()}] ${msg}`);

function readDirectoryFiles(dirPath, extFilter, bufferSize = 1024, logFunc = writeLog) {
    const filesToProcess = [];
    const watcher = chokidar.watch(dirPath, { persistent: true });

    watcher.on('add', (filePath) => {
        if (path.extname(filePath) === extFilter) {
            filesToProcess.push(filePath);
        }
    });

    async function processFiles() {
        while (filesToProcess.length > 0) {
            const filePath = filesToProcess.shift();

            try {
                const contentPromise = readFile(filePath, 'utf8');
                const content = await contentPromise;
                logFunc(`Processing ${filePath}: ${content.length} bytes`);
                if (Buffer.isBuffer(content)) content = content.toString('utf8'); // Ensure we're working with a string

                // Implement buffering here using async iterators or a queue to read the file contents in chunks, if necessary
            } catch (error) {
                logFunc(`Error reading file ${filePath}: ${error.message}`);
            }
        }
    }

    processFiles();
}
