```javascript
/**
 * Function to dynamically load and execute a series of tests for a given module in a Node.js environment.
 *
 * @param {string} moduleName - Name of the module to be tested.
 * @param {Array<{label: string, testFunction: function}>} testCases - Array of objects containing test labels and corresponding test functions.
 * @param {boolean} dependencyCheck - Flag indicating whether to perform dependency checks before running tests.
 */
async function runModuleTests(moduleName, testCases, dependencyCheck = true) {
  // Import required dependencies
  const importDynamic = typeof import !== 'undefined' ? import : require;
  const { Blueslip } = await importDynamic('blueslip');

  // Initialize a Blueslip instance for mocking
  let blueslipInstance;

  try {
    // Perform dependency checks (if required) and load the module
    if (dependencyCheck) {
      const dependencies = require('./dependencies.json');
      await checkDependencies(moduleName, dependencies);
      blueslipInstance = new Blueslip();
      await importDynamic(`./${moduleName}`);
    }

    // Create a Map to store test results and manage state between concurrent tests
    const testResults = new Map();

    // Execute tests in parallel with promise.allSettled
    const testPromises = testCases.map(async (testCase) => {
      // Reset Blueslip instance after each test
      blueslipInstance.reset();

      // Log start of the test
      console.log(`Starting test [${moduleName} - ${testCase.label}]`);

      try {
        // Load the specified module using dynamic imports (import())
        const { testFunction } = await importDynamic(`./${moduleName}`);

        // Measure the execution time of the test function
        const startTime = Date.now();
        await testFunction();
        const endTime = Date.now() - startTime;
        console.log(`Test [${moduleName} - ${testCase.label}] completed in ${endTime}ms`);

        // Store the result of the test in the Map
        testResults.set(testCase.label, { status: 'passed', time: endTime });
      } catch (error) {
        console.log(`Test [${moduleName} - ${testCase.label}] failed with error:\n${error}`);
        testResults.set(testCase.label, { status: 'failed', error });
      }
    });

    // Wait for all tests to complete and return the test results
    const results = await Promise.allSettled(testPromises);
    return Array.from(testResults.entries()).map(([label, result]) => ({ label, status: result.status, time: result.time }));
  } catch (error) {
    console.log(`Failed to execute module tests:\n${error}`);
    throw error;
  }
}

/**
 * Function to check if the given module has all its dependencies
 * @param {string} moduleName - Name of the module to be checked.
 * @param {Object} dependencies - Object containing the expected dependencies for the module.
 */
async function checkDependencies(moduleName, dependencies) {
  const packageJsonPath = `./${moduleName}/package.json`;
  const packageJson = require(packageJsonPath);

  // Check if the required dependencies are present in the package.json file
  for (const dependency in dependencies) {
    if (!packageJson.dependencies[dependency] || !packageJson.devDependencies[dependency]) {
      throw new Error(`Missing dependency [${dependency}] for module [${moduleName}]`);
    }
  }
}
```

