class RateLimiter {
    private $userIds;
    private $lastAttempts;

    public function __construct() {
        $this->userIds = [];
        $this->lastAttempts = [];
    }

    // Update the rate limiter for a specific user
    public function update($userId) {
        $this->userIds[$userId] = time();
        $this->lastAttempts[$userId] = 0;
    }

    // Check if the user can make another attempt based on the current time and rate limit settings
    public function canAttempt($userId, $currentTime) {
        if (!array_key_exists($userId, $this->userIds)) {
            return true;
        }

        $timeSinceLastAttempt = $currentTime - $this->userIds[$userId];
        if ($timeSinceLastAttempt < 60) {
            $attemptsRemaining = 5 - floor($timeSinceLastAttempt / 60);
            if ($attemptsRemaining <= 0) {
                return false;
            }
            $this->lastAttempts[$userId] = $attemptsRemaining;
            return $attemptsRemaining > 1;
        }

        $this->userIds[$userId] = $currentTime;
        $this->lastAttempts[$userId] = 5;
        return true;
    }

    public function getLastAttempts($userId) {
        return isset($this->lastAttempts[$userId]) ? $this->lastAttempts[$userId] : -1;
    }
}

// updateUserPassword function
function updateUserPassword(DB_UserPassword $dao, RateLimiter $rateLimiter, $username, $newPassword) {
