```rust
use std::env;
use std::fs::{self, File};
use std::io::{BufReader, Write};
use std::path::PathBuf;
use git2::{Repository, RepositoryOpenOptions};
use sysinfo::{System, SystemExt};
use tokio::sync::RwLock;
use rustc_driver::{Command, Options as RustcOptions};
use log::*;
use serde::{Deserialize, Serialize};

type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

#[derive(Serialize, Deserialize)]
struct CompileResult {
    time: f64,
    memory_before: u64,
    memory_after: u64,
    errors: Vec<String>,
}

#[tokio::main]
async fn main() -> Result<()> {
    let system = System::new().unwrap();
    let logger = setup_logger(&get_env_log_level());

    let log_level = get_env_log_level();
    info!("Log level: {}", log_level);

    // Create a thread pool
    let thread_pool = rayon::ThreadPoolBuilder::new().num_threads(num_cpus::get() as usize).build_global().unwrap();

    let compile_futures = fs::read_dir("src")?
                             .filter_map(|entry| {
                                 if entry.is_file() && entry.path().extension().and_then(std::ffi::OsStr::to_str) == Some("rs") {
                                     Some(compile_file(&entry.path(), &logger, system.clone()))
                                 } else {
                                     None
                                 }
                             })
                             .collect::<Vec<_>>();

    futures::future::join_all(compile_futures)
                                .await
                                .into_iter()
                                .for_each(|res| res.map_err(|e| eprintln!("{}", e)))?;

    Ok(())
}

fn get_env_log_level() -> log::LevelFilter {
    match env::var("RUST_LOG") {
        Ok(val) => match val.to_lowercase().as_str() {
            "info" | "debug" | "trace" => log::LevelFilter::from_str(&val).unwrap(),
            _ => log::LevelFilter::Info,
        },
        Err(_) => log::LevelFilter::Info,
    }
}

fn setup_logger(log_level: &'static str) -> log::Logger {
    let builder = log4rs::init_filter!(|f| f.level().filter(|l| l >= log::LevelFilter::from_str(log_level).unwrap()));
    builder.build().appender_or_init_file("rust_compiler.log", Default::default()).unwrap()
}

fn num_cpus() -> usize {
    num_cpus::get()
}

async fn compile_file(file_path: &PathBuf, logger: &Logger, system: System) -> Result<CompileResult> {
    let mut repo = match Repository::open_in_memory(&git2::Oid::new("init"))? {
        Some(repo) => repo,
        None => {
            error!("Could not open an in-memory repository");
            return Err(Box::new(std::io::Error::new(
                std::io::IOErrorKind::Other,
                "Could not open in-memory repository",
            )));
        }
    };

    let url = file_path.parent().unwrap().join("url.git");
    git2::Repository::clone(&url, &mut repo)?;

    let (before_rss, after_rss) = measure_memory(system.clone(), file_path);

    let output = CompileResult {
        time: 0.0,
        memory_before: before_rss,
        memory_after: after_rss,
        errors: Vec::new(),
    };

    thread_pool.install(|| {
        let file_path = file_path.clone();
        move || {
            let mut options = RustcOptions::new();
            options.push_str("--crate-name");
            options.push_str(&file_path.file_stem().unwrap().to_str().unwrap());
            let command = Command::new("rustc")
                .args(options)
                .arg(file_path);

            let result = rustc_driver::run(command)?;
            match result {
                Ok(_) => {
                    output.time = system.current_time().as_secs_f64();
                    output.errors = Vec::new();
                }
                Err(err) => {
                    let error_message = err.to_string();
                    let category = if let Some(line) = error_message.lines().next() {
                        match line.trim() {
                            "error: failed to parse Front" => "parsing errors",
                            "error: Could not find reference" => "build failures",
                            _ => "unknown errors",
                        }
                    } else {
                        "unknown errors"
                    };

                    output.errors.push(format!(
                        "Error category: {}, error message: {}",
                        category, error_message
                    ));
                }
            }
            logger.log_with().level(log::LevelFilter::Debug).args(&format!("{:?}", &output)).send()?;
            output
        }
    });

    thread_pool.with(|pool| pool.join_all(vec![thread_pool.install(move || output)]))
              .unwrap();
}

fn measure_memory(system: System, file_path: &PathBuf) -> (u64, u64) {
    let mut rss = system.current_resident_set_size();
    fs::write(&file_path.with_extension(".rs"), "")?;
    system.current_resident_set_size().saturating_sub(rss)
}
```

