I'm glad to help you create a Java program that automates Docker container deployment and executes shell commands within it. To accomplish this task, let's make use of `Docker Java API` and `ExecRunnable` from `com.github.dockerjava.api.command`. Here's a simplified version to get you started; you can expand on it as per your project requirements:

```java
import com.github.dockerjava.api.DockerClient;
import com.github.dockerjava.api.command.*;
import com.github.dockerjava.api.model.*;
import com.github.dockerjava.core.DockerClientBuilder;

public class DockerDeployer {
    private static final String DOCKER_IMAGE = "your_docker_image";
    private static final List<String> SHELL_COMMANDS = Arrays.asList("command1", "command2");

    public void deploy() throws Exception {
        DockerClientBuilder builder = DockerClientBuilder.createDefault();
        DockerClient client = builder.build();

        try (ContainerCreateResponse response = client.containers().createCmd(DOCKER_IMAGE).exec()) {
            Container container = response.getIdRef();

            ExecRunnable runnable = new ExecRunnable(container.getId(), SHELL_COMMANDS);
            runnable.withTty(true);
            runnable.withAttachStdin(true);
            runnable.withAttachStdout(true);
            runnable.withAttachStderr(true);

            ExecResponse execResponse = client.execs().postExecInfo(runnable);

            if (execResponse.getCreated() != null) {
                Execution execution = execResponse.getCreated();
                waitForExecutionCompletion(client, execution.getId());
                System.out.println("Execution completed successfully!");
            } else {
                throw new RuntimeException("Failed to start execution");
            }
        } catch (DockerException e) {
            if (e.getResponseCode() == 404 && e.getMessage().contains("Not Found")) {
                System.out.println("Docker not found or incorrect image specified.");
            } else {
                throw e;
            }
        }
    }

    private void waitForExecutionCompletion(DockerClient client, String executionId) throws Exception {
        Execution exec = null;
        while (true) {
            exec = client.execs().getExec(executionId);
            if ("completed".equals(exec.getStatusCode())) {
                break;
            }
            Thread.sleep(1000);
        }
    }
}
```

