```javascript
const asyncQueue = require('async-queue');
const axios = require('axios');

// Helper function to fetch metadata about a number using an external API (simulating a promise)
const fetchMetadata = number => new Promise((resolve, reject) => {
  setTimeout(() => {
    // Simulate potential errors during the external call
    if (Math.random() > 0.1) {
      return reject(new Error(`Error fetching metadata for number: ${number}`));
    }
    resolve({ number, metadata: `Metadata for number: ${number}` });
  }, 500);
});

// Helper function to perform the reduction operation using callback
const reduceNumber = (acc, current) => {
  // Simulate asynchronous operation with delay
  return new Promise((resolve) => {
    setTimeout(() => {
      try {
        // Callback for the current number and accumulated value
        const result = callback(acc, current);
        resolve(result);
      } catch (error) {
        console.error(`Error processing number ${current}:`, error.message);
        resolve(error);
      }
    }, 100);
  });
}

// Main asyncArrayReduce function
const asyncArrayReduce = (arr, initialValue, callback, maxConcurrency = 10) => {
  if (!Array.isArray(arr)) {
    throw new Error('Input array must be provided');
  }
  const queue = asyncQueue(maxConcurrency);

  let accumulatedValue = initialValue;

  for (const number of arr) {
    // Check if the element is a number and not undefined or null
    if (!Number.isFinite(number) || number === null || number === undefined) {
      throw new Error(`Invalid array element: ${number}`);
    }
    queue.push(() => reduceNumber(accumulatedValue, number).then((result) => accumulatedValue = result));
  }

  // Run the queue with a promise to wait for all operations to complete before returning
  return Promise.all(queue.drain()).then(() => accumulatedValue);
}

// Unit tests for individual components of asyncArrayReduce
describe('asyncArrayReduce', () => {
  it('should reduce an array of numbers asynchronously with a callback', async () => {
    const result = await asyncArrayReduce([1, 2, 3], 0, (acc, current) => acc + current);
    expect(result).toEqual(6);
  });

  it('should handle errors within the callback and return an error object', async () => {
    const errCallback = jest.fn(() => { throw new Error('Test Error'); });
    await expect(asyncArrayReduce([1, 2], undefined, errCallback)).rejects.toEqual(new Error('Test Error'));
  });

  it('should limit the number of concurrent asynchronous operations', async () => {
    const longRunningOperation = (acc, current) => new Promise(resolve => setTimeout(() => resolve(acc + current), 1000));
    await asyncArrayReduce([1, 2, 3], 0, longRunningOperation, 1);
    // Only one operation should have been executed at a time
  });

  it('should simulate external API calls and handle promises appropriately', async () => {
    const apiCallback = jest.fn(async (acc, current) => {
      const metadata = await fetchMetadata(current);
      return acc + metadata.number;
    });
    const result = await asyncArrayReduce([1, 2], 0, apiCallback);
    expect(apiCallback).toHaveBeenCalledTimes(2);
    expect(result).toEqual({ number: 3, metadata: 'Metadata for number: 3' });
  });
});
```

