```csharp
using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Process = System.Diagnostics.Process;

public class WebsiteManager
{
    private readonly ILogger<WebsiteManager> _logger;
    private readonly IServiceProvider _serviceProvider;
    private readonly string _rootDirectory;

    public WebsiteManager(ILoggerFactory loggerFactory, IConfiguration configuration)
    {
        _logger = loggerFactory.CreateLogger<WebsiteManager>();
        _serviceProvider = new ServiceCollection()
            .AddLogging(loggingBuilder => loggingBuilder.AddConsole())
            .BuildServiceProvider();
        _rootDirectory = configuration["RootDirectory"];
    }

    public async Task AddAndStartWebsiteAsync(string siteName, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(_rootDirectory))
        {
            _logger.LogError("Invalid RootDirectory provided.");
            throw new ArgumentException("RootDirectory must be provided.");
        }

        var directoryPath = Path.Combine(_rootDirectory, siteName);

        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError($"Invalid DirectoryPath: {directoryPath}");
            throw new DirectoryNotFoundException();
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");

        if (!File.Exists(webConfigPath))
        {
            _logger.LogError($"Invalid web.config path: {webConfigPath}");
            throw new FileNotFoundException();
        }

        var siteExist = Directory.EnumerateFiles(directoryPath).Any(f => f.Contains(siteName));
        if (siteExist)
        {
            var uniqueSiteName = $"{siteName}_{DateTimeOffset.UtcNow:yyyyMMddhhmmssfff}";
            directoryPath = Path.Combine(_rootDirectory, uniqueSiteName);
        }

        _logger.LogInformation($"Creating site directory: {directoryPath}");
        Directory.CreateDirectory(directoryPath);

        var configService = _serviceProvider.GetRequiredService<IConfiguration>();
        var portNumber = configService.GetValue<int>("PortNumber");
        var startupParameters = configService.GetSection("StartupParameters").GetChildren().Select(c => c.Key).ToList();

        using (var process = new Process())
        {
            process.StartInfo.FileName = "dotnet";
            process.StartInfo.Arguments = $"run --project {Path.Combine(directoryPath, "MyWebsite.csproj")} -- {string.Join(" ", startupParameters)}";
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;
            process.StartInfo.WorkingDirectory = directoryPath;
            process.StartInfo.CreateNoWindow = true;

            _logger.LogInformation($"Starting site: {siteName} on port: {portNumber}");
            var startResult = await Task.Run(() => process.Start(), cancellationToken);

            if (!startResult)
            {
                var errorLines = process.StandardError.ReadToEnd().Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries);
                _logger.LogError($"Failed to start site: {siteName}. Error details:\n{string.Join("\n", errorLines)}");
                throw new Exception("Failed to start the site.");
            }

            await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken); // Wait for the site to start

            if (!process.HasExited)
            {
                process.Kill();
                _logger.LogError($"Failed to stop site: {siteName}. Forced termination.");
                throw new Exception("Failed to stop the site.");
            }
        }
    }
}
```

