```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MD5Hasher {
    private static final Logger LOGGER = LoggerFactory.getLogger(MD5Hasher.class);

    private ExecutorService threadPool;
    private ConcurrentHashMap<String, BigInteger> cache;
    private int maxCacheSize;
    private int maxThreads;

    public MD5Hasher(int maxCacheSize, int maxThreads) {
        this.maxCacheSize = maxCacheSize;
        this.maxThreads = maxThreads;
        threadPool = Executors.newFixedThreadPool(maxThreads);
        cache = new ConcurrentHashMap<>(maxCacheSize);
    }

    public BigInteger computeMD5(String input) {
        if (input == null || input.length() > 1000) {
            throw new IllegalArgumentException("Input string cannot be null or exceed 1000 characters.");
        }

        BigInteger hash = cache.get(input);
        if (hash != null) {
            return hash;
        }

        CompletableFuture<BigInteger> future = CompletableFuture.supplyAsync(() -> computeMD5Internal(input), threadPool);
        try {
            BigInteger result = future.get(1, TimeUnit.MINUTES);
            cache.putIfAbsent(input, result);
            return result;
        } catch (Exception e) {
            LOGGER.error("Error computing MD5 hash for {}", input, e);
            throw new RuntimeException(e);
        } finally {
            if (cache.size() > maxCacheSize) {
                cache.keySet().stream().sorted((k1, k2) -> Long.valueOf(cache.get(k1).longValue()).compareTo(Long.valueOf(cache.get(k2).longValue()))).limit(maxCacheSize - 1).forEach(cache::remove);
            }
        }
    }

    private BigInteger computeMD5Internal(String input) {
        MessageDigest md;
        try {
            md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger bigInteger = new BigInteger(1, messageDigest);
            return bigInteger;
        } catch (NoSuchAlgorithmException e) {
            LOGGER.error("Error computing MD5 hash for {}", input, e);
            throw new RuntimeException(e);
        }
    }
}
```

This class uses a non-blocking thread pool, caching mechanism with LRU eviction policy, and supports configuration via the constructor. The `computeMD5()` method validates input strings, handles large inputs efficiently, and gracefully handles exceptions and errors. Finally, it provides a way to configure the maximum number of threads in the thread pool and the cache size, as well as logging errors and exceptions using SLF4J.

