const semaphore = require('kajuss-semaphore')(10); // Adjust the number based on the desired max concurrent operations

async function asyncArrayReduce(arr, initialValue, callback, progressCallback, options) {
  let accumulator = options && options.accumulator ? options.accumulator : (acc, val) => acc + val;
  let results = [];

  try {
    for (let i = 0; i < arr.length; i++) {
      const task = async () => {
        const result = await simulateExternalApiCall(arr[i], progressCallback);
        results[i] = result;
      };

      if (!options || options.parallelism <= semaphore.take()) {
        await task();
        semaphore.release();
      } else {
        await new Promise((resolve) => {
          task().then(resolve, (error) => {
            console.error(`Error during reduction: ${error}`);
            semaphore.release();
          });
        });
      }
    }
  } catch (error) {
    return { error };
  }

  if (!options || options.parallelism === Infinity) {
    let accumulatedValue = initialValue;
    for (let i = 0; i < results.length; i++) {
      accumulatedValue = callback(accumulatedValue, results[i]);
    }
    return accumulatedValue;
  } else {
    const chunks = Array.from({ length: Math.ceil(results.length / options.parallelism) }, () => []);

    for (let i = 0; i < results.length; i++) {
      chunks[Math.floor(i / options.parallelism)].push(results[i]);
    }

    let chunkPromises = [];
    for (let i = 0; i < chunks.length; i++) {
      chunkPromises.push(asyncParallelReduce(chunks[i], initialValue, callback));
    }

    let resultsChunked = await Promise.all(chunkPromises);
    let finalResult = resultsChunked.reduce((acc, val) => acc + val, 0);
    return finalResult;
  }
}

async function asyncParallelReduce(arr, initialValue, callback) {
  let accumulator = (acc, val) => acc + val;

  try {
    const semaphore = require('kajuss-semaphore')(arr.length);
    let results = [];

    for (let i = 0; i < arr.length; i++) {
      const task = async () => {
        const result = await simulateExternalApiCall(arr[i]);
        results[i] = result;
      };

      if (!semaphore.take()) {
        await new Promise((resolve) => {
          task().then(resolve, (error) => {
            console.error(`Error during reduction: ${error}`);
            semaphore.release();
          });
        });
      } else {
        await task();
        semaphore.release();
      }
    }

    let accumulatedValue = initialValue;
    for (let i = 0; i < results.length; i++) {
      accumulatedValue = callback(accumulatedValue, results[i]);
    }

    semaphore.close();

    return accumulatedValue;
  } catch (error) {
    console.error(`Error during reduction: ${error}`);
    throw error;
  }
}

function simulateExternalApiCall(val, progressCallback) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const randomDelay = Math.floor(Math.random() * 1000);
      const result = val + randomDelay;

      if (progressCallback) {
        progressCallback({ completed: arr.indexOf(val), currentValue: result });
      }

      resolve(result);
    }, Math.max(50, val));
  });
}
```

