function runTests(moduleLabel, testLabels, testFunctions, dataSources, cleanupFunctions) {
  const module = require(moduleLabel);
  const blueslip = require('blueslip'); // Mocking library

  // Initialize Blueslip for each test
  function initBlueslip() {
    return new Promise((resolve) => {
      blueslip.reset();
      resolve();
    });
  }

  async function runTest(testLabel, dataSource, cleanupFunction) {
    try {
      console.log(`Running test: ${testLabel}`);
      await initBlueslip();
      const data = await dataSource();
      const result = await testFunctions[testLabel](data);
      console.log(`Test result for ${testLabel}: ${result ? 'PASS' : 'FAIL'}`);

      // Execute cleanup functions in the correct order and handle dependencies
      let index = cleanupFunctions.findIndex(({label}) => label === testLabel);
      for (let i = index + 1; i < cleanupFunctions.length; i++) {
        await cleanupFunctions[i]();
      }
      await cleanupFunction(data);
    } catch (error) {
      console.log(`Test failure for ${testLabel}: ${error}`);
    }
  }

  async function runAllTests() {
    let promises = [];
    for (let testLabel of testLabels) {
      const dataSource = dataSources[testLabel];
      const cleanupFunction = cleanupFunctions[testLabel];
      promises.push(runTest(testLabel, dataSource, cleanupFunction));
    }
    await Promise.all(promises);
    blueslip.reset(); // Reset Blueslip only after all tests are completed
  }

  runAllTests();
}
