            {
                var cryptoProvider = _cryptoProviders.GetValueOrDefault(contextName) ?? ThrowMissingContextException(contextName);

                var decodedBytes = Convert.FromBase64String(base64EncodedMessage);
                var tsCryptoService = new TripleDESCryptoServiceProvider();

                using (var memoryStream = new MemoryStream(decodedBytes))
