                        }
                    }
                }
            }
            catch (Exception ex)
            {
                throw new DecryptionException($"Error occurred while decrypting message: {ex.Message}", ex);
            }
        }

        private TripleDESCryptoServiceProvider ThrowMissingContextException(string contextName)
        {
            lock (_lock)
            {
                if (!_cryptoProviders.ContainsKey(contextName))
                    throw new Exception($"No encryption context found with name: {contextName}");
            }

            return null;
        }
