First, let's define the Semaphore structure:

```c
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[64];
    pthread_mutex_t lock;
    pthread_cond_t cond;
    long count;
} Semaphore;
```

Here's the function to initialize a semaphore:

```c
Semaphore* create_semaphore(const char* name, long initialValue) {
    Semaphore *sem = malloc(sizeof(Semaphore));
    strcpy(sem->name, name);
    pthread_mutex_init(&sem->lock, NULL);
    pthread_cond_init(&sem->cond, NULL);
    sem->count = initialValue;
    return sem;
}
```

Delete a semaphore:

```c
void delete_semaphore(Semaphore* sem) {
    pthread_mutex_destroy(&sem->lock);
    pthread_cond_destroy(&sem->cond);
    free(sem);
}
```

Increment a semaphore:

```c
void increment_semaphore(Semaphore* sem) {
    pthread_mutex_lock(&sem->lock);
    ++sem->count;
    pthread_mutex_unlock(&sem->lock);
}
```

Decrement a semaphore:

```c
bool decrement_semaphore(Semaphore* sem) {
    pthread_mutex_lock(&sem->lock);
    if (sem->count > 0) {
        --sem->count;
        pthread_mutex_unlock(&sem->lock);
        return true;
    }
    pthread_mutex_unlock(&sem->lock);
    return false;
}
```

