Now let's create a command-line interface for managing semaphores:

```c
#include <getopt.h>

void cli(int argc, char **argv) {
    Semaphore* sem = NULL;
    char operation, name[64], value_str[10];

    while ((operation = getopt(argc, argv, "c:d:in:")) != -1) {
        switch (operation) {
            case 'c':
                sem = create_semaphore(optarg, atol(value_str));
                log("Created semaphore: ", optarg);
                break;
            case 'd':
                delete_semaphore(sem);
                free(sem);
                log("Deleted semaphore: ", sem->name);
                sem = NULL;
                break;
            case 'i':
                increment_semaphore(sem);
                log("Incremented semaphore: ", sem->name);
                break;
            case 'n':
                sem = create_semaphore(optarg, atol(value_str));
                log("Renamed semaphore: ", sem->name, " to ", optarg);
                break;
        }
    }
}
```

