```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class DynamicTripleDesDecryptor
{
    private readonly ICspService _cspService;
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] Iv)> _keyIvCache = new ConcurrentDictionary<string, (byte[], byte[])>();
    private readonly int _maxRetries;
    private readonly TimeSpan _retryDelay;

    public DynamicTripleDesDecryptor(ICspService cspService, int maxRetries, TimeSpan retryDelay)
    {
        _cspService = cspService;
        _maxRetries = maxRetries;
        _retryDelay = retryDelay;
    }

    public async Task<string> DecryptMessage(string base64EncodedMessage, string contextId)
    {
        var keyIvPair = await GetKeyIvAsync(contextId);
        byte[] decryptedData;

        try
        {
            using (var tripleDes = TripleDES.Create())
            {
                tripleDes.Key = keyIvPair.Key;
                tripleDes.IV = keyIvPair.Iv;

                var data = Convert.FromBase64String(base64EncodedMessage);
                using (var msDecrypt = new MemoryStream(data))
                {
                    using (var msEncrypt = new MemoryStream())
                    {
                        tripleDes.Mode = CipherMode.CBC;
                        tripleDes.Padding = PaddingMode.PKCS7;
                        using (var cs = new CryptoStream(msEncrypt, tripleDes.CreateDecryptor(), CryptoStreamMode.Write))
                            msEncrypt.CopyTo(cs);
                        msEncrypt.Close();

                        decryptedData = msDecrypt.ToArray();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            throw new Exception($"Failed to decrypt message: {ex.Message}", ex);
        }

        return Encoding.UTF8.GetString(decryptedData);
    }

    private async Task<(byte[], byte[])> GetKeyIvAsync(string contextId, int retryCount = 0)
    {
        if (_keyIvCache.TryGetValue(contextId, out var cached)) return cached;

        try
        {
            var keyIvResponse = await _cspService.FetchKeysAndIVsAsync(contextId);
            if (keyIvResponse != null)
            {
                _keyIvCache.TryAdd(contextId, keyIvResponse);
                return keyIvResponse;
            }
        }
        catch (Exception ex)
        {
            if (retryCount < _maxRetries)
            {
                await Task.Delay(_retryDelay);
                return await GetKeyIvAsync(contextId, retryCount + 1);
            }

            throw new Exception($"Failed to fetch keys and IVs for context Id: {contextId}, Error: {ex.Message}", ex);
        }

        throw new Exception("Context not found or invalid.");
    }
}

public interface ICspService
{
    Task<KeyValuePair<byte[], byte[]>> FetchKeysAndIVsAsync(string contextId);
}
