Here's a pseudo-code example in Kotlin, using an LRUCache (Least Recently Used Cache) for efficient theme bitmap caching and RxJava for handling high concurrency:

```kotlin
import java.io.*
import android.graphics.BitmapFactory
import android.graphics.BitmapFactory.decodeStream
import com.google.gson.Gson
import io.reactivex.Observable
import io.reactivex.schedulers.Schedulers

class ThemeManager {
    private val themeCache = LRUCache<String, Bitmap>(MAX_CACHED_THEMES)
    private var primaryThemeDirectory: File? = null
    private var fallbackThemeDirectory: File? = null

    fun setPrimaryThemeDirectory(directory: File) {
        this.primaryThemeDirectory = directory
    }

    fun setFallbackThemeDirectory(directory: File) {
        this.fallbackThemeDirectory = directory
    }

    fun getThemeBitmap(themeName: String): Observable<Bitmap> {
        return if (primaryThemeDirectory != null) {
            loadThemeBitmapFromPrimaryDirectory(themeName)
        } else if (fallbackThemeDirectory != null) {
            loadThemeBitmapFromFallbackDirectory(themeName)
        } else {
            throw IllegalStateException("No valid theme directories set.")
        }
    }

    private fun loadThemeBitmapFromPrimaryDirectory(themeName: String): Observable<Bitmap> {
        return Observable.fromCallable {
            val themeFile = File(primaryThemeDirectory!!, "$themeName.png")
            if (!themeFile.exists()) throw FileNotFoundException("Theme file not found.")

            try {
                val `in` = FileInputStream(themeFile)
                BitmapFactory.decodeStream(`in`)
            } catch (e: Exception) {
                Log.e("ThemeManager", "Failed to load theme bitmap.", e)
                throw e
            }
        }.doOnSubscribe { Log.d("ThemeManager", "Loading theme bitmap $themeName") }
        .onErrorResumeNext { e ->
            if (e is FileNotFoundException) {
                loadThemeBitmapFromFallbackDirectory(themeName)
                    .doOnError { throw e }
            } else {
                Observable.error(e)
            }
        }
        .observeOn(Schedulers.io())
        .onTerminateDetach()
    }

    private fun loadThemeBitmapFromFallbackDirectory(themeName: String): Observable<Bitmap> {
        return Observable.fromCallable {
            val themeFile = File(fallbackThemeDirectory!!, "$themeName.png")
            if (!themeFile.exists()) throw FileNotFoundException("Theme file not found.")

            try {
                val `in` = FileInputStream(themeFile)
                BitmapFactory.decodeStream(`in`)
            } catch (e: Exception) {
                Log.e("ThemeManager", "Failed to load theme bitmap.", e)
                throw e
            }
        }.doOnSubscribe { Log.d("ThemeManager", "Loading fallback theme bitmap $themeName") }
        .onErrorResumeNext { e ->
            if (e is FileNotFoundException) {
                Bitmap.createBitmap(1, 1, Bitmap.Config.ARGB_8888)
            } else {
                Observable.error(e)
            }
        }
        .observeOn(Schedulers.io())
        .onTerminateDetach()
    }
}
```

