    public class TripleDesDecryptor
    {
        private readonly IExternalCsp _csp;
        private readonly ConcurrentDictionary<int, KeyPool> _keyPools;
        private readonly object _contextLock = new object();

        public TripleDesDecryptor(IExternalCsp csp)
        {
            _csp = csp;
            _keyPools = new ConcurrentDictionary<int, KeyPool>();
        }

        public async Task<string> DecryptMessageAsync(string base64EncodedMessage, int clearanceLevel)
        {
            var context = await CreateDecryptionContextAsync(clearanceLevel);
            if (!context.Validated) return context.Source + ": Message validation failed.";

            using (var tripledes = TripleDESCryptoServiceProvider.Create())
            {
                byte[] data = Convert.FromBase64String(base64EncodedMessage);
                ICryptoTransform transform = tripledes.CreateDecryptor(context.Key, context.IV);
                using (MemoryStream ms = new MemoryStream(data))
                {
                    using (CryptoStream cs = new CryptoStream(ms, transform, CryptoStreamMode.Read))
                    {
                        byte[] resultArray = new byte[data.Length];
                        await cs.ReadAsync(resultArray, 0, resultArray.Length);
                        return Encoding.UTF8.GetString(resultArray);
                    }
                }
            }
        }

        private async Task<DecryptionContext> CreateDecryptionContextAsync(int clearanceLevel)
        {
            var context = new DecryptionContext(_csp.Source, clearanceLevel);
            context.Key = await _keyPools.GetOrAdd(clearanceLevel, keyLevel =>
            {
                KeyPool keyPool = new KeyPool();
                return Task.Run(() => keyPool.FetchKeysAndIVsFromCspAsync(_csp))
                    .ContinueWith(t => t.Result);
            });
            context.IV = await _csp.RetrieveIVAsync(context.Source, clearanceLevel);
            context.Validated = await context.ValidateMessageAsync();
            return context;
        }
    }

    public interface IExternalCsp
    {
        string Source { get; }
        Task<CspKey> FetchKeysAndIVsAsync(TripleDesDecryptor decryptor);
