using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;
using System.Threading.Tasks;
using System.Linq;
using System.Runtime.Caching;

public class XPathParser
{
    private static ObjectCache _cache = MemoryCache.Default;
    private const int CacheDurationInMinutes = 5;

    public async Task<IEnumerable<XElement>> QueryAsync(string xml, string xpathExpression)
    {
        var key = $"xpath_{xpathExpression}";

        if (_cache.Get(key) is XPathResult cachedResult)
        {
            return cachedResult;
        }

        try
        {
            var document = new XmlDocument();
            document.LoadXml(xml);
            var nodes = document.XPathSelectElements(xpathExpression);

            if (nodes.Count > 1)
            {
                throw new Exception($"Multiple elements found with XPath '{xpathExpression}'.");
            }

            if (nodes.Count == 0)
            {
                throw new Exception($"No element found with XPath '{xpathExpression}'.");
            }

            _cache.Add(key, nodes, CacheItemPolicy.AbsoluteExpiration(TimeSpan.FromMinutes(CacheDurationInMinutes)));
            return nodes;
        }
        catch (Exception ex)
        {
            throw new Exception($"Error while querying XML with XPath '{xpathExpression}'. Details: {ex.Message}");
        }
    }

    public async Task<T> QueryFirstAsync<T>(string xml, string xpathExpression)
    {
        var nodes = await QueryAsync(xml, xpathExpression);
        return nodes.FirstOrDefault()?.ToObject<T>();
    }

    // Extension method for easily converting an XElement to a specific type T.
    public static T ToObject<T>(this XElement element)
    {
        if (element == null) throw new ArgumentNullException(nameof(element));

        var serializer = new XmlSerializer(typeof(T));
        using (var reader = new StringReader(element.ToString()))
        {
            return (T)serializer.Deserialize(reader);
        }
    }
}
