#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <sys/types.h>
#include <dirent.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>

#define MAX_THREADS 10
#define BUFFER_SIZE 4096

typedef void* (_imagemagick_function)(char*, char*);
void* imgmagick_convert(void* arg) {
    imagemagick_function func = (imagemagick_function)arg[0];
    char* input = arg[1];
    char* output = arg[2];
    free(arg);
    return func(input, output);
}

int convert_directory(char* input_dir, char* output_dir, imagemagick_function imgmagick_func) {
    DIR* dir;
    struct dirent* entry;
    pthread_t threads[MAX_THREADS];
    bool success = true;
    int thread_count = 0;

    if(!input_dir || !output_dir || !imgmagick_func) {
        fprintf(stderr, "Invalid arguments.\n");
        return -1;
    }

    if(mkdir(output_dir, 0755) < 0 && errno != EEXIST) {
        perror("Failed to create output directory.");
        return -2;
    }

    dir = opendir(input_dir);
    if(!dir) {
        perror("Failed to open input directory.");
        return -3;
    }

    while((entry = readdir(dir)) != NULL) {
        char* base = strdup(entry->d_name);
        char* ext = strrchr(base, '.');

        if(!ext || strcmp(ext, ".jpeg") && strcmp(ext, ".jpg")) {
            free(base);
            continue;
        }

        char input_path[1024], output_path[1024];
        snprintf(input_path, sizeof(input_path), "%s/%s", input_dir, base);
        snprintf(output_path, sizeof(output_path), "%s/%s.pdf", output_dir, base);

        void* arg[3] = {imgmagick_func, strdup(input_path), strdup(output_path)};
        if(pthread_create(&threads[thread_count++], NULL, imgmagick_convert, arg)) {
            success = false;
            break;
        }
    }

    closedir(dir);

    for(int i = 0; i < thread_count; ++i) {
        void* ret;
        if(pthread_join(threads[i], &ret)) {
            success = false;
            break;
        } else if((int)ret != 0) {
            success = false;
        }
    }

    return success ? 0 : thread_count - success;
}
```

