// Function to get all JPEG files in a directory (case-insensitive)
vector<string> getJpegFilesInDirectory(const string& directoryPath) {
    vector<string> jpegFiles;
    bipc::mutex mtx; // Lock for thread safety

    for (auto& entry : fs::recursive_directory_iterator(directoryPath)) {
        if (entry.path().extension() == ".jpg" || entry.path().extension() == ".jpeg") {
            string filename = entry.path().filename().string();
            // Lock the mutex before adding a file to avoid race conditions
            unique_lock<bipc::mutex> lock(mtx);
            jpegFiles.push_back(filename);
        }
    }

    return jpegFiles;
}

