        boost::thread t([&](const string& filePath, const string& fileName) {
            try {
                int ret = convertJpegToPdf(filePath);
                if (ret == 0) {
                    lock_guard<bipc::mutex> lock(htmlMutex); // Lock before adding to the HTML to ensure thread safety
                    ScriptObject scriptObject;
                    // Populate your script object with data from the file content here
                    stringstream keyStream;
                    keyStream << "key_" << this_thread::get_id();
                    string key = keyStream.str();
                    scriptObject.key = key;
                    scriptObjects.push_back(scriptObject);

                    lock.unlock(); // Unlock after adding the new JavaScript object to the HTML string
                } else {
                    failedConversions++;
                }
            } catch (...) {
                cerr << "Error converting file: [Unhandled exception]" << endl;
                failedConversions++;
            }
        }, jpegFile, fileName);
        threads.push_back(std::move(t));
    }

    for (auto& t : threads) {
        t.join();
    }

    // Render the HTML with the collected JavaScript objects and append it to the footer
    html += renderHTML(scriptObjects, "<footer>");

    return failedConversions;
}
```

