int processUserInput(char **input, UserSettings *settings, char **processedText) {
    CURL *curl;
    CURLcode res;
    size_t len = strlen(*input);

    // Allocate memory for processed text if it's not provided
    if (!processedText) {
        processedText = malloc(settings->maxLength + 1);
        if (!processedText) return INVALID_POINTER;
    }

    // Set up curl, API endpoint URL, and user settings for request
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) return INVALID_POINTER;

    char url[256];
    snprintf(url, sizeof(url), "https://api.example.com/settings/%ld?trim=%d&capitalize=%d", settings->maxLength, settings->trim, settings->capitalize);

    // Perform the API request and process the response
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, processedText);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        free(processedText);
        return OTHER_ERROR;
    }

    // Check for API rate limits and manage concurrent requests using a global semaphore (not shown here, use pthread_mutex_t)

    // Adjust processed text based on user's settings
    if (settings->trim) {
        processedText += strspn(processedText, " ");
        processedText[strlen(processedText)] = '\0';
    }

    if (settings->capitalize) {
        strcpy(processedText, toupper(processedText));
    }

    // Ensure the processed text does not exceed the user's maxLength
    if (strlen(processedText) > settings->maxLength) {
        processedText[settings->maxLength - 1] = '\0';
    }

    *input = processedText;
    return SUCCESS;
}
