using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;
using MyNamespace.Services;
using MyNamespace.Models;
using Newtonsoft.Json;

namespace MyNamespace.Controllers {
    public class ConfigurationController : ControllerBase {
        private readonly ILogger<ConfigurationController> _logger;
        private readonly IDatabaseService _databaseService;
        private readonly IConfigurationService _configurationService;
        private readonly IDistributedCache _cache;
        private const string VersionControlApiKey = "YOUR_API_KEY";

        public ConfigurationController(ILogger<ConfigurationController> logger,
                                        IDatabaseService databaseService,
                                        IConfigurationService configurationService,
                                        IDistributedCache cache) {
            _logger = logger;
            _databaseService = databaseService;
            _configurationService = configurationService;
            _cache = cache;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateUserConfiguration([FromBody] UpdateConfigurationDto dto) {
            if (dto == null || string.IsNullOrEmpty(dto.UserId) || string.IsNullOrEmpty(dto.ConfigurationName) || string.IsNullOrEmpty(dto.NewValue)) {
                return BadRequest("Invalid input parameters.");
            }

            // Check if the configuration exists for the given user (using cache for performance)
            var cachedConfigurations = await _cache.GetAsync($"UserConfigurations_{dto.UserId}");
            var configurations = JsonConvert.DeserializeObject<List<Configuration>>(cachedConfigurations);
            if (configurations == null || !configurations.Any(c => c.Name == dto.ConfigurationName)) {
                return NotFound("Configuration not found for the specified user.");
            }

            // Ensure thread safety when updating
            var currentVersion = configurations.First(c => c.Name == dto.ConfigurationName).Version;
            if (!_cache.TryGet($"UserConfig_{dto.UserId}_{dto.ConfigurationName}", out var cachedConfiguration)) {
                cachedConfiguration = JsonConvert.SerializeObject(configurations.Where(c => c.Name == dto.ConfigurationName).First());
                await _cache.SetAsync($"UserConfig_{dto.UserId}_{dto.ConfigurationName}", cachedConfiguration, TimeSpan.FromMinutes(5));
            }

            // Update the configuration using a service class
            var updatedConfiguration = await _configurationService.UpdateConfigurationAsync(dto.UserId, dto.ConfigurationName, dto.NewValue, currentVersion);

            // Integrate with an external API for version control and logging of changes
            if (updatedConfiguration != null) {
                var apiResponse = await CallVersionControlApiAsync($"{UpdatedConfigurationUri}/{dto.UserId}/{dto.ConfigurationName}", updatedConfiguration);
                if (apiResponse.IsSuccessStatusCode) {
                    // If successful, update the cache with the new configuration and version
                    await _cache.SetAsync($"UserConfig_{dto.UserId}_{dto.ConfigurationName}", JsonConvert.SerializeObject(updatedConfiguration), TimeSpan.FromMinutes(5));
                    return Ok("Configuration updated successfully.");
                } else {
                    // Handle errors returned from the version control API here
                    return StatusCode((int)apiResponse.StatusCode, apiResponse.ReasonPhrase);
                }
            } else {
                _logger.LogError("Failed to update configuration.");
                return StatusCode(StatusCodes.Status500InternalServerError, "An error occurred while updating the configuration.");
            }
        }

        private async Task<HttpResponseMessage> CallVersionControlApiAsync(string uri, Configuration updatedConfiguration) {
            var httpClient = new HttpClient();
            var versionControlData = new VersionControlData {
                UserId = updatedConfiguration.UserId,
                ConfigurationName = updatedConfiguration.Name,
                OldValue = updatedConfiguration.OldValue,
                NewValue = updatedConfiguration.NewValue,
                Version = updatedConfiguration.Version,
                Timestamp = DateTimeOffset.Now
            };
            var json = JsonConvert.SerializeObject(versionControlData);
            var content = new StringContent(json, System.Text.Encoding.UTF8, "application/json");
            var apiResponse = await httpClient.PostAsync(uri, content);
            return apiResponse;
        }
    }
}
```

