        [HttpPost]
        public async Task<IActionResult> UpdateContent(int pageSectionId, int elementId, string htmlContent) {
            if (!ModelState.IsValid) return BadRequest(ModelState);

            // Validate IDs within the system (assuming you have a validation method)
            if (!IsValidSectionId(pageSectionId)) return BadRequest("Invalid section ID");
            if (!IsValidElementId(elementId)) return BadRequest("Invalid element ID");

            // Ensure data consistency without conflicts using locks or optimistic concurrency control
            var lockKey = $"{pageSectionId}:{elementId}";
            await _redisCache.LockAsync(lockKey);

            try {
                // Load cached HTML content if available to minimize database access
                string cachedContent = await _redisCache.GetAsync<string>(lockKey);
                if (cachedContent != null) htmlContent = cachedContent;

                // Update the data in your ApplicationDbContext with transactional support
                using var transaction = await _dbContext.Database.BeginTransactionAsync();

                try {
                    // Perform necessary updates and save changes to the database
                    // ...

                    // Save transaction and commit if successful, otherwise rollback
                    await _dbContext.SaveChangesAsync();
                    transaction.Commit();
                } catch (DbUpdateConcurrencyException ex) {
                    transaction.Rollback();
                    _logger.LogError(ex, "Failed to update content due to concurrency conflict");
                    return StatusCode(StatusCodes.Status409Conflict);
                } catch (Exception ex) {
                    transaction.Rollback();
                    _logger.LogError(ex, "Failed to update content");
                    return StatusCode(StatusCodes.Status500InternalServerError);
                }
            } finally {
                // Release the lock
                await _redisCache.ReleaseLockAsync(lockKey);
            }

            // Interact with external content management service using retry logic for transient failures
            const int maxRetries = 3;
            var success = false;
            var retriesLeft = maxRetries;

            do {
                try {
                    await SendContentToExternalServiceAsync(htmlContent);
                    success = true;
                    break;
                } catch (Exception ex) {
                    if (retriesLeft-- <= 0) throw;
                    _logger.LogError(ex, $"Failed to send content to external service. Retrying...");
                    await Task.Delay(TimeSpan.FromSeconds(5));
                }
            } while (true);

            // Log all update attempts and results for auditing purposes
            _logger.LogInformation($"Successfully updated content: pageSectionId={pageSectionId}, elementId={elementId}");

            return Ok();
        }

        private async Task SendContentToExternalServiceAsync(string htmlContent) {
            var request = new HttpRequestMessage {
                Method = HttpMethod.Post,
                RequestUri = new Uri("https://content-management-service.com/api/update"),
                Content = new StringContent(JsonConvert.SerializeObject(new { content = htmlContent }), System.Text.Encoding.UTF8, "application/json")
            };

            using var response = await _httpClient.SendAsync(request);
            if (!response.IsSuccessStatusCode) throw new Exception($"Failed to send content to external service: {response.ReasonPhrase}");
        }

