    let path = env::var(env_var_name).unwrap_or_else(|_| "my_directory".to_string());
    let path = Path::new(&path);

    if path.exists() {
        match path.canonicalize().map(|p| p.into_os_string()) {
            Ok(existing_path) => {
                let env_var = format!("{}={}", env_var_name, existing_path.to_str().unwrap());
                set_env(env_var_name.as_str(), &env_var);
                existing_path.into_string()
            }
            Err(_) => panic!("Failed to canonicalize path"),
