# json_base/json_base.py
import os
import json
from json import JSONDecodeError
from typing import Any, Callable, Dict, List, Type
import concurrent.futures
import yaml
from yaml import Loader

class JSONBase:
    _registry = {}
    _lazy_loaded = False

    def __init__(self, data: Any):
        self.data = data

    @staticmethod
    def to_json(obj: Any) -> str:
        # Optimized JSON conversion for large datasets
        ...

    @classmethod
    def from_json(cls, json_str: str) -> 'JSONBase':
        try:
            data = json.loads(json_str)
        except JSONDecodeError as e:
            raise ValueError(f"Invalid JSON string: {e}")

        if not cls._registry or not hasattr(cls, '_factory_func'):
            raise AttributeError("Subclass registration required")

        return cls._factory_func(**data)

    @staticmethod
    def register_factory(factory_func: Callable[[Dict], Type]) -> None:
        if not hasattr(JSONBase, '_registry'):
            JSONBase._registry = {}

        factory_id = factory_func.__name__
        if factory_id in JSONBase._registry:
            raise ValueError("Duplicate factory function ID")

        JSONBase._registry[factory_id] = factory_func

    @classmethod
    def discover_subclasses(cls, directory: str) -> None:
        for file in os.listdir(directory):
            if not file.endswith('.py'):
                continue

            module_name = f'{directory.replace("/", ".")}.{file[:-3]}'
            __import__(module_name)

            for name, obj in sys.modules[module_name].__dict__.items():
                if issubclass(obj, JSONBase):
                    factory_func = getattr(obj, 'create', None)
                    if factory_func:
                        JSONBase.register_factory(factory_func)

    @staticmethod
    def get_registry() -> Dict[str, Callable[[Dict], Type]]:
        if not JSONBase._lazy_loaded:
            with concurrent.futures.ThreadPoolExecutor() as executor:
                results = executor.map(JSONBase._load_from_yaml, json_base.__path__)

            for result in results:
                JSONBase._registry.update(result)

            JSONBase._lazy_loaded = True

        return JSONBase._registry

    @staticmethod
    def _load_from_yaml(directory: str) -> Dict[str, Callable[[Dict], Type]]:
        yaml_files = [os.path.join(directory, file) for file in os.listdir(directory) if file.endswith('.yaml')]
        result = {}

        with concurrent.futures.ThreadPoolExecutor() as executor:
            results = executor.map(load_from_yaml, yaml_files)

        for result_part in results:
            if not isinstance(result_part, dict):
                continue

            for id_, factory_func in result_part.items():
                result[id_] = factory_func

        return result

def load_from_yaml(file_path: str) -> Any:
    with open(file_path, 'r') as file:
        data = yaml.load(file, Loader=Loader)

    if not isinstance(data, dict):
        raise ValueError("Invalid YAML data")

    return data['factories']

# subclasses/custom_class.py
from json_base import JSONBase
from typing import Any

@JSONBase.register_factory
def create_custom_instance(id: str) -> 'CustomClass':
    if id == 'custom_id':
        return CustomClass()

class CustomClass(JSONBase):
    def __init__(self, data: Any):
        super().__init__(data)

# example usage
registry = JSONBase.get_registry()
instance = registry['create_custom_instance']({'id': 'custom_id'}).from_json('{"data": "example data"}')
print(instance.data)
