from concurrent.futures import ThreadPoolExecutor, as_completed
from collections import defaultdict
from typing import List, Dict, Any
import logging
from datetime import timedelta

class TestRunner:
    def __init__(self, module_label: str, test_suites: List[Dict], config: Dict):
        self.module_label = module_label
        self.test_suites = test_suites
        self.config = config
        self.concurrency = min(config["concurrency"], len(self.test_suites))
        self.timeout = timedelta(seconds=config["timeout"])
        self.resource_manager = ResourceManager()

    def run(self):
        self.resource_manager.init_resources()
        test_results = defaultdict(lambda: {"passed": 0, "failed": 0})
        executed_tests = set()

        with ThreadPoolExecutor(max_workers=self.concurrency) as executor:
            futures = [executor.submit(self._execute_test_suite, suite) for suite in self.test_suites]

            for future in as_completed(futures):
                result = future.result()
                suite_name = result["suite_name"]
                test_case_name = result["test_case_name"]

                if result["status"] == "success":
                    test_results[test_case_name]["passed"] += 1
                else:
                    test_results[test_case_name]["failed"] += 1

                self.resource_manager.release_resources()
                executed_tests.add((suite_name, test_case_name))
                logging.info(f"{suite_name}.{test_case_name} execution status: {result['status']}")

        self.generate_report(test_results, executed_tests)
        self.resource_manager.close_resources()

    def _execute_test_suite(self, suite: Dict) -> Dict:
        suite_name = suite["label"]
        test_cases = suite["test_cases"]
        in_memory_state = self.resource_manager.get_in_memory_state()

        start_time = time.time()
        test_statuses = []

        for test_case in test_cases:
            test_case_name = test_case["label"]
            url_path, expected_response = test_case["url"], test_case["expected_response"]

            try:
                response = self._execute_test_case(url_path, in_memory_state)

                if response.content != expected_response:
                    logging.error(f"{suite_name}.{test_case_name} test failed (expected {expected_response!r}, got {response.content!r})")
                    return {"status": "failure", "suite_name": suite_name, "test_case_name": test_case_name}

                logging.info(f"{suite_name}.{test_case_name} test passed")
                test_statuses.append({"status": "success", "suite_name": suite_name, "test_case_name": test_case_name})
            except Exception as e:
                logging.error(f"{suite_name}.{test_case_name} test execution failed with error {e}")
                return {"status": "failure", "suite_name": suite_name, "test_case_name": test_case_name}

        elapsed_time = time.time() - start_time
        logging.info(f"{suite_name} execution time: {elapsed_time:.4f} seconds")

        return {"status": "success", "suite_name": suite_name, "test_statuses": test_statuses}

