```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>

typedef struct {
    char* word;
    int length;
} WordData;

void trimAndCapitalize(char** str) {
    // Trim and capitalize the first letter of each word in the string
    if (*str != NULL) {
        char *start = *str;
        for (char* p = start; *p != '\0'; ++p)
            if (isalpha(*p)) {
                *p -= 32;
                break;
            }
        char *end = strchr(start, ' ');
        if (end == NULL) end = strchr(start, '\0');
        for (char* p = start; p < end; ) {
            for (char* q = p + 1; *q != '\0'; ++q)
                if (!isspace(*q)) break;
            size_t len = q - p;
            char* trimmed = (char*)realloc(p, len + 2);
            if (trimmed == NULL) exit(-1); // Handle memory errors here
            memmove(trimmed, p, len);
            trimmed[len] = ' ';
            trimmed[len + 1] = '\0';
            p = trimmed + len + 1;
        }
        *str = realloc(*str, strlen(start) + end - start); // Reallocate the original string
        if (*str == NULL) exit(-1); // Handle memory errors here
        memmove(*str, start, end - start);
    }
}

