const MAX_PARALLEL = 4;
let semaphore = new Semaphore(MAX_PARALLEL);
let cache = new Map();

function asyncArrayReduce(arr, initialValue, callback, { accumulator, customAccumulator }) {
    return new Promise((resolve, reject) => {
        let completed = 0;
        const result = Array.isArray(initialValue) ? initialValue : [initialValue];
        const tasks = [];

        function worker(acc, val, index, arr) {
            if (typeof acc !== 'undefined') { // If accumulator is not provided, use the default accumulator
                if (!customAccumulator) return callback(acc, val, index, arr);
                else return customAccumulator(acc, val, index, arr);
            }
            semaphore.take(() => {
                tasks.push(() => callback(acc, val, index, arr).then((nextVal) => {
                    completed++;
                    if (completed === arr.length) resolve(result);
                    else result[index] = nextVal;
                }, (error) => {
                    reject(error);
                }).finally(() => semaphore.release()));
            });
        }

        for (let i = 0, len = arr.length; i < len; ++i) {
            if (cache.has(arr[i])) worker(result[i], arr[i], i, arr);
            else tasks.push(() => fetchData(arr[i]).then(data => cache.set(arr[i], data), error => console.error(`Error fetching data for ${arr[i]}: ${error}`)).finally(() => semaphore.take()));
        }

        Promise.all(tasks).then(() => worker()).catch(error => reject(error));
    });
}

class Semaphore {
    constructor(initialCount) {
        this.count = initialCount;
        this.waiters = [];
    }

    take() {
        if (this.count > 0) {
            this.count--;
            return Promise.resolve();
        } else {
            return new Promise(resolve => {
                this.waiters.push(resolve);
            });
        }
    }

    release() {
        if (this.waiters.length > 0) {
            const waiter = this.waiters.shift();
            this.count++;
            waiter(this.count);
        }
    }
}

