import Promise from 'bluebird';
import WebpackHotMiddleware from 'webpack-hot-middleware';
import webpack from 'webpack';
import chalk from 'chalk';

export async function scriptLoader(config) {
  const cache = new Map();
  const compiler = webpack(require('./webpack.config'));
  const hmrMiddleware = WebpackHotMiddleware(compiler);

  return Promise.each(config, async (item) => {
    if (!cache.has(item)) {
      try {
        const asset = await compiler.outputFileSystem.getCompilerOutputByAssetIdAsync(item);
        cache.set(item, asset);
      } catch (error) {
        console.error(`${chalk.red('Error')}:\tUnable to load ${item}.`, error);
      }
    }

    if (!cache.has(item)) {
      const script = document.createElement('script');
      script.src = cache.get(item) || item;
      script.onerror = (e) => console.error(`${chalk.red('Error')}:\tScript ${item} failed to load or execute:`, e);
      script.onload = () => console.log(`${chalk.green('Loaded')}:\tScript ${item}`);
      document.head.appendChild(script);
    }
  });
}
