        var tasks = new List<Task<(TAccumulator, XElement[])>>();
        int completedOperations = 0;
        int totalOperations = xmlDocuments.Length;

        ParallelOptions parallelOptions = new()
        {
            MaxDegreeOfParallelism = options?.MaxDegreeOfParallelism ?? Environment.ProcessorCount,
            TaskSchedulerHint = TaskSchedulerHint.LongRunning
        };

        for (int i = 0; i < xmlDocuments.Length; i++)
        {
            var task = Task.Run(() => ParseAndReduce(xmlDocuments[i], reducer, options), parallelOptions);
            tasks.Add(task);
        }

        await Task.WhenAll(tasks);

        TAccumulator accumulatedValue = initialValue;
        var parsedXmlDocs = new XElement[tasks.Count];
        for (int i = 0; i < tasks.Count; i++)
        {
            if (!tasks[i].Result.Item2.IsEmpty)
            {
                parsedXmlDocs[i] = tasks[i].Result.Item2;
                _progressCallback?.Invoke(completedOperations++, totalOperations, _xPathExtractor(parsedXmlDocs[i]), accumulatedValue);
                accumulatedValue = reducer(accumulatedValue, parsedXmlDocs[i]);
            }
        }

        return accumulatedValue;
    }

    private async Task<(TAccumulator, XElement[])> ParseAndReduce<TAccumulator>(XElement xmlDocument, Action<TAccumulator, XElement> reducer, Options options = null)
    {
        var parsedXmlDoc = _cache.GetOrAdd(_xPathExtractor(xmlDocument), (key, _) => ParseXmlDocumentAsync(xmlDocument, key, options));
        var accumulatedValue = default(TAccumulator);

        if (!parsedXmlDoc.Item2)
        {
            throw new Exception($"No data found using XPath expression: {_xPathExtractor(xmlDocument)}");
        }

        await Task.Run(() =>
        {
            try
            {
                var nodes = parsedXmlDoc.Item1.Elements(_xPathExtractor(parsedXmlDoc.Item1)).ToList();
                if (nodes.Count > 1)
                {
                    throw new Exception($"Multiple matching nodes found using XPath expression: {_xPathExtractor(parsedXmlDocument)}");
                }

                if (!nodes[0].IsEmpty)
                {
                    accumulatedValue = reducer(accumulatedValue, nodes[0]);

                    foreach (var childNode in nodes[0].Elements())
                    {
                        var childNodesTask = ParseAndReduce<TAccumulator>(childNode, reducer, options);
                        accumulatedValue = await Task.Run(() => ReduceAsync(accumulatedValue, childNodesTask));
                    }
                }
            }
            catch (Exception ex)
            {
                throw new Exception($"Error extracting data from XML document: {ex.Message}");
            }
        });

        return (accumulatedValue, parsedXmlDoc.Key);
    }

    private async Task<XElement> ParseXmlDocumentAsync(XElement xmlDocument, string xPathExpression, Options options = null)
    {
        try
        {
            await _semaphore.WaitAsync();

            var httpRequestMessage = new HttpRequestMessage(HttpMethod.Get, $"https://validationapi.com/validate/{xPathExpression}");
            httpRequestMessage.Headers.Authorization = new AuthenticationHeaderValue("Bearer", "YOUR_AUTH_TOKEN");
            using var httpResponse = await _httpClient.SendAsync(httpRequestMessage);
            if (!httpResponse.IsSuccessStatusCode)
            {
                throw new Exception($"Error from validation API: {httpResponse.ReasonPhrase}");
            }

            var content = await httpResponse.Content.ReadAsStringAsync();
            var validationResult = JsonSerializer.Deserialize<ValidationResult>(content);
            if (!validationResult.IsValid)
            {
                throw new Exception($"Invalid data in XPath expression: {xPathExpression}");
            }

            return XElement.Parse(validationResult.Xml);
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private async Task<TAccumulator> ReduceAsync<TAccumulator>(TAccumulator accumulator, (TAccumulator, XElement[]) result)
    {
        if (!result.Item2.IsEmpty)
        {
            return await Task.Run(() => Reduce(accumulator, result));
        }

        return accumulator;
    }

    private TAccumulator Reduce<TAccumulator>(TAccumulator accumulator, (TAccumulator, XElement[]) result)
    {
        foreach (var (reducedAccumulator, node) in result.Item1)
        {
            accumulator = reducer(accumulator, node);
        }

        return accumulator;
    }
}

