```python
import yaml
import os
from dataclasses import dataclass
from typing import Any, Dict, List
import concurrent.futures

class CryptoItem:
    def __init__(self, name: str, func_ref: type, **kwargs):
        self.name = name
        self.func_ref = func_ref
        self.params = kwargs

@dataclass
class CryptoConfig:
    hashes: List[CryptoItem]
    ciphers: List[CryptoItem]

def _load_config(filepath: str) -> CryptoConfig:
    with open(filepath, 'r') as file:
        config = yaml.safe_load(file)

    hashes, ciphers = sorted(config['hashes']), sorted(config['ciphers'])
    return CryptoConfig({'hashes': hashes, 'ciphers': ciphers})

def _check_available(item: CryptoItem):
    try:
        item.func_ref()  # Try to create an instance of the function/cipher if possible
        return True
    except Exception as e:
        print(f"Error checking availability for {item.name}: {e}")
        return False

def _load_crypto_items(config: CryptoConfig) -> List[CryptoItem]:
    items = []
    for crypto_type, crypto_list in config.__dict__.items():
        for item in crypto_list:
            if not _check_available(item):
                continue
            items.append(item)
    return items

def load_crypto_config(filepath: str) -> List[CryptoItem]:
    config = _load_config(filepath)
    return _load_crypto_items(config)

def _verify_format(config: CryptoConfig):
    if not all(item.name for item in config.hashes + config.ciphers):
        raise ValueError("Each cryptographic item must have a name.")

def _extend_with(existing_config: CryptoConfig, new_items: List[CryptoItem]):
    hashes, ciphers = existing_config.__dict__['hashes'], existing_config.__dict__['ciphers']

    new_hashes, new_ciphers = [], []
    for item in new_items:
        if item.name.startswith('hash'):
            new_hashes.append(item)
        elif item.name.startswith('cipher'):
            new_ciphers.append(item)

    extended_config = CryptoConfig({'hashes': hashes + new_hashes, 'ciphers': ciphers + new_ciphers})
    return _verify_format(extended_config), extended_config

def extend_crypto_config(existing_config: CryptoConfig, new_items: List[CryptoItem]):
    if not _extend_with(existing_config, new_items)[0]:
        raise ValueError("Invalid or unavailable cryptographic items.")

    return _extend_with(existing_config, new_items)[1]

def parallelize_load_crypto_items(items: List[CryptoItem], chunksize: int = 5):
    with concurrent.futures.ThreadPoolExecutor() as executor:
        future_to_item = {executor.submit(_check_available, item): item for item in [items[i:i + chunksize] for i in range(0, len(items), chunksize)]}

    loaded_items = []
    for future in concurrent.futures.as_completed(future_to_item):
        if future.result():
            loaded_items += list(future.item)
    return loaded_items
```

