angular.module('app').service('DialogFieldService', ['$http', '$rootScope', '$q', function($http, $rootScope, $q) {
    var cache = {},
        refreshInterval;

    this.refreshFields = function(fieldNames, resourceId, url) {
        var deferred = $q.defer();

        if (!cache[resourceId]) {
            cache[resourceId] = {};
        }

        var cachedData = cache[resourceId][url];
        if (cachedData && fieldNames.some(function(field) { return cachedData.hasOwnProperty(field); })) {
            // If data is available in the cache and includes requested fields, resolve immediately with the cached data
            deferred.resolve(cachedData);
        } else {
            // Otherwise, make a request to the API
            $http.get(url + '?resourceId=' + resourceId)
                .then(function(response) {
                    var data = response.data;

                    if (data) {
                        cache[resourceId][url] = data; // Cache the response for future requests

                        $rootScope.$broadcast('dialogFieldRefreshMessage', { fieldNames: fieldNames, data: data });
                    } else {
                        deferred.reject('Failed to refresh dialog fields.');
                    }
                })
                .catch(function() {
                    deferred.reject('Error occurred while refreshing dialog fields.');
                });
        }

        return deferred.promise;
    };

    $rootScope.$on('dialogFieldRefreshMessage', function(event, message) {
        angular.element('.dialog-field').each(function() {
            var field = $(this),
                name = field.attr('name');

            if (message.data && message.data.hasOwnProperty(name)) {
                field.val(message.data[name]);
            }
        });
    });

    // Pagination support (assuming API returns paginated data)
    refreshInterval = setInterval(function() {
        angular.element('.dialog-field').each(function() {
            var field = $(this);
            if (field.attr('needsRefresh')) {
                DialogFieldService.refreshFields([field.attr('name')], field.data('resourceId'), field.data('url')).then(function(data) {
                    field.val(data[field.attr('name')]);
                }, function() {
                    // Handle error gracefully, e.g. by showing an error message or disabling the field
                });
            }
        });
    }, 10000); // Adjust this value to control refresh interval
});
