const { Promise, mapSeries } = require('bluebird');
const fs = require('fs');
const axios = require('axios');
const AWS = require('aws-sdk'); // or Google Cloud Storage equivalent
const Logger = require('logger');

const S3 = new AWS.S3(); // or Google Cloud Storage equivalent initialization

function uploadFileFromUrl(url, bucketName, key) {
  return new Promise((resolve, reject) => {
    try {
      // 1. System Integration and External Dependencies
      const fileStream = axios({ method: 'GET', url, responseType: 'stream' });

      // 2. Performance Optimization and Resource Management
      // Chunking the file into smaller parts for efficient uploads
      const chunkSize = 10 * 1024 * 1024; // 10MB chunks
      let remainingBytes = fileStream.headers['content-length'];
      let currentChunkIndex = 0;

      function uploadChunk(chunk) {
        return new Promise((resolve, reject) => {
          const params = {
            Bucket: bucketName,
            Key: key + '_' + currentChunkIndex,
            Body: chunk,
          };

          // Upload the current chunk to cloud storage
          S3.putObject(params, function(err, data) {
            if (err) return reject(err);
            remainingBytes -= chunk.length;
            currentChunkIndex++;

            // If all chunks have been uploaded, finalize the file in the cloud storage
            if (!remainingBytes) {
              const params = { Bucket: bucketName, Key: key };
              S3.headObject(params, function(err, data) {
                if (err) return reject(err);
                resolve(data.Location);
              });
            } else {
              // Fetch the next chunk and continue uploading
              fileStream.data.then((chunk) => uploadChunk(chunk));
            }
          });
        });
      }

      // Start fetching and uploading the first chunk
      fileStream.data.then((chunk) => uploadChunk(chunk)).catch(reject);
    } catch (err) {
      Logger.error(`Error while uploading file: ${err}`);
      reject(err);
    }
  });
