```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;
import java.io.IOException;
import java.util.Map;
import java.util.ConcurrentHashMap;
import java.util.Optional;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

public class JsonParser {
    private static final OkHttpClient httpClient = new OkHttpClient();
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();

    public static <T> Optional<T> parseJson(String jsonPath) {
        String key = "parsed_" + jsonPath;
        if (cache.containsKey(key)) {
            return Optional.of((T) cache.get(key));
        }

        try {
            JsonNode rootNode = objectMapper.readTree(jsonPath);
            TypeReference<T> typeRef = new TypeReference<>() {};
            T result = objectMapper.treeToValue(rootNode.at(jsonPath), typeRef);
            cache.putIfAbsent(key, result);
            return Optional.of(result);
        } catch (IOException e) {
            System.err.println("Error while parsing JSON: " + e.getMessage());
            return Optional.empty();
        }
    }

    public static String getJsonFromApi(String apiUrl) throws IOException {
        Request request = new Request.Builder()
                .url(apiUrl)
                .build();
        try (Response response = httpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new IOException("Failed to fetch JSON from API: " + apiUrl);
            }
            return response.body().string();
        }
    }
}
```
