public class RandomValueGenerator
{
    private float _minValue;
    private float _maxValue;
    private int _calls = 0;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        if (maxValue < minValue)
            throw new ArgumentException("Max value should be greater than or equal to the Min value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateFloat() => UnityEngine.Random.Range(_minValue, _maxValue);

    public int GenerateInt() => (int)UnityEngine.Random.Range(_minValue, _maxValue + 1);

    public IEnumerable<int> GenerateUniqueRandomIntegers(int n)
    {
        if (n > (_maxValue - _minValue + 1))
            throw new ArgumentOutOfRangeException("The requested number of integers exceeds the range size.");

        HashSet<int> uniqueValues = Enumerable.Range((int)_minValue, (int)(_maxValue - _minValue + 1)).ToHashSet();
        HashSet<int> generatedValues = new HashSet<int>();

        while (generatedValues.Count < n)
            generatedValues.Add((int)UnityEngine.Random.Range(_minValue, _maxValue + 1));

        return generatedValues;
    }

    public override string ToString() => $"{_minValue} to {_maxValue}";

    // For performance optimization and auditing purposes
    public void ResetCallCounter() => _calls = 0;

    public int GetCallCount() => _calls;
}
