void distribute_keys(const char* range, const char* keys, void (*api_func)(const char*, const char*, int)) {
    pthread_t threads[atol(range)]; // Create a thread for each number in the given range
    long offset = 0;
    char** key_list = malloc((strlen(keys) + 1) * sizeof(char*)); // Allocate memory for key list
    char* token = strtok(const_cast<char*>(keys), ",");
    int i = 0;

    while (token != nullptr) {
        key_list[i] = token;
        ++i;
        token = strtok(nullptr, ",");
    }
    key_list[i] = nullptr; // Mark the end of the list

    unsigned char digest[SHA256_DIGEST_LENGTH];
    md5_hash(keys); // Generate MD5 hash for all keys

    long range_start = strtol(strtok(const_cast<char*>(range), "-"), nullptr, 10);
    long range_end = strtol(strchr(range, '-') + 2, nullptr, 10);

    // Launch a thread for each number in the given range
    for (long i = range_start; i < range_end; ++i) {
        Record* record = malloc(sizeof(Record));
        record->value = rand() % 100 + 1;
        record->offset = offset++;

        char key[strlen(key_list[rand() % i]) + 1];
        strcpy(key, key_list[rand() % i]); // Pick a random key from the list
        pthread_create(&threads[i], nullptr, [=] { api_func(md5_hash(key), &record); }, nullptr);
    }

    for (int i = 0; i < range_end - range_start; ++i) {
        pthread_join(threads[i], nullptr);
    }

    free(key_list); // Free allocated memory
}
