using System.Threading.Tasks;
using System.Timers;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Process = System.Diagnostics.Process;

namespace WebsiteDirectoryManager
{
    public class SiteManager
    {
        private readonly ILogger<SiteManager> _logger;
        private readonly IConfiguration _config;
        private readonly string _directoryPath;
        private readonly TimeSpan _retryInterval;
        private int _retryCount = 0;

        public SiteManager(ILogger<SiteManager> logger, IConfiguration config)
        {
            _logger = logger;
            _config = config;
            _directoryPath = _config.GetValue<string>("DirectoryPath");
            _retryInterval = TimeSpan.FromSeconds(_config.GetValue<int>("RetryInterval"));
        }

        public async Task AddSiteAsync(string siteName, Action<ProcessStartInfo> configureStartInfo)
        {
            if (!Directory.Exists(_directoryPath))
                throw new DirectoryNotFoundException($"The directory '{_directoryPath}' was not found.");

            var existingSites = Directory.EnumerateFiles(_directoryPath, "web.config");
            var uniqueSiteName = siteName + (_existingSites.Any(x => x.Contains(siteName)) ? DateTime.UtcNow.Ticks : string.Empty);

            if (!File.Exists($"{_directoryPath}\\{uniqueSiteName}.config"))
            {
                _logger.LogInformation($"Adding site '{uniqueSiteName}' to directory '{_directoryPath}'.");
                // Implement code for adding a new web.config file here.
            }
            else
            {
                _logger.LogWarning($"A site with the name '{siteName}' already exists in the directory '{_directoryPath}'. Using a unique name '{uniqueSiteName}' instead.");
            }

            var startInfo = new ProcessStartInfo();
            configureStartInfo(startInfo);
            startInfo.WorkingDirectory = _directoryPath;
            startInfo.Arguments += $" /site:{uniqueSiteName}";

            try
            {
                using (var process = new Process { StartInfo = startInfo })
                {
                    process.Start();

                    await Task.Delay(_retryInterval, CancellationToken.None);

                    while (_retryCount < _config.GetValue<int>("RetryCount"))
                    {
                        if (process.HasExited)
                            break;

                        try
                        {
                            process.Start();
                            await Task.Delay(_retryInterval, CancellationToken.None);
                        }
                        catch (Exception ex)
                        {
                            _logger.LogError(ex, "Failed to start the site.");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "An error occurred while adding or starting the site.");
            }

            // Implement code for monitoring the site's health and logging relevant metrics here.
        }
    }
}
