        public AsyncDataCopier(HttpClient httpClient, string contextId, TimeSpan retryInterval, int maxConcurrentDecryptions)
        {
            _httpClient = httpClient;
            _contextId = contextId;
            _retryInterval = retryInterval;
            _maxConcurrentDecryptions = maxConcurrentDecryptions;
            _keyAndIvCache = new ConcurrentDictionary<string, Tuple<TripleDESCryptoServiceProvider, ICryptoTransform, byte[]>>();
            _decryptionQueue = new ConcurrentQueue<Tuple<string, byte[], CancellationTokenSource>>();
        }

        public async Task CopyDataAsync(IDictionary<string, List<byte[]>> dataSources)
        {
            var decryptedData = new Dictionary<string, List<byte[]>>();

            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = _maxConcurrentDecryptions };
            Parallel.ForEach(dataSources, options, (sourceKey, tokenSource) =>
            {
                tokenSource.Value.Token.ThrowIfCancellationRequested();

                var decryptionTask = DecryptMessageAsync(sourceKey, sourceKey, tokenSource.Value);
                _decryptionQueue.Enqueue(Tuple.Create(sourceKey, dataSources[sourceKey], tokenSource.Value));
