            await Task.WhenAll(_decryptionQueue.Select(t => DecryptMessageAsync(t.Item1, t.Item2, t.Item3)));

            Parallel.ForEach(_decryptionQueue, (decrementionTaskTuple) =>
            {
                decrementionTaskTuple.Item3.Token.ThrowIfCancellationRequested();
                decryptedData[decrementionTaskTuple.Item1] = decrementionTaskTuple.Item2;
            });
        }

        private async Task<string> DecryptMessage(string base64EncodedMessage, string contextId)
        {
            var keysAndIv = await FetchKeysAndIvAsync(contextId);

            using (var cryptoProvider = TripleDESCryptoServiceProvider.Create())
            {
                cryptoProvider.Key = keysAndIv.Item1;
                cryptoProvider.IV = keysAndIv.Item2;
                var encryptor = cryptoProvider.CreateDecryptor();
                var decryptedBytes = Encoding.UTF8.GetBytes(Convert.FromBase64String(base64EncodedMessage));
                var decryptionBuffer = new MemoryStream();
                using (var transform = encryptor.CreateTransform())
                {
                    transform.TransformBlock(decryptedBytes, 0, decryptedBytes.Length, decryptionBuffer, 0, transform.TransformBlockAsync(decryptedBytes, 0, decryptedBytes.Length, decryptionBuffer, 0).ConfigureAwait(false));
                }

                return Encoding.UTF8.GetString(decryptionBuffer.ToArray());
            }
        }

