#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct FSA {
    int num_states;
    int **transitions;
    char *state_names;
} FSA;

struct Loader {
    void *data_source; // User-defined data source
    size_t buffer_size;
    size_t position;
};

void initLoader(struct Loader *loader, void *data_source, size_t buffer_size) {
    loader->data_source = data_source;
    loader->buffer_size = buffer_size;
    loader->position = 0;
}

int loadNextState(struct Loader *loader, FSA *fsa) {
    if (loader->position >= loader->buffer_size) return -1; // EOF or error

    int state_index = fsa->num_states++;
    fsa->transitions = realloc(fsa->transitions, sizeof(int *) * fsa->num_states);
    fsa->state_names = realloc(fsa->state_names, sizeof(char) * (fsa->num_states + 1));

    int transition_data[2];
    char state_name[256];

    if (fread(&transition_data, sizeof(int), 2, loader->data_source) != 2 ||
        fscanf(loader->data_source, " %255s", state_name) != 1) {
        perror("Error reading data");
        return -1; // Error in data or network failure
    }

    fsa->transitions[state_index] = transition_data;
    strcpy(fsa->state_names + state_index, state_name);

    loader->position += sizeof(int) * 2 + strlen(state_name) + 1; // Account for space after state name
    return state_index;
}

void expandStateList(int *current_states, int num_states, FSA *fsa, struct Loader *loader, int last_state) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_states; ++i) {
        if (current_states[i] == last_state) {
            while (1) {
                int new_state = loadNextState(loader, fsa);
                if (new_state == -1) return; // Error or EOF

                fsa->transitions[current_states[fsa->num_states - 1]][0] = new_state;
                current_states = realloc(current_states, sizeof(int) * (fsa->num_states + 1));
                current_states[fsa->num_states] = new_state;
            }
        }
    }

    pthread_mutex_lock(&mutex);
    fsa->transitions[last_state][1] = fsa->num_states - 1; // Set the next pointer of the last state in the original list
    pthread_mutex_unlock(&mutex);
}
```
