#include <stdio.h>
#include <string.h>
#include <locale.h> // For wcschr, wcslen and mbstowcs

size_t mbstrlen(const char *str) {
    size_t len = 0;
    const char *ptr = str;
    while (*ptr++) ++len;
    return len;
}

size_t wcslen(const wchar_t *str) {
    size_t len = 0;
    const wchar_t *ptr = str;
    while (*ptr++) ++len;
    return len;
}

void expandWithSlash(char **out, const char *input, size_t sizeLimit, size_t maxBufferSize) {
    size_t inputLen = mbstrlen(input);
    size_t bufferSize = (inputLen < maxBufferSize) ? inputLen + 1 : maxBufferSize;

    if (bufferSize > sizeLimit) {
        // Truncate the string to fit within sizeLimit while maintaining a valid ASCII slash or null terminator
        char *truncatedStr = malloc(sizeLimit);
        if (!truncatedStr) return NULL;

        size_t copyLength = (bufferSize > maxBufferSize - 1) ? (sizeLimit - 1) : bufferSize - 1;
        memcpy(truncatedStr, input, copyLength);
        truncatedStr[copyLength] = '/';
        truncatedStr[sizeLimit - 1] = '\0'; // Ensure a valid null terminator

        *out = truncatedStr;
    } else {
        char *str = malloc(bufferSize);
        if (!str) return NULL;

        memcpy(str, input, inputLen);
        str[inputLen] = '/';
        *(str + bufferSize - 1) = '\0'; // Ensure a valid null terminator

        *out = str;
    }
}
