use std::env;
use std::fs::{self, create_dir_all};
use std::path::PathBuf;
use std::sync::{Mutex, Arc};
use chrono::{DateTime, Utc, Duration};
use log::*;
use serde::{Deserialize, Serialize};
use simple_logger;
use reqwest;
use diesel;
use dotenv;
use config::Config;
use uuid::Uuid;

// Config struct for loading configuration from a .env file
#[derive(Serialize, Deserialize, Debug)]
struct Config {
    max_directories: u32,
    cleanup_interval: Duration,
    log_file: String,
}

// Directory struct to store metadata and reference count
#[derive(Debug, Identifiable, Queryable, Insertable)]
#[table_name = "directories"]
pub struct Directory {
    id: i32,
    path: String,
    creation_time: DateTime<Utc>,
    last_access_time: Option<DateTime<Utc>>,
    referenced: bool,
}

// Main function to create directory and set environment variable
pub fn create_and_set_env(dir_name: &str) -> Result<(), Box<dyn std::error::Error> {
    let config = load_config()?;

    // Check if the environment variable is already set, and use the existing value if it is
    if env::var_os("MY_DIR").is_some() {
        return Ok(());
    }

    let dir_path = create_dir_all(PathBuf::from(dir_name))?;
    let dir_path_str = dir_path.to_str().unwrap();

    // Set the environment variable to the path of the directory
    env::set_var("MY_DIR", dir_path_str);

    // Insert metadata into the database
    let db = establish_connection();
    diesel::insert_into(Directory::table)
        .values((
            creation_time: Utc::now(),
            last_access_time: None,
            referenced: true,
        ))
        .on_conflict((id,))
        .do_update()
        .set((last_access_time.eq(Utc::now()), referenced.eq(true)))
        .execute(db)?;

    // Cleanup old directories
    cleanup(config.cleanup_interval)?;

    Ok(())
}

// Utility function to load the configuration from a .env file
fn load_config() -> Result<Config, Box<dyn std::error::Error>> {
    dotenv::dotenv().ok();

    let config = Config::default();
    let mut mapped = config.map(|c| c.merge(dotenv::var("APP_CONFIG")?.parse::<Config>()?));
    mapped["APP_CONFIG"] = Some(dotenv::var("APP_CONFIG")?.parse::<Config>()?);

    Ok(mapped.into_inner())
}

// Utility function to connect to the database
fn establish_connection() -> diesel::SqliteConnection {
    let db_path = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    SqliteConnection::establish(&db_path).unwrap()
}

// Cleanup function to delete old, unused directories
fn cleanup(interval: Duration) -> Result<(), Box<dyn std::error::Error>> {
    let mut last_scan = Utc::now();
    let max_directories = Config::load()?.max_directories as usize;

    loop {
        let db = establish_connection();
        let directories = database::find_unreferenced_old(db, max_directories)?;

        for dir in directories {
            fs::remove_dir_all(&PathBuf::from(dir.path))?;
        }

        last_scan = Utc::now();
        if (Utc::now() - last_scan) > interval {
            break;
        }

        std::thread::sleep(Duration::from_millis(100));
    }

    Ok(())
