```javascript
const fs = require('fs-extra');
const path = require('path');
const readlim = require('readable-stream-limiter');
const lodash = require('lodash');
const chokidar = require('chokidar');

class FileCache {
  constructor() {
    this.cache = new Map();
  }

  async get(filePath) {
    if (this.cache.has(filePath)) return this.cache.get(filePath);
    const content = await fs.readFile(filePath, 'utf8');
    this.cache.set(filePath, content);
    return content;
  }
}

const bufferSize = 1024 * 64; // Set your desired buffer size
const maxFileSizeThreshold = 100 * (1024 ** 2); // Set your maximum file size threshold in bytes

async function readDirectoryFiles(directory, extension, logger) {
  const cache = new FileCache();
  const limiter = readlim({ concurrency: 5 });

  try {
    const files = await fs.readdir(directory);
    const filteredFiles = files.filter(file => path.extname(file) === `.${extension}`);

    for (const file of filteredFiles) {
      const fullPath = path.join(directory, file);
      const stats = await fs.stat(fullPath);

      if (stats.isFile() && stats.size <= maxFileSizeThreshold) {
        limiter.getAsync(() => {
          return fs.createReadStream(fullPath, { bufferSize })
            .on('data', chunk => {
              logger.log(`Processing file: ${file}, Size: ${chunk.length}`);
            })
            .on('end', async () => {
              const content = await cache.get(fullPath);
              // Process the concatenated string here
            });
        });
      }
    }
  } catch (error) {
    console.error(`Error: ${error}`);
  }
}
```

In this code, `readDirectoryFiles` is asynchronous and reads files in parallel using a Readable Stream Limiter. The buffer size for reading file contents can be adjusted by modifying the `bufferSize` constant. Files larger than the specified `maxFileSizeThreshold` are not processed to avoid potential crashes.

The function integrates a FileCache class that stores previously read files, reducing redundant reads when the same directory is accessed multiple times. An error is logged if an issue occurs during file reading or processing. The logger logs the name of each file being processed and its content length.

