fn create_directory(name: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let mut dir_path = env::current_dir()?;
    let dir_path = dir_path.join(name);

    if env::var("MyDir").is_err() {
        info!("Creating new directory...");
        std::fs::create_dir_all(&dir_path)?;
    } else {
        info!("Using existing directory.");
    }

    info!("Directory path: {:?}", dir_path);
    Ok(dir_path)
}

fn set_environment_variable(name: &str, value: &PathBuf) -> Result<(), Box<dyn std::error::Error>> {
    let old_value = env::var(name)?;
    if old_value != value.to_str().unwrap() {
        info!("Setting environment variable...");
        env::set_var(name, value.to_str().unwrap());
    } else {
        info!("Environment variable already set.");
    }

    Ok(())
}

fn main() {
