class SpecificClass {
    // Your specific class implementation here
};

std::unique_ptr<std::vector<std::string>> loadResourceBundle(const std::string& path) {
    std::ifstream bundleFile(path);
    if (!bundleFile.is_open()) {
        throw std::runtime_error("Could not open resource file");
    }

    auto bundleItems = std::make_unique<std::vector<std::string>>();
    size_t count = 0;

    std::string line;
    while (std::getline(bundleFile, line)) {
        ++count;
        bundleItems->push_back(line);
    }

    if (!bundleFile.eof()) {
        throw std::runtime_error("Invalid resource file format");
    }

    return bundleItems;
}

std::unique_ptr<SpecificClass> deserializeResource(const std::string& path, const std::vector<std::string>& bundle) {
    std::ifstream dataFile(path + bundle.front(), std::ios::binary);
    if (!dataFile.is_open()) {
        throw std::runtime_error("Could not open resource data file");
    }

    auto data = std::make_unique<char[]>(bundle.at(1).size());
    dataFile.read((char*)data.get(), bundle.at(1).size());

    if (dataFile.gcount() != bundle.at(1).size()) {
        throw std::runtime_error("Resource data file does not contain the expected number of bytes");
    }

    auto objectStream = java::io::ObjectInputStream();
    try {
        objectStream.reset(new java::io::ObjectInputStream(java::io::ByteArrayInputStream((jbyteArray)data.get())));
        auto clazz = java::lang::Class<SpecificClass>::get(std::string("YourPackageName.SpecificClass"));
        return std::make_unique<SpecificClass>(clazz->newInstance({}));
    } catch (const java::lang::InstantiationException& e) {
        throw std::runtime_error("Unable to instantiate the deserialized object");
    } catch (const java::lang::ClassNotFoundException& e) {
        throw std::runtime_error("The class being deserialized was not found");
    } catch (...) {
        throw std::runtime_error("Deserialization failed unexpectedly");
    }
}
