    user_settings user_data;  // Initialize user settings
    get_user_settings(username, &user_data);  // Fetch user's settings from API

    pthread_mutex_lock(&cipher_mutex);  // Lock cipher for concurrent request safety

    if (num_concurrent_requests >= MAX_CONCURRENT_REQUESTS) {
        fprintf(stderr, "API rate limit reached. Queue the request.\n");
        pthread_mutex_unlock(&cipher_mutex);
        return;
    }

    num_concurrent_requests++;  // Increment number of concurrent requests

