using System;
using System.Collections.Generic;
using UnityEngine;

public class RandomValueGenerator
{
    private float _minValue;
    private float _maxValue;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        if (maxValue < minValue)
            throw new ArgumentException("Max value should be greater than or equal to the min value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GetRandomFloat() => UnityEngine.Random.Range(_minValue, _maxValue);

    public int GetRandomInteger() => (int)UnityEngine.Random.Range(_minValue, _maxValue);

    public List<int> GetRandomIntegers(int count)
    {
        if (count > Mathf.CeilToInt((_maxValue - _minValue + 1)))
            throw new ArgumentOutOfRangeException("The requested count is greater than the total number of unique integers in the range.");

        HashSet<int> randomIntegers = new HashSet<int>();
        while (randomIntegers.Count < count)
            randomIntegers.Add((int)UnityEngine.Random.Range(_minValue, _maxValue + 1));

        return new List<int>(randomIntegers);
    }

    public override string ToString() => $"Min value: {_minValue}, Max value: {_maxValue}";
}
