int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    *nfalist = (NFAPI_CRC_INDICATION_PDU_T*) malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfalist == NULL) {
        perror("Error: Memory allocation failed.");
        return 1;
    }

    int unique_tags[num_structures]; // Array to store unique RX_UE_INFORMATION_TAG values
    int tag_index = 0;

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_structures; ++i) {
        uint32_t tag = (uint32_t)(i + time(NULL)); // Generate unique RX_UE_INFORMATION_TAG value based on current time

        // Check if the tag is already in use and generate a new one if it is
        while (bin_search(unique_tags, tag_index, unique_tags + tag_index) >= 0) {
            tag = (uint32_t)(i + time(NULL));
        }

        unique_tags[tag_index++] = tag;

        // Set the RNTI value to a large number (e.g., 0xFFFFFFFF) as it doesn't matter for our purposes
        ((NFAPI_CRC_INDICATION_PDU_T*)(*nfalist + i))->RNTI = ~0;

        // Set the CRCFLAG value based on the corresponding rule in crc_flag_rules
        ((NFAPI_CRC_INDICATION_PDU_T*)(*nfalist + i))->CRC_INDICATION_REL8_TAG = crc_flag_rules[i];

        // Log the creation of each structure using an external logging function
        log_structure_creation((NFAPI_CRC_INDICATION_PDU_T*)(*nfalist + i));
    }

    pthread_mutex_unlock(&mutex);

    int mismatches = validate_structures(num_structures, crc_flag_rules, *nfalist);
    if (mismatches > 0) {
        printf("Warning: %d structures do not comply with the predefined CRC flag rules.\n", mismatches);
    }

    return 0;
}

