```javascript
const { Readable, Transform, Writable } = require('stream');
const fs = require('fs');
const https = require('https');
const zlib = require('zlib');

class CopyStream extends Transform {
  constructor(targetBufferSize) {
    super({ objectMode: true });
    this._targetBufferSize = targetBufferSize;
    this._totalReceived = 0;
    this._buffer = Buffer.alloc(this._targetBufferSize);
    this._bufferPosition = 0;
  }

  _transform(chunk, encoding, callback) {
    if (this._bufferPosition + chunk.length > this._targetBufferSize) {
      this.push(this._buffer);
      this._buffer = Buffer.alloc(this._targetBufferSize);
      this._bufferPosition = 0;
    }

    this._buffer.write(chunk, this._bufferPosition);
    this._bufferPosition += chunk.length;
    this._totalReceived += chunk.length;
    callback();
  }

  _flush(callback) {
    this.push(this._buffer);
    this.emit('finish');
    callback();
  }
}

async function copyData(sources, targetBufferSize, byteRanges) {
  const outputStream = new Writable({
    objectMode: true,
    write(chunk, encoding, callback) {
      if (Buffer.isBuffer(chunk)) {
        this.push(chunk);
      }
      callback();
    },
  });

  const copyStream = new CopyStream(targetBufferSize);
  copyStream.pipe(outputStream);

  let promises = [];

  for (let source of sources) {
    if (source.type === 'buffer') {
      promises.push(Promise.resolve({ data: source.data }));
    } else if (source.type === 'file') {
      promises.push(
        new Promise((resolve, reject) => {
          const readStream = fs.createReadStream(source.path, { start: source.range[0], end: source.range[1] });
          readStream.on('error', reject);
          readStream.pipe(copyStream);
        })
      );
    } else if (source.type === 'http') {
      const options = {
        method: 'GET',
        headers: source.headers,
        hostname: source.host,
        port: source.port,
        path: source.path,
        agent: false,
      };
      if (source.range) {
        options.headers['Range'] = `bytes=${source.range[0]}-${source.range[1]}`;
      }

      promises.push(
        new Promise((resolve, reject) => {
          const request = https.request(options, (response) => {
            response.on('error', reject);
            if (!response.headers.get('Content-Length')) {
              // Handle invalid Content-Length header in the response
              return;
            }
            if (!source.range) {
              response.pipe(copyStream);
              response.on('end', resolve);
            } else if (Number(response.headers.get('Content-Length')) >= source.range[1] - source.range[0]) {
              response.pipe(copyStream);
              response.on('end', resolve);
            } else {
              // Handle the case where the requested byte range exceeds the available data in the response
              console.error(`Requested byte range ${source.range[0]}-${source.range[1]} is out of bounds for this response`);
              response.destroy();
              resolve();
            }
          });
          request.on('error', reject);
          request.end();
        })
      );
    }
  }

  await Promise.all(promises);
  copyStream.emit('finish');

  return outputStream.getBufferUnref();
}
```

