```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    long value;
    long timestamp;
} Record;

void init_record(Record* record, long value) {
    time_t now = time(NULL);
    record->value = value;
    record->timestamp = now + rand() % 1000000;
}

long* allocate_offsets(size_t size) {
    long* offsets = malloc(sizeof(long) * size);
    if (!offsets) {
        fprintf(stderr, "Error: Unable to allocate memory for offsets\n");
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand();
    }
    return offsets;
}

int* allocate_keys(size_t size) {
    int* keys = malloc(sizeof(int) * size);
    if (!keys) {
        fprintf(stderr, "Error: Unable to allocate memory for keys\n");
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        keys[i] = rand();
    }
    return keys;
}

Record* allocate_records(size_t size) {
    Record* records = malloc(sizeof(Record) * size);
    if (!records) {
        fprintf(stderr, "Error: Unable to allocate memory for records\n");
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        init_record(&records[i], rand());
    }
    return records;
}

void destroy_memory(long* offsets, int* keys, Record* records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;
long* generate_data(size_t size, long delay_min, long delay_max) {
    pthread_mutex_lock(&records_lock);
    long* offsets = allocate_offsets(size);
    int* keys = allocate_keys(size);
    Record* records = allocate_records(size);

    if (!offsets || !keys || !records) {
        pthread_mutex_unlock(&records_lock);
        destroy_memory(offsets, keys, records);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        init_record(&records[i], offsets[i] + keys[i]);
    }

    pthread_mutex_unlock(&records_lock);

    for (size_t i = 0; i < size; ++i) {
        usleep(rand() % (delay_max - delay_min + 1) + delay_min);
    }

    return offsets;
}
```

This code includes a `Record` struct, functions for initializing records and allocating arrays, a lock for concurrent access to the records array, and a function that generates data with thread-safety. The `destroy_memory()` function handles resource deallocation gracefully in case of memory allocation failures.

