using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace DynamicTripleDesDecryptor
{
    public class DecryptionRequest
    {
        public string Base64EncodedMessage { get; set; }
        public Guid RequestId { get; set; }
    }

    public class KeyConfiguration
    {
        [JsonProperty("key")]
        public byte[] Key { get; set; }

        [JsonProperty("iv")]
        public byte[] Iv { get; set; }
    }

    public interface ICryptographicServiceProvider
    {
        Task<KeyConfiguration> FetchKeysAsync(Guid contextIdentifier);
        void LogError(string message, Exception exception = null);
    }

    public class DynamicTripleDesDecryptor : IDisposable
    {
        private readonly ICryptographicServiceProvider _csp;
        private readonly TripleDESCryptoServiceProvider _tripleDes;
        private readonly Queue<DecryptionRequest> _decryptionQueue = new Queue<DecryptionRequest>();
        private readonly SemaphoreSlim _concurrencySemaphore = new SemaphoreSlim(10, 10);
        private readonly Timer _keyRotationTimer;

        public DynamicTripleDesDecryptor(ICryptographicServiceProvider csp)
        {
            _csp = csp;
            _tripleDes = new TripleDESCryptoServiceProvider();
            _keyRotationTimer = new Timer(KeyRotationCallback, null, TimeSpan.Zero, TimeSpan.FromMinutes(5));
        }

        public void EnqueueDecryptionRequest(DecryptionRequest request)
        {
            _decryptionQueue.Enqueue(request);
        }

        public async Task DecryptAsync()
        {
            if (!_concurrencySemaphore.Wait())
                return;

            try
            {
                var keyConfiguration = await _csp.FetchKeysAsync(_tripleDes.Key.GetHashCode().ToString());

                ValidateConfiguration(keyConfiguration);

                var messageBytes = Convert.FromBase64String(DecryptionRequest.Base64EncodedMessage);
                using (var ms = new MemoryStream(messageBytes))
                {
                    _tripleDes.Key = keyConfiguration.Key;
                    _tripleDes.IV = keyConfiguration.Iv;

                    var decryptor = new CryptoStream(ms, _tripleDes.CreateDecryptor(), CryptoStreamMode.Read);
                    var plaintextBytes = new byte[decryptor.ReadByte()];
                    decryptor.Read(plaintextBytes, 0, plaintextBytes.Length);

                    Console.WriteLine($"Decrypted message: {Encoding.UTF8.GetString(plaintextBytes)}");
                }
            }
            catch (Exception ex)
            {
                _csp.LogError($"Decryption error: {ex.Message}", ex);
            }
            finally
            {
                _concurrencySemaphore.Release();
            }
        }

        public void Dispose()
        {
            _keyRotationTimer?.Dispose();
        }

        private static void KeyRotationCallback(object state)
        {
            // Implement key rotation logic here
        }

        private void ValidateConfiguration(KeyConfiguration configuration)
        {
            if (configuration == null || configuration.Key.Length != 24 || configuration.Iv.Length != 8)
                throw new ArgumentException("Invalid key or IV configuration.");
        }
    }
}
