                return jsonify({"status": "error", "message": "Shipping address is outside the valid region"}), 400
            order = Order(**request_data)
            db.session.add(order)
            db.session.commit()
            return jsonify({"status": "success", "data": request_data})
        else:
            return jsonify({"status": "error", "message": "Invalid or tampered signature"}), 403

