        if not order:
            return jsonify({"status": "error", "message": "Order not found"}), 404
        if request.headers.get('X-Signature'):
            if hmac.compare_digest(request.headers.get('X-Signature'), order.signature):
                order.canceled = True
                db.session.commit()
                return jsonify({"status": "success", "message": "Order canceled successfully"})
            else:
                return jsonify({"status": "error", "message": "Invalid or tampered signature"}), 403
        else:
            return jsonify({"status": "error", "message": "Missing signature for cancel operation"}), 403

api.add_resource(OrderResource, '/order')

if __name__ == '__main__':
    app.run(debug=True)
