const _ = require('lodash');

function asyncReducePokemons(pokemonArray, callback) {
  if (!Array.isArray(pokemonArray) || pokemonArray.length === 0) {
    return Promise.resolve('Error: Empty array or invalid input.');
  }

  const getPokemonDetails = (id) => {
    // Use an asynchronous library function to retrieve the Pokemon's type and name here.
    // Replace this placeholder with actual implementation.
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        const pokemon = { name: 'Placeholder Pokemon', type: '' };
        resolve(pokemon);
      }, Math.random() * 100);
    });
  };

  let processedPokemons = [];
  let currentResult = '';

  const processNextPokemon = async () => {
    if (!processedPokemons.length) {
      // Base case: all Pokemons have been processed.
      return Promise.resolve(currentResult);
    }

    const pokemon = processedPokemons.shift();
    const details = await getPokemonDetails(pokemon.id);

    try {
      const weaknesses = _.flowRight(
        // Use the callback function to determine the weaknesses based on Pokemon type.
        callback,
        (acc, weakness) => acc + weakness + ','
      )(details.type);

      currentResult += weaknesses;
    } catch (error) {
      console.error(`Error processing Pokemon "${details.name}":`, error);
      // In case of an error, remove the erroneous Pokemon from the array and continue with the next one.
      processedPokemons = _.without(processedPokemons, pokemon);
    }

    return processNextPokemon();
  };

  return pokemonArray.reduce((acc, pokemon) => {
    if (!_.isNumber(pokemon.id)) {
      throw new Error('Each Pokemon object must have a numeric "id" property.');
    }

    // Use lodash to safely push the current Pokemon to the processed array without concerns about concurrent modifications.
    return acc.concat([pokemon]);
  }, [])
    .then(processNextPokemon)
    .catch((error) => {
      console.error(`Error initializing Pokemons processing:`);
      throw error;
    });
}
