int main(int argc, char** argv) {
    if (argc != 7) {
        printf("Usage: %s key iv_len mode data enc|dec\n", argv[0]);
        return -1;
    }

    const unsigned char* key = argv[1];
    size_t iv_len = strtol(argv[2], NULL, 10);
    const char* mode = argv[3];
    const unsigned char* data = (const unsigned char*) argv[4];
