        printf("Error initializing context\n");
        return -1;
    }

    size_t data_len = strlen((const char*)data);
    unsigned char encrypted[data_len];
    if (strcmp(action, "enc") == 0) {
        des_encrypt(&ctx, encrypted, data_len);
        printf("Encrypted: ");
        for (size_t i = 0; i < data_len; ++i) {
            printf("%02X ", encrypted[i]);
        }
        printf("\n");
    } else if (strcmp(action, "dec") == 0) {
        des_context tmp_ctx;
        memcpy(&tmp_ctx, &ctx, sizeof(des_context));
        des_init(&tmp_ctx, key, strlen((char*)key), "", 0);
        des_decrypt(&tmp_ctx, encrypted, data_len);
        printf("Decrypted: ");
        for (size_t i = 0; i < data_len; ++i) {
            printf("%c", encrypted[i]);
        }
        printf("\n");
    } else {
        printf("Invalid action specified\n");
        return -1;
    }

    des_cleanup(&ctx);
    return 0;
}
