def run_sed(commands):
    try:
        result = subprocess.check_call(commands)
    except subprocess.CalledProcessError as e:
        raise Exception("Sed command failed with the following error:\n" + str(e))

def load_config(filename, params):
    config = {}
    with open(filename) as f:
        for line in f:
            key, value = line.strip().split('=')
            config[key] = params[value]
    return config

def main(params):
    config = load_config("kickstart.conf", params)
    run_sed(["sed", "-i", f"s/{config['PLACEHOLDER1']}/{config['VALUE1']}/g", "./kickstart.conf"])
    run_sed(["sed", "-i", f"s/{config['PLACEHOLDER2']}/{config['VALUE2']}/g", "./kickstart.conf"])
    run_sed(["sed", "-i", "a\npassword = " + config['ENCRYPTED_PASSWORD'], "./kickstart.conf"])

