class JsonObject {
  constructor(data) {
    this._data = JSON.parse(JSON.stringify(data)); // Deep clone data to avoid mutation issues
  }

  toJsonString() {
    return JSON.stringify(this._data);
  }

  static fromJsonString(jsonString, factoryRegistry) {
    const objectData = JSON.parse(jsonString);
    if (factoryRegistry[objectData['id']]) {
      return new factoryRegistry[objectData['id']](objectData);
    }
    throw new Error(`No factory function found for ID: ${objectData['id']}`);
  }

  static registerFactory(id, Factory) {
