use std::env;
use std::fs::{create_dir, remove_dir};
use std::io::{BufWriter, Write};
use std::path::PathBuf;
use std::sync::Mutex;
use time::SystemTime;
use chrono::Utc;
use log::*;

// Define the logger
static LOGGER: Mutex<Logger> = Mutex::new(Builder::root()
    .format(|(_, record)| format!("{}", record))
    .filter(Some("my_logger"), LevelFilter::Info)
    .build());

fn create_and_set_dir(dir_name: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let dir_path_var = "DIR_PATH";

    // Check if DIR_PATH is already set
    if env::var_os(dir_path_var).is_some() {
        let dir_path = env::var(dir_path_var)?;
        let run_timestamp = Utc::now().format("%Y%m%d-%H%M%S").to_string();
        let sub_dir_name = format!("{}_run_{}", dir_name, run_timestamp);

        // Create the subdirectory using the existing DIR_PATH
        let sub_dir_path = PathBuf::from(dir_path).join(&sub_dir_name);
        create_dir_all(&sub_dir_path)?;

        // Set the environment variable to the path of the new directory
        env::set_var(dir_path_var, sub_dir_path.to_str().unwrap());

        // Log the creation and setting of the directory
        let mut logger = LOGGER.lock().unwrap();
        writeln!(logger, "Created directory: {}", &sub_dir_path.display())?;

        // Delete the temporary subdirectory after logging if it was created based on existing DIR_PATH
        drop(sub_dir_path);
        Ok(())
    } else {
        let dir_path = create_dir(PathBuf::from(dir_name))?;

        // Set the environment variable to the path of the new directory and log the creation and setting of the directory
        env::set_var(dir_path_var, &dir_path.to_str().unwrap());
        let mut logger = LOGGER.lock().unwrap();
        writeln!(logger, "Created directory: {}", &dir_path.display())?;
        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Use the function with a given directory name
    create_and_set_dir("my_directory")?;
    Ok(())
}
