bool validate_oauth2_token(char *token) {
    JsonObject *json = json_tokener_parse(token);
    bool isValid = json != NULL &&
                  json_object_get_string_ex(json, "access_token") != NULL &&
                  json_object_get_int_ex(json, "expires_in") >= 0 &&
                  strcmp(json_object_get_string_ex(json, "token_type"), "Bearer") == 0 &&
                  (json_object_object_get(json, "refresh_token") == NULL || json_object_get_string_ex(json, "refresh_token") != NULL);
    json_object_put(json);
    return isValid;
}
