function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
    // Database connection (using PDO for better performance and security)
    $db = new PDO('mysql:host=localhost;dbname=hospital', 'username', 'password');
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    // External weather API for closure reasons check (replace with actual API function call)
    $weatherData = getWeatherData('city_id');

    // Rate limiting using a simple cache mechanism (replace with a more robust solution if needed)
    if (!hasRateLimited($ipAddress)) {
        setRateLimit($ipAddress);

        // Begin transaction
        $dbTransaction = $db->beginTransaction();

        try {
            // Check for potential closure reasons due to extreme weather conditions
            if (in_array($newStatus, ['closed', 'emergency']) && ($weatherData['conditions'] == 'extreme')) {
                notifyWeatherAPI('clinic-closure', $clinicId);
                notifyEmergencyTeamViaEmail('clinic-closure', $clinicId);
            }

            // Check for overlapping appointments with the patient scheduling system (replace with actual function call)
            if (!checkAppointmentOverlaps($clinicId, $newStatus)) {
                updateClinicAvailability($clinicId, $newStatus);

                // Update clinic status, last modified IP address, and last modified date in the database
                $stmt = $db->prepare("UPDATE clinics SET status=?, last_modified_ip=?, last_modified=NOW() WHERE id=?");
                $stmt->execute([$newStatus, $ipAddress, $clinicId]);

                // Commit transaction and return success message
                $dbTransaction->commit();
                return 'Clinic status updated successfully.';
            } else {
                throw new Exception('Overlapping appointments found.');
            }
        } catch (\Exception $e) {
            // Rollback transaction in case of errors
            $dbTransaction->rollBack();
