```python
import requests
from lxml import etree, cache
from xml.etree.ElementTree import XMLParser

class XmlProcessor:
    def __init__(self, api_url):
        self.api_url = api_url
        self.cache = cache.ElementCache()

    def _xslt_transform(self, xml, xslt_file):
        with open(xslt_file, 'rb') as f:
            xslt = etree.XML(f.read())
            return etree.XSLT(xslt).result_element(etree.fromstring(xml))

    def _extract_field(self, element, field_name):
        if not element or not hasattr(element, 'tag'):
            return None

        if len([e for e in element if e.tag == field_name]) > 1:
            raise Exception(f'Multiple elements with name "{field_name}" found')

        try:
            return element[0].text
        except (AttributeError, IndexError):
            return None

    def _process_xml(self, xml, field_names, xslt_file=None):
        if xslt_file:
            xml = self._xslt_transform(xml, xslt_file)

        result = {}

        for field in field_names:
            try:
                result[field] = self._extract_field(etree.XML(xml), field)
            except Exception as e:
                print(f'Error while processing field "{field}": {e}')

        return result

    def fetch_and_process_xml(self, api_params, field_names, xslt_file=None):
        cache_key = hashlib.md5(json.dumps(api_params).encode('utf-8')).hexdigest()

        if cache_key in self.cache:
            xml = self.cache[cache_key]
        else:
            response = requests.get(self.api_url, params=api_params)
            if not response.ok:
                print(f'Error while fetching XML: {response.status_code} - {response.reason}')
                return None

            xml = etree.XML(response.content, parser=XMLParser(encoding='utf-8'))
            self.cache[cache_key] = xml

        processed_xml = self._process_xml(xml, field_names, xslt_file)

        return processed_xml
```

This code defines a `XmlProcessor` class that fetches XML documents from an external REST API, processes them using lxml library, and extracts specific fields. The cache system avoids redundant API calls by storing the results of previous field extractions in memory. Custom data formatting can be achieved through XSLT transformations, and error handling is implemented to manage missing or multiple elements with the same name. The function is easily extensible for adding new field extraction rules in the future.

