void openLogFile(FILE **logFile, const char *path, size_t bufferSize) {
    // Open log file with specified path and bufferSize
    *logFile = fopen(path, "a");
    if (*logFile == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void closeLogFile(FILE **logFile) {
    // Close the open log file
    fclose(*logFile);
}

int logCondition(const char *condition, int severity, const char *format, ...) {
    FILE *logFile = NULL;
    va_list args;
    char buffer[4096];

    if (condition) {
        openLogFile(&logFile, "path/to/your-logfile.txt", sizeof(buffer));

        va_start(args, format);
        snprintf(buffer, sizeof(buffer), getCurrentTimestamp());
        vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), format, args);
        va_end(args);

        fprintf(logFile, "%s [%s]: ", buffer, logSeverityToString(severity));
        fflush(logFile);

        // Call the logging system with the appropriate severity level and message
        // (integration with an external logging system not shown here)
    }

    closeLogFile(&logFile);

    return 0;
}

const char *logSeverityToString(Severity severity) {
    switch (severity) {
        case LOG_ERROR:
            return "ERROR";
        case LOG_WARNING:
            return "WARNING";
        case LOG_INFO:
            return "INFO";
        default:
            break;
    }
}
