using UnityEngine;

public class WeatherDataFetcher
{
    private string _apiKey;
    private string _apiEndpoint;
    private CacheManager _cacheManager;
    private int _randomMin;
    private int _randomMax;

    public WeatherDataFetcher(string configFilePath)
    {
        var configJson = ReadConfigFile(configFilePath);
        _apiKey = configJson["ApiKey"];
        _apiEndpoint = configJson["ApiEndpoint"];
        _cacheManager = new CacheManager();
        _randomMin = configJson["RandomMin"];
        _randomMax = configJson["RandomMax"];
    }

    private JObject ReadConfigFile(string filePath)
    {
        if (File.Exists(filePath))
        {
            var json = File.ReadAllText(filePath);
            return JObject.Parse(json);
        }
        else
        {
            throw new FileNotFoundException("Configuration file not found", filePath);
        }
    }

    public int GetRandomIntInclusive(int min, int max)
    {
        return UnityEngine.Random.Range(Mathf.Clamp(min, _randomMin, _randomMax), Mathf.Clamp(max, _randomMin, _randomMax));
    }

    public IList<int> GetRandomIntList(int size)
    {
        var list = new HashSet<int>();
        while (list.Count < size)
        {
            list.Add(GetRandomIntInclusive(_randomMin, _randomMax));
        }
        return new List<int>(list);
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        sb.AppendLine($"API Key: {_apiKey}");
        sb.AppendLine($"API Endpoint: {_apiEndpoint}");
        sb.AppendLine($"Random Value Range: [{_randomMin}, {_randomMax}]");
        return sb.ToString();
    }

    public async Task<WeatherData> FetchWeatherDataFromAPIAsync(double latitude, double longitude)
    {
        var cacheKey = $"{latitude}-{longitude}";
        WeatherData data;

        if (_cacheManager.TryGetValue(cacheKey, out data)) // Cache hit
        {
            PrintCacheHit();
            return data;
        }

        try
        {
            var httpWebRequest = WebRequest.CreateHttp($"{_apiEndpoint}/weather?lat={latitude}&lon={longitude}");
            httpWebRequest.Headers["Authorization"] = $"Bearer {_apiKey}";
            using (var response = await httpWebRequest.GetResponseAsync())
            {
                if (response.IsSuccessStatusCode)
                {
                    var jsonResponse = await new StreamReader(response.GetResponseStream()).ReadToEndAsync();
                    data = JsonConvert.DeserializeObject<WeatherData>(jsonResponse);
                    _cacheManager.Add(cacheKey, data); // Cache miss
                    PrintRequestMade();
                }
                else
                {
                    throw new HttpRequestException($"API request failed with status code: {response.StatusCode}");
                }
            }
        }
        catch (HttpRequestException ex)
        {
            PrintNetworkTimeout();
            return null;
        }

        return data;
    }

    private void PrintCacheHit()
    {
        Console.WriteLine("Cache Hit: Fetched weather data from cache");
    }

    private void PrintRequestMade()
    {
        Console.WriteLine("Request Made: Fetching weather data from API");
    }

    private void PrintNetworkTimeout()
    {
        Console.WriteLine("Network Timeout: Unable to connect to the API");
    }
}

