public class LogProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(LogProcessor.class);
    private LoadingCache<String, Function<JsonNode, Map<String, Object>>> metricExtractors;
    private LoadingCache<String, Object> cache;

    public LogProcessor(List<MetricDefinition> metricDefinitions) {
        metricExtractors = CacheBuilder.newBuilder()
                .expireAfterAccess(Duration.ofMinutes(5))
                .build((key) -> () -> buildExtractor(key, metricDefinitions));
        cache = CacheBuilder.newBuilder()
                .expireAfterAccess(Duration.ofMinutes(1))
                .build();
    }

    private Function<JsonNode, Map<String, Object>> buildExtractor(String key, List<MetricDefinition> metricDefinitions) {
        return (jsonNode) -> metricDefinitions.stream()
                .filter(def -> def.getKey().equals(key))
                .findFirst()
                .map(MetricDefinition::getExtractor)
                .orElseThrow(() -> new IllegalArgumentException("Unknown metric: " + key))
                .apply(jsonNode);
    }

    public void processLogs(List<ConsumerRecord<String, String>> logs) {
        logs.forEach((log) -> {
            try {
                JsonNode jsonNode = mapper.readTree(log.value());
                Map<String, Object> metrics = metricExtractors.get("metrics").call(jsonNode);

                handleMetrics(metrics);

                if (!cache.asMap().containsKey(log.key())) {
                    cache.put(log.key(), metrics);
                } else {
                    combineMetrics(cache.get(log.key()), metrics);
                }
            } catch (IOException | ExecutionException e) {
                LOGGER.error("Error processing log: {}", e.getMessage());
            }
        });
    }

    private void handleMetrics(Map<String, Object> metrics) {
        // Add your real-time aggregation and alerting logic here based on predefined thresholds
    }

    private void combineMetrics(Object currentValues, Map<String, Object> newValues) {
        // Implement merging of the extracted metric values for efficient caching
    }
}

class MetricDefinition {
    private final String key;
    private final Function<JsonNode, Object> extractor;

    public MetricDefinition(String key, Function<JsonNode, Object> extractor) {
        this.key = key;
        this.extractor = extractor;
    }

    public String getKey() {
        return key;
    }

    public Function<JsonNode, Object> getExtractor() {
        return extractor;
    }
}
