function handleClinicOperations($operation, $clinicData) {
    static $concurrency = 0;
    static $rateLimitPerIP = [];
    static $connectionPool; // Initialize connection pool here
    static $queueManager; // Initialize queue manager here

    if (!$connectionPool) {
        // Initialize connection pool using your preferred PHP ORM or PDO library
    }

    if (!$queueManager) {
        // Initialize queue manager using a reliable queueing system such as Beanstalkd, Redis, or RabbitMQ
    }

    switch ($operation) {
        case 'create':
            $name = array_shift($clinicData);
            if (strlen($name) > 50 || !in_array(strtolower(substr($name, 0, strpos($name, " "))), allowedLanguages())) {
                throw new Exception("Invalid clinic name.");
            }

            $clinicID = createClinicRecord($connectionPool, $name, ...$clinicData); // Replace ellipsis with additional clinic data fields
            break;

        case 'update':
            if (!isset($clinicData['status'])) {
                throw new Exception("Missing required field: status.");
            }

            updateClinicStatus($connectionPool, $clinicData['id'], $clinicData['status']);

            switch ($clinicData['status']) {
                case 'closed':
                case 'emergency':
                    $weatherAPI = new WeatherAPI(); // Initialize your weather API class here
                    $weatherCheck = $weatherAPI->checkWeatherRisks($clinicData['location']);

                    if ($weatherCheck) {
                        clearAndRescheduleAppointments($queueManager, $clinicData['id']);

                        $patientEmailService = new PatientEmailService(); // Initialize your patient email service class here
                        $patientsWithAppointments = getPatientsWithAppointmentsAtClinic($connectionPool, $clinicData['id']);

                        foreach ($patientsWithAppointments as $patient) {
                            $patientEmailService->sendAlternativeClinicOptions($patient);
                        }
                    }
                    break;
            }
            updateClinicMetadata($connectionPool, $clinicData['id'], 'last_modified', time(), $_SERVER['REMOTE_ADDR']);
            break;

        case 'delete':
            if (!getClinicUsageCount($connectionPool, $clinicData['id']) > 0) {
                deleteClinicRecord($connectionPool, $clinicData['id']);

                $patientEmailService = new PatientEmailService(); // Initialize your patient email service class here
                $patientsWithAppointments = getPatientsWithAppointmentsAtClinic($connectionPool, $clinicData['id']);

                foreach ($patientsWithAppointments as $patient) {
                    $patientEmailService->sendAlternativeClinicOptions($patient);
                }
            } else {
                throw new Exception("Cannot delete clinic in use.");
            }
            break;
    }

    ++$concurrency;
    if ($concurrency > 1000) {
        usleep(1000 * microtime(true)); // Adjust sleep duration as needed to manage concurrency
        $concurrency = 0;
    }

    rateLimit($clinicData['ip']);
}

function rateLimit($ip) {
    if (!isset($rateLimitPerIP[$ip])) {
        $rateLimitPerIP[$ip] = 0;
    }

    if (time() - $rateLimitPerIP[$ip]['timestamp'] < 3600) { // Adjust time in seconds as needed for rate limiting
        throw new Exception("Exceeded operation limit per hour.");
    }

    $rateLimitPerIP[$ip] = ['timestamp' => time()];
}
