class FileLoader {
  constructor(apiUrl, queue) {
    this.apiUrl = apiUrl;
    this.queue = queue || [];
    this.loadedFiles = new Set();
    this.log = console.log;
  }

  async loadFile(file) {
    if (this.loadedFiles.has(file)) return;

    try {
      const response = await fetch(`${this.apiUrl}/files/${file}`);
      if (!response.ok) throw new Error(`Failed to load file: ${file}`);

      const content = await response.text();
      this.log(`Loaded ${chalk.green(file)}`);
      fs.writeFileSync(`${file}.js`, content);
      this.loadedFiles.add(file);
    } catch (error) {
      this.log(`Error loading ${chalk.red(file)}: ${error.message}`);
      if (error.name === 'SyntaxError') {
        this.log(`${file} contains syntax errors, skipping...`);
