#[derive(Serialize, Deserialize, Debug)]
struct TestCase {
    id: String,
    input: serde_json::Value,
    expected_output: serde_json::Value,
}

trait JsonParserTrait {
    fn from_str(json: &str) -> Self;
    fn to_string(&self) -> String;
}

struct JsonParser<T: JsonParserTrait> {
    id: String,
    factory: Box<dyn Fn() -> T + Send>,
}

impl<T: JsonParserTrait> Clone for JsonParser<T> {}

impl<T: JsonParserTrait> fmt::Display for JsonParser<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "JsonParser({})", self.id)
    }
}

impl<T: JsonParserTrait> Deserialize for JsonParser<T> {
    fn deserialize<D>(d: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'_>,
    {
        let json = Deserialize::deserialize(d)?;
        let id = json.get("id").unwrap().as_str().unwrap().to_string();
        let factory = json.get("factory").unwrap().deserialize(JsonParserFactory::<T>::deserializer)?;
        Ok(Self { id, factory })
    }
}

struct JsonParserFactory<T: JsonParserTrait> {
    registry: Mutex<HashMap<String, Box<dyn Fn() -> T + Send>>>,
}

impl<T: JsonParserTrait> Default for JsonParserFactory<T> {
    fn default() -> Self {
        Self {
            registry: Mutex::new(HashMap::new()),
        }
    }
}

impl<T: JsonParserTrait> JsonParserFactory<T> {
    pub fn register(&mut self, id: String, factory: Box<dyn Fn() -> T + Send>) {
        let mut registry = self.registry.lock().unwrap();
        *registry.entry(id).or_insert(factory)
    }

    fn deserializer<'de>() -> serde::Deserializer<'de> {
        serde::Deserializer::new(JsonParserFactory::<T>::deserialize_tuple)
    }

    fn deserialize_tuple<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::de::Deserializer<'de>,
    {
        let registry = &mut *JsonParserFactory::<T>::registry();
        let id = <&str>::deserialize(deserializer.next_value())?;
        let factory = <Box<dyn Fn() -> T + Send>>::deserialize(deserializer)?;
        registry.insert(id.to_string(), Box::new(factory));
        Ok(Self {})
    }
}

impl<T: JsonParserTrait> JsonParser<T> {
    pub async fn run_tests(
        module_label: &str,
        test_labels: Vec<String>,
        test_functions: Vec<Box<dyn Fn() + Send + Sync + 'static>>,
        cleanup_function: Box<dyn Fn() + Send + 'static>,
    ) {
        let environment_var = format!("TEST_{}", module_label.to_uppercase());
        let directories = test_labels
            .par_iter()
            .map(|test| format!("{}_{}", environment_var, test))
            .collect::<Vec<String>>();
        let temp_dirs = directories
            .into_par_iter()
            .filter(|dir| !fs::metadata(Path::new(dir)).is_ok())
            .collect::<Vec<&str>>();
        if !temp_dirs.is_empty() {
            println!(
                "Creating missing test directories: {}",
                temp_dirs.join(", ")
            );
            fs::create_dir_all(directories.iter().map(|dir| Path::new(dir)).collect::<Vec<Path>>())
                .expect("Failed to create test directory");
        }

        let env = env::var_os("RUST_TEST_THREADS").unwrap_or_else(|_| env::OsString::from("1"));
        let threads = env.to_string_lossy().parse::<usize>().expect("Invalid thread count");
        println!("Running tests in parallel with {} threads", threads);
        executor::block_on(future::try_join_all(
            (0..threads).map(|_| {
                test_functions
                    .par_iter()
                    .filter_map(|test| {
                        let label = test.label();
                        if test_labels.contains(&label) {
                            Some(async move {
                                let environment_var = format!("TEST_{}", module_label.to_uppercase());
                                let dir = env::var_os(environment_var)
                                    .expect("Missing test directory");
                                let mut current_dir = Path::new("");
                                if let Ok(cwd) = env::current_dir() {
                                    current_dir = cwd;
                                }
                                let dir = Path::new(&dir.to_str().unwrap());
                                fs::set_current_dir(dir)?;
                                test().await
                            })
                        } else {
                            None
                        }
                    })
                    .collect::<Vec<Option<Box<dyn FnOnce() + Send + Sync + 'static>>>>(),
            })
            .collect::<Vec<_>>(),
        ))
        .await
        .unwrap_or_else(|e| {
            println!("Encountered error while running tests: {}", e);
            cleanup_function();
            std::process::exit(1)
        });

        for result in results {
            match result {
                Ok(_) => println!("Test passed"),
                Err(e) => println!("Test failed with error: {}", e),
            }
        }
        cleanup_function();
    }
}
```

