```python
import argon2
import json
import datetime as dt
import requests
import os
from typing import Dict

# Third-party API URL and headers
API_URL = "https://your-api-url.com"
API_HEADERS = {"Authorization": "Bearer your-access-token"}

def serialize(data: Dict):
    with open("tokens.json", "w") as f:
        json.dump(data, f)

def deserialize():
    if os.path.exists("tokens.json"):
        with open("tokens.json", "r") as f:
            return json.load(f)
    return None

def get_token() -> Dict or None:
    data = deserialize()
    if data and dt.datetime.now() < data["exp"]:
        return data

    response = requests.post(API_URL + "/tokens", headers=API_HEADERS)
    if response.status_code == 200:
        token_data = response.json()
        serialize({"exp": dt.datetime.now() + dt.timedelta(seconds=token_data["expires_in"]), **token_data})
        return token_data
    else:
        print("Error getting access token.")
        return None

def argon2_hash(password: str, d=4, m=16384, t=2):
    algorithm = argon2.ALG_ARGON2id
    pw = argon2.passwd(password, salt=os.urandom(32), d=d, m=m, t=t)
    return pw.encode()

def argon2_verify(hashed: bytes, password: str, d=4, m=16384, t=2):
    algorithm = argon2.ALG_ARGON2id
    raw_pw = argon2.passwd(password, salt=hashed[:32], d=d, m=m, t=t)
    return raw_pw == hashed[len(raw_pw):]

def password_validate(password: str):
    if len(password) < 8:
        print("Password too short. Must be at least 8 characters.")
        return False
    if any(c.isdigit() for c in password) is False or any(c.isalpha() for c in password) is False:
        print("Password must contain both numbers and letters.")
        return False
    if password == "password" or password == "qwerty" or password == "123456":
        print("Weak password detected.")
        return False
    return True

def test_token():
    token = get_token()
    while token is not None:
        print(f"Access Token: {token}")
        token = get_token()

def test_password(password):
    hashed = argon2_hash(password)
    if argon2_verify(hashed, password):
        print("Password verified.")
    else:
        print("Invalid password.")

def main():
    valid_pass = "secure-password"
    if not password_validate(valid_pass):
        return

    test_token()
    hashed = argon2_hash(valid_pass)
    test_password(hashed)

if __name__ == "__main__":
    main()
```

