using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using log4net;

public class DynamicTextProcessor
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(DynamicTextProcessor));
    private readonly IFetchSettings _settingsFetcher;
    private readonly IDictionary<string, Func<byte[], byte[]>> _hashAlgorithms;
    private const int MaxChunkSize = 1048576; // 1MB

    public DynamicTextProcessor(IFetchSettings settingsFetcher)
    {
        _settingsFetcher = settingsFetcher;
        _hashAlgorithms = new Dictionary<string, Func<byte[], byte[]>>
        {
            { "MD5", HashUtilities.ComputeHash },
            { "SHA1", SHA1.Create.ComputeHash },
            { "SHA256", SHA256.Create.ComputeHash }
        };
    }

    public async Task ProcessUserInput(string input, int testSuiteId)
    {
        if (string.IsNullOrEmpty(input))
        {
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));
        }

        var userSettings = await _settingsFetcher.GetUserSettings();
        if (userSettings == null)
        {
            throw new InvalidOperationException("Failed to fetch user settings.");
        }

        int maxLength = userSettings.MaxLength > 0 ? Math.Min(userSettings.MaxLength, input.Length) : int.MaxValue;
        string processedInput = input.Substring(0, maxLength);

        if (userSettings.TrimInput)
        {
            processedInput = processedInput.Trim();
        }

        if (userSettings.CapitalizeInput)
        {
            processedInput = processedInput.ToUpperInvariant();
        }

        Log.InfoFormat("Processing test case #{0} with input: {1}", testSuiteId, processedInput);

        var watch = System.Diagnostics.Stopwatch.StartNew();
        byte[] hash = GenerateHash(processedInput, userSettings.HashAlgorithm);
        watch.Stop();
        Log.InfoFormat("Hash computation for test case #{0} took {1}ms", testSuiteId, watch.ElapsedMilliseconds);

        // You can extend this class with additional functionality like concurrent processing, rate limiting, network failure handling, etc.
    }

    private Func<byte[], byte[]> GetHashAlgorithm(string algorithmName)
    {
        return _hashAlgorithms[algorithmName];
    }

    private byte[] GenerateHash(string input, string algorithmName)
    {
        var algorithm = GetHashAlgorithm(algorithmName);
        return algorithm(Encoding.UTF8.GetBytes(input));
    }
}
