using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Newtonsoft.Json;

public class ConfigurationService
{
    private readonly HttpClient _httpClient;
    private readonly ApplicationDbContext _dbContext;
    private readonly string _cacheRootDirectory;
    private readonly object _themeBitmapLock = new object();
    private readonly Bitmap _currentThemeBitmap = null;

    public ConfigurationService(HttpClient httpClient, ApplicationDbContext dbContext, string cacheRootDirectory)
    {
        _httpClient = httpClient;
        _dbContext = dbContext;
        _cacheRootDirectory = cacheRootDirectory;
    }

    public async Task<bool> UpdateUserConfigurationAsync(int userId, string configurationName, string configurationValue)
    {
        if (string.IsNullOrEmpty(configurationName) || string.IsNullOrEmpty(configurationValue))
            return false;

        var userConfiguration = await _dbContext.UserConfigurations
            .FirstOrDefaultAsync(uc => uc.UserId == userId && uc.ConfigurationName == configurationName);

        if (userConfiguration == null)
            return false;

        userConfiguration.ConfigurationValue = configurationValue;
        await _dbContext.SaveChangesAsync();

        // Cache management and theme bitmap handling
        var cachedThemeBitmapPath = GetCachedThemeBitmapPath(configurationName);
        if (File.Exists(cachedThemeBitmapPath))
        {
            lock (_themeBitmapLock)
            {
                if (_currentThemeBitmap != null && !_currentThemeBitmap.IsDisposed)
                    _currentThemeBitmap.Dispose();
                _currentThemeBitmap = Image.FromFile(cachedThemeBitmapPath);
            }
        }

        // External API integration for version control and logging
        var apiResponse = await _httpClient.PostAsJsonAsync("https://your-api-url.com/log-change", new { UserId = userId, ConfigurationName = configurationName, ConfigurationValue = configurationValue });
        if (!apiResponse.IsSuccessStatusCode)
            return false;

        return true;
    }

    private string GetCachedThemeBitmapPath(string configurationName) => Path.Combine(_cacheRootDirectory, $"{configurationName}.png");
}
