```cpp
#include <iostream>
#include <memory>
#include <vector>
#include <sstream>
#include <exception>
#include <thread>
#include <mutex>
#include <boost/serialization/access.hpp>
#include <boost/serialization/vector.hpp>
#include <boost/serialization/unique_ptr.hpp>
#include <blueslip/Blueslip.h>

class OctreeNode {
public:
    std::vector<std::unique_ptr<OctreeNode>> children;
    std::vector<std::vector<int>> data;
    bool isLeaf = true;

private:
    friend class boost::serialization::access;
    template<class Archive> void serialize(Archive& ar, const unsigned int version) {
        ar & children & data & isLeaf;
    }
};

class Octree {
public:
    Octree(int featureSize, int numInitialNodes, int maxCapacity);
    ~Octree();
    void insertPoint(const std::vector<float>& point);
    std::vector<int> queryPoints(const std::vector<float>& point) const;
    void clear();

private:
    std::unique_ptr<OctreeNode> root;
    int featureSize;
    int maxCapacity;
    mutable std::mutex mtx;
};

Octree::Octree(int featureSize, int numInitialNodes, int maxCapacity)
    : featureSize(featureSize), maxCapacity(maxCapacity) {
    if (featureSize <= 0 || maxCapacity <= 0) {
        throw std::invalid_argument("Feature size and maximum capacity must be positive.");
    }

    std::unique_ptr<OctreeNode> currentNode = std::make_unique<OctreeNode>();
    root = std::make_unique<OctreeNode>();
    currentNode->children.resize(8);

    std::thread thread([this, currentNode]() {
        for (int i = 0; i < numInitialNodes; ++i) {
            auto childIndex = rand() % 8;
            if (!currentNode->children[childIndex]) {
                currentNode->children[childIndex] = std::make_unique<OctreeNode>();
            }
            currentNode = currentNode->children[childIndex];
        }
    });

    thread.detach();
}

Octree::~Octree() {
    clear();
}

void Octree::insertPoint(const std::vector<float>& point) {
    std::unique_lock<std::mutex> lock(mtx);

    auto currentNode = root.get();
    int index = 0;
    for (size_t i = 0; i < 3; ++i) {
        float coord = point[i];
        if (coord >= currentNode->data[2 * index] && coord < currentNode->data[2 * index + 1]) {
            index |= 1 << i;
        } else {
            return; // Point is outside the bounding box, no need to continue.
        }
    }

    if (!currentNode->isLeaf) {
        for (auto& child : currentNode->children) {
            if (child) {
                currentNode = child.get();
                break;
            }
        }
        insertPoint(point);
        return;
    }

    int childIndex = index;
    auto newLeaf = std::make_unique<OctreeNode>();
    currentNode->children[childIndex] = std::move(newLeaf);
    currentNode->data.push_back({ point[0], point[1], point[2], point[3] });

    if (currentNode->data.size() > maxCapacity) {
        balanceNode(currentNode.get());
    }
}

std::vector<int> Octree::queryPoints(const std::vector<float>& point) const {
    std::unique_lock<std::mutex> lock(mtx);
    auto currentNode = root.get();

    int index = 0;
    for (size_t i = 0; i < 3; ++i) {
        float coord = point[i];
        if (coord >= currentNode->data[2 * index] && coord < currentNode->data[2 * index + 1]) {
            index |= 1 << i;
        }
    }

    std::vector<int> results;
    if (!currentNode->isLeaf) {
        for (const auto& child : currentNode->children) {
            if (child) {
                results.insert(results.end(), child->queryPoints(point).begin(), child->queryPoints(point).end());
            }
        }
    } else {
        for (auto dataPoint : currentNode->data) {
            if (point[0] >= dataPoint[0] && point[1] >= dataPoint[1] && point[2] >= dataPoint[2]) {
                results.push_back(dataPoint[3]);
            }
        }
    }

    return results;
}

void Octree::clear() {
    std::unique_lock<std::mutex> lock(mtx);
    root.reset();
}

void runModuleTests(const std::string& moduleName, int featureSize, int numInitialNodes, int maxCapacity) {
    try {
        Blueslip::initialize();
        std::cout << "Initializing " << moduleName << " module..." << std::endl;

        Octree octree(featureSize, numInitialNodes, maxCapacity);
        // Insert and query points here...

        Blueslip::finalize();
        std::cout << "Resetting Blueslip mocking library." << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error in " << moduleName << " module tests: " << e.what() << std::endl;
    }
}
