void registerAttack(int id, std::function<void(Character&)> action, int cooldown) {
    attacks[id] = std::make_pair(action, std::chrono::steady_clock::now());
}

void selectAttack(Character& character) {
    auto now = std::chrono::steady_clock::now();
    auto it = attacks.begin();
    for (; it != attacks.end(); ++it) {
        if (it->second.second + std::chrono::seconds(it->second.first.third) > now) continue;
        it->second.second = now;
        it->first(character);
        std::cout << "Selected attack: " << it->first << ", remaining cooldown time: " << (it->second.second + it->second.first.third - now).count() / 1000000000.0 << " seconds" << std::endl;
        return;
    }
    // Default action when all attacks are on cooldown.
    std::cout << "No attack available, performing default action." << std::endl;
}

// Example usage of registerAttack function:
void Attack1(Character& character) {
    std::cout << "Performing attack 1" << std::endl;
}

void Attack2(Character& character) {
    std::cout << "Performing attack 2" << std::endl;
}

void Attack3(Character& character) {
    std::cout << "Performing attack 3" << std::endl;
}

int main() {
    registerAttack(1, Attack1, 5);
    registerAttack(2, Attack2, 7);
    registerAttack(3, Attack3, 10);

    Character character;
    // Update the character's state here or through an external API call.

    while (true) {
        selectAttack(character);
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    return 0;
}
```

This code registers the attacks using a map and ensures that they are thread-safe by checking if the cooldown period has expired before executing each attack. It also provides a default action when all attacks are on cooldown and optimizes the function for high-frequency combat scenarios by using `std::this_thread::sleep_for` with a short sleep interval.

