int async_aggregate(const char** sources, const size_t count, Future** futures, const void* initial_dict,
                     void (*callback)(Future*, void*), Config config) {
    sem_init(&config.semaphore, 0, config.semaphore);
    CURLM *multi_handle = curl_multi_init();

    int num_completed = 0;
    bool has_failed = false;

    // Create and store futures for each source
    Future** completed_futures = malloc(count * sizeof(Future*));
    for (size_t i = 0; i < count; ++i) {
        // Handle external API calls with proper rate limiting and API rate limits
        CURL *curl_handle = ... // Initialize curl handle using the appropriate library function, setting up rate limiting

        Future* future = create_future(callback, &initial_dict);
        add_curl_perform_to_future(future, curl_handle);
        futures[i] = future;
        completed_futers[num_completed++] = future;
    }

    // Perform asynchronous operations and semaphore management
    while (num_completed < count && !has_failed) {
        int still_running = 0;
        CURLcode res = curl_multi_wait(multi_handle, config.semaphore);

        if (res == CURLM_CALL_MULTI_PERFORM) {
            // Handle individual API calls and semaphore release for completed operations
            for (int i = 0; i < num_completed; ++i) {
                Future* future = completed_futures[i];
                CURL* curl_handle = ... // Retrieve the curl handle associated with this future

                if (!future_is_done(future)) {
                    continue;
                }

                if (future_get_exception(future) != NULL) {
                    has_failed = true;
                    break;
                }

                callback(future, initial_dict);
                sem_post(&config.semaphore);
            }

            still_running = num_completed;
        } else if (res != CURLM_OK) {
            has_failed = true;
            break;
        }

        // Retry failed operations and update semaphore count based on the number of completed operations
        for (int i = 0; i < num_completed && !has_failed; ++i) {
            Future* future = completed_futures[i];

            if (!future_is_done(future)) {
                continue;
            }

            if (future_get_exception(future) != NULL) {
                int retries_left = config.retries - 1;

                if (retries_left <= 0 || time(NULL) - future_get_timestamp(future) < config.delay_ms * CLOCKS_PER_SEC / 1000) {
                    // Skip this failed operation and move on to the next one
                    continue;
                }

                // Reset the timestamp for this future and retry the operation
                future_set_timestamp(future, time(NULL));
                future_retry();
            }
        }
    }

    curl_multi_cleanup(multi_handle);
    sem_destroy(&config.semaphore);
    free(completed_futures);

    return has_failed ? 1 : 0;
}
