```csharp
public interface IConfigurationObserver
{
    void OnSettingsUpdated(GameSettings newSettings);
}

public class ConfigurationSubject : INotifyPropertyChanged
{
    private GameSettings _settings;
    public event PropertyChangedEventHandler PropertyChanged;

    public GameSettings Settings
    {
        get => _settings;
        set
        {
            if (_settings == value) return;
            _settings = value;
            OnPropertyChanged();
            NotifyObservers(_settings);
        }
    }

    private void NotifyObservers(GameSettings newSettings)
    {
        var handlers = _observers.ToArray();
        foreach (var observer in handlers)
        {
            observer.OnSettingsUpdated(newSettings);
        }
    }

    private readonly List<IConfigurationObserver> _observers = new List<IConfigurationObserver>();

    public void RegisterObserver(IConfigurationObserver observer)
    {
        _observers.Add(observer);
    }

    public void UnregisterObserver(IConfigurationObserver observer)
    {
        _observers.Remove(observer);
    }
}
```

