using System;
using System.IO;
using System.Threading;
using System.Diagnostics;
using System.Linq;
public class ProcessStarter
{
    private readonly Logger _logger;
    public ProcessStarter(Logger logger) { this._logger = logger; }

    public Process StartSite(string directoryPath, string siteName, string mode, string[] arguments = null)
    {
        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError(new DirectoryNotFoundException($"The specified directory does not exist: {directoryPath}"), "Failed to start the website.");
            return null;
        }

        var webConfigFile = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFile))
        {
            _logger.LogError(new FileNotFoundException($"The web.config file does not exist in the directory: {webConfigFile}"), "Failed to start the website.");
            return null;
        }

        var configManager = new ConfigurationManager();
        var settings = configManager.RetrieveSettings(siteName);

        // Integrate with an external configuration service here...

        var processStartInfo = new ProcessStartInfo
        {
            FileName = settings["executable"],
            WorkingDirectory = directoryPath,
            Arguments = string.Join(" ", arguments ?? Array.Empty<string>()),
            RedirectStandardOutput = true,
            UseShellExecute = false,
        };

        if (mode == "debug")
        {
            processStartInfo.Arguments += " --debug";
        }
        else if (mode == "release")
        {
            // Add release-specific arguments...
        }
        else
        {
            throw new ArgumentException("Invalid mode specified.", nameof(mode));
        }

        var process = new Process
        {
            StartInfo = processStartInfo
        };

        try
        {
            process.Start();
            var timeoutCts = new CancellationTokenSource();
            if (!process.WaitForExit(TimeSpan.FromMinutes(5)))
            {
                _logger.LogError(new TimeoutException("The website did not start within the specified time limit."), "Failed to start the website.");
                process.CloseMainWindow();
                timeoutCts.Cancel();
            }

            if (process.ExitCode != 0)
            {
                var errorMessage = process.StandardOutput.ReadToEnd();
                _logger.LogError(new Exception($"The website exited with an error code: {process.ExitCode}. Error message: {errorMessage}"), "Failed to start the website.");
                return null;
            }

            return process;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"An error occurred while starting the website: {siteName}. Retry attempt: {RetryAttempts}");
            if (RetryAttempts >= 3)
            {
                return null;
            }
            Thread.Sleep(1000); // Retry after 1 second
        }

        return StartSite(directoryPath, siteName, mode, arguments);
    }
}
