import re
from collections import defaultdict
import os
import sys
import time
import hashlib
import aiohttp

class LogParser:
    def __init__(self, log_file, api_url):
        self.log_file = log_file
        self.api_url = api_url
        self.ip_stats = defaultdict(lambda: {'requests': 0, 'total_time': 0, 'avg_time': 0})

    async def process_chunk(self, chunk):
        # Regex patterns to extract relevant HTTP request information
        ip_pattern = re.compile(r'\S+ \S+ \S+:\S+ \[\d{2}/\w{3} \d{4}: \d{2}:[0-9]{2}:[0-9]{2}')
        status_code_pattern = re.compile(r'HTTP/\d+\.\d+" (\d{3})')

        for line in chunk.split('\n'):
            try:
                ip, timestamp = line.split(' - ')
                ip_match = ip_pattern.search(ip)
                status_code_match = status_code_pattern.search(line)
                if ip_match and status_code_match:
                    self.ip_stats[ip_match.group(1)]['requests'] += 1
                    self.ip_stats[ip_match.group(1)]['total_time'] += time.strptime(timestamp, '%d/%b/%Y:%H:%M:%S') - time.gmtime()
                    self.ip_stats[ip_match.group(1)]['avg_time'] = self.ip_stats[ip_match.group(1)]['total_time'] / self.ip_stats[ip_match.group(1)]['requests']

                # Send aggregated statistics to external API in real-time
                if len(self.ip_stats) >= 50:
                    async with aiohttp.ClientSession() as session:
                        await self._send_stats(session)
            except Exception as e:
                print(f"Error while processing log chunk: {e}", file=open("error_log.txt", "a"))

    async def _send_stats(self, session):
        # Implement the logic to serialize and send data to external API here
        pass

    @staticmethod
    def read_file(file_path, chunk_size=1024*1024):
        with open(file_path, 'r') as f:
            chunks = []
            while True:
                data = f.read(chunk_size)
                if not data: break
                chunks.append(data)
            return '\n'.join(chunks)

    @staticmethod
    def run():
        parser = LogParser('large_log_file.log', 'https://your-api-url.com')
        chunked_log = LogParser.read_file('large_log_file.log')
        asyncio.run(parser._async_main(chunked_log))

    @staticmethod
    async def _async_main(chunked_log):
        chunks = await asyncio.gather(*[LogParser.process_chunk(chunk, parser) for chunk in [iter(chunked_log, '')]])

