const CACHE_TTL: u64 = 60 * 5; // Cache expires after 5 minutes

fn cache_weather_data(location: &str, weather_data: Value) -> Result<(), Box<dyn std::error::Error>> {
    let expiration_time = SystemTime::now() + Duration::from_secs(CACHE_TTL);
    cache.insert(location, (weather_data, expiration_time));
    Ok(())
}

fn get_cached_weather_data(location: &str) -> Option<(&Value, &SystemTime)> {
    cache.get(location).map(|(weather_data, expiration_time)| {
        if *expiration_time > SystemTime::now() {
            (weather_data, expiration_time)
        } else {
            cache.remove(location);
            None
        }
    })
}
```

This code snippet initializes a simple cache for weather data with a Time To Live (TTL) of 5 minutes. The `get_cached_weather_data()` function checks if the requested location is available in the cache, and returns the cached weather data if it has not expired yet. Otherwise, it removes the entry from the cache and returns None.

