# Rate limiting decorator
def rate_limited(limit=10, time=60):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if hasattr(args[0], 'rate_limits'):
                if datetime.now() > args[0].rate_limits + timedelta(minutes=time):
                    args[0].reset_ratelimit()
                    args[0].rate_limits = datetime.now()
                    if args[0].requests >= limit:
                                return {"error": "Rate limit exceeded.", "status_code": 429}, 429
            args[0].requests += 1
            return func(*args, **kwargs)
        return wrapper
    return decorator

class Resource:
