    hash_obj = hashlib.md5()
    with open(file_path, 'rb') as file:
        while True:
            data = file.read(8192)  # Adjust chunk size according to performance needs
            if not data:
                break
            hash_obj.update(data)
    return hash_obj.hexdigest()

