const semaphore = require('kamel-semaphore')(5); // Semaphore for concurrency control
const LRUCache = require('lru-cache'); // Cache for external API calls
const jwt = require('jsonwebtoken'); // Authentication library

// Load authentication token securely
const token = process.env.API_TOKEN;

// Custom Accumulator function (can handle synchronous and asynchronous operations)
function customAccumulator(acc, curr, callback) {
  // Perform a synchronous operation here...
  setTimeout(() => {
    // ... and an asynchronous one using a promise
    const result = someAsyncOperation(curr);
    result.then(res => callback(acc + res))
      .catch(err => callback({ error: err }));
  }, Math.random() * 1000);
}

// Function to fetch a valid JWT token
function getJwtToken() {
  return new Promise((resolve, reject) => {
    jwt.verify(token, (err, decoded) => {
      if (err) {
        reject(new Error('Invalid authentication token'));
      } else {
        resolve(decoded.token);
      }
    });
  });
}

// Cache for external API calls
const apiCache = new LRUCache({ max: 100, maxAge: 60 * 5 }); // 5 minutes cache duration

// Function to simulate an external API call that returns a promise
async function someAsyncOperation(number) {
  const token = await getJwtToken();

  // Fetch from cache if available or make the actual API call and store in cache
  let apiResult;
  if (apiCache.has(number)) {
    apiResult = apiCache.get(number);
  } else {
    const apiResponse = await fetch(`https://external-api.com/${number}`, { headers: { Authorization: `Bearer ${token}` } });
    apiResult = await apiResponse.json();
    apiCache.set(number, apiResult);
  }

  return apiResult;
}

// asyncArrayReduce function implementation
async function asyncArrayReduce(array, initialValue, callback) {
  let accumulatedValue = initialValue;

  // Handle the case when array is empty or undefined
  if (!Array.isArray(array)) throw new Error('The provided array must be an instance of Array');
  if (array.length === 0) return accumulatedValue;

  const promiseChain = array.map((num, index) => {
    // Throttling: delay the external API call based on a rate limiter function
    const delayMs = rateLimiter(index);

    return semaphore.acquire()
      .then(() => someAsyncOperation(num))
      .then((result) => customAccumulator(accumulatedValue, result, callback))
      .finally(() => semaphore.release());
  });

  await Promise.allSettled(promiseChain);

  return accumulatedValue;
}

// Rate limiter function (based on a simple delay)
function rateLimiter(index) {
  // Adjust the delay based on your specific needs, e.g., exponential backoff or token bucket algorithms
  const baseDelayMs = 1000; // 1 second
  return Math.floor((baseDelayMs * index) / promiseChain.length);
}
