using System;
using System.Collections.Concurrent;
using System.Xml;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Globalization;
using System.IO;
using System.Text.RegularExpressions;
using Newtonsoft.Json;
using System.Net.Http;
using Microsoft.Win32;

public class XmlReducer
{
    private readonly XPathDocument _xpathDoc;
    private readonly XmlNamespaceManager _nsManager;
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(5); // Adjust parallelism as needed
    private readonly HttpClient _httpClient;
    private readonly TimeSpan _timeout = TimeSpan.FromSeconds(10);
    private readonly string _authenticationToken;
    private readonly CultureInfo _culture;
    private readonly bool _validateSchema;
    private readonly Action<string, int, object> _onProgress;

    public XmlReducer(XmlReader reader, XPathNavigator root, XmlNamespaceManager nsManager, HttpClient httpClient, string authenticationToken, CultureInfo culture, bool validateSchema = false, Action<string, int, object> onProgress = null)
    {
        _xpathDoc = new XPathDocument(reader);
        _nsManager = nsManager;
        _httpClient = httpClient;
        _authenticationToken = authenticationToken;
        _culture = culture;
        _validateSchema = validateSchema;
        _onProgress = onProgress;
    }

    public async Task<dynamic> AsyncXmlReduce(string[] xPathExpressions, Func<XPathNavigator, object> accumulator, int parallelism = 5, double throttleRate = 1.0)
    {
        var tasks = new List<Task>();

        try
        {
            foreach (var expression in xPathExpressions)
            {
                string key = expression + _nsManager.GetNamespaceURI(_nsManager.Namespaces()[0].Key);
                object cachedResult;
                if (_cache.TryGetValue(key, out cachedResult))
                {
                    tasks.Add(Task.FromResult(cachedResult));
                }
                else
                {
                    var parsingTask = Task.Run(() => ParseAndCacheAsync(expression));
                    tasks.Add(parsingTask);
                }
            }

            await Task.WhenAll(tasks.Take(parallelism)).ConfigureAwait(false);

            dynamic accumulatedValue = accumulator(_xpathDoc.CreateNavigator());
            foreach (var task in tasks)
            {
                if (!task.IsFaulted)
                {
                    accumulatedValue = accumulator((XPathNavigator)task.Result);
                }
                else
                {
                    throw task.Exception;
                }
            }

            return accumulatedValue;
        }
        catch (AggregateException ex)
        {
            foreach (var innerException in ex.InnerExceptions)
            {
                Console.WriteLine($"Error: {innerException}");
            }
            throw;
        }
    }

    private async Task<object> ParseAndCacheAsync(string xPathExpression)
    {
        _semaphore.Wait();
        try
        {
            var navigator = _xpathDoc.CreateNavigator();
            var nodeList = navigator.Select(xPathExpression, _nsManager);

            if (nodeList.Count > 1)
            {
                throw new Exception($"Multiple matching nodes found for XPath expression: {xPathExpression}");
            }

            if (nodeList.Count == 0)
            {
                return null;
            }

            var node = nodeList[0];
            var xmlReader = node.ReadSubtree();
            var result = ValidateAndTransformXml(xmlReader);

            string key = xPathExpression + _nsManager.GetNamespaceURI(_nsManager.Namespaces()[0].Key);
            _cache[key] = result;

            if (_onProgress != null)
            {
                _onProgress($"Parsed XML using XPath expression: {xPathExpression}", 1, result);
            }

            return await CallExternalApiAsync(result).ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex}");
            throw;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private XmlReader ValidateAndTransformXml(XmlReader reader)
    {
        if (_validateSchema && File.Exists("schema.xsd"))
        {
            var schema = new XmlSchemaSet();
            schema.Add(XmlReader.Create("schema.xsd"));
            var validator = new XmlValidator(schema);
            reader.MoveToContent(); // Move the reader to content position
            if (!validator.Validate(reader))
            {
                throw new Exception("XML document is invalid against specified schema");
            }
        }

        // Add your custom transformations here, if needed

        return reader;
    }

    private async Task<object> CallExternalApiAsync(object data)
    {
        // Simulate an external API call within the callback function, which returns a promise.
        var apiCallTask = await Task.Run(() =>
        {
            var request = new HttpRequestMessage
            {
                Method = HttpMethod.Post,
                RequestUri = new Uri("https://your-api-url"),
                Content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json"),
                Headers =
                {
                    { "Authorization", $"Bearer {_authenticationToken}" }
                }
            };

            var throttleFactor = Math.Min(1.0, throttleRate * _httpClient.GetRequestCount());
            var delay = TimeSpan.FromMilliseconds((double)Math.Round(1000 / throttleFactor));
            await Task.Delay(delay);

            var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead);
            response.EnsureSuccessStatusCode();
            return JsonConvert.DeserializeObject(await response.Content.ReadAsStringAsync(), data.GetType());
        });

        // Handle promises appropriately to ensure the reduction process continues only after all external calls have completed.
        return await apiCallTask;
    }
}
