    int source_id;
    pthread_t thread_id;
    std::vector<std::pair<int, future<void*>>> futures;
    void* data;
} SourceData;

static LogMessage messages[1024];
static volatile size_t message_count = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t log_cond = PTHREAD_COND_INITIALIZER;
static double messages_per_second = 1000.0;
static clock_t last_log_time = 0;
static const int buffer_size = 1024;

void asyncLogCondition(enum Severity severity, const char* format, ...) {
    va_list args;
    va_start(args, format);

    // Create a LogMessage object and fill it with the formatted message
    snprintf(messages[message_count].timestamp, sizeof(messages[message_count].timestamp), "%.3f", time(NULL));
    vsnprintf(messages[message_count].message, sizeof(messages[message_count].message), format, args);
    messages[message_count].severity = severity;

    // Increment the message count and notify if it's time to log a new message
    message_count++;
    pthread_mutex_lock(&log_mutex);
    clock_t now = clock();
    double seconds_since_last_log = (now - last_log_time) / CLOCKS_PER_SEC;
    if(seconds_since_last_log >= 1.0 / messages_per_second) {
        last_log_time = now;
        for(size_t i = 0; i < message_count; i++) {
            printf("%s [%s] %s\n", messages[i].timestamp, severity_names[messages[i].severity], messages[i].message);
        }
        message_count -= (size_t)message_count / buffer_size;
    }
    pthread_mutex_unlock(&log_mutex);
    pthread_cond_signal(&log_cond);
    va_end(args);
}

void* mergeData(SourceData* data) {
    void** merged_data = malloc(sizeof(void*) * data->futures.size());
    for(auto& future : data->futures) {
        void* value = future.second.get();
        int source_id = future.first;
        int index = source_id % data->source_id;
        merged_data[index] = value;
    }
    data->data = merged_data;
    free(merged_data);
    return nullptr;
}

void processSource(SourceData* data) {
    if(!data || !data->source_id) return;

    for(auto& future : data->futures) {
        auto promise = std::move(future.second);
        promise.then([data](void* value) { processSource(data); });
    }

    pthread_mutex_lock(&log_mutex);
    if(message_count >= buffer_size) {
        pthread_cond_wait(&log_cond, &log_mutex);
    }
    asyncLogCondition(INFO, "Source %d processed.\n", data->source_id);
    pthread_mutex_unlock(&log_mutex);
}

void addFuture(SourceData* data, int source_id, future<void*> promise) {
    data->futures.push_back({source_id, std::move(promise)});
}
