struct Word {
    char* word;
    struct Word* next;
};

sem_t semaphore;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int total_length = 0;
int limit = 0;
char* result = NULL;

void fetchWords(const char* url) {
    // Implement system dependencies for fetching the word list from an external API
}

void processWord(struct Word* word) {
    size_t len = strlen(word->word);
    if (total_length + len > limit) return;

    total_length += len;

    // Trim the word and capitalize the first letter
    char* new_word = malloc(len + 1);
    strncpy(new_word, word->word + 1, len - 2);
    new_word[len - 1] = toupper(*new_word);
    new_word[len] = '\0';

    // Add the processed word to the result string and free the old word memory
    if (result) {
        strcat(result, " ");
        strcat(result, new_word);
    } else {
        result = malloc(sizeof(char) * total_length + 1);
        strcpy(result, new_word);
    }

    free(new_word);
    free(word->word);
    free(word);
}

void* fetchAndProcessWords(void* arg) {
    const char* url = (const char*)arg;
    struct Word* words = NULL;
    fetchWords(url);

    pthread_mutex_lock(&mutex);
    struct Word* current = words;
    while (current != NULL) {
        struct Word* next = current->next;
        processWord(current);
        current = next;
    }
    pthread_mutex_unlock(&mutex);

    // Free the memory of the fetched words and return
    struct Word* temp;
    while (words != NULL) {
        temp = words->next;
        free(words->word);
        free(words);
        words = temp;
    }

    return NULL;
}

char* dynamicTrimAndCapitalize(const char* input, const char* url) {
    if (!input || !url) return NULL;

    // Calculate the average word length and adjust the size limit accordingly
    int total_words = 1; // Count the input words as well
    for (char* ptr = input; *ptr != '\0'; ptr = strchr(ptr + 1, ' ')) {
        ++total_words;
    }
    double average_word_length = strlen(input) / total_words;
    limit = (total_words + 1) * average_word_length + 10; // Account for spaces and potential truncation

    sem_init(&semaphore, SEMAPHORE_COUNT, SEMAPHORE_COUNT);

    pthread_t threads[SEMAPHORE_COUNT];
    for (int i = 0; i < SEMAPHORE_COUNT; ++i) {
        if (pthread_create(&threads[i], NULL, fetchAndProcessWords, url) != 0) return NULL;
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < SEMAPHORE_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }
    pthread_mutex_unlock(&mutex);

    sem_destroy(&semaphore);

    if (result) return result;
    free(result);
    return NULL;
}
