const axios = require('axios');

const asyncArrayReduce = async (arr, initialValue, callback) => {
  const semaphore = new Semaphore(concurrencyLimit); // Concurrency limit variable

  let accumulator = initialValue;
  for (let i = 0; i < arr.length; i++) {
    await semaphore.acquire();
    axios.get(`https://api.example.com/data/${arr[i]}`, { headers: { Authorization: 'Bearer ${token}' } })
      .then(response => {
        response.data.then(data => callback(accumulator, data))
          .catch(error => console.error(`Error fetching data for ${arr[i]}:`, error));
      })
      .catch(error => console.error(`Error fetching data from API:`, error));
    semaphore.release();
  }
};

// Semaphore implementation (you can use a library such as 'semaphore-async-await' for better performance)
class Semaphore {
  constructor(concurrencyLimit) {
    this.limit = concurrencyLimit;
    this.queue = [];
  }

  acquire() {
    return new Promise((resolve, reject) => {
      if (this.limit > 0) {
        --this.limit;
        resolve();
      } else {
        this.queue.push(() => {
          ++this.limit;
          resolve();
        });
      }
    });
  }

  release() {
    if (this.queue.length > 0) {
      const callback = this.queue.shift();
      callback();
    } else {
      --this.limit;
    }
  }
}
