```python
import requests
import time
import json
from xml.etree import ElementTree as ET
import csv
import os
import zipfile
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import urljoin, urlparse
from schematics import Validator, Model, SchemaError
from bottleneck import RateLimiter
from datetime import datetime
from pathlib import Path

class DataFetchError(Exception):
    pass

def fetch_and_process_data(url, data_formats, max_concurrent=5, request_timeout=10, base_dir='downloads', schema_validator=None, disk_space_limit=None, rate_limiter=None):
    log = print
    start_time = datetime.now()

    downloaded_files = set()
    url_queue = [(url, data_format) for data_format in data_formats]

    executor = ThreadPoolExecutor(max_workers=max_concurrent)

    def fetch_and_process(url, data_format):
        try:
            if rate_limiter and not rate_limiter.sleep():
                raise DataFetchError("Rate limit exceeded")

            response = requests.get(url, timeout=request_timeout)
            response.raise_for_status()

            file_path = os.path.join(base_dir, f'{datetime.now().strftime("%Y%m%d-%H%M%S")}.{data_format}')
            with open(file_path, 'wb') as f:
                if data_format == 'zip':
                    z = zipfile.ZipFile(f)
                    z.write(response.content)
                    z.close()
                else:
                    f.write(response.content)

            downloaded_files.add((url, data_format, file_path))
            log(f"Downloaded {data_format} from {url}")

            if schema_validator:
                validate_data(file_path, schema_validator)

            if disk_space_limit and len(downloaded_files) > disk_space_limit:
                for _ in downloaded_files:
                    os.remove(_[2])
                log(f"Deleted {len(downloaded_files)} files to maintain disk space limit")

            return file_path
        except (requests.exceptions.RequestException, DataFetchError) as e:
            log(f"Failed to download data from {url}: {e}")
            time.sleep(2 ** (failed_attempts[url] + 1))
            return None

    failed_attempts = {}
    processed_urls = set()

    def process_subpages(page_url):
        for link in page_url.cssselect("a"):
            href = link.get("href")
            if href and not href in processed_urls:
                processed_urls.add(href)
                url_queue.append((urljoin(page_url, href), data_formats[0]))

    while url_queue or any(processed_urls):
        url, data_format = url_queue.pop(0) if url_queue else None

        if not url:
            log("No more URLs to process")
            break

        page_url = URL(url)
        if page_url.scheme not in ('http', 'https'):
            log(f"Invalid URL: {url}")
            continue

        if page_url.url in processed_urls:
            continue

        processed_urls.add(page_url.url)

        try:
            response = requests.head(url, timeout=request_timeout)
            response.raise_for_status()
        except requests.exceptions.RequestException as e:
            log(f"Failed to head {url}: {e}")
            failed_attempts[page_url.url] = failed_attempts.get(page_url.url, 0) + 1
            continue

        if failed_attempts[page_url.url] >= 3:
            log(f"Giving up on {page_url.url} after 3 failures")
            continue

        process_subpages(page_url)

        if not data_format:
            for data_format in data_formats:
                file_path = fetch_and_process(page_url, data_format)
                if file_path:
                    break

def validate_data(file_path, schema_validator):
    with open(file_path) as f:
        data = json.load(f) if file_path.endswith('.json') else ET.parse(f).getroot()

    try:
        schema_validator.validate(data)
    except SchemaError as e:
        raise DataFetchError(f"Invalid data format in {file_path}: {e}")

class URL:
    def __init__(self, url):
        self.url = url
        self.scheme = urlparse(url).scheme
```

