const axios = require('axios');
const dotenv = require('dotenv');
const qs = require('qs');
const nodemailer = require('nodemailer');
const jwt = require('jsonwebtoken');
const { v4: uuidv4 } = require('uuid');
require('dotenv').config();

// Set up constants and configurations
const API_RATE_LIMIT = parseInt(process.env.API_RATE_LIMIT) || 10; // Maximum number of API calls per minute
const API_RETRY_DELAY = parseInt(process.env.API_RETRY_DELAY) || 5000; // Milliseconds to wait before retrying an API call
const ACCESS_TOKEN_MEMORY_KEY = 'accessToken';
const LOGGER = console; // Use a proper logger library for production

// Initialize storage for access tokens and payment details
let storedAccessTokens = {};
let storedPaymentDetails = {};

async function authenticateUser(code) {
  // Replace with your OAuth 2.0 provider URL
  const authUrl = 'https://your-oauth-provider.com/authorize';
  // Replace with your OAuth 2.0 client ID and secret
  const clientId = process.env.OAUTH_CLIENT_ID;
  const clientSecret = process.env.OAUTH_CLIENT_SECRET;
  const tokenUrl = 'https://your-oauth-provider.com/token';

  try {
    const response = await axios.post(tokenUrl, qs.stringify({
      grant_type: 'authorization_code',
      client_id: clientId,
      client_secret: clientSecret,
      code: code,
      redirect_uri: process.env.OAUTH_REDIRECT_URI
    }));

    const accessToken = response.data.access_token;
    storedAccessTokens[uuidv4()] = accessToken; // Store the access token securely in memory

    LOGGER.info('User authenticated successfully');
    return accessToken;
  } catch (error) {
    LOGGER.error(`Failed to authenticate user: ${error}`);
    throw error;
  }
}

async function verifyTransaction(accessToken, orderId) {
  try {
    const headers = { Authorization: `Bearer ${accessToken}` }; // Use the stored access token for API calls
    const response = await axios.get(`${API_ENDPOINT}/transactions/${orderId}`, { headers });

    if (!response.data || !response.data.status) {
      throw new Error('Transaction not found or invalid status');
    }

    storedPaymentDetails[uuidv4()] = response.data; // Store the payment details securely in memory
    return response.data;
  } catch (error) {
    handleError(error);
    if (shouldRetry(error)) {
      await sleep(API_RETRY_DELAY);
      return verifyTransaction(accessToken, orderId); // Recursively retry the API call if necessary
    }
    throw error;
  }
}

function shouldRetry(error) {
  const retryAfter = parseInt(error.headers['retry-after']) || 0;
  return retryAfter > 0 && Date.now() < error.response.data.rateLimitResetAt;
}

async function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function handleError(error) {
  LOGGER.error(`API Error: ${error}`);
  const transporter = nodemailer.createTransport({
    host: process.env.EMAIL_HOST,
    port: process.env.EMAIL_PORT,
    auth: {
      user: process.env.EMAIL_USER,
      pass: process.env.EMAIL_PASS
    }
  });

  const mailOptions = {
    from: process.env.EMAIL_FROM,
    to: process.env.EMAIL_TO,
    subject: 'API Error',
    text: `Error details: \n\n${error.stack}`
  };

  transporter.sendMail(mailOptions, (error, info) => {
    if (error) {
      LOGGER.error(`Failed to send error email: ${error}`);
    } else {
      LOGGER.info(`Error email sent: ${info.response}`);
    }
  });
}

// Replace with your payment gateway API endpoint
const API_ENDPOINT = 'https://your-payment-gateway-api.com';

module.exports = { authenticateUser, verifyTransaction };
