```c
#include <stdio.h>
#include <jansson.h>

bool is_valid_oauth2_token(const char *token_str) {
    json_t *root, *access_token, *expires_in, *token_type, *refresh_token;
    const char *token_type_str;
    int expires_in_val;

    root = json_loads(token_str, 0, NULL);
    if (!root || !json_is_object(root)) {
        return false;
    }

    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");
    refresh_token = json_object_get(root, "refresh_token");

    if (!access_token || !json_is_string(access_token) ||
        !expires_in || !json_is_number(expires_in) ||
        !token_type || !json_is_string(token_type)) {
        return false;
    }

    token_type_str = json_string_value(token_type);
    if (strcmp(token_type_str, "Bearer") != 0) {
        return false;
