  using IpPort = std::pair<std::string, int>;
  SemaphoreManager(const IpPort& server_ip_port)
      : io_service_(boost::asio::io_service()),
        semaphores_mutex_(),
        server_(server_ip_port, io_service_) {
    start();
  }

