    if (sem == SEM_FAILED) {
      LOG(error) << "Failed to create semaphore: " << strerror(errno);
      throw std::runtime_error("Semaphore creation failed");
    }
    return sem;
  }

  void deleteSemaphore(const std::string& name) {
    sem_t* sem = sem_open(name.c_str(), O_RDONLY);
    if (sem == SEM_FAILED) {
      LOG(error) << "Failed to open semaphore for deletion: " << strerror(errno);
      throw std::runtime_error("Semaphore deletion failed");
    }
    sem_close(sem);
    sem_unlink(name.c_str());
  }

