    BibleTextAnalyzer.factories[id] = Creator;
  }

  static create(id) {
    if (!BibleTextAnalyzer.factories[id]) throw new Error(`No factory registered for ID: ${id}`);

    return BibleTextAnalyzer.factories[id]();
  }
}

