namespace EncryptionService
{
    public class AuthenticationService
    {
        private const string Key = "[YOUR_SECRET_KEY]";
        private const string IV = "[YOUR_SECRET_IV]";

        private TripleDESCryptoServiceProvider _tripleDES;
        private HMACSHA256 _hmacSHA256;

        public AuthenticationService()
        {
            _tripleDES = new TripleDESCryptoServiceProvider();
            _hmacSHA256 = new HMACSHA256(Encoding.UTF8.GetBytes(Key));
        }

        public string DecryptAndValidateMessage(string base64EncodedMessage)
        {
            if (!IsBase64Valid(base64EncodedMessage))
            {
                throw new ArgumentException("Invalid Base64 encoding.");
            }

            var decryptedData = Decrypt(base64EncodedMessage);

            var hmacHash = GetHMACSHA256Hash(decryptedData);
            var expectedHMAC = decryptedData.Substring(decryptedData.Length - 64);

            if (!hmacHash.Equals(expectedHMAC))
            {
                throw new AuthenticationException("Invalid HMAC signature.");
            }

            return Encoding.UTF8.GetString(decryptedData, 0, decryptedData.Length - 64);
        }

        private bool IsBase64Valid(string base64EncodedMessage)
        {
            // Implement your Base64 validation logic here
        }

        private byte[] Decrypt(string base64EncodedMessage)
        {
            var encryptedData = Convert.FromBase64String(base64EncodedMessage);
            _tripleDES.Key = Encoding.UTF8.GetBytes(Key);
            _tripleDES.IV = Encoding.UTF8.GetBytes(IV);
            var decryptor = _tripleDES.CreateDecryptor();
            return decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
        }

        private byte[] GetHMACSHA256Hash(byte[] data)
        {
            _hmacSHA256.Init(new SHA256Managed());
            return _hmacSHA256.ComputeHash(data);
        }
    }

    public class AuthenticationException : Exception
    {
        public AuthenticationException() { }
