const chai = require('chai');
const fs = require('fs-extra');
const FileSystem = require('./FileSystem');
const expect = chai.expect;

describe('FileSystem', () => {
  it('should return an empty string for an empty directory', (done) => {
    const fileSystem = new FileSystem({ recursive: false });
    const dirPath = './test/empty_directory';

    fs.remove(dirPath)
      .then(() => fs.mkdirs(dirPath))
      .then(() => fileSystem.readDirectoryFiles(dirPath, (err, content) => {
        expect(content).to.equal('');
        done();
      }));
  });
