    async def _handle_failure(exception):
        self.logger.error(f'Test failed with error: {exception}')
        raise exception

    def _sanitize_input(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Validate and sanitize input here before performing operations
            return func(*args, **kwargs)
        return wrapper

