            self._cache_config(config_label, config_data)

            data = {}
            for data_source_label, func in zip(data_source_labels, test_functions):
                data[data_source_label] = await self._fetch_data(data_source_label)

            results = []
            for i, (test_function, data_source_label) in enumerate(zip(test_functions, data_source_labels)):
                async def wrapper():
                    try:
                        result = await self._run_test_Async(test_function, config_data, data[data_source_label])
                        results.append((result, f'{module_label}_{config_labels[i]}_{data_source_labels[i]}'))
                    except Exception as e:
                        results.append((await self._handle_failure(e), f'{module_label}_{config_labels[i]}_{data_source_labels[i]} (failed)'))

            await self._execute_cleanup_functions(cleanup_functions)
            for result, label in results:
                print(f'Test result for {label}: {result}')
