}

class WeaknessDetector {
    private static final Map<String, Map<String, Integer>> WEAKNESS_DATA = new HashMap<>();

    public String getWeaknesses(Pokemon pokemon) {
        Map<String, Integer> weaknesses = getWeaknessesFromDatabase(pokemon.getType());
        if (!weaknesses.isEmpty()) {
            return formatWeaknesses(weaknesses);
        } else {
            ApiClient apiClient = // Initialize and configure your API client here
            Pokemon pokemonDetails = apiClient.getPokemonDetails("https://api.example.com/pokemon/" + pokemon.getName());
            if (pokemonDetails != null) {
                weaknesses = getWeaknessesFromDatabase(pokemonDetails.getType());
                if (!weaknesses.isEmpty()) {
                    return formatWeaknesses(weaknesses);
                } else {
                    WEAKNESS_DATA.computeIfAbsent(pokemon.getType(), k -> fetchDefaultWeaknessData()).getOrDefault("Unknown", 0).let(this::formatWeaknesses);
                }
            } else {
                return "Failed to retrieve Pokemon details from the API.";
            }
        }
    }

    private Map<String, Integer> getWeaknessesFromDatabase(String pokemonType) {
        Database database = // Initialize and configure your database connection here
        try (Connection connection = database.getConnection()) {
            Statement statement = connection.createStatement();
            ResultSet resultSet = statement.executeQuery("SELECT weakness, strength FROM weaknesses WHERE pokemon_type = '" + pokemonType + "'");
            Map<String, Integer> weaknesses = new HashMap<>();
            while (resultSet.next()) {
                weaknesses.put(resultSet.getString("weakness"), resultSet.getInt("strength"));
            }
            return weaknesses;
        } catch (SQLException e) {
            // Log the error and provide a fallback mechanism if necessary
            return new HashMap<>();
        }
    }

    private String formatWeaknesses(Map<String, Integer> weaknesses) {
        StringBuilder result = new StringBuilder();
        for (Map.Entry<String, Integer> entry : weaknesses.entrySet()) {
            result.append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
        }
        return result.toString();
    }
}
