            let _ = cache.write().unwrap().insert(city, CurrentWeather { /* populate the struct */ });
        }
        data
    }).timeout(std::time::Duration::from_secs(5)).await?;

    let forecast_task = spawn_blocking(move || get_forecast(&api, city).unwrap());

    // Wait for both tasks to complete and display the data
    let current_weather = current_weather_task?.unwrap();
    let forecast = forecast_task?.unwrap();

    println!("Current weather for {}:", city);
    println!("{}", serde_json::to_string(&current_weather).unwrap());
    println!("\nForecast for next 24 hours:");
    println!("{}", serde_json::to_string(&forecast).unwrap());
}
