```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <zlib.h>

#define BUF_SIZE 1024

typedef struct {
    FILE *input;
    gzFile zinput;
    int compress;
    char *output;
} FileData;

void parse_options(int argc, char **argv, FileData *data);
int open_file(char *filename, FileData *data);
void close_file(FILE *file, gzFile zfile, FileData *data);
size_t readline(FileData *data);
void print_usage();

int main(int argc, char **argv) {
    FileData data = {NULL};
    parse_options(argc, argv, &data);

    size_t total_lines = 0;
    for (int i = optind; i < argc; ++i) {
        if (!open_file(argv[i], &data)) return 1;

        size_t lines_in_this_file = 0;
        while ((lines_in_this_file = readline(&data))) {
            total_lines += lines_in_this_file;
        }

        close_file(data.input, data.zinput, &data);
    }

    if (data.output && total_lines > 0) {
        FILE *output = fopen(data.output, "w");
        if (!output) return 1;

        fprintf(output, "%lu\n", total_lines);
        fclose(output);
    } else {
        printf("%lu\n", total_lines);
    }

    return 0;
}

void parse_options(int argc, char **argv, FileData *data) {
    int c;
    const char *const short_opts = "cdo:";
    const struct option long_opts[] = {
        {"compress", no_argument, NULL, 'c'},
        {"decompress", no_argument, NULL, 'd'},
        {"output", required_argument, NULL, 'o'},
        {0}
    };

    while ((c = getopt_long(argc, argv, short_opts, long_opts, NULL)) != -1) {
        switch (c) {
            case 'c': data->compress = 1; break;
            case 'd': data->compress = -1; break;
            case 'o': data->output = optarg; break;
            default: print_usage(); exit(EXIT_FAILURE);
        }
    }
}

int open_file(char *filename, FileData *data) {
    FILE *input = fopen(filename, "r");
    if (!input) return 0;

    data->input = input;
    if (data->compress > 0) {
        gzFile zinput = gzopen(filename, data->compress ? "rb" : "w");
        if (!zinput) {
            fclose(input);
            return 0;
        }
        data->zinput = zinput;
    }
    return 1;
}

void close_file(FILE *file, gzFile zfile, FileData *data) {
    if (zfile) gzclose(zfile);
    fclose(data->input);
    data->input = NULL;
    data->zinput = NULL;
}

size_t readline(FileData *data) {
    char buf[BUF_SIZE];
    size_t bytes_read, line_len = 0;

    while ((bytes_read = fread(buf, sizeof(char), BUF_SIZE - 1, data->input)) > 0) {
        if (data->compress > 0 && (bytes_read = gzinflate(data->zinput, buf, bytes_read) != bytes_read)) break;

        for (size_t i = 0; i < bytes_read; ++i) {
            if (buf[i] == '\n') break;
            if (line_len >= BUF_SIZE - 1) return UINT64_MAX; // Avoid buffer overflow
            buf[line_len++] = buf[i];
        }
    }

    return line_len > 0 ? line_len : UINT64_MAX;
}

void print_usage() {
    printf("Usage: ccount [options] <file1> [...]\n"
           "Options:\n"
           "-c         Compress input files before processing\n"
           "-d         Decompress input files after processing\n"
           "-o <output> Redirect output to a specified file\n");
}
```

This code assumes the presence of zlib for compression/decompression support. It should be compiled with `gcc -o ccount ccount.c -lz`. The usage information and error handling have been implemented as requested.

