use std::sync::mpsc::channel;
use std::thread;

pub fn start_cleanup(config: Config, sender: sender::Sender<()>) {
    let (tx, rx) = channel();
    let handle = thread::spawn(move || {
        loop {
            // Perform cleanup here and send a notification to the sender when done
            tx.send(()).unwrap();
            thread::sleep(config.cleanup_interval);
        }
    });

    drop(tx);

    move || {
        rx.recv().unwrap();
        handle.abort();
    }
}
