            }
        }

        var taskCompletionSource = new TaskCompletionSource<DataTableReader>();
        TcpClient client;
        DataTableReader result;

        _retryTimer?.Change(Timeout.Infinite, Timeout.Infinite); // Stop any current retry timer

        Func<Task> retryAction = async () =>
