                    result = await PacketHandler.ReadResultAsync(networkStream);
                }
            }
            catch (SocketException ex)
            {
                if (_retryTimer == null || _retryTimer.Change(Math.Pow(2, _retryAttempts), Timeout.Infinite) <= 0)
                    _retryTimer = new Timer(RetryAction, this);
                if (++_retryAttempts > 3)
                    taskCompletionSource.SetResult(null); // Error code or Exception object for maximum retries reached
            }
            catch (Exception ex)
            {
                // Log the error and handle it appropriately
                taskCompletionSource.SetResult(null); // Error code or Exception object
            }
        };

        _retryAttempts = 0;
        _retryTimer = new Timer(RetryAction, this);
        await retryAction();

        if (result == null)
            return null; // Error code or Exception object

        callback(result); // Call the provided callback function with the result
        return taskCompletionSource.Task.Result;
    }

    private static int _retryAttempts = 0;
}
