```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.*;
import java.math.BigInteger;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

public class FileHashService {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileHashService.class);

    private ExecutorService executor;
    private ConcurrentHashMap<String, Object> cache;
    private int maxThreads;
    private int maxCacheSize;
    private long timeoutMillis;
    private FileSystemWatcher watcher;

    public FileHashService(int maxThreads, int maxCacheSize, long timeoutMillis) {
        this.maxThreads = maxThreads;
        this.maxCacheSize = maxCacheSize;
        this.timeoutMillis = timeoutMillis;
        executor = Executors.newFixedThreadPool(maxThreads);
        cache = new ConcurrentHashMap<>(maxCacheSize);
        watcher = new FileSystemWatcher();
    }

    public void start() {
        watcher.start();
    }

    public void stop() throws InterruptedException {
        watcher.stop();
        executor.shutdownNow();
        if (!executor.awaitTermination(30, TimeUnit.SECONDS)) {
            LOGGER.warn("Timed out while shutting down executor");
        }
    }

    public void addWatchFolder(Path folder) throws IOException {
        watcher.addWatch(folder);
    }

    public String computeMD5(String filePath) {
        Object cacheKey = getCacheKey(filePath);
        if (cache.containsKey(cacheKey)) {
            return (String) cache.get(cacheKey);
        }
        Callable<String> task = () -> computeMD5Task(filePath);
        try {
            Future<String> future = executor.submit(task);
            String result = future.get(timeoutMillis, TimeUnit.MILLISECONDS);
            if (result != null) {
                cache.putIfAbsent(cacheKey, result);
            }
            return result;
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            LOGGER.error("Error computing MD5 hash for {}: {}", filePath, e.getMessage());
            return null;
        } catch (IOException e) {
            LOGGER.error("Invalid or unreachable file path: {}", filePath);
            return null;
        }
    }

    private Object getCacheKey(String filePath) {
        return MD5.asHexa(filePath).substring(0, 8);
    }

    // Implement the computeMD5Task and other required methods here.
}
```

This code creates a `FileHashService` that uses an executor service for non-blocking thread pools, a concurrent hashmap for caching, a file system watcher to detect changes in files, and SLF4J for logging. The maximum number of threads, cache size, and timeout can be configured via constructor parameters.

