    public async Task ExecuteDatabaseOperationWithRetry(byte[] data, string connectionString)
    {
        if (!IsValidConnectionString(connectionString))
            throw new ArgumentException("Invalid connection string.", nameof(connectionString));

        var connectionAttempts = 0;
        while (connectionAttempts < 3 && !IsConnected(connectionString))
        {
            try
            {
                await ConnectAndExecuteDatabaseOperationAsync(data, connectionString);
                return;
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Failed to connect to the database.");
                connectionAttempts++;
                await Task.Delay(_exponentialBackoff * connectionAttempts, CancellationToken.None);
            }
        }

        // If we've exhausted retries, log the error and throw an exception.
        _logger.Error("Exceeded maximum retry attempts.");
        throw new Exception("Could not connect to the database after three attempts.");
    }

