class DESCipher : public Cipher {
public:
    std::string encrypt(const std::string& plainText, const std::string& key) {
        CryptoPP::DES_ECB::Encryption ecb;
        CryptoPP::StringSource sss(plainText, true, new CryptoPP::HexEncoder(new CryptoPP::StringSink(cipherText)));
        ecb.ProcessBlocks(sss, new CryptoPP::StringSink(cipherText));
        return cipherText;
    }

    std::string decrypt(const std::string& encryptedText, const std::string& key) {
        CryptoPP::DES_ECB::Decryption ecb;
        CryptoPP::StringSource sss(encryptedText, true, new CryptoPP::HexDecoder(new CryptoPP::StringSink(plainText)));
        ecb.ProcessBlocks(sss, new CryptoPP::StringSink(plainText));
