    std::string encrypt(const std::string& plainText, const std::string& key) {
        CryptoPP::DES_CFB::Encryption ecfb;
        CryptoPP::StringSource sss(plainText, true, new CryptoPP::HexEncoder(new CryptoPP::StringSink(cipherText)));
        CryptoPP::MemorySource mms(iv_, iv_.size(), new CryptoPP::StreamTransformationFilter(ecfb, new CryptoPP::HexEncoder(new CryptoPP::StringSink(iv_))));
        ecfb.SetKeyWithIV(CryptoPP::HexDecoder(key), iv_);
        ecfb.ProcessBlocks(sss, mms);
        return cipherText;
    }

    std::string decrypt(const std::string& encryptedText, const std::string& key) {
        CryptoPP::DES_CFB::Decryption ecfb;
        CryptoPP::StringSource sss(encryptedText, true, new CryptoPP::HexDecoder(new CryptoPP::StringSink(cipherText)));
        CryptoPP::MemorySource mms(iv_, iv_.size(), new CryptoPP::StreamTransformationFilter(ecfb, new CryptoPP::HexEncoder(new CryptoPP::StringSink(iv_))));
        ecfb.SetKeyWithIV(CryptoPP::HexDecoder(key), iv_);
        ecfb.ProcessBlocks(sss, mms);
        std::string decryptedText = cipherText;
        cipherText.resize(0);
        return decryptedText;
    }

