import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ChatMessageProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(ChatMessageProcessor.class);

    private final KafkaProducer<String, JsonObject> kafkaProducer;
    private final Jedis redisClient;
    private final ConcurrentHashMap<String, User> users;
    private final ConcurrentHashMap<String, Room> rooms;
    private final ReadWriteLock userLock = new ReentrantReadWriteLock();
    private final ReadWriteLock roomLock = new ReentrantReadWriteLock();

    public ChatMessageProcessor() {
        Properties kafkaProps = new Properties();
        // Set your Kafka properties here

        this.kafkaProducer = new KafkaProducer<>(kafkaProps);
        this.redisClient = new Jedis("localhost");

        this.users = new ConcurrentHashMap<>();
        this.rooms = new ConcurrentHashMap<>();
    }

    public void processMessage(String userId, String roomId, String message) {
        if (!validateUser(userId)) {
            LOGGER.error("Invalid user ID: {}", userId);
            return;
        }

        if (!validateRoom(roomId)) {
            LOGGER.error("Invalid room ID: {}", roomId);
            return;
        }

        synchronized (userLock) {
            User user = users.get(userId);
            if (user == null || !user.canSendMessage()) {
                LOGGER.warn("User {} throttled or not found", userId);
                return;
            }
        }

        synchronized (roomLock) {
            Room room = rooms.get(roomId);
            if (room == null) {
                // Handle the creation of a new room here
                room = new Room(roomId);
                rooms.put(roomId, room);
            }
        }

        room.addMessage(message);

        JsonObject messageObj = new JsonObject();
        messageObj.addProperty("userId", userId);
        messageObj.addProperty("roomId", roomId);
        messageObj.addProperty("message", message);

        ProducerRecord<String, JsonObject> producerRecord = new ProducerRecord<>("chat-topic", messageObj);
        this.kafkaProducer.send(producerRecord, (metadata, exception) -> {
            if (exception != null) {
                LOGGER.error("Error sending message to Kafka: {}", exception.getMessage());
                retrySendMessage(producerRecord);
            } else {
                LOGGER.debug("Message sent successfully to Kafka: {} - {}", metadata.topic(), metadata.offset());
            }
        });
    }

