#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t nfalist_mutex = PTHREAD_MUTEX_INITIALIZER;

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules) {
    if (num_structures <= 0 || nfalist == NULL || crc_flag_rules == NULL) {
        // Handle error cases gracefully
        return -1;
    }

    *nfalist = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*nfalist == NULL) {
        // Handle memory allocation error
        return -1;
    }

    int *unique_tags = (int *)calloc(num_structures, sizeof(int));

    if (unique_tags == NULL) {
        free(*nfalist);
        // Handle memory allocation error
        return -1;
    }

    for (int i = 0; i < num_structures; ++i) {
        pthread_mutex_lock(&nfalist_mutex);

        (*nfalist)[i].rx_ue_information_tag = unique_tags[i]++;
        (*nfalist)[i].rnti = (RNTI)i; // Assuming RNTI is an integer type
        (*nfalist)[i].crc_indication_rel8_tag.crcflag = crc_flag_rules[i % array_length(crc_flag_rules)];

        log_structure_creation((*nfalist)[i]);

        pthread_mutex_unlock(&nfalist_mutex);
    }

    free(unique_tags);
    return 0;
}

int read_and_find_max(int *array, int *max) {
    if (array == NULL || max == NULL) {
        // Handle error cases gracefully
        return -1;
    }

    int size = array_size(array);
    if (size <= 0) {
        // Handle empty array case gracefully
        *max = 0;
        return 0;
    }

    for (int i = 0; i < size; ++i) {
        if (array[i] > *max) {
            *max = array[i];
        }
    }

    printf("The largest integer is: %d\n", *max);
    return 0;
}
```

