#include <stdbool.h>
#include <ctype.h>
#include <spell-checking-api/spell_checker.h> // Replace with the actual header for your spell checking API

char* trimAndCapitalize(char* str, size_t limit, char** words, size_t num_words) {
    if (!str || !words) return NULL;

    size_t str_len = strlen(str);
    size_t trimmed_len = 0;
    for (size_t i = 0; i < num_words; ++i) {
        const char* word = words[i];
        if (!word) continue;
        trimmed_len += strspn(str, word); // Count the number of characters from 'str' that match the current word
    }
    char* trimmed_str = malloc(strlen(str) - trimmed_len * num_words + 1);
    if (!trimmed_str) return NULL;
    snprintf(trimmed_str, strlen(str) - trimmed_len * num_words + 1, "%s", str + trimmed_len * num_words);

    if (strlen(trimmed_str) <= limit) {
        char* capitalized_str = malloc(strlen(trimmed_str) + num_words);
        if (!capitalized_str) {
            free(trimmed_str);
            return NULL;
        }

        size_t pos = 0;
        for (size_t i = 0; i < num_words; ++i) {
            const char* word = words[i];
            if (!word) continue;

            size_t word_len = strlen(word);
            if (pos + word_len > limit) break;

            capitalized_str[pos++] = toupper((unsigned char)word[0]); // Capitalize the first letter of each word
            memcpy(&capitalized_str[pos], word + 1, word_len - 1); // Append the rest of the word
            pos += (word_len - 1);
        }
        capitalized_str[pos++] = ' '; // Add a space after each word

        // Spell-checking API call here, replace with your actual implementation
        bool is_valid_spelling = spell_check(capitalized_str);
        if (!is_valid_spelling) {
            free(capitalized_str);
            free(trimmed_str);
            return NULL;
        }

        capitalized_str[pos] = '\0'; // Terminate the string
        return capitalized_str;
    }

    free(trimmed_str);
    return NULL;
}
