import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.LinkedBlockingDeque;
import java.util.concurrent.RejectedExecutionHandler;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class MD5AndSHA256Hasher {
    private static final Logger LOGGER = LoggerFactory.getLogger(MD5AndSHA256Hasher.class);
    private static final int MAX_THREADS = 10;
    private static final int CACHE_SIZE = 1000;
    private static final long EVICTION_INTERVAL = TimeUnit.MINUTES.toMillis(5);
    private static final String REDIS_KEY_PREFIX = "md5_sha256_hashes:";

    private final RedisTemplate<String, String> redisTemplate;
    private final ThreadPoolExecutor threadPool;
    private final ConcurrentMap<String, Future<String>> cache;
    private final Deque<String> lruCacheQueue;
    private final ScheduledExecutorService evictionScheduler;

    public MD5AndSHA256Hasher(RedisTemplate<String, String> redisTemplate) {
        this.redisTemplate = redisTemplate;
        threadPool = (ThreadPoolExecutor) Executors.newFixedThreadPool(MAX_THREADS);
        cache = new LinkedHashMap<>(CACHE_SIZE + 1, 0.75F, true);
        lruCacheQueue = new LinkedBlockingDeque<>(CACHE_SIZE);
        evictionScheduler = Executors.newSingleThreadScheduledExecutor(new RejectedExecutionHandler() {
            @Override
            public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) {
                LOGGER.error("Rejected execution: {}", r.toString());
            }
        });
        evictionScheduler.scheduleWithFixedDelay(() -> {
            String lruKey = lruCacheQueue.pollLast();
            if (lruKey != null && cache.containsKey(lruKey)) {
                cache.remove(lruKey);
                redisTemplate.delete(REDIS_KEY_PREFIX + lruKey);
            }
        }, EVICTION_INTERVAL, EVICTION_INTERVAL, TimeUnit.MILLISECONDS);
    }

    public String computeHash(String input, Charset charset) {
        validateInput(input, charset);
        Future<String> future = threadPool.submit(() -> getMD5AndSHA256Hashes(input, charset));
        cache.putIfAbsent(input, future);
        lruCacheQueue.addLast(input);
        return future.toString(); // Return the Future's toString() representation as a placeholder for actual hash value
    }

    private void validateInput(String input, Charset charset) {
        if (input == null || input.length() > 1000 || charset == null) {
            throw new IllegalArgumentException("Invalid input or character set");
        }
    }

    // ... Implement getMD5AndSHA256Hashes(String, Charset), handle batch processing jobs and other required methods ...
}
