import org.apache.avro.generic.GenericData;
import org.apache.avro.specific.EncryptedMessageData;
import org.apache.commons.codec.digest.HmacSha256;
import org.bouncycastle.jce.provider.BouncyCastleProvider;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.InvalidAlgorithmParameterException;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Decryptor {
    private static final String AES_ALGORITHM = "AES";
    private static final int KEY_LENGTH = 256;
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    // Load configuration for keys and IVs from a file or database
    private Map<String, SecretKey> keys;
    private Map<String, byte[]> ivs;

    public Decryptor() throws NoSuchAlgorithmException {
        Security.addProvider(new BouncyCastleProvider());
        KeyGenerator keyGenerator = KeyGenerator.getInstance(AES_ALGORITHM);
        keyGenerator.init(KEY_LENGTH);
        keys = new HashMap<>();
        ivs = new HashMap<>();
    }

    public String decryptMessages(String json) {
        GenericData.Mapper<EncryptedMessageData> mapper = new GenericData.Mapper<>(EncryptedMessageData.class);
        List<Map<String, Object>> messages = mapper.fromJson(json);

        List<Future<Map<String, Object>>> futures = new ArrayList<>();

        for (Map<String, Object> message : messages) {
            String keyId = (String) message.get("key");
            SecretKey key = keys.get(keyId);
            if (key == null) {
                throw new IllegalStateException("Missing key for decryption: " + keyId);
            }

            byte[] ivBytes = ivs.get(keyId);
            if (ivBytes == null) {
                throw new IllegalStateException("Missing initialization vector for decryption: " + keyId);
            }

            IvParameterSpec iv = new IvParameterSpec(ivBytes);

            String encryptedMessage = (String) message.get("encrypted_message");
            EncryptedMessageData decryptedMessageData;
            try {
                decryptedMessageData = decryptAES(encryptedMessage, key, iv);
            } catch (Exception e) {
                throw new RuntimeException("Failed to decrypt message: " + encryptedMessage, e);
            }

            String hmac = (String) message.get("hmac");
            byte[] calculatedHmac = calculateHMAC(decryptedMessageData.getData().toString(), key);

            if (!Arrays.equals(Base64.getEncoder().decode(hmac), calculatedHmac)) {
                throw new RuntimeException("Invalid HMAC for message: " + encryptedMessage);
            }

            futures.add(executor.submit(() -> validateAndPackage(decryptedMessageData)));
        }

        List<Map<String, Object>> results = new ArrayList<>();
        for (Future<Map<String, Object>> future : futures) {
            results.add(future.get());
        }

        return mapper.toJson(results);
    }

    private EncryptedMessageData decryptAES(String encryptedText, SecretKey key, IvParameterSpec iv) throws Exception {
        Cipher cipher = Cipher.getInstance(AES_ALGORITHM + "/CBC/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, key, iv);
        byte[] decryptedBytes = cipher.doFinal(Base64.getDecoder().decode(encryptedText));
        return new EncryptedMessageData().fromBytes(decryptedBytes);
    }

    private byte[] calculateHMAC(String data, SecretKey key) {
        HmacSha256 hmac = new HmacSha256(key.getEncoded());
        hmac.reset();
        hmac.update(data.getBytes(StandardCharsets.UTF_8));
        return hmac.doFinal();
    }

    private Map<String, Object> validateAndPackage(EncryptedMessageData decryptedMessage) {
        if (!decryptedMessage.validate()) {
            return new HashMap<>(){
                {
                    put("success", false);
                    put("error_message", "Invalid encrypted message");
                }
            };
        }

        Map<String, Object> result = new HashMap<>();
        result.putAll(decryptedMessage.toMap());
        result.put("success", true);
        return result;
    }
}
```

