```java
import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.net.URLClassLoader;
import javax.xml.bind.JAXBContext;
import javax.xml.bind.JAXBException;
import javax.xml.validation.Schema;
import javax.xml.validation.Validator;
import javax.xml.stream.XMLInputFactory;
import javax.xml.stream.XMLStreamConstants;
import javax.xml.stream.XMLStreamReader;

public class Deserializer {
    private static final ThreadLocal<Class<?>> CLASS_CACHE = new ThreadLocal<>();
    private static final ClassLoader CLASSLOADER = Deserializer.class.getClassLoader();

    public static <T> T deserialize(byte[] data) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            Class<?> clazz = CLASS_CACHE.get();
            if (clazz == null) {
                synchronized (CLASS_CACHE) {
                    clazz = getClassFromDataStream(ois);
                    CLASS_CACHE.set(clazz);
                }
            }
            T object = (T) ois.readObject();

            validateSchema(clazz);
            validateData(object, clazz);

            return object;
        } catch (IOException | ClassNotFoundException | InstantiationException | IllegalAccessException e) {
            throw new RuntimeException("Failed to deserialize data", e);
        } catch (JAXBException e) {
            throw new RuntimeException("Failed to validate schema", e);
        }
    }

    private static Class<?> getClassFromDataStream(ObjectInputStream ois) throws ClassNotFoundException {
        DataInputStream dis = new DataInputStream(ois);
        String className = dis.readUTF();
        return CLASSLOADER.loadClass(className);
    }

    private static void validateSchema(Class<?> clazz) throws JAXBException {
        // Implement schema retrieval from external configuration management system here
        URL schemaUrl = getSchemaUrlForClass(clazz);
        Schema schema = JAXBContext.newInstance(clazz).getSchema();
        schema.newValidator().validate(getXMLStreamReaderFromDataStream(schemaUrl));
    }

    private static void validateData(Object object, Class<?> clazz) throws JAXBException {
        // Implement data validation using JAXB here
        JAXBContext context = JAXBContext.newInstance(clazz);
        Marshaller marshaller = context.createMarshaller();
        marshaller.setProperty(Marshaller.JAXB_FORMATTED_OUTPUT, true);
        marshaller.marshal(object, new StringWriter());
    }

    private static URL getSchemaUrlForClass(Class<?> clazz) {
        // Implement schema URL retrieval based on the class here
        return clazz.getResource("/" + clazz.getSimpleName() + ".xsd");
    }

    private static XMLStreamReader getXMLStreamReaderFromDataStream(URL url) throws IOException {
        InputStream inputStream = url.openStream();
        XMLInputFactory factory = XMLInputFactory.newInstance();
        return factory.createXMLStreamReader(inputStream);
    }
}
