enum FileType { TEXT, IMAGE, DOCUMENT, PDF };
const char *fileTypes[] = {"txt", "jpg", "png", "pdf"};
int digits[4] = {3, 3, 5, 5};

// External logging system interface (replace this with actual implementation)
void log_error(const char *message);

// Function to parse the input filename and determine its extension
char *parse_filename(const char *input_filename) {
    size_t len = strlen(input_filename);
    char *filename = malloc(len + 1); // +1 for null terminator
    strcpy(filename, input_filename);

    // Find the last dot to determine the extension
    size_t i;
    for (i = len - 1; i > 0 && filename[i] != '.'; --i) {}

    if (i <= 0) {
        free(filename);
        log_error("Invalid filename: no extension found");
        return NULL;
    }

    // Move the dot to the end of the base name and null-terminate it
    memmove(&filename[i + 1], &filename[i], len - i);
    filename[i] = '\0';

    return filename;
}

// Function to check if the given file type is supported
bool is_supported(const char *extension) {
    for (size_t i = 0; i < sizeof(fileTypes) / sizeof(char*); ++i) {
        if (strcmp(extension, fileTypes[i]) == 0) {
            return true;
        }
    }
    return false;
}

// Function to generate the new filename with the given file type and digit count
void generate_new_filename(const char *base_name, const char *extension,
                           int digits, char *output_filename) {
    snprintf(output_filename, INT_MAX, "%s%d%s", base_name, digits, extension);
}

// Function to modify the input filename based on the given file type and digit count
int rename_file(const char *input_filename, const char *new_extension, int new_digits) {
    char *base_name = parse_filename(input_filename);
    if (base_name == NULL) {
        return -1;
    }

    if (!is_supported(new_extension)) {
        free(base_name);
        log_error("Invalid file type");
        return -2;
    }

    char new_filename[INT_MAX];
    generate_new_filename(base_name, new_extension, new_digits, new_filename);

    // Rename the file using rename() function (not provided here)

    free(base_name);
    return 0;
}

// Main function to execute the renaming operation based on command-line arguments or configuration file
int main(int argc, char **argv) {
    if (argc < 3 || argc > 4) {
        log_error("Usage: ./program input_filename output_extension [digits]");
        return -3;
    }

    const char *input_filename = argv[1];
    const char *output_extension = argv[2];
    int digits = argc == 4 ? atoi(argv[3]) : digits[TEXT]; // Use default digit count for text files

    if (rename_file(input_filename, output_extension, digits) < 0) {
        return -1;
    }

    return 0;
}
