base64encoded_t encode_pem_to_base64(const char* pem) {
    BIO *bio = BIO_new(BIO_s_mem());
    PEM_write_bio_X509(bio, d2i_X509_fp((FILE*)bio, NULL), NULL);
    BIO_free_all(bio);

    unsigned long len = BIO_get_mem_data(bio) + BIO_get_mem_length(bio);
    char *output = static_cast<char*>(malloc(len));
    memcpy(output, BIO_get_mem_ptr(bio), len);

    BIO_free_all(bio);

    // Encode the PEM data to base64
    BIO *b64 = BIO_new(BIO_f_base64());
    BIO *bio_out = BIO_new_mem_buf(output, len);
    BIO_push(b64, bio_out);
    BIO_free_all(bio_out);

    unsigned long encoded_len;
    char* base64data = BIO_get_mem_ptr(b64) + BIO_get_mem_length(b64);
    encoded_len = BIO_get_mem_length(b64);

    BIO_flush(b64);
    BIO_reset(b64);

    return { base64data, encoded_len };
