void* authenticate(const TransactionRequest *request) {
    CURL *curl;
    CURLcode res;
    char access_token[2048];
    int retries = 5;

    do {
        curl = curl_easy_init();
        if (curl) {
            snprintf(access_token, sizeof(access_token), "http://oauth-server.com/token?client_id=%s&client_secret=%s&grant_type=client_credentials", request->client_id, request->client_secret);
            curl_easy_setopt(curl, CURLOPT_URL, access_token);
            curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L); // Temporarily disable SSL verification for simplicity
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, nullptr);
            res = curl_easy_perform(curl);

            if (res != CURLE_OK) {
                printf("Authentication failed with error: %s\n", curl_easy_strerror(res));
                retries--;
                sleep(pow(2, retries)); // Exponential backoff
            } else {
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, access_token);
                if (strncmp(access_token, "error", 5) == 0) {
                    retries--;
                } else {
                    snprintf(access_token, sizeof(access_token), "%s", curl_easy_getinfo(curl, CURLINFO_PRIVATE));
                    break; // Authentication successful
                }
            }

            curl_easy_cleanup(curl);
        }
    } while (retries > 0);

    if (retries == 0) {
        fprintf(stderr, "Maximum retries reached, giving up on authentication.\n");
    }

    return access_token;
}

