```python
import argparse
import csv
import sys
from io import StringIO

def read_csv(filepath, separator):
    with open(filepath, 'r') as f:
        csv_reader = csv.reader(f, delimiter=separator)
        header = next(csv_reader)
        for row in csv_reader:
            yield dict(zip(header, row))

def filter_data(data, filter_function):
    return [row for row in data if filter_function(row)]

def process_file(filepath, columns, separator=',', output_file=sys.stdout, filter_function=None):
    try:
        csv_data = list(read_csv(filepath, separator))
        output_data = [row[col] for row in csv_data if col in row and isinstance(row, dict)]
        if filter_function:
            output_data = filter_data(output_data, filter_function)
        if output_file != sys.stdout:
            with open(output_file, 'w') as out:
                writer = csv.writer(out)
                for row in output_data:
                    writer.writerow([row])
        else:
            print('\n'.join([','.join(map(str, row)) for row in output_data]))
    except Exception as e:
        print(f"Error processing file '{filepath}': {e}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('files', metavar='FILE', type=str, nargs='+', help='CSV files to process')
    parser.add_argument('-s', '--separator', default=',', help='Specify a different separator character than the default comma (`,`)')
    parser.add_argument('-o', '--output', type=str, help='Redirect the output to a specified file instead of printing to stdout')
    parser.add_argument('-f', '--filter', metavar='FILTER', help="Apply a filter to the extracted data based on a condition (e.g., filtering rows where a certain column value is greater than a specified threshold)")
    parser.add_argument('columns', metavar='COLUMN', nargs='*', help='Specify which columns to extract from each file')

    args = parser.parse_args()

    if not args.files or not args.columns:
        print(parser.print_help())
        sys.exit(1)

    for file in args.files:
        process_file(file, args.columns, separator=args.separator, output_file=args.output, filter_function=getattr(sys, args.filter))

if __name__ == "__main__":
    main()
```

