#include <sys/types.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <glob.h>
#include <subprocess.h>

sem_t semaphore;

int convert_images_to_pdf(char *dir, char *output_file, char **image_filenames) {
    int num_files = 0;
    glob_t files;
    char pattern[256];
    memset(pattern, 0, 256);
    strcat(pattern, "*.");
    strcat(pattern, "jpg");
    strcat(pattern, ";*.");
    strcat(pattern, "jpeg");
    strcat(pattern, ";*.");
    strcat(pattern, "png");
    strcat(pattern, ";*.");
    strcat(pattern, "gif");
    glob(dir, GLOB_TILDE, NULL, &files);
    num_files = files.gl_pathc;

    sem_init(&semaphore, 0, num_files);

    int i;
    for (i = 0; i < num_files; ++i) {
        pthread_t thread;
        char *filename = files.gl_pathv[i];
        pthread_create(&thread, NULL, convert_image_to_pdf, (void *)filename);
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(thread, NULL);
    }

    sem_destroy(&semaphore);

    char command[1024];
    snprintf(command, sizeof(command), "pdftk %s cat output %s", join_filenames(image_filenames, num_files), output_file);
    system(command);

    return 0;
}

void *convert_image_to_pdf(void *filename) {
    sem_wait(&semaphore);

    char command[256];
    snprintf(command, sizeof(command), "convert %s -quality 75% -density 300x300 %s.pdf", (char *)filename, (char *)filename);
    pid_t pid = fork();
    if (pid == 0) {
        system(command);
        exit(0);
    }

    sem_post(&semaphore);
}

char *join_filenames(char **files, int length) {
    char *result = malloc(length * 256);
    if (!result) return NULL;
    int i = 0;
    for (i = 0; i < length - 1; ++i) {
        strcat(result, files[i]);
        strcat(result, " ");
    }
    strcat(result, files[length - 1]);
    return result;
}
