        {
            // Arrange
            var dataFile = "invalid_data.bin";
            var errorLogFile = "error_log.txt";
            var connectionString = "Your_Database_Connection_String";
            var logger = Mock.Of<ILogger>();
            var dataLoader = new DataLoader(dataFile, errorLogFile, connectionString);

            // Act & Assert
            Assert.Throws<InvalidDataException>(() => dataLoader.LoadData());
        }
    }
