```php
    class AdvancedPasswordManager {
        private $hashedPassword;
        private $saltRoundCount = 12;
        private static $cache = [];

        public function generateSecureRandomString($length) {
            if (!isset(self::$cache[$length])) {
                $charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()';
                shuffle(str_split($charSet));
                self::$cache[$length] = substr(implode('', array_slice(str_split($charSet), 0, $length)), 0, $length);
            }
            return self::$cache[$length];
        }

        public function hashPassword($password) {
            $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
        }

        public function checkPassword($password) {
            return password_verify($password, $this->hashedPassword);
        }

        public function validateCharacterSet($characterSet) {
            if (!preg_match('/[A-Z]/', $characterSet) || !preg_match('/[a-z]/', $characterSet) || !preg_match('/\d/', $characterSet) || !preg_match('/[^\w]/', $characterSet)) {
                return substr($characterSet, 0, 12) . $this->generateSecureRandomString(strlen($characterSet) - 12);
            }
            return $characterSet;
        }

        public function setSaltRoundCount($rounds) {
            if ($rounds < 12 || $rounds > 31) {
                throw new Exception("The salt round count must be between 12 and 31.");
            }
            $this->saltRoundCount = $rounds;
        }

        public function resetPassword() {
            $this->hashPassword(sha1($this->generateSecureRandomString(64)));
            unset(self::$cache[strlen($this->hashedPassword)]);
        }

        public function logPasswordAttempts($ipAddress, $result) {
            // Implement database or file-based logging here
        }

        public function enforceTwoFactorAuthentication() {
            // Implement 2FA mechanism here
        }
    }
