#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <fcntl.h>

int jpeg2pdf(char *input, char *output) {
    pid_t pid = fork();
    if (pid == -1) return -1; // Error forking
    if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WEXITSTATUS(status); // Exit status of child
    } else { // Child process
        char *args[] = {"jpeg2pdf", input, output, NULL};
        execv("/usr/bin/jpeg2pdf", args); // Replace current process with jpeg2pdf
        exit(1); // Error executing command
    }
}
```

