```java
import java.io.IOException;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.concurrent.ConcurrentHashMap;
import java.time.Instant;

class DisjointPairChecker {
    private static class UnionFind {
        private int[] parent;
        private int[] rank;

        UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 1;
            }
        }

        int find(int x) {
            if (x != parent[x]) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return;
            }

            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
                rank[rootX] += rank[rootY];
            } else {
                parent[rootX] = rootY;
                rank[rootY] += rank[rootX];
            }
        }
    }

    private static class ErrorHandler {
        public void handleArrayError(IllegalArgumentException exception) {
            System.err.println("Error: Invalid input array size.");
        }

        public void handleNegativeNumber(int number) {
            System.err.println("Error: The input array contains negative numbers.");
        }

        public void handleDuplicateElement(List<Integer> list) {
            System.err.println("Error: The input array contains duplicate elements: " + list);
        }
    }

    private static class ApiCommunicator {
        private String apiEndpoint;

        ApiCommunicator(String apiEndpoint) {
            this.apiEndpoint = apiEndpoint;
        }

        void logData(int disjointPairs, long timeTaken) throws IOException {
            Map<String, Object> data = Map.of("disjoint_pairs", disjointPairs, "time_taken", timeTaken);
            RestUtils.postJson(apiEndpoint, data);
        }
    }

    private static class RestUtils {
        public static void postJson(String url, Map<String, Object> json) throws IOException {
            // Implement HTTP POST request with JSON payload here using a popular library like OkHttp or Apache HttpClient
        }
    }

    public static int countDisjointPairs(int[] array, String apiEndpoint) throws IOException {
        ErrorHandler errorHandler = new ErrorHandler();
        ApiCommunicator communicator = new ApiCommunicator(apiEndpoint);

        if (array.length > 100_000) {
            errorHandler.handleArrayError(new IllegalArgumentException("Input array size exceeds the maximum limit."));
        }

        for (int i = 0; i < array.length; i++) {
            if (array[i] < 0) {
                errorHandler.handleNegativeNumber(array[i]);
            }
        }

        List<Integer> uniqueElements = Arrays.stream(array).distinct().sorted().collect(Collectors.toList());
        if (uniqueElements.size() != array.length) {
            errorHandler.handleDuplicateElement(uniqueElements);
        }

        UnionFind uf = new UnionFind(uniqueElements.size());
        long totalTimeTaken = 0;

        for (int i = 0; i < array.length; i++) {
            long startTime = Instant.now().toEpochMilli();
            uf.union(uniqueElements.indexOf(array[i]), uniqueElements.indexOf(array[i + 1]));
            totalTimeTaken += (Instant.now().toEpochMilli() - startTime);
        }

        int disjointPairs = uniqueElements.size() - uf.getComponentsCount();
        communicator.logData(disjointPairs, totalTimeTaken);

        return disjointPairs;
    }
}
```

This code defines a `DisjointPairChecker` class that contains nested classes for Union-Find operations, error handling, API communication, and HTTP requests using RestUtils. The main `countDisjointPairs` function handles the array input, checks for errors, performs Union-Find operations with optimized path compression and union by rank, and logs the number of disjoint pairs found along with the time taken to perform each check.

Please note that you will need to implement the RestUtils.postJson() method using a popular HTTP library like OkHttp or Apache HttpClient to communicate with the external API. Additionally, this code assumes that the input array is sorted after finding unique elements for better performance and maintainability.

