// Helper functions
const fetchScript = async (url, key, fallbackUrl) => {
  // Fetch script from URL and handle errors
};

const isKeyValid = (key, validKeys) => validKeys.includes(key);

const getMetadata = async (scriptKey) => {
  // Fetch metadata for a given script key from an external configuration service
};

const sanitizeScriptContent = (content) => {
  // Sanitize the script content to prevent XSS attacks
};

// renderFooterScripts function
const renderFooterScripts = async (scriptArray, validKeys) => {
  let renderedHTML = '';
  let retries = 3;

  for (const script of scriptArray) {
    if (!script.src || !script.type || !script.key) {
      console.error(`Missing required property(ies) in script object: ${JSON.stringify(script)}`);
      continue;
    }

    const isValidKey = isKeyValid(script.key, validKeys);
    if (!isValidKey) {
      console.log(`Skipping invalid script key: ${script.key}`);
      continue;
    }

    let metadata = {};
    try {
      metadata = await getMetadata(script.key);
    } catch (error) {
      console.error(`Error fetching metadata for script key: ${script.key}. Error details: ${error}`);
    }

    let content;
    if (metadata.fallbackUrl && !content) {
      try {
        content = await fetchScript(metadata.fallbackUrl, script.key, metadata.primarySrc);
      } catch (error) {
        retries--;
        if (retries > 0) {
          console.log(`Retrying to fetch script for key: ${script.key}. Remaining retries: ${retries}`);
        } else {
          console.error(`Failed to fetch script for key: ${script.key} after all retries`);
          continue;
        }
      }
    }

    if (!content) {
      try {
        content = await fetchScript(script.src, script.key, metadata.fallbackUrl);
      } catch (error) {
        retries--;
        if (retries > 0) {
          console.log(`Retrying to fetch script for key: ${script.key}. Remaining retries: ${retries}`);
        } else {
          console.error(`Failed to fetch script for key: ${script.key} after all retries`);
          continue;
        }
      }
    }

    if (!content || content.length === 0) {
      console.error(`Empty or invalid script content for key: ${script.key}`);
      continue;
    }

    const sanitizedContent = sanitizeScriptContent(content);

    renderedHTML += `<script type="${script.type}" id="${script.key}">${sanitizedContent}</script>`;
  }

  return renderedHTML;
};
