fn create_directory_and_set_env(dir_name: &str) -> Result<String, Box<dyn Error>> {
    let current_dir = env::current_dir()?;
    let mut dir_path = current_dir;
    if env::var("MY_DIR").is_ok() {
        dir_path.push(env::var("MY_DIR")?.as_str());
