#include <openssl/evp.h>

EVP_CIPHER *init_cipher(const CipherConfig* config, const unsigned char *key, const unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    if (!ctx) {
        // Handle memory allocation failures
        return NULL;
    }

    if (config->mode == CFB && config->iv_size != MAX_CFB_IV_LEN) {
        // Handle invalid IV length for CFB mode
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    const EVP_CIPHER *cipher = EVP_get_cipherbyname("des-" + std::string(config->mode == EDE ? "ede3" : config->mode == CFB ? "cfb1" : config->mode == EDE3 ? "ede3" : config->mode));
    if (!cipher) {
        // Handle invalid mode specifications
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, key, iv)) {
        // Handle initialization failures
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
