import requests

# Sample dictionary mapping product categories to risk levels (can be expanded)
risk_levels = {
    'Electronics': {'low': [(0, 199), (500, float('inf'))], 'medium': [(200, 499), (500, 999)], 'high': [(500, float('inf'])},
    'Appliances': {'low': [(0, 199), (300, float('inf'))], 'medium': [(200, 399), (400, 699)], 'high': [(700, float('inf'])},
    # Add more product categories and risk level ranges as needed
}

def get_product_risk(product):
    category = product.category.lower()

    if category not in risk_levels:
        return "Unable to determine risk level for this product category."

    base_risk = determine_base_risk(product)

    for risk, ranges in risk_levels[category].items():
        for lower, upper in ranges:
            if base_risk >= lower and (upper == float('inf') or base_risk < upper):
                return f"Risk level: {risk}"

    # If no matching range is found, assume low risk
    return "Risk level: low"

def determine_base_risk(product):
    # Calculate the base risk based on the product's price and quantity (can be customized)
    base_risk = max((product.price * product.quantity) / 1000, 1)

    # Make an API request to get additional detailed risk information for the given product category
    try:
        api_response = requests.get(f'https://risk-assessment-api.com/{product.category}')
        if api_response.status_code == 200:
            # Process the response from the API to adjust the base risk accordingly
            adjusted_base_risk = process_api_response(api_response)
            return adjusted_base_risk
    except Exception as e:
        print(f"Error fetching data from risk assessment API: {e}")

    # If the API request fails or no adjustments are needed, return the base risk
    return base_risk

def process_api_response(api_response):
    # Process the response from the external risk assessment API as needed (can be customized)
    adjusted_base_risk = api_response.json()['risk'] * 1.5
    return adjusted_base_risk
