    while True:
        try:
            config.reload()
            game_engine = GameEngine(config)
            # Run the simulation here
            # ...
        except Exception as e:
            print(f"Error in game engine: {e}")
            time.sleep(2)  # Give some time for the user to fix the issue

if __name__ == "__main__":
