  function createDirectory(name) {
    var deferred = $q.defer();

    if (process.env.DIRECTORY_PATH) {
      deferred.resolve(process.env.DIRECTORY_PATH);
    } else {
      $http.post('/api/directories', { name: name }).then(function(response) {
        process.env.DIRECTORY_PATH = response.data;
        deferred.resolve(process.env.DIRECTORY_PATH);
      }, function(error) {
        $log.error('Error creating directory: ', error);
        deferred.reject(error);
      });
    }

    return deferred.promise;
  }

  function refreshFields(fields, urls) {
    var promises = [];

    angular.forEach(urls, function(url, i) {
      if (url.indexOf(fields[i]) !== -1) {
        var promise = $http.get(url).then(function(response) {
          // update dialog field with refreshed data and implement pagination
          // cache recent results to minimize API calls
        }, function(error) {
          // handle error gracefully
        });

        promises.push(promise);
      }
    });

    return $q.all(promises);
  }

  function cleanup() {
    var deferred = $q.defer();

    if (dirs.length > MAX_DIRS) {
      dirs.sort(function(a, b) {
        return new Date(b.createdAt) - new Date(a.createdAt);
      });

      var count = 0;
      angular.forEach(dirs, function(dir) {
        $http.delete('/api/directories/' + dir._id).then(function() {
          count++;
          if (count === dirs.length) {
            deferred.resolve();
          }
        }, function(error) {
          // handle error gracefully and log appropriately
        });
      });
    }

    $timeout(function() {
      cleanup();
    }, CLEANUP_INTERVAL);
  }

  setConfig('config.json');
  cleanup();

  return {
    createDirectory: createDirectory,
    refreshFields: refreshFields
  };
}]);
