        .await?
        .json::<AppConfig>()
        .await?;

    *CACHE.lock().unwrap() = Some(response);

    Ok(())
}

fn set_env_variables(config: &AppConfig) {
    for (key, value) in config.settings.iter() {
        env::set_var(key, value);
    }
}

