import os
import requests
from urllib.parse import urljoin
import json
from datetime import timedelta
import logging
import cachetools
import jsonschema
from jsonschema2popo import Draft7Validator, PopulatedManualSchema

# External configuration management system (e.g., JSON file)
CONFIG_FILE = 'config.json'
SCRIPT_SECTION_KEY = 'scripts'

# Schema for script object in config file
script_schema = {
    "type": "array",
    "items": {
        "type": "object",
        "properties": {
            "id": {"type": "string"},
            "src": {"type": "string"},
            "fallback": {"type": "string"}
        },
        "required": ["id", "src", "fallback"]
    }
}

# Initialize logger and cache
logger = logging.getLogger(__name__)
script_cache = cachetools.TTLCache(maxsize=100, ttl=timedelta(minutes=5))

def load_config():
    with open(CONFIG_FILE) as f:
        data = json.load(f)
        return data[SCRIPT_SECTION_KEY]

@cachetools.cached(cache=script_cache, key=hash)
def get_script_content(src):
    response = requests.get(src)
    if response.status_code == 200:
        return response.text
    else:
        logger.warning(f"Script '{src}' failed to load.")
        return None

def generate_footer():
    scripts = load_config()
    footer = ""
    for script in scripts:
        id, src, fallback = script['id'], script['src'], script['fallback']
        content = get_script_content(src)
        if content:
            footer += f'<script id="{id}" src="{src}"></script>\n'
        else:
            footer += f'<script id="{id}">{fallback}</script>\n'
    return footer

def main():
    try:
        jsonschema.validate(load_config(), PopulatedManualSchema(script_schema))
        html = generate_footer()
        print(html)
    except Exception as e:
        logger.error(f"Configuration error: {e}")

if __name__ == "__main__":
    main()
```

This code assumes that you have an external configuration file (`config.json`) with a "scripts" array containing script objects in the specified format. The script caches loaded scripts for 5 minutes to reduce HTTP requests, and logs errors and cache hits/misses for debugging and monitoring purposes. Non-JavaScript users or users with disabled JavaScript will receive the fallback content defined in the configuration.

