```java
public class JwtProcessor {
    private final ConfigurationManager configurationManager;
    private final JwtValidator jwtValidator;
    private final CacheStorage<String, ValidatedJwt> cache;

    // Constructor with DI

    public User processToken(String token) throws Exception {
        ValidatedJwt cachedToken = cache.get(token);
        if (cachedToken != null && !cachedToken.isExpired()) {
            return cachedToken.getUser();
        }

        User user = jwtValidator.extractUserInfo(token);
        if (!jwtValidator.validate(token)) {
            throw new InvalidJwtException("Invalid JWT");
        }

        cache.put(token, new ValidatedJwt(user));
        return user;
    }
}
