    private readonly TimeSpan _timeout = TimeSpan.FromMinutes(5);
    private readonly IQueue _queue;
    private readonly ICryptographicServiceProvider _csp;
    private readonly Encoding _encoding = Encoding.UTF8;

    public DynamicTripleDesDecryptor(IQueue queue, ICryptographicServiceProvider csp)
    {
        _queue = queue;
        _csp = csp;
