    public string DecryptBase64(string message)
    {
        // Fetch keys and IVs from CSP
        var keyAndIv = _csp.FetchKeysAndIV();

        // Validate keys and IVs before decryption
        ValidateKeyAndIV(keyAndIv);

        // Derive encryption keys from master key and context identifier
        var tripleDESKey = TripleDESCryptoServiceProvider.Create();
        tripleDESKey.Key = DeriveKeyFromMasterAndContext(keyAndIv.Key, keyAndIv.ContextId);

        var iv = Encoding.Convert(Encoding.UTF8, Encoding.ASCII, System.Text.RegularExpressions.Regex.Unescape(keyAndIv.IV));
        using (var decryptor = new TripleDESCryptoServiceProvider())
        {
            decryptor.IV = iv;
            decryptor.Key = tripleDESKey.Key;
            var plaintext = decryptor.CreateDecryptor().TransformFinalBlock(Convert.FromBase64String(message), 0, message.Length);
