           if (!preg_match('/[A-Z]/', $characterSet) || !preg_match('/[a-z]/', $characterSet) || !preg_match('/[0-9]/', $characterSet) || !preg_match('/[!@#$%^&*()]/', $characterSet)) {
               return str_replace(' ', '', trim($this->characterSet));
           }

           return $characterSet;
       }

       public function setSaltRoundCount($rounds) {
           if ($rounds < 12 || $rounds > 31) {
               throw new Exception("Salt round count must be between 12 and 31.");
           }

           $this->saltRounds = $rounds;
       }

       public function resetPassword() {
           $this->hashedPassword = $this->hashPassword($this->generateSecureRandomString(60)); // 60 characters for increased security
           unset(self::$cachedStrings[60]);
       }

