```python
import argparse
import json
import logging
import os
import ssl
import sys
import time
from http.server import HTTPServer, BaseHTTPRequestHandler
from threading import Event, Lock
from urllib.parse import urlparse

class RateLimiter:
    def __init__(self, max_requests=50):
        self.lock = Lock()
        self.requests = {}
        self.max_requests = max_requests
        self.reset_time = 60

    def get(self, ip):
        with self.lock:
            if ip not in self.requests:
                self.requests[ip] = 1
            else:
                self.requests[ip] += 1

            if time.time() - self.requests[ip]['time'] > self.reset_time:
                self.requests[ip]['count'] = 1
                self.requests[ip]['time'] = time.time()

        return self.requests[ip]['count']

    def update(self, ip):
        with self.lock:
            if ip in self.requests:
                self.requests[ip]['time'] = time.time()
                self.requests[ip]['count'] += 1

class Config:
    def __init__(self, config_file):
        with open(config_file) as f:
            self.data = json.load(f)

    @property
    def host(self):
        return self.data['host']

    @property
    def port(self):
        return int(self.data['port'])

    @property
    def ssl_cert(self):
        return self.data['ssl']['certificate']

    @property
    def ssl_key(self):
        return self.data['ssl']['key']

    @property
    def allowed_ips(self):
        return set([ip for ip in self.data['allowed_ips'] if validate_ip(ip)])

    @property
    def logfile(self):
        return self.data.get('logfile', sys.stdout)

    @property
    def loglevel(self):
        return getattr(logging, self.data['loglevel'].upper())

def validate_ip(ip):
    parsed = urlparse(ip)
    return bool(parsed.netloc or parsed.hostname or parsed.host)

class CustomRequestHandler(BaseHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        self.ratelimiter = RateLimiter()
        super().__init__(*args, **kwargs)

    def do_HEAD(self):
        self.send_response(200)
        self.end_headers()

    def do_GET(self):
        if self.ratelimiter.get(self.client_address[0]) > 5:
            self.send_response(429)
            self.end_headers()
            return

        # Add your custom logic here for handling GET requests

def setup_logging(config):
    handler = logging.StreamHandler(stream=config.logfile)
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    handler.setFormatter(formatter)

    logger = logging.getLogger()
    logger.setLevel(config.loglevel)
    logger.addHandler(handler)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('config', help='Path to the configuration file')
    parser.add_argument('--debug', action='store_true', help='Enable debug mode')
    parser.add_argument('--ssl', action='store_false', dest='no_ssl', help='Disable SSL encryption')
    args = parser.parse_args()

    config = Config(args.config)
    setup_logging(config)

    if not args.no_ssl:
        context = ssl.create_default_context()
        context.load_cert_chain(config.ssl_cert)
        context.load_verification_chain(config.ssl_cert, None)
        server_address = (config.host, config.port)
    else:
        server_address = (config.host, config.port)

    httpd = HTTPServer(server_address, CustomRequestHandler)
    if args.debug:
        httpd.socket = sslwrap_socket(httpd.socket, context=context, do_handshake_on_connect=False)

    print(f'Starting server on {config.host}:{config.port}')
    for ip in config.allowed_ips:
        print(f'Allowed IP address: {ip}')

    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print('Shutting down server...')
        httpd.server_close()

if __name__ == '__main__':
    main()
