Here's a basic structure for your Python script. I will provide you with the main function, configuration class, and helper functions needed to manage the lifecycle of a Docker container in a swarm mode environment. The script uses `docker` SDK for Python, read config from YAML, and sends notifications to Slack using requests.

```python
import os
import yaml
import time
import requests
from docker import APIVersionNotFound, Client
from typing import Dict

class Config:
    def __init__(self, config_path):
        with open(config_path) as f:
            self.data = yaml.safe_load(f)

    @property
    def container_name(self):
        return self.data['container']['name']

    @property
    def delay_range(self):
        return int(self.data['delay']['min']) if not self.data['delay']['max'] else (
            int(self.data['delay']['min']) + int(self.data['delay']['max']))

    @property
    def slack_webhook_url(self):
        return self.data['slack']['webhook_url']

def send_slack_notification(message: str, webhook_url: str):
    response = requests.post(webhook_url, json={'text': message})
    if not response.ok:
        print(f"Failed to send Slack notification: {response.reason}")

def run_docker_command(client: Client, command: str) -> Dict:
    try:
        return client.api.command(**{'Command': command})['StreamingOutput']
    except APIVersionNotFound as e:
        print(f"Docker version error: {e}")
        return {}

def main():
    config = Config('config.yaml')
    client = Client(base_url="unix:///var/run/docker.sock", version='auto')

    container_name = config.container_name
    delay_range = config.delay_range
    slack_webhook_url = config.slack_webhook_url

    while True:
        time.sleep(random.uniform(0, delay_range))
        try:
            action = input("Enter action (start/stop): ")
            if action == 'start':
                containers = run_docker_command(client, f"ps -a -q {container_name} | grep -v PID")['SplitStream']
                if not containers:
                    status = run_docker_command(client, f"start --attach {container_name}")['StreamingOutput'].strip()
                    if 'Started' in status:
                        send_slack_notification(f"Container '{container_name}' started successfully.", slack_webhook_url)
                else:
                    print("Container is already running.")
            elif action == 'stop':
                containers = run_docker_command(client, f"ps -a -q {container_name} | grep -v PID")['SplitStream']
                if containers:
                    status = run_docker_command(client, f"kill --signal 2 {containers[0]}")['StreamingOutput'].strip()
                    if 'Killed' in status:
                        send_slack_notification(f"Container '{container_name}' stopped successfully.", slack_webhook_url)
                else:
                    print("Container is not running.")
            else:
                print("Invalid action. Please enter start or stop.")
        except KeyboardInterrupt:
            print("\nExiting...")
            break

if __name__ == "__main__":
    main()
```

