```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/semaphore.h>
#include <string.h>
#include <dirent.h>
#include <libghostscript.h>

void convert_images_to_pdf(char *inputDir, char *outputFile, char **imageFilenames) {
  int semId = semget((key_t)12345678, 1, IPC_CREAT | 0644);
  semctl(semId, 0, SETVAL, 1); // Set initial value to 1 (only one process can proceed at a time)

  gs_lib *gs = gs_new();
  int result;

  for (int i = 0; imageFilenames[i] != NULL; ++i) {
    result = semop(semId, &ops, 1); // Wait until the semaphore is signaled to proceed
    if (result < 0) {
      perror("semop");
      return;
    }

    gs_open_file(gs, imageFilenames[i], "r");
    result = gs_new_image(gs, "last", NULL); // Append the new image to the PDF
    if (result < 0) {
      perror("gs_new_image");
      return;
    }
  }

  result = gs_write_file(gs, outputFile, "pdfwrite");
  if (result < 0) {
    perror("gs_write_file");
    return;
  }

  gs_close_file(gs);
  gs_free_object(gs, gs->graphics_state, 1);
  gs_free(gs);

  semctl(semId, 0, IPC_RMID); // Delete the semaphore after use
}
