SCRIPT_CACHE = LRUCache(maxsize=CONFIG["script_cache_size"])

class Script:
    def __init__(self, id, src, fallback):
        self.id = id
        self.src = src
        self.fallback = fallback
        self.loaded = False
        self.version = CONFIG.get(f"script_{id}_version", None)

def script_key(script):
    return (script.id, script.version) if script.version else script.id

def get_script_url(script):
    script_data = CONFIG[script.id]
    url = script_data["url"]
    if script.version:
        url += f"/{script.version}"
    return url

def fetch_and_cache_script(script):
    key = script_key(script)
    if key in SCRIPT_CACHE:
        script.content = SCRIPT_CACHE[key]
        script.loaded = True
        logging.debug(f"Loaded script {script.id} from cache.")
        return script

    try:
        response = requests.get(get_script_url(script), timeout=CONFIG["request_timeout"])
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        logging.error(f"Failed to load script {script.id}: {e}")
        return script

    script.content = response.content.decode("utf-8")
    SCRIPT_CACHE[key] = script.content
    script.loaded = True
    logging.debug(f"Fetched and cached script {script.id}.")
    return script

