            footer += f'<noscript>{CONFIG["no_javascript_message"]}</noscript>\n'

    return footer

def determine_script_type(script):
    if CONFIG.get("cdn"):
        parsed = urlparse(get_script_url(script))
        if parsed.scheme == "http" or parsed.scheme == "https":
            if any(ext in script.content for ext in (".js", ".mjs")):
                return "javascript"
            elif any(ext in script.content for ext in (".css",)):
                return "css"
            else:
                # Use feature detection to determine the type of script if it's not JavaScript or CSS
                fd = FeatureDetect()
                if fd.is_media_query_supported():
                    return "css"
                elif fd.is_audio_api_supported():
                    return "audio"
                elif fd.is_video_api_supported():
                    # Add video tag fallback detection and rendering here
                    pass
                else:
                    return "unknown"
        else:
            # Assume the script is a local file with a known extension
            script_path = os.path.abspath(get_script_url(script))
            ext = os.path.splitext(script_path)[1]
            if ext in (".js", ".mjs"):
                return "javascript"
            elif ext in (".css",):
                return "css"
            else:
                # Use feature detection to determine the type of script if it's not JavaScript or CSS
                fd = FeatureDetect()
                if fd.is_media_query_supported():
                    return "css"
                elif fd.is_audio_api_supported():
                    return "audio"
                elif fd.is_video_api_supported():
                    # Add video tag fallback detection and rendering here
                    pass
                else:
                    return "unknown"
    else:
        raise ValueError("CDN must be configured to determine script type.")

