```csharp
using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Xml.XPath;
using System.Threading.Tasks;
using System.Threading;
using System.Net.Http;
using Newtonsoft.Json;

namespace AsyncAesCbcInitiate
{
    public class Options
    {
        public int Parallelism { get; set; } = 4;
        public TimeSpan ThrottleInterval { get; set; } = TimeSpan.FromSeconds(1);
        public Action<int, double> ProgressCallback { get; set; }
        public Func<string, T> CustomAccumulator { get; set; }
    }

    public class DataWithToken
    {
        public string Data { get; set; }
        public string Token { get; set; }
    }

    public class ReductionResult
    {
        public double Value { get; set; }
        public Exception Error { get; set; }
    }

    public static class AesCbc
    {
        private static readonly ConcurrentDictionary<string, XElement> _cache = new ConcurrentDictionary<string, XElement>();

        public static async Task<XElement> ParseXmlAsync(string xml, string xPath)
        {
            if (_cache.TryGetValue(xPath, out var parsed))
                return parsed;

            using var reader = new StringReader(xml);
            var document = XDocument.Load(reader);
            parsed = document.Root.XPathSelectElement(xPath);
            _cache[xPath] = parsed;
            return parsed;
        }

        private static async Task<DataWithToken> FetchApiData(string url, HttpClient client)
        {
            var request = new HttpRequestMessage { Method = HttpMethod.Get, RequestUri = new Uri(url) };
            using var response = await client.SendAsync(request);
            if (!response.IsSuccessStatusCode)
                throw new Exception($"API request failed: {response.StatusCode}");
            var content = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<DataWithToken>(content);
        }

        public static async Task<ReductionResult> AsyncAesCbcInitiate(string[] xmls, double initialValue, Options options)
        {
            var cts = new CancellationTokenSource();
            var semaphore = new SemaphoreSlim(options.Parallelism);
            var tasks = new List<Task>();
            var accumulatedValue = initialValue;
            var operationCount = xmls.Length;

            options.ProgressCallback?.Invoke(0, accumulatedValue);

            foreach (var xml in xmls)
            {
                await semaphore.WaitAsync(cts.Token);
                tasks.Add(Task.Run(async () =>
                {
                    try
                    {
                        var parsedXml = await ParseXmlAsync(xml, "YourXPathQuery");
                        if (parsedXml == null)
                            throw new Exception("No matching nodes found");
                        if (parsedXml.Elements().Count() > 1)
                            throw new Exception($"Multiple matching nodes found: {parsedXml.Elements().Count()}");

                        var dataWithToken = await FetchApiData(parsedXml.Element("your-api-call").Value, options.ApiClient);
                        if (options.CustomAccumulator != null)
                            accumulatedValue = options.CustomAccumulator(dataWithToken.Data);
                        else
                            accumulatedValue += double.Parse(dataWithToken.Data);

                    }
                    catch (Exception ex)
                    {
                        return new ReductionResult { Error = ex };
                    }
                    finally
                    {
                        semaphore.Release();
                        options.ProgressCallback?.Invoke(++operationCount, accumulatedValue);
                    }
                }));
            }

            await Task.WhenAll(tasks);

            return new ReductionResult { Value = accumulatedValue };
        }
    }
}
```

