public class FileLoader {
    private static final Logger LOGGER = Logger.getLogger(FileLoader.class.getName());

    public MoSTState loadStateFromFile(String filePath) {
        FileInputStream inputStream;
        ObjectInputStream objectInput;
        MoSTState state = null;

        try {
            inputStream = new FileInputStream(filePath);
            objectInput = new ObjectInputStream(inputStream);

            // Check the class that is being deserialized
            Object readObject = objectInput.readObject();

            if (readObject instanceof MoSTState) {
                state = (MoSTState) readObject;

                // Add your validation logic here for version compatibility and data consistency checks

                LOGGER.log(Level.INFO, "Successfully loaded state from file: {0}", filePath);
            }
        } catch (IOException | ClassNotFoundException e) {
            LOGGER.log(Level.SEVERE, "Failed to load state from file: {0}", filePath, e);
        } finally {
            try {
                if (objectInput != null) objectInput.close();
                if (inputStream != null) inputStream.close();
            } catch (IOException e) {
                LOGGER.log(Level.WARNING, "Failed to close stream for file: {0}", filePath, e);
            }
        }

        return state;
    }
}
