import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.PostConstruct;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DirectoryCompressor {
    private static final Logger LOGGER = LoggerFactory.getLogger(DirectoryCompressor.class);
    private static final int MAX_RETRIES = 3;
    private static final String COMMAND = "jar -cfv %s %s"; // Replace with the appropriate command for your system (e.g., "7z a -tzip %s %s" for 7-Zip)

    private Path inputDir;
    private Path outputZipFile;
    private int compressionLevel;
    private boolean excludePatterns;

    public void setInputDir(String inputDirPath) {
        this.inputDir = Paths.get(inputDirPath);
    }

    public void setOutputZipFile(String outputZipFilePath) {
        this.outputZipFile = Paths.get(outputZipFilePath);
    }

    public void setCompressionLevel(int compressionLevel) {
        this.compressionLevel = compressionLevel;
    }

    public void setExcludePatterns(boolean excludePatterns) {
        this.excludePatterns = excludePatterns;
    }

    @PostConstruct
    private void init() {
        checkAndDeleteOutputZipFile();
        if (!Files.exists(inputDir) || !Files.isDirectory(inputDir)) {
            throw new IllegalArgumentException("Input directory does not exist or is not a valid directory.");
        }
    }

    public void compress() throws IOException, InterruptedException {
        List<String> commandArgs = new ArrayList<>();
        commandArgs.add(String.format(COMMAND, outputZipFile.toString(), inputDir.toString()));
        if (compressionLevel > 0) {
            commandArgs.add("-C");
            commandArgs.add(String.valueOf(compressionLevel));
        }
        if (excludePatterns) {
            // Add logic for specifying exclude patterns here
        }

        Process process = Runtime.getRuntime().exec(commandArgs.toArray(String[]::new));

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            LOGGER.error("Compression error: {}", line);
        }

        int exitValue = process.waitFor();
        if (exitValue != 0) {
            throw new RuntimeException("Compression failed with exit code " + exitValue);
        }
    }

    private void checkAndDeleteOutputZipFile() {
        if (Files.exists(outputZipFile)) {
            try {
                Files.deleteIfExists(outputZipFile);
            } catch (Exception e) {
                LOGGER.error("Failed to delete existing ZIP file: {}", outputZipFile, e);
            }
        }
    }
}
```

