async function runTests(suite) {
  let retries = retryAttempts;
  while (retries > 0) {
    try {
      return await suite();
    } catch (error) {
      console.log(`Test failed, attempting ${retries} more time(s). Error:`, error);
      retries--;
      await timeout(retryDelay);
    }
  }
  throw new Error('All retry attempts have been exhausted.');
}

// Main function to manage and run tests
