import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.*;
import io.netty.channel.socket.SocketChannel;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class AsyncServer {
    private final EventLoopGroup group = new NioEventLoopGroup();
    private final ServerBootstrap bootstrap = new ServerBootstrap();

    public void start(int port) throws Exception {
        bootstrap
            .group(group)
            .channel(NioServerSocketChannel.class)
            .childHandler(new ChannelInitializer<SocketChannel>() {
                @Override
                protected void initChannel(SocketChannel channel) throws Exception {
                    ChannelPipeline pipeline = channel.pipeline();
                    pipeline.addLast(new IdleStateHandler());
                    pipeline.addLast(new ChannelInboundHandlerAdapter() {
                        private final ThreadPoolExecutor pool = Executors.newFixedThreadPool(10);

                        @Override
                        public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
                            pool.submit(() -> handleRequest((String)msg, ctx));
                        }
                    });
                }
            })
            .option(ChannelOption.SO_BACKLOG, 128)
            .childOption(ChannelOption.SO_KEEPALIVE, true);

        ChannelFuture future = bootstrap.bind(port).sync();
        future.channel().closeFuture().sync();
    }

    private void handleRequest(String request, ChannelHandlerContext ctx) {
        // Implement your request handling logic here
    }
}
