#include <boost/asio.hpp>
#include <forward_list>
#include <iostream>
#include <string>
#include <utility>

namespace asio = boost::asio;
using asio::ip::tcp;

std::forward_list<std::string> dataList;

void handleRequest(const std::string& request, asio::yield_context yield) {
    // Implement your request handling logic here
}

void startServer(int port) {
    try {
        io_service service;
        tcp::acceptor acceptor(service, tcp::endpoint(tcp::v4(), port));

        for (;;) {
            tcp::socket socket = acceptor.accept(yield);
            if (!socket) {
                break;
            }

            std::thread{ [socket]() { handleRequest("", socket) }, "" }.detach();
        }
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << '\n';
    }
}

void insertAfter(const std::string& key, const std::string& value) {
    auto it = dataList.begin();
    if (it != dataList.end()) {
        for (; it != dataList.end() && it->compare(key) != 0; ++it);
        if (it == dataList.end()) {
            dataList.push_back(value);
        } else {
            auto nextIt = std::next(it);
            dataList.insert(nextIt, value);
        }
    } else {
        dataList.push_front(key);
        dataList.push_after(dataList.begin(), value);
    }
}
```

