    public async Task UpdateUserConfigAsync(string userId, string configName, object configValue)
    {
        try
        {
            await HandleDependentTasksAsync();

            var dbConnection = new SqlConnection(_connectionString);
            await dbConnection.OpenAsync();

            // Cache management and optimization strategies here
            var cachedConfigValue = _nCache.Get(CreateCacheKey(userId, configName));
            if (cachedConfigValue != null)
            {
                // If the value is in cache, update it only if the new value is different from the cached value.
                if (!JsonConvert.AreEqual(configValue, cachedConfigValue))
                {
                    _nCache.Put(CreateCacheKey(userId, configName), configValue);
                }
            }
            else
            {
                // If the value is not in cache, always write to database and cache the new value.
                await dbConnection.ExecuteAsync($"UPDATE UserConfig SET ConfigValue = @configValue WHERE UserId = @userId AND ConfigName = @configName", new { userId, configName, configValue });
                _nCache.Put(CreateCacheKey(userId, configName), configValue);
            }
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Error while updating user configuration.");
            throw;
        }
    }

