def read_config(filename):
    with open(filename) as f:
        data = json.load(f)
    return data

def parse_cryptographic_functions(data):
    hashes, ciphers = [], []
    for item in sorted(data, key=str.lower):
        if item.startswith("hash"):
            hashes.append(item)
        elif item.startswith("cipher"):
            ciphers.append(item)
    return hashes, ciphers

def get_sequence_number(item):
    parts = item.split(".")
    return int(parts[-1]) if len(parts) > 1 else None

