import requests
import json
from functools import lru_cache

API_KEY = 'your_api_key'  # Replace with your actual API key
API_URL = 'http://api.openweathermap.org/data/2.5/weather'
CACHE_DURATION = 600  # Cache duration in seconds (10 minutes)

@lru_cache(maxsize=None, typed=False, cache=True)
def fetch_weather_data(location):
    params = {'q': location, 'appid': API_KEY}
    response = requests.get(API_URL, params=params)
    if response.status_code == 200:
        return json.loads(response.text)
    else:
        return None

class WeatherManager:
    def __init__(self):
        self._data = {}
        self._cache_timer = None

    def update_weather(self, location, data):
        if not location in self._data or self.is_cached_stale():
            self._data[location] = data
            self._cache_timer = self.schedule_cache_refresh()

    def get_weather(self, location):
        if location in self._data and not self.is_cached_stale():
            return self._data[location]
        else:
            return None

    @staticmethod
    def is_cached_stale():
        if WeatherManager._cache_timer:
            elapsed = int(time.time()) - WeatherManager._cache_timer
            return elapsed > CACHE_DURATION

    @staticmethod
    def schedule_cache_refresh():
        refresh_time = time.time() + CACHE_DURATION
        WeatherManager._cache_timer = refresh_time
        return refresh_time

