```java
import io.reactivex.Observable;
import io.reactivex.functions.Function;
import okhttp3.*;
import java.io.IOException;

public class WeatherApi {
    private static final String API_KEY = "your_api_key";  // Replace with your actual API key
    private static final String API_URL = "http://api.openweathermap.org/data/2.5/weather";
    private static final int CACHE_DURATION_SECONDS = 600;  // Cache duration in seconds (10 minutes)

    public interface WeatherDataDeserializer {
        WeatherData deserialize(String json);
    }

    public Observable<WeatherData> fetchWeatherDataAsync(final String location, final WeatherDataDeserializer deserializer) {
        OkHttpClient client = new OkHttpClient();
        Request request = new Request.Builder()
                .url(API_URL + "?q=" + location + "&appid=" + API_KEY)
                .build();

        return Observable.create((ObservableOnSubscribe<WeatherData>) emitter -> {
            try {
                Response response = client.newCall(request).execute();
                if (response.isSuccessful()) {
                    WeatherData data = deserializer.deserialize(response.body().string());
                    emitter.onNext(data);
                } else {
                    emitter.onError(new Exception("Failed to fetch weather data"));
                }
            } catch (IOException e) {
                emitter.onError(e);
            }
        })
                .doOnSubscribe(__ -> WeatherManager.scheduleCacheRefresh())
                .retryWhen(errors -> errors.flatMap(error -> {
                    if (error instanceof TimeoutException) {
                        return Observable.timer(1, TimeUnit.SECONDS);  // Retry after 1 second for TimeoutExceptions
                    } else {
                        return Observable.error(error);
                    }
                }));
    }

    public static void scheduleCacheRefresh() {
        WeatherManager.scheduleCacheRefresh();
    }
}
```

