public class HashService {
    private static final Logger LOGGER = LoggerFactory.getLogger(HashService.class);
    private static final int MAX_THREADS = 10;
    private static final int CACHE_SIZE = 1000;
    private static final long TIMEOUT_MILLIS = 5000;
    private final ReadWriteLock cacheLock = new ReentrantReadWriteLock();
    private final ConcurrentHashMap<String, Map.Entry<String, String>> cache;
    private final ExecutorService threadPool;

    public HashService() {
        this(MAX_THREADS, CACHE_SIZE);
    }

    public HashService(int maxThreads, int cacheSize) {
        this.threadPool = Executors.newFixedThreadPool(maxThreads);
        this.cache = new ConcurrentHashMap<>(cacheSize);
    }

    public Map<String, String> computeHashes(Path filePath) throws FileNotFoundException {
        validateFilePath(filePath);

        String md5 = cacheLock.readLock().lock() ? getCachedMd5(filePath) : null;
        String sha256 = cacheLock.writeLock().lock() ? getCachedSha256(filePath) : null;

        if (md5 != null && sha256 != null) {
            cacheLock.writeLock().unlock();
            cacheLock.readLock().unlock();
            return Map.of("MD5", md5, "SHA-256", sha256);
        }

        CompletionService<Map<String, String>> completionService = new ExecutorCompletionService<>(threadPool);
        Callable<Map<String, String>> task = () -> computeHashesInSeparateThread(filePath);
        completionService.submit(task);

        Map<String, Future<Map<String, String>>> futures = new HashMap<>();
        futures.put("MD5", completionService.take());
        futures.put("SHA-256", completionService.take());

        Map<String, String> results = new HashMap<>();
        for (Map.Entry<String, Future<Map<String, String>>> entry : futures.entrySet()) {
            results.put(entry.getKey(), entry.getValue().get().get(entry.getKey()));
        }

        cacheLock.writeLock().unlock();
        cacheLock.readLock().unlock();
        return results;
    }

