        public Task<string> GenerateMd5Async(byte[] input) => GenerateHashAsync("MD5", input);
        public Task<string> GenerateSha1Async(string input) => GenerateHashAsync("SHA1", input);
        public Task<string> GenerateSha1Async(byte[] input) => GenerateHashAsync("SHA1", input);
        public Task<string> GenerateSha256Async(string input) => GenerateHashAsync("SHA256", input);
