        public Task<string> CompressDataAsync(byte[] input) => CompressAsync("GZip", input);
        public Task<string> EncryptDataAsync(string input) => EncryptAsync("AES", input);
        public Task<string> EncryptDataAsync(byte[] input) => EncryptAsync("AES", input);

        private async Task<string> GenerateHashAsync(string algorithmName, string input)
        {
            if (string.IsNullOrEmpty(algorithmName)) throw new ArgumentNullException(nameof(algorithmName));
            if (_hashAlgorithms.TryGetValue(algorithmName, out var hashAlgorithmFactory))
            {
                using (var hash = hashAlgorithmFactory())
                {
                    await Task.Run(() => hash.ComputeHashAsync(Encoding.UTF8.GetBytes(input)));
                    return BitConverter.ToString(hash.Hash).Replace("-", string.Empty);
                }
            }
            throw new KeyNotFoundException($"Hash algorithm '{algorithmName}' not found.");
        }

        private async Task<string> GenerateHashAsync(string algorithmName, byte[] input)
        {
            if (string.IsNullOrEmpty(algorithmName)) throw new ArgumentNullException(nameof(algorithmName));
            if (_hashAlgorithms.TryGetValue(algorithmName, out var hashAlgorithmFactory))
            {
                using (var hash = hashAlgorithmFactory())
                {
                    await Task.Run(() => hash.ComputeHashAsync(input));
                    return BitConverter.ToString(hash.Hash).Replace("-", string.Empty);
                }
            }
            throw new KeyNotFoundException($"Hash algorithm '{algorithmName}' not found.");
        }

