        // Attempt fallback mechanism if primary recording fails
        if (recorderType == "database" && recorderType != "payment_processor") {
            // Open log file, record the error and close the file
            logger.recordError(e.what());
        } else if (recorderType == "payment_processor" && transaction_queue.size() > 1) {
            // Process multiple transactions concurrently to reduce API calls
            std::unique_lock<std::mutex> lock(transaction_queue_mutex);
            cv.wait(lock, [&](){ return !transaction_queue.empty(); });
            Transaction nextTransaction = transaction_queue.front();
            transaction_queue.pop_front();
            lock.unlock();

            recordTransaction(nextTransaction, "payment_processor"); // Recurse to process more transactions if queue is not empty
        } else {
            errorCode = -1;
        }
    }

