pthread_cond_t fsa_condition;

// Define the expandStateList function here
void expandStateList(int **state_list_ptr, size_t *num_states_ptr, FSA *fsa, const char *url) {
    StateList *states = NULL; // The expanded state list
    int last_state = *state_list_ptr[*num_states_ptr - 1]; // Last state in the current list

    pthread_mutex_lock(&fsa_lock);

    // Load states from cache or external data source if not already loaded
    if (!states) {
        if (load_states(url, &states)) {
            // Handle error cases here, e.g., return early with an appropriate error message
            printf("Error loading states from URL: %s\n", url);
            pthread_mutex_unlock(&fsa_lock);
            return;
        }
    }

    // Initialize a temporary state list for expanded states and their indices in the original list
    int *expanded_indices = malloc(*num_states_ptr * sizeof(int));
    if (!expanded_indices) {
        printf("Error allocating memory for expanded_indices array.\n");
        pthread_mutex_unlock(&fsa_lock);
        return;
    }

    int num_expanded = 0;
    for (size_t i = 0; i < *num_states_ptr; ++i) {
        expanded_indices[i] = -1;
        if (fsa_transition(fsa, state_list_ptr[i], states->symbol)) {
            expanded_indices[i] = num_expanded++;
        }
    }

    // Allocate memory for the new state list and copy over the relevant elements
    int *new_state_list = malloc((*num_states_ptr + num_expanded) * sizeof(int));
    if (!new_state_list) {
        printf("Error allocating memory for new_state_list array.\n");
        free(expanded_indices);
        pthread_mutex_unlock(&fsa_lock);
        return;
    }

    // Copy over the original states and expanded states, keeping them in the same order as the original list
    memcpy(new_state_list, *state_list_ptr, *num_states_ptr * sizeof(int));
    for (size_t i = 0; i < num_expanded; ++i) {
        new_state_list[*num_states_ptr + i] = states->ids[expanded_indices[i]];
    }

    // Update the expanded state list and number of states pointers
    free(*state_list_ptr);
    *state_list_ptr = new_state_list;
    *num_states_ptr += num_expanded;

    // If the last state in the original list has been expanded, update its next pointer to the start of the new state list
    if (last_state >= 0 && expanded_indices[last_state] != -1) {
        int next_state = states->ids[expanded_indices[last_state]];
        FSAState *last_fsa_state = fsa_get_state(fsa, last_state);
        last_fsa_state->next = &(*state_list_ptr)[0];
    }

    pthread_mutex_unlock(&fsa_lock);

    // Implement caching mechanism here, e.g., store the loaded states for future expansions
}
