app = Flask(__name__)

# Global cache for fetched scripts
CACHE = {}

@app.route('/api/scripts', methods=['POST'])
def renderFooterScripts():
    data = request.get_json()

    if not data or 'scripts' not in data:
        return jsonify({'error': 'Missing script data.'}), 400

    footer_scripts = []
    for script in data['scripts']:
        if not all([script.get(key) for key in ('src', 'type', 'key')]):
            return jsonify({'error': 'Script object is missing required properties.'}), 400

        # Calculate file hash here (Performance Optimization and Scalability)
        script_hash = hashlib.md5(requests.get(script['src']).content).hexdigest()

        if script_hash in CACHE:
            footer_scripts.append(CACHE[script_hash])
        else:
            # Fetch the script content here (Integration with External Systems or Databases)
            response = requests.get(script['src'])
            if response.status_code == 200:
                CACHE[script_hash] = f'<script src="{script["src"]}" type="{script["type"]}" key="{script["key"]}">{' + response.content.decode() + '</script>'
                footer_scripts.append(CACHE[script_hash])
            else:
                # Handle potential network errors (Error Handling and Edge Case Management)
                return jsonify({'error': f'Failed to fetch script "{script["src"]}". Status code: {response.status_code}'}), 500

    return jsonify({'footer_scripts': footer_scripts})

