// Configuration file structure and handling functions
typedef struct Config {
    char *primitive;
    int encrypted;
} Config;

Config* load_config(const char* filename);

// Key management functions
EVP_PKEY* generate_key();
void encrypt_key(EVP_PKEY *key, const char *passphrase);
void decrypt_key(EVP_PKEY *key, const char *passphrase);

// Cryptographic primitive operations with thread-safety and memory management
CRYPTO_EX_DATA* add_primitive(const char *name, EVP_PKEY *key, int encrypted);
void remove_primitive(CRYPTO_EX_DATA *data);
CRYPTO_EX_DATA* find_primitive(const char *name);
int verify_primitive(const char *name);

// Logging and error handling functions
void log_error(const char *message);
void monitor_performance();

// Backend switching functions
int switch_backend(const char *backend);

// Main function
int init_cryptographic_library() {
    Config* config = load_config("config.json");
    if (!config) return 1; // Error handling for failed configuration loading

    CRYPTO_malloc_init();
    CRYPTO_mem_controls_init();

    pthread_mutex_t library_lock = PTHREAD_MUTEX_INITIALIZER;
    CRYPTO_library_lock(library_lock);

    EVP_PKEY *master_key = generate_key();
    encrypt_key(master_key, "passphrase"); // Placeholder passphrase for security purposes

    int success = 1;
    for (Config* current_config = config; current_config && success; current_config = current_config->next) {
        const char *name = current_config->primitive;
        if (!verify_primitive(name)) continue; // Skip if primitive not supported

        CRYPTO_EX_DATA* data = add_primitive(name, master_key, current_config->encrypted);
        if (!data) {
            success = 0;
            log_error("Failed to add primitive.");
        }
    }

    if (success) {
        monitor_performance();
        return 0; // Successful initialization
    } else {
        CRYPTO_cleanup_all_ex_data();
        CRYPTO_free_ex_data(config);
        return 1; // Initialization failed
    }
}
