void insertAfter(std::forward_list<std::string>& list, const std::string& key, const std::string& value) {
    auto it = list.begin();
    if (it == list.end()) {
        list.push_back(value);
        return;
    }

    for (auto i = it; next(i) != list.end(); ++i) {
