#include <experimental/resync.hpp>

namespace std {
    template<> class forward_list<std::pair<const std::string, std::mutex>> {
        // Custom implementation of forward_list for pairs of strings and mutexes
        // ... (implement the necessary member functions and types)
    };
}

class DataSource {
public:
    virtual ~DataSource() {}
    virtual bool find(const std::string& search, std::forward_list<std::pair<const std::string, std::mutex>>* list) = 0;
};

class EfficientDataSource : public DataSource {
private:
    std::unordered_map<std::string, std::forward_list<std::pair<const std::string, std::mutex>>> data;

public:
    bool find(const std::string& search, std::forward_list<std::pair<const std::string, std::mutex>>* list) override {
        auto it = data.find(search);
        if (it != data.end()) {
            // Use resync to perform the operation with atomicity
            std::experimental::resync([&]() mutable {
                for (auto element : it->second) {
                    list->push_front(element);
                    element.first.unlock();
                }
            });
            return true;
        }
        return false;
    }
};

class ThreadSafeList {
private:
    std::forward_list<std::pair<const std::string, std::mutex>> list;
    std::mutex mtx;

public:
    void push_front(const std::pair<const std::string, std::string>& pair) {
        std::lock_guard<std::mutex> lock(mtx);
        list.emplace_front(pair);
    }

    const std::forward_list<std::pair<const std::string, std::string>>& get() const {
        return list;
    }
};

void updateList(DataSource& dataSource, ThreadSafeList& threadSafeList, const std::string& search, const std::string& update) {
    auto searchList = new std::forward_list<std::pair<const std::string, std::mutex>>();
    if (!dataSource.find(search, searchList)) {
        // Use resync to perform the operation with atomicity
        std::experimental::resync([&]() mutable {
            threadSafeList.push_front({update, std::mutex()});
        });
    } else {
        // Update the list using a lock to ensure thread safety
        std::unique_lock<std::mutex> lock(threadSafeList.mtx);
        threadSafeList.push_front({search, std::mutex()});
        for (auto element : *searchList) {
            threadSafeList.push_front(element);
            lock.unlock();
            std::unique_lock<std::mutex> subLock(element.second);
            subLock.unlock();
        }
    }
    delete searchList;
}
