import org.springframework.stereotype.Component;
import java.io.FileInputStream;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@Component
public class AsyncMD5Calculator implements AsyncMD5Service {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);

    @Override
    public CompletableFuture<String> calculateMD5(String filePath) throws IOException {
        Path path = Paths.get(filePath);
        if (!Files.exists(path) || !Files.isReadable(path)) {
            throw new FileNotFoundException("File does not exist or is inaccessible: " + filePath);
        }

        CompletableFuture<String> result = CompletableFuture.supplyAsync(() -> {
            try (MessageDigest messageDigest = MessageDigest.getInstance("MD5")) {
                byte[] buffer = new byte[1024];
                FileInputStream fileInputStream = new FileInputStream(filePath);

                int bytesRead;
                while ((bytesRead = fileInputStream.read(buffer)) != -1) {
                    messageDigest.update(buffer, 0, bytesRead);
                }

                byte[] digestBytes = messageDigest.digest();
                return DigestUtils.byteToHex(digestBytes);
            } catch (Exception e) {
                throw new RuntimeException("Error calculating MD5 hash", e);
            }
        }, executor);

        // Use `thenApply` for transforming the result into a meaningful format
        result.thenApply(hexDigest -> String.format("%s (MD5: %s)", filePath, hexDigest));

        return result;
    }
}
```

