const axios = require('axios'); // Importing axios for API calls

async function asyncReduce(arr, initialValue, callback, apiUrl) {
  let accumulator = initialValue;
  let promises = [];

  // Creating promises for each array element to fetch additional data from the external API
  for (let i = 0; i < arr.length; i++) {
    const url = `${apiUrl}/${arr[i]}`;
    promises.push(axios.get(url));
  }

  // Waiting for all promises to resolve or reject
  try {
    const responses = await Promise.all(promises);

    // Transforming the API responses into a new array of numbers
    const numericResponses = responses.map((response) => response.data);

    // Using reduce() synchronously on the transformed array, combining the numbers with the callback function
    accumulator = numericResponses.reduce((acc, num) => callback(acc, num), initialValue);

  } catch (error) {
    console.error(`Error fetching data from API: ${error.message}`);
  }

  return { reducedValue: accumulator, error: undefined };
}

// Sample usage
const numbers = Array.from({ length: 100000 }, () => Math.floor(Math.random() * 1000000));
asyncReduce(numbers, 0, (acc, num) => acc + num * num, 'https://api.example.com/square').then((result) => {
  console.log('Reduced value:', result.reducedValue);
});
```

