class AdvancedWebSecurityManager {
    private $characterSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()';
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $cache = [];

    public function generateSecureRandomString($length, $characterSet = null) {
        if ($characterSet === null) {
            $characterSet = $this->characterSet;
        }
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomCharacter = $characterSet[rand(0, strlen($characterSet) - 1)];
            if (!in_array($randomCharacter, $this->cache[$length])) {
                $this->cache[$length][$randomCharacter] = true;
                $randomString .= $randomCharacter;
            }
        }
        return $randomString;
    }

    public function hashPassword($password, $saltRoundCount) {
        if ($saltRoundCount < 12 || $saltRoundCount > 31) {
            throw new Exception('Invalid salt round count. Must be between 12 and 31.');
        }
        $this->saltRoundCount = $saltRoundCount;
        $hashedPassword = password_hash($password, PASSWORD_BCRYPT);
        $this->hashedPassword = $hashedPassword;
        return $hashedPassword;
    }

    public function checkPassword($hashedPassword, $password) {
        return password_verify($password, $hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (preg_match('/[A-Z]/', $characterSet) && preg_match('/[a-z]/', $characterSet) && preg_match('/[0-9]/', $characterSet) && preg_match('/[!@#$%^&*()]/', $characterSet)) {
            return true;
        }
        throw new Exception('Invalid character set. Must contain at least one uppercase letter, one lowercase letter, one digit, and one special character.');
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            throw new Exception('Invalid salt round count. Must be between 12 and 31.');
        }
        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $this->hashedPassword = $this->hashPassword(mt_rand(), $this->saltRoundCount);
        unset($this->cache[strlen($this->hashedPassword)]);
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Implement logging using a database or file-based system.
    }
}
