// renderFooterScripts function
async function renderFooterScripts(scripts) {
  const renderedScripts = [];

  // Iterate through scripts, handling each one asynchronously
  await Promise.all(
    scripts.map(async (script) => {
      if (!script.src || !script.type || !script.key || !validateKey(script.key)) return;

      let fetchedScript = getCachedScript(`${script.key}`);

      if (!fetchedScript) {
        try {
          const response = await fetch(script.src, { cache: 'no-store' });
          const contentType = response.headers.get('Content-Type');

          if (contentType !== script.type) throw new Error(`Incorrect content type for ${script.src}`);

          fetchedScript = await response.text();

          // Cache the fetched script locally and in memory
          cacheScript(`${script.key}`, fetchedScript);
        } catch (error) {
          if (error.name === 'AbortError' || error.name === 'TypeError') return; // AbortError can occur when a request is aborted due to network changes (e.g., offline mode)

          console.error(`Failed to fetch script ${script.src}:`, error);

          // Retry logic (up to 3 retries with a 5-second delay between attempts)
          for (let i = 1; i < 4; i++) {
            try {
              await new Promise((resolve) => setTimeout(resolve, 5000 * i));
              fetchedScript = await fetch(script.src);
              break;
            } catch (retryError) {
              console.error(`Retry ${i + 1} failed for script ${script.src}:`, retryError);
            }
          }
        }
      }

      try {
        // Sanitize the fetched script content to prevent XSS attacks
        const safeContent = sanitizeScript(fetchedScript);

        renderedScripts.push(
          `<script type="${script.type}" src="${script.src || ''}">\n${safeContent}\n</script>`
        );
      } catch (error) {
        console.error(`Failed to sanitize script ${script.src}:`, error);
      }
    })
  );

  // Provide user feedback for processing status, including notifications for skipped or failed scripts
  if (scripts.length !== renderedScripts.length) {
    const missingScriptCount = scripts.length - renderedScripts.length;
    console.log(`${missingScriptCount} script${missingScriptCount === 1 ? '' : 's'} skipped due to invalid key or fetching issues.`);
  }

  // Render the footer with the processed scripts
  const footer = document.querySelector('footer');
  footer.innerHTML = renderedScripts.join('\n');
}
