const Blueslip = require('blueslip'); // mocking library

// Define optimized regular expressions for Old Testament and New Testament books
const oldTestamentRegex = /(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)/;
const newTestamentRegex = /(Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude|Revelation)/;

class BibleTextAnalyzer {
  constructor(text) {
    this.text = text;
  }

  analyze() {
    // Normalize the input, ignoring punctuation and special characters
    const normalizedText = this.text.toLowerCase().match(/\w+/g);

    if (!normalizedText || !Array.isArray(normalizedText)) {
      throw new Error('Invalid input');
    }

    let oldCount = 0;
    let newCount = 0;

    for (const word of normalizedText) {
      if (oldTestamentRegex.test(word)) oldCount++;
      else if (newTestamentRegex.test(word)) newCount++;
    }

    const books = { OldTestament: [], NewTestament: [] };
    for (const word of normalizedText) {
      if (oldTestamentRegex.test(word)) books.OldTestament.push(word);
      else if (newTestamentRegex.test(word)) books.NewTestament.push(word);
    }

    // Integration with an external API to verify the presence of the extracted books in a database of biblical books
    // ...

    const log = this.log.bind(this);
    log(`Old Testament: ${JSON.stringify(books.OldTestament)}`);
    log(`New Testament: ${JSON.stringify(books.NewTestament)}`);

    return { OldCount: oldCount, NewCount: newCount, Books: books };
  }

  get log() {
    // Logging mechanism to track the frequency of each book's occurrence in the analyzed texts
    const self = this;
    return function(msg) {
      if (!self.logger) self.logger = new Blueslip();
      self.logger.info(msg);
    };
  }
}

// Registry of factory functions for creating subclasses of the BibleTextAnalyzer class
const analyzersRegistry = {};

function registerAnalyzer(id, Constructor) {
  analyzersRegistry[id] = function() {
    const args = Array.from(arguments);
    return new Constructor(...args);
  };
}

// Example of a custom religious text analyzer
registerAnalyzer('QuranAnalyzer', class extends BibleTextAnalyzer {
  constructor(text, quranRegex) {
    super(text);
    this.quranRegex = quranRegex;
  }

  analyze() {
    // Override the analyze method to include custom regular expression for identifying the Quran
    const normalizedText = this.text.toLowerCase().match(/\b(\w+)\b/g);

    if (!normalizedText || !Array.isArray(normalizedText)) {
      throw new Error('Invalid input');
    }

    let count = 0;

    for (const word of normalizedText) {
      if (this.quranRegex.test(word)) count++;
    }

    const log = this.log.bind(this);
    log(`Quran: ${count}`);

    return count;
  }
});

