#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <dlfcn.h>

typedef void* (*AlgorithmFunction)(void*, const char*, size_t);

typedef struct Algorithm {
    const char *name;
    AlgorithmFunction function;
    // Add necessary parameters for the algorithm function here...
} Algorithm;

typedef struct Library {
    const char *path;
    void *handle;
    Algorithm** algorithms;
    size_t numAlgorithms;
    pthread_mutex_t mutex;
} Library;

Library* loadLibrary(const char *path) {
    void *handle = dlopen(path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error: Could not open library %s\n", path);
        return NULL;
    }

    Library* lib = malloc(sizeof(Library));
    lib->path = path;
    lib->handle = handle;
    lib->algorithms = NULL;
    lib->numAlgorithms = 0;
    pthread_mutex_init(&lib->mutex, NULL);

    return lib;
}

Algorithm** loadAvailableAlgorithms(Library *lib) {
    if (lib->algorithms != NULL)
        return lib->algorithms;

    void (*SymbolLookup)(const char *, size_t, Algorithm **);
    SymbolLookup = dlsym(lib->handle, "get_available_algorithms");

    if ((*SymbolLookup)(NULL, 0, &lib->numAlgorithms) < 0 ||
        lib->algorithms = malloc(lib->numAlgorithms * sizeof(Algorithm*)) == NULL) {
        fprintf(stderr, "Error: Failed to get available algorithms from library %s\n", lib->path);
        free(lib);
        return NULL;
    }

    (*SymbolLookup)(lib->algorithms, lib->numAlgorithms, &lib->numAlgorithms);

    return lib->algorithms;
}

Algorithm* getAlgorithmByName(Library *lib, const char *name) {
    Algorithm **algorithms = loadAvailableAlgorithms(lib);

    for (size_t i = 0; i < lib->numAlgorithms; ++i) {
        if (strcmp((*algorithms[i])->name, name) == 0)
            return *algorithms[i];
    }

    fprintf(stderr, "Error: Algorithm %s not found in library %s\n", name, lib->path);
    return NULL;
}

void freeLibrary(Library **libPtr) {
    if (*libPtr == NULL) return;

    pthread_mutex_destroy(&(*libPtr)->mutex);
    dlclose((*libPtr)->handle);
    free((*libPtr)->algorithms);
    free(*libPtr);

    *libPtr = NULL;
}

// This function should be implemented based on the specific third-party library API.
AlgorithmFunction get_available_algorithms(Algorithm **algorithms, size_t numAlgorithms, size_t *returnSize) {
    // Replace this with the actual implementation for your third-party library.
}
