int num_created_structures = 0; /* Number of created structures */
const int MAX_STRUCTURES = 1000; /* Maximum number of structures to create */

void *worker(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *structure = (NFAPI_CRC_INDICATION_PDU_T *) arg;
    // Populate the structure here with unique RX_UE_INFORMATION_TAG and RNTI values
    // Set CRCFLAG based on crc_flag_rules
    // Log the structure creation using log_structure_operation

    int sockfd = create_socket(ip_address, port);
    send_structure(sockfd, structure);
