int processNFALIST(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int max_threads, char *ip_address, int port) {
    sem_init(&mutex, 0, 1); /* Initialize the mutex semaphore */

    pthread_t threads[max_threads]; /* Array of thread IDs */

    if (num_structures > MAX_STRUCTURES) {
        log_structure_operation("Error: Number of structures exceeded the maximum limit.");
        return 1;
    }

    *nfalist = calloc(num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (*nfalist == NULL) {
        log_structure_operation("Error: Out of memory.");
        return 1;
    }

    for (int i = 0; i < num_structures; ++i) {
        /* Allocate memory for each structure and populate it */
        (*nfalist)[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if ((*nfalist)[i] == NULL) {
            log_structure_operation("Error: Out of memory.");
            return 1;
        }
    }

    int threads_count = num_structures < max_threads ? num_structures : max_threads;
    for (int i = 0; i < threads_count; ++i) {
        pthread_create(&threads[i], NULL, worker, (*nfalist)[num_created_structures++]);
    }

    /* Wait for all threads to finish */
    for (int i = 0; i < threads_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&mutex);

    return 0;
}
