int convert_images_to_pdf(const char *input_dir, const char *output_file, const RSA_CTX *rsa_ctx, int dpi) {
    PDF_CTX pdf_ctx = { 0 };
    pthread_t threads[10];
    DIR *dir;
    struct dirent *entry;
    struct stat st;

    rsa_init(rsa_ctx, rsa_ctx->private_key_file, rsa_ctx->password);

    pdf_ctx.dpi = dpi;
    pdf_ctx.num_images = 0;
    pdf_ctx.processed = 0;
    pthread_mutex_init(&pdf_ctx.mutex, NULL);
    pthread_cond_init(&pdf_ctx.cond, NULL);

    dir = opendir(input_dir);
    if (!dir) {
        fprintf(stderr, "Failed to open directory: %s\n", input_dir);
        return 1;
    }

    while ((entry = readdir(dir)) != NULL) {
        char *pattern = strcasecmp(basename(input_dir), "*") == 0 ? entry->d_name : basename(input_dir);
        if (wildmatch(pattern, entry->d_name) && stat(entry->d_name, &st) == 0 && S_ISREG(st.st_mode)) {
            FILE *img_file = fopen(entry->d_name, "rb");
            if (img_file) {
                PDF_CTX tmp_pdf_ctx = pdf_ctx;
                strcpy(tmp_pdf_ctx.input_file->fname, entry->d_name);
                pthread_create(&threads[pdf_ctx.num_images], NULL, image_to_pdf, &tmp_pdf_ctx);
                pdf_ctx.num_images++;
            } else {
                fprintf(stderr, "Failed to open file: %s\n", entry->d_name);
            }
        }
    }
    closedir(dir);

    for (size_t i = 0; i < pdf_ctx.num_images; i++) {
        pthread_join(threads[i], NULL);
    }

    rsa_cleanup(rsa_ctx);

    if (pdf_ctx.processed != pdf_ctx.num_images) {
        return pdf_ctx.processed;
    }

    // Create the output PDF file, cache intermediate results and perform the remaining tasks.

    return 0;
}
