import com.google.common.cache.*;
import org.apache.commons.codec.digest.MessageDigestAlgorithms;
import org.redisson.api.RedissonClient;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileNotFoundException;
import java.io.FileReader;
import java.io.IOException;
import java.nio.charset.Charset;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.locks.Lock;

public class DirectoryProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(DirectoryProcessor.class);

    private RedissonClient redissonClient;
    private LoadingCache<String, String> cache;
    private ExecutorService executor;

    public DirectoryProcessor(RedissonClient redissonClient) {
        this.redissonClient = redissonClient;
        CacheBuilder<String, String> cacheBuilder = CacheBuilder.newBuilder()
                .maximumSizePerDirectory(100) // Set your desired limit here
                .expireAfterAccessDuration(1, TimeUnit.HOURS); // Adjust time-to-live as needed
        this.cache = cacheBuilder.build((key, value) -> {
            try {
                return processFile(key);
            } catch (Exception e) {
                LOGGER.error("Error processing file {}", key, e);
                throw new RuntimeException(e);
            }
        });
        this.executor = Executors.newFixedThreadPool(5); // Adjust the number of threads according to your needs
    }

    public String processDirectoryContents(String directoryPath, Charset charset, int maxFileSizeInBytes) throws IOException {
        File dir = new File(directoryPath);
        if (!dir.exists() || !dir.isDirectory() || dir.getAbsolutePath().length() > 1000) {
            throw new IllegalArgumentException("Invalid directory path");
        }

        List<Callable<String>> tasks = new ArrayList<>();
        for (File file : Objects.requireNonNull(dir.listFiles())) {
            if (!file.isHidden() && file.getName().endsWith(".txt")) { // Adjust file extension here
                if (file.length() > maxFileSizeInBytes) continue;
                tasks.add(() -> processFile(file.getAbsolutePath(), charset));
            }
        }

        Future<String> result = null;
        try {
            result = executor.submit(tasks);
            String concatenatedContent = "";
            for (Future<String> future : result) {
                concatenatedContent += cache.getIfPresent(future.get());
            }

            for (File file : Objects.requireNonNull(dir.listFiles())) {
                if (!file.isHidden() && file.getName().endsWith(".txt")) { // Adjust file extension here
                    byte[] sha256 = MessageDigest.getInstance(MessageDigestAlgorithms.SHA_256).digest(future.get().getBytes());
                    byte[] md5 = MessageDigest.getInstance(MessageDigestAlgorithms.MD5).digest(future.get().getBytes());

                    redissonClient.getMap("fileHashes").put(file.getAbsolutePath(), Arrays.toString(sha256) + "," + Arrays.toString(md5));
                }
            }
            return concatenatedContent;
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException("Error processing files", e);
        } finally {
            executor.shutdown();
        }
