```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.Serialization.Formatters.Binary;
using System.Text;
using Newtonsoft.Json;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Task = System.Threading.Tasks.Task;

public class DataLoader
{
    private readonly ILogger<DataLoader> _logger;
    private readonly IConfiguration _configuration;
    private readonly string _serializationFormat;

    public DataLoader(ILogger<DataLoader> logger, IConfiguration configuration)
    {
        _logger = logger;
        _configuration = configuration;
        _serializationFormat = _configuration.GetValue<string>("SerializationFormat");
    }

    public async Task<List<T>> LoadDataAsync<T>()
    {
        var serializerType = GetSerializerType(_serializationFormat);
        if (serializerType == null)
        {
            _logger.LogError("Invalid serialization format: {0}", _serializationFormat);
            throw new ArgumentException("Invalid serialization format.");
        }

        var serializer = Activator.CreateInstance(serializerType);
        using var fileStream = File.OpenRead(_configuration["DataFilePath"]);
        return await Task.Run(() =>
        {
            try
            {
                if (_serializationFormat == "Binary")
                {
                    return (List<T>)new BinaryFormatter().Deserialize(fileStream);
                }
                else if (_serializationFormat == "Json")
                {
                    var jsonReader = new JsonTextReader(new StreamReader(fileStream));
                    return serializer.Deserialize<List<T>>(jsonReader);
                }
                else
                {
                    throw new NotSupportedException("Unsupported serialization format.");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to load data from file.");
                throw;
            }
        });
    }

    private Type GetSerializerType(string format)
    {
        if (format == "Binary") return typeof(BinaryFormatter);
        else if (format == "Json") return typeof(JsonConverter); // Replace this with the appropriate Newtonsoft.Json type for deserialization
        else return null;
    }
}
```

This code defines a `DataLoader` class that loads data asynchronously from a binary file using either BinaryFormatter or Json.NET (Newtonsoft.Json) based on the configured serialization format. It uses the Microsoft.Extensions.Configuration and Microsoft.Extensions.Logging packages for configuration and logging, respectively. The code demonstrates exception handling for various edge cases, such as an invalid format or file corruption.

