    unsigned short CRC_INDICATION_REL8_TAG;
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_pdus(size_t N) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    unsigned int next_crcflag = 0;

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);
        pdus[i].RNTI = i + 1;
        pdus[i].CRC_INDICATION_REL8_TAG = next_crcflag++;
        pdus[i].rx_ue_information_tag.field1 = (rand() % 100); // Replace with appropriate initialization
        pdus[i].rx_ue_information_tag.field2 = (rand() % 100); // Replace with appropriate initialization
        pthread_mutex_unlock(&mutex);
    }

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t N) {
    free(pdus);
}

int main() {
    srand(time(NULL));
    const size_t N = 100000;
    NFAPI_CRC_INDICATION_PDU_T *pdus = create_pdus(N);
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for pdus\n");
        return EXIT_FAILURE;
    }

    // Implement logging mechanism here

