        return "new_master_key_" + _contextId;
    }

    public byte[] Decrypt(byte[] encryptedMessage) {
        var encryptionKey = Encoding.UTF8.GetBytes(_key); // Convert the key to bytes for AES
        using (var aesAlg = Aes.Create()) {
            aesAlg.Key = encryptionKey;
            aesAlg.IV = new byte[aesAlg.BlockSize / 8]; // Initialize the IV with zeros

            using (var msDecrypt = new MemoryStream(encryptedMessage)) {
                var cs = new CryptoStream(msDecrypt, aesAlg.CreateDecryptor(), CryptoStreamMode.Read);
                return new byte[cs.ReadByte()]; // Read the decrypted message into a byte array
            }
        }
    }

