public class PaymentProcessor {
    private static final int MAX_RETRIES = 5;
    private static final long BACKOFF_MULTIPLIER = 2L;
    private DataSource dataSource;
    private AuditLogger auditLogger;
    private List<PaymentGateway> paymentGateways;
    private FraudDetection fraudDetection;

    public PaymentProcessor(DataSource dataSource, AuditLogger auditLogger, List<PaymentGateway> paymentGateways, FraudDetection fraudDetection) {
        this.dataSource = dataSource;
        this.auditLogger = auditLogger;
        this.paymentGateways = paymentGateways;
        this.fraudDetection = fraudDetection;
    }

    public void processPayment(Payment payment) {
        int retriesLeft = MAX_RETRIES;
        long backoff = 100L;

        while (true) {
            try {
                for (PaymentGateway gateway : paymentGateways) {
                    if (gateway.validatePayment(payment)) {
                        if (!fraudDetection.isFraudulent(payment)) {
                            gateway.processPayment(payment);
                            updateAuditLog(payment);
                            return;
                        }
                    }
                }

                throw new PaymentProcessingException("All payment gateways and fraud detection failed");
            } catch (TransientErrorException e) {
                if (retriesLeft == 0) {
                    throw e;
                }
                retriesLeft--;
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ignored) {
                }
                backoff *= BACKOFF_MULTIPLIER;
            } catch (Exception e) {
                throw new UnexpectedErrorException("Unexpected error occurred", e);
            }
        }
    }

    private void updateAuditLog(Payment payment) throws SQLException {
        Connection connection = dataSource.getConnection();
        PreparedStatement statement = connection.prepareStatement("INSERT INTO audit_log (payment_id, status, timestamp) VALUES (?, ?, ?)");
        statement.setInt(1, payment.getId());
        statement.setString(2, payment.getStatus().name());
        statement.setTimestamp(3, new Timestamp(System.currentTimeMillis()));
        statement.executeUpdate();
    }
}

