// Global variables for thread-safe queue and logging
pthread_mutex_t requestQueueMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t requestQueueCond = PTHREAD_COND_INITIALIZER;
queue_t *requestQueue = NULL;
int MAX_CONCURRENT_REQUESTS = 10;
FILE *logFile;

typedef struct {
    char *input; // User input string
    size_t maxLength; // Maximum allowed length of the processed string
    bool trim; // Whether to perform trimming
    bool capitalize; // Whether to convert all characters to uppercase
    bool removePunctuation; // Whether to remove punctuation marks
    char *language; // User's preferred language (e.g., "en", "es", "fr")
} ProcessingSettings;

void processUserInput(ProcessingSettings settings) {
    if (!settings.input || !settings.language) {
        fprintf(logFile, "Invalid input or language setting\n");
        return;
    }

    // Perform API authentication here if needed

    char *processedString = calloc(settings.maxLength + 1, sizeof(char));
    if (!processedString) {
        fprintf(logFile, "Out of memory\n");
        return;
    }

    // Detect language and adjust whitespace rules, handle accented characters, etc.
    setlocale(LC_ALL, settings.language);

    // Fetch user-specific settings from API
    apiSettings result = fetchUserSettingsAPI(settings.language);

    if (result.error) {
        fprintf(logFile, "Error fetching user settings: %s\n", result.message);
        free(processedString);
        return;
    }

    // Adjust the size limit of the processed string based on the user's settings
    size_t adjustedMaxLength = (settings.maxLength < result.maxLength) ? settings.maxLength : result.maxLength;

    // Perform trimming, capitalization, and punctuation removal if necessary
    strncpy(processedString, trimAndCapitalizeString(settings.input, adjustedMaxLength, settings.trim, settings.capitalize, settings.removePunctuation), adjustedMaxLength);

    free(settings.input); // Free original input string to minimize memory usage

    if (result.rateLimitReached) {
        sleep(result.rateLimitDuration); // Handle API rate limits
    }

    // Process the finalized string according to user's language settings here, e.g., proper noun and verb conjugation, etc.

    printf("Processed input: %s\n", processedString);
    free(processedString);
}

void initRequestQueue() {
    requestQueue = malloc(MAX_CONCURRENT_REQUESTS * sizeof(queue_t));
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; ++i) {
        queue_init(&requestQueue[i]);
    }
}

void enqueueRequest(ProcessingSettings settings) {
    pthread_mutex_lock(&requestQueueMutex);

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; ++i) {
        if (queue_empty(&requestQueue[i])) {
            queue_push(&requestQueue[i], settings);
            pthread_mutex_unlock(&requestQueueMutex);
            pthread_cond_signal(&requestQueueCond);
            break;
        }
    }

    if (i == MAX_CONCURRENT_REQUESTS) { // All queues are full, wait for a space to become available
        pthread_mutex_unlock(&requestQueueMutex);
        pthread_cond_wait(&requestQueueCond, &requestQueueMutex);
    }
}

ProcessingSettings dequeueRequest() {
    ProcessingSettings settings;
    queue_t *queue = NULL;

    pthread_mutex_lock(&requestQueueMutex);

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; ++i) {
        if (!queue_empty(&requestQueue[i])) {
            queue = &requestQueue[i];
            settings = queue_pop(queue);
            break;
        }
    }

    pthread_mutex_unlock(&requestQueueMutex);

    if (queue == NULL) { // All queues are empty, return an empty structure
        settings.input = NULL;
        settings.maxLength = 0;
        settings.trim = false;
        settings.capitalize = false;
        settings.removePunctuation = false;
        settings.language = NULL;
    }

    return settings;
}

void *processRequests(void *arg) {
    while (1) {
        ProcessingSettings settings = dequeueRequest();
        if (!settings.input) break; // All requests have been processed, exit the loop

        processUserInput(settings);
    }

    return NULL;
}

void run() {
    logFile = fopen("process_log.txt", "w");
    initRequestQueue();

    pthread_t threads[MAX_CONCURRENT_REQUESTS];

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; ++i) {
        if (pthread_create(&threads[i], NULL, processRequests, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            exit(1);
        }
    }

    // Process user input here and enqueue it using enqueueRequest()

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(logFile);
}
