**JavaScript Function**

```javascript
const asyncArrayReduce = (arr, initialValue, reducer, config) =>
    new Promise((resolve, reject) => {
        const maxConcurrent = Math.min(config.maxParallel || 4, arr.length);
        let completedOps = 0;
        const semaphore = new Promise((res) => res({ signal: res }));
        const cache = new Map();

        const worker = (index, resolveAll, rejectAll) => {
            if (index >= arr.length) {
                resolveAll(null);
                return;
            }

            let value = cache.get(arr[index].word);
            if (!value) {
                fetch(`https://api-url.com/${arr[index].word}`, {
                    headers: {
                        Authorization: `Bearer ${config.api_token}`
                    }
                })
                    .then((res) => res.json())
                    .then((data) => {
                        value = reducer(value, data);
                        cache.set(arr[index].word, value);
                        worker(index + 1, resolveAll, rejectAll);
                    })
                    .catch((err) => {
                        console.error(`Error fetching ${arr[index].word}:`, err);
                        if (config.cache_policy === 'ignore') {
                            worker(index + 1, resolveAll, rejectAll);
                        } else {
                            rejectAll(err);
                        }
                    });
            } else {
                worker(index + 1, resolveAll, rejectAll);
            }
        };

        const start = Date.now();
        Promise.all([semaphore, ...Array(maxConcurrent).fill().map(() => worker(0, (result) => {
            completedOps += result ? result.length : 1;
            if (config.callback) config.callback(completedOps, reduceResult);
            if (completedOps === arr.length) resolve(reduceResult);
        }, (error) => reject(error)))]).then((results) => {
            const duration = Date.now() - start;
            const reduceResult = config.reducer(initialValue, results[0][1]);
            if (config.callback) config.callback(completedOps, reduceResult);
            if (duration > config.throttle_interval * completedOps) {
                setTimeout(() => asyncArrayReduce(arr, initialValue, reducer, config), config.throttle_interval);
            }
        });
    });
```

