#include <functional>

struct AttackProfile {
    std::string name;
    int damage;
    float costEnergy;
    int cooldownSeconds;
    std::vector<std::function<void(Character&)}} specialEffects;
};

class Character {
public:
    float health;
    float energy;
    float distanceToEnemy;

    // Set the character's state or update it through an external API call.
    void setState(const CharacterState& state) {
        // Update character attributes based on the provided state.
    }

    AttackProfile selectAttack() const {
        std::vector<AttackProfile> availableAttacks;

        // Filter out attack profiles with cooldowns or resource limitations.
        for (const auto& profile : attackProfiles) {
            if (cooldownMap[profile.name].expired()) {
                if (energy >= profile.costEnergy && distanceToEnemy <= MAX_DISTANCE_TO_ENEMY) {
                    availableAttacks.push_back(profile);
                }
            }
        }

        // Sort available attacks based on some strategy, e.g., damage first.
        std::sort(availableAttacks.begin(), availableAttacks.end());

        // Return the best attack, or a default non-attack action if no attack is available.
        return availableAttacks.empty() ? DEFAULT_NON_ATTACK : availableAttacks[0];
    }
private:
    std::unordered_map<std::string, std::chrono::steady_clock::time_point> cooldownMap; // Stores the last time an attack was used.
    const std::vector<AttackProfile> attackProfiles;
};
```

