```python
# json_base/__init__.py
from abc import ABC, abstractmethod
import yaml
from threading import Lock
from time import time
from typing import Any, Dict, Type, Union
import os
import json

class JSONBase(ABC):
    def to_json(self) -> str:
        pass

    @classmethod
    def from_json(cls, data: Union[str, dict]) -> "JSONBase":
        pass

    @staticmethod
    def load_yaml_registry(file_path: str) -> None:
        with open(file_path, 'r') as f:
            registry = yaml.safe_load(f)
            for class_id, data in registry.items():
                cls = JSONBase._get_class(data['class'])
                instance = cls.from_json(data['instance'])
                JSONBase.registry[class_id] = (cls, instance)

    @staticmethod
    def save_registry(file_path: str) -> None:
        registry = {k: v[0].__name__ + ':' + str(v[1]) for k, v in JSONBase.registry.items()}
        with open(file_path, 'w') as f:
            yaml.dump(registry, f)

    @staticmethod
    def _get_class(name: str) -> Type["JSONBase"]:
        module_name, class_name = name.rsplit('.', 1)
        __import__(module_name)
        return getattr(__import__(module_name), class_name)

    @staticmethod
    def _get_registry() -> Dict[str, (Type["JSONBase"], "JSONBase")]:
        if not hasattr(JSONBase, '_registry_lock'):
            JSONBase._registry_lock = Lock()
        return getattr(JSONBase, '_registry', {})

    @classmethod
    def register(cls) -> None:
        class_id = cls.__name__
        if not hasattr(cls, '__json_class_id__'):
            cls.__json_class_id__ = class_id
        if class_id in JSONBase._get_registry():
            raise ValueError(f"Subclass {cls.__name__} is already registered.")
        JSONBase._get_registry()[class_id] = (cls, None)

    @classmethod
    def discover_subclasses(directory: str) -> None:
        for root, dirs, files in os.walk(directory):
            for file in files:
                if file.endswith('.py'):
                    module = __import__(os.path.split(root)[1])
                    for name, obj in vars(module).items():
                        if isinstance(obj, type) and issubclass(obj, JSONBase):
                            obj.register()

# json_base/registry.py
JSONBase._registry = {}

# subclasses/my_class.py
from json_base import JSONBase

class MyClass(JSONBase):
    __json_class_id__ = 'my_class'

    def to_json(self) -> str:
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, data: Union[str, dict]) -> "MyClass":
        if isinstance(data, str):
            data = json.loads(data)
        instance = MyClass()
        for key, value in data.items():
            setattr(instance, key, value)
        return instance
