const fs = require('fs');
const path = require('path');
const minimatch = require('minimatch');
const chokidar = require('chokidar');
const nodeFetch = require('node-fetch');
const LRUCache = require('lru-cache');
const dotenv = require('dotenv');

// Load environment variables
dotenv.config();

// Configuration
const concurrency = parseInt(process.env.CONCURRENCY || 4);
const maxRetries = parseInt(process.env.MAX_RETRIES || 3);
const backoff = Math.pow(2, process.env.BACKOFF || 1);
const logLevel = process.env.LOG_LEVEL || 'info';
const caching = Boolean(process.env.CACHE === 'true');
const cacheSize = parseInt(process.env.CACHE_SIZE || 1000);

// Logging function
function log(level, message) {
  if (logLevel !== 'silent') {
    const logger = console[level] || console.error;
    logger(`${level.toUpperCase()}: ${message}`);
  }
}

// Cache for storing processed files to minimize redundant file retrievals
const cache = new LRUCache({ max: cacheSize });

// Util function for retrying failed file fetches
async function retryFetch(url, attempts) {
  if (attempts > maxRetries) {
    log('error', `Failed to fetch URL after ${maxRetries} retries: ${url}`);
    throw new Error(`Failed to fetch URL after ${maxRetries} retries`);
  }

  try {
    return await nodeFetch(url, { retry: attempts > 1 });
  } catch (error) {
    log('warning', `Failed to fetch URL (${attempts} of ${maxRetries}). Retrying...\n${error.message}`);
    return await retryFetch(url, attempts + 1);
  }
}

// Function for processing files based on given filters
function processFiles(dir, extensions, callback) {
  fs.readdir(dir, (err, files) => {
    if (err) {
      log('error', `Failed to read directory: ${dir}\n${err.message}`);
      return;
    }

    const pending = [];

    files.forEach((file) => {
      const filePath = path.join(dir, file);

      if (fs.statSync(filePath).isDirectory()) {
        // Recursively process directories
        processFiles(filePath, extensions, callback);
      } else {
        // Check for matching extension(s) and process the file if it matches
        const match = extensions.some((ext) => minimatch(path.extname(file), ext));
        if (match) {
          // Handle large files using streaming
          const stream = fs.createReadStream(filePath);
          pending.push({ stream, filePath });
        }
      }
    });

    if (!pending.length) {
      log('info', 'Finished processing all files');
      return callback();
    }

    let processed = 0;
    const processNextFile = () => {
      if (!pending.length || processed >= pending.length) {
        // Finished processing all files and streams
        log('info', 'Finished processing all files and streams');
        return callback();
      }

      const { stream, filePath } = pending[processed];
      stream.on('error', (error) => {
        log('error', `Error while processing file: ${filePath}\n${error.message}`);
      });
      stream.on('end', processNextFile);
      stream.pipe(process, { end: false });
      processed++;
    };

    processNextFile();
  });
}

// Function for fetching and processing files asynchronously
async function fetchAndProcessFiles(url, dir, extensions) {
  // Handle file system changes by using chokidar to watch the remote server or local machine
  const watcher = chokidar.watch([dir], { ignoreInitial: true });

  watcher.on('add', (path) => {
    log('info', `New file added: ${path}`);
    fetchAndProcessFiles(url, path, extensions);
  });

  watcher.on('change', (path) => {
    log('info', `File changed: ${path}`);
    fetchAndProcessFiles(url, path, extensions);
  });

  try {
    // Retrieve the directory content from the remote server or local file system
    const response = await nodeFetch(url);
    const content = await response.text();

    // Parse the content as a JSON object and extract the directory path
    const data = JSON.parse(content);
    const dirPath = data.directory;

    // Check if the directory already exists in cache, use it directly if found
    const cachedDir = cache.get(dirPath);
    if (cachedDir) {
      log('info', `Using cached directory: ${dirPath}`);
      return processFiles(cachedDir, extensions, () => {});
    }

    // Otherwise, retrieve the directory content again and process the files
    await fs.mkdirSync(dirPath);
    fs.writeFileSync(path.join(dirPath, 'index.json'), JSON.stringify(data));
    fetchAndProcessFiles(url, dirPath, extensions);
  } catch (error) {
    log('error', `Error while fetching and processing files: ${url}\n${error.message}`);
    throw error;
  }
}
```

