class BibleTextAnalyzer {
  constructor() {}

  static REGEX_OLD_TESTAMENT = /[Oo]ld\s+[Tt]estament\b/gi;
  static REGEX_NEW_TESTAMENT = /New\s+Testament\b/gi;
  static REGEX_BOOKS = {
    OT: /Matthew|Mark|Luke|John|Acts|Romans|1Corinthians|2Corinthians|Galatians|Ephesians|Philippians|Colossians|1Thessalonians|2Thessalonians|1Timothy|2Timothy|Titus|Philemon|Hebrews|James|1Peter|2Peter|1John|2John|3John|Jude|Revelation/gi,
    NT: /Matthew|Mark|Luke|John|Acts|Romans|1Corinthians|2Corinthians|Galatians|Ephesians|Philippians|Colossians|1Thessalonians|2Thessalonians|1Timothy|2Timothy|Titus|Philemon|Hebrews|James|1Peter|2Peter|2John|3John|Jude|Revelation/gi
  };

  static analyze(text) {
    if (!text || typeof text !== 'string') throw new Error('Invalid input');

    let otMatches = text.match(BibleTextAnalyzer.REGEX_BOOKS.OT);
    let ntMatches = text.match(BibleTextAnalyzer.REGEX_BOOKS.NT);

    if (otMatches && ntMatches) {
      throw new Error('Invalid input, found both Old and New Testament books');
    }

    const results = {};
    if (otMatches) results.OT = otMatches;
    if (ntMatches) results.NT = ntMatches;

    return results;
  }
}
