```sql
CREATE PROCEDURE GetEmployeesWithWeather
    @SupervisorID INT,
    @PageSize INT = 10,
    @PageIndex INT = 1
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        e.Name AS EmployeeName,
        e.City,
        e.Address,
        COUNT(d.ID) AS DirectReports,
        w.WeatherData
    FROM
        Employees e
            LEFT JOIN DirectReports d ON e.ID = d.SupervisorID
            LEFT JOIN (
                SELECT City, WeatherData = json_query(apiCall.result, '$.weather') AS WeatherData
                FROM OpenWeatherApiCalls owc
                    INNER JOIN OPENJSON((SELECT apiCall FROM (SELECT TOP (1) apiCall FROM OpenWeatherApiCalls WHERE City = e.City ORDER BY CalledAt DESC) as temp), '$.weather') AS weatherData
                WHERE owc.City = e.City AND DATEDIFF(MINUTE, owc.CalledAt, GETDATE()) <= 60
            ) w ON 1=1
    GROUP BY
        e.Name,
        e.City,
        e.Address
    ORDER BY
        e.ID OFFSET (@PageIndex - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
```

