```javascript
const net = require('net');
const { promisify } = require('util');
const cache = new Map(); // In-memory cache
const maxConnections = 100;
const rateLimitInterval = 60 * 1000; // 1 minute interval for rate limiting
let connectionCount = 0;
const log = (message) => console.log(`[Server]: ${message}`);

// Promisified versions of socket events
const connect = promisify(Socket.prototype.connect);
const data = promisify(Socket.prototype.getDataStream 'pipe');

class Socket extends net.Socket {
  constructor(socket) {
    super(socket);
    this.id = ++connectionCount;
  }

  async handleRateLimit() {
    if (!this.rateLimited) {
      clearTimeout(this.rateLimitTimeout);
      this.rateLimited = false;
    } else {
      return log(`Client ${this.id}: Rate-limited.`);
    }
  }

  async handleConnection() {
    try {
      await this.handleRateLimit();
      this.on('data', handleData);
      this.on('end', handleEnd);
    } catch (error) {
      log(`Client ${this.id}: Error: ${error}`);
      this.destroy();
    }
  }

  async handleData(chunk) {
    try {
      const key = JSON.parse(chunk).key;
      if (!cache.has(key)) cache.set(key, new Set());
      cache.get(key).add(this);
      log(`Client ${this.id}: Stored data for key "${key}"`);
    } catch (error) {
      log(`Client ${this.id}: Error: ${error}`);
    }
  }

  async handleEnd() {
    if (cache.has(this.data)) {
      cache.get(this.data).delete(this);
      if (cache.get(this.data).size === 0) cache.delete(this.data);
      log(`Client ${this.id}: Removed data for key "${this.data}"`);
    }
    this.destroy();
  }
}

const server = net.createServer((socket) => {
  new Socket(socket).handleConnection();
});

server.on('error', (error) => log(`Server: Error: ${error}`));
server.on('listening', () => log('Server listening on the port'));

server.listen(3000, { backlog: maxConnections });

setInterval(() => {
  if (connectionCount === 0) return;
  log('Graceful shutdown starting...');
  server.close(() => process.exit());
}, rateLimitInterval);
```

This code creates a simple TCP server using the `net` module that manages incoming connections efficiently, has an in-memory cache for storing and retrieving data from clients, implements a rate-limiting mechanism, and uses logging to record all server activities. The server will gracefully shutdown every minute if there are no active connections.

