class ImageProcessor {
public:
    ImageProcessor(const std::string& inputPath, const std::string& outputDir, const std::string& format)
        : _inputPath(inputPath), _outputDir(outputDir), _format(format) {}

    void processImage() {
        Magick::Image img;
        try {
            img.read(_inputPath);
            Magick::WriteImage(Magick::Image(_inputPath), format(), _outputDir + "/" + img.filename() + "." + _format);
        } catch (const Exception& e) {
            handleError(e);
        }
    }

    ProcessingStatus getProcessingStatus() const { return _processingStatus; }

    void enqueueForConversion() {
        std::unique_lock<std::mutex> lock(_queueMutex);
        _conversionQueue.push([this](){ processImage(); });
    }

    bool cancelOngoingConversions() {
        std::unique_lock<std::mutex> lock(_queueMutex);
        while (!_conversionQueue.empty()) {
            _cancelEvent.notify_one();
            lock.wait(lock, [this](){ return !_conversionQueue.empty() && _cancelRequested; });
        }
        _cancelRequested = false;
        return true;
    }

private:
    void handleError(const Magick::Exception& e) {
        std::cerr << "Error processing image: " << e.what() << '\n';
        _processingStatus = ProcessingStatus::Failure;
        logConversionAttemptDetails();
    }

    void logConversionAttemptDetails() const {
        // Implement logging functionality here
    }

    std::string _inputPath, _outputDir, _format;
    ProcessingStatus _processingStatus = ProcessingStatus::Failure;
    std::queue<std::function<void()>> _conversionQueue;
    std::condition_variable _cancelEvent;
    bool _cancelRequested = false;
    std::mutex _queueMutex;
};
