import os
import json
import cryptography
from cryptography.fernet import Fernet
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import serialization, hashes
from cryptography.hazmat.primitives.asymmetric import rsa
import requests
from requests.auth import HTTPBasicAuth
import threading
import logging
import time
from datetime import datetime, timedelta

class SecureFileStorage:
    def __init__(self, config_file, kms_url, auth):
        self.config = self._load_config(config_file)
        self.kms_url = kms_url
        self.auth = auth
        self.keys = {}
        self._key_pool = threading.LocalThreadSafeDictionary()
        self.rate_limiter = threading.Semaphore(self.config['rate_limit'])
        self.log = logging.getLogger(__name__)

    def _load_config(self, config_file):
        with open(config_file) as f:
            return json.loads(f.read())

    def fetch_key(self, algorithm):
        if algorithm not in self.keys:
            key = requests.get(f"{self.kms_url}/{algorithm}", auth=self.auth).content
            pem_key = serialization.load_pem_private_key(key, password=b'secret-password', backend=default_backend())
            self.keys[algorithm] = {
                'key': key,
                'key_obj': pem_key
            }
        return self.keys[algorithm]['key_obj']

    def _encrypt(self, data, algorithm):
        key = self.fetch_key(algorithm)
        f = Fernet(key)
        return f.encrypt(data).decode()

    def _decrypt(self, encrypted_data, algorithm):
        key = self.fetch_key(algorithm)
        f = Fernet(key)
        return f.decrypt(encrypted_data)

    def encrypt_file(self, filepath, algorithm, output_file=None):
        if not output_file:
            output_file = f'{os.path.splitext(filepath)[0]}-enc.{os.path.splitext(filepath)[1]}'

        with open(filepath, 'rb') as infile:
            data = infile.read()
            encrypted_data = self._encrypt(data, algorithm)

        with open(output_file, 'wb') as outfile:
            outfile.write(encrypted_data)

    def decrypt_file(self, filepath, algorithm, output_file=None):
        if not output_file:
            output_file = f'{os.path.splitext(filepath)[0]}-dec.{os.path.splitext(filepath)[1]}'

        with open(filepath, 'rb') as infile:
            encrypted_data = infile.read()
            decrypted_data = self._decrypt(encrypted_data, algorithm)

        with open(output_file, 'wb') as outfile:
            outfile.write(decrypted_data)

    @threading.locks.ThreadLockContextManager.requested_by_current_thread()
    def get_key(self, algorithm):
        key = self._key_pool.get(algorithm)
        if not key:
            key = self.fetch_key(algorithm)
            self._key_pool[algorithm] = key
        return key

