class SerializableOctreeCache {
public:
    std::unique_ptr<Octree> getOrCreate(const void* serializedData, size_t serializationSize) {
        auto it = cache.find(reinterpret_cast<uintptr_t>(serializedData));
        if (it != cache.end())
            return it->second;

        try {
            JNIEnv *env;
            jclass octreeClass;
            jmethodID constructor;
            jobject serializedObject = Java_SerializeHelper::deserialize(env, serializedData, serializationSize);
            octreeClass = env->FindClass("SerializableOctree");
            constructor = env->GetMethodID(octreeClass, "<init>", "([B)V");

            jobject OctreeInstance = env->NewObject(octreeClass, constructor, serializedData);
            auto octreePtr = std::unique_ptr<Octree>(static_cast<Octree*>(env->NewGlobalRef(OctreeInstance)));
            cache[reinterpret_cast<uintptr_t>(serializedData)] = std::move(octreePtr);
            return octreePtr;
        } catch (const std::exception &e) {
            std::cerr << "Error during deserialization: " << e.what() << std::endl;
            throw;
        }
    }

private:
    std::unordered_map<uintptr_t, std::unique_ptr<Octree>> cache;
};

class InitializableSerializableOctree {
public:
    std::unique_ptr<Octree> initializeSerializableOctree(size_t featureSize, size_t initialLeafNodes, size_t maxDataCapacity) {
        auto serializedData = readSerializedObjectFromFile("octree.ser"); // Adjust this line to load the serialized octree from a suitable location or stream
        return serializableOctreeCache.getOrCreate(serializedData.data(), serializedData.size());
    }

private:
    static SerializableOctreeCache serializableOctreeCache;
};

// Assuming you have a helper class Java_SerializeHelper for serialization and deserialization using Java
std::unique_ptr<char[]> readSerializedObjectFromFile(const std::string &filename) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open())
        throw std::runtime_error("Could not open the serialized octree file: " + filename);

    std::streampos size;
    file.seekg(0, std::ios::end);
    size = file.tellg();
    file.seekg(0, std::ios::beg);

    auto data = std::make_unique<char[]>(size);
    file.read(data.get(), size);
    if (file.gcount() != size)
        throw std::runtime_error("Failed to read the entire serialized octree from file");

    return data;
}
