    private static final int RETRY_DELAY_MS = 5000;
    private static final OkHttpClient httpClient = new OkHttpClient();

    public static PokemonScriptResponse authAndCacheUserScripts(Pokemon pokemon, String directoryPath) {
        if (!new File(directoryPath + "/web.config").exists()) {
            return null;
        }

        RedisTemplate<String, String> redisTemplate = new RedisTemplate<>();
        Jedis jedis = new Jedis();

        List<ScriptObject> scripts = getScriptObjectsFromDirectory(directoryPath);
        ScriptObject[] filteredScripts = filterInvalidScriptKeys(scripts);

        Map<String, String> scriptMetadata = getScriptMetadata(filteredScripts);

        for (ScriptObject script : filteredScripts) {
            String cachedContent = redisTemplate.opsForValue().get(script.getKey());
            if (cachedContent == null || !isContentCurrent(jedis, cachedContent, scriptMetadata.get(script.getKey()))) {
                String content = fetchAndCacheScript(httpClient, script);
                if (content != null) {
                    redisTemplate.opsForValue().set(script.getKey(), content);
                }
            }
        }

        StringBuilder renderedScripts = new StringBuilder();
        for (ScriptObject script : filteredScripts) {
            String content = redisTemplate.opsForValue().get(script.getKey());
            if (content != null) {
                renderedScripts.append(sanitizeContent(content)).append("\n");
            }
        }

        PokemonScriptResponse response = new PokemonScriptResponse();
        response.setPokemon(pokemon);
        response.setScripts(renderedScripts.toString());

