package com.mycompany.commandexecutor;

import java.io.*;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class CommandExecutor {
    private static final Logger LOGGER = Logger.getLogger(CommandExecutor.class.getName());
    private String dbUrl, dbUsername, dbPassword;
    private int maxRetries, retryDelay;
    private ExecutorService executor;

    // Constructor, setters and getters for the properties

    public void executeCommands(List<String> commands) {
        try (Connection connection = DriverManager.getConnection(dbUrl, dbUsername, dbPassword)) {
            executor = Executors.newCachedThreadPool();

            for (int i = 0; i < maxRetries; i++) {
                boolean success = true;

                Process process;
                BufferedReader inputStreamReader, errorStreamReader;
                String command = commands.get(i);

                File fileToDelete = new File("path/to/yourfile");
                if (fileToDelete.exists()) {
                    fileToDelete.delete();
                }

                process = Runtime.getRuntime().exec(command);

                inputStreamReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                errorStreamReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                String line;
                while ((line = inputStreamReader.readLine()) != null) {
                    System.out.println(line);
                }

                while ((line = errorStreamReader.readLine()) != null) {
                    LOGGER.log(Level.SEVERE, line);
                    success = false;
                }

                if (!success) {
                    Thread.sleep(retryDelay * 1000L);
                    continue;
                }

                storeResultInDatabase(connection, command);
            }
        } catch (IOException | InterruptedException | SQLException e) {
            LOGGER.log(Level.SEVERE, e.getMessage(), e);
        }
    }

    private void storeResultInDatabase(Connection connection, String command) throws SQLException {
        PreparedStatement statement = connection.prepareStatement("INSERT INTO commands_execution (command, result) VALUES (?, ?)");
        statement.setString(1, command);
        statement.setString(2, "SUCCESS"); // or failure depending on the execution status
        statement.executeUpdate();
    }

    public static void main(String[] args) {
        CommandExecutor executor = new CommandExecutor();
        executor.setDbUrl("jdbc:mysql://localhost/command_execution?useSSL=false");
        executor.setDbUsername("username");
        executor.setDbPassword("password");
        executor.setMaxRetries(3);
        executor.setRetryDelay(5); // seconds
        List<String> commands = Arrays.asList("mkdir", "touch", "ls");
        executor.executeCommands(commands);
    }
}
```

