#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_THREADS 10
#define QUEUE_CAPACITY 10

typedef struct {
    sem_t empty; // Semaphore to indicate if the queue is empty
    sem_t full; // Semaphore to indicate if the queue is full
    sem_t mutex; // Semaphore for thread synchronization
    char data[QUEUE_CAPACITY][256];
    size_t head, tail;
} Queue;

Queue *queue_init(size_t capacity) {
    Queue *q = malloc(sizeof(Queue));
    if (!q) return NULL;

    if (sem_init(&q->empty, 1, capacity)) {
        free(q);
        return NULL;
    }
    if (sem_init(&q->full, 0, 0)) {
        sem_destroy(&q->empty);
        free(q);
        return NULL;
    }
    if (sem_init(&q->mutex, 1, 1)) {
        sem_destroy(&q->empty);
        sem_destroy(&q->full);
        free(q);
        return NULL;
    }

    q->head = q->tail = 0;
    return q;
}

void enqueue(Queue *q, const char *data) {
    sem_wait(&q->mutex);

    if (q->tail == (QUEUE_CAPACITY + q->head) % QUEUE_CAPACITY) {
        // Queue is full; wake up a consumer thread
        sem_post(&q->full);
    }

    strcpy(q->data[q->tail], data);
    q->tail = (QUEUE_CAPACITY + q->tail + 1) % QUEUE_CAPACITY;

    // Wake up a producer thread if the queue is not empty
    if (q->head != q->tail) {
        sem_post(&q->empty);
    }

    sem_post(&q->mutex);
}

char *dequeue(Queue *q) {
    char *data;

    sem_wait(&q->mutex);

    if (q->head == q->tail) {
        // Queue is empty; return NULL and wake up a producer thread if necessary
        data = NULL;
        if (q->empty && !sem_trywait(&q->full)) {
            sem_post(&q->mutex);
            sem_wait(&q->full);
        }
    } else {
        data = q->data[q->head];
        q->head = (QUEUE_CAPACITY + q->head + 1) % QUEUE_CAPACITY;
        // Wake up a consumer thread if the queue is not empty
        if (q->head != q->tail) {
            sem_post(&q->empty);
        }
    }

    sem_post(&q->mutex);

    return data;
}

bool isQueueEmpty(const Queue *q) {
    bool empty;

    sem_wait(&q->mutex);
    empty = (q->head == q->tail);
    sem_post(&q->mutex);

    return empty;
}

void *producer(void *arg) {
    // Implement the producer logic here using Bluebird, Logger, File Uploader, etc.
    // ...
    return NULL;
}

void *consumer(void *arg) {
    // Implement the consumer logic here using Bluebird, Logger, File Uploader, etc.
    // ...
    return NULL;
}

void queue_destroy(Queue *q) {
    sem_destroy(&q->empty);
    sem_destroy(&q->full);
    sem_destroy(&q->mutex);
    free(q);
}

int main() {
    Queue *queue = queue_init(QUEUE_CAPACITY);
    pthread_t producers[MAX_THREADS], consumers[MAX_THREADS];

    // Initialize and start producer threads
    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&producers[i], NULL, producer, NULL);
    }

    // Initialize and start consumer threads
    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&consumers[i], NULL, consumer, NULL);
    }

    // Wait for all threads to finish execution
    for (size_t i = 0; i < MAX_THREADS * 2; ++i) {
        pthread_join(producers[i % MAX_THREADS], NULL);
        pthread_join(consumers[i % MAX_THREADS], NULL);
    }

    queue_destroy(queue);

    return 0;
}
```

This code provides a basic structure for a thread-safe queue using semaphores and includes functions to enqueue, dequeue, and check if the queue is empty. The program creates producer threads that fill the queue with data and consumer threads that process the data. The number of producers and consumers can be configured by changing the value of MAX_THREADS.

The main function initializes the queue, creates and starts both types of threads, waits for them to finish execution, and then cleans up resources before exiting. It is important to implement the producer and consumer functions with your preferred file uploading library.

