import java.io.File;
import java.nio.channels.*;
import java.net.InetSocketAddress;
import java.util.*;
import java.util.concurrent.*;
import java.awt.ImageIO;
import java.awt.image.BufferedImage;
import javax.imageio.stream.FileImageInputStream;
import com.itextpdf.kernel.events.PdfDocumentEvent;
import com.itextpdf.kernel.pdf.PdfDocument;
import com.itextpdf.kernel.pdf.PdfWriter;
import com.itextpdf.layout.element.Paragraph;
import com.itextpdf.layout.document.Document;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import net.coobird.thumbnailator.Thumbnails;

public class ImageToPdfConverter {
    private static final Logger LOGGER = LoggerFactory.getLogger(ImageToPdfConverter.class);

    public int convertImages(String inputDir, String pattern, File outputFile, int dpi, ProgressCallback progressCallback) throws Exception {
        if (!new File(inputDir).exists() || !new File(inputDir).isDirectory()) {
            throw new IllegalArgumentException("Invalid input directory.");
        }

        List<File> imageFiles = findMatchingFiles(inputDir, pattern);

        if (imageFiles.isEmpty()) {
            LOGGER.warn("No matching images found in the specified pattern.");
            return 0;
        }

        // Handle connection state changes
        SocketChannel socketChannel = SocketChannel.open();
        socketChannel.connect(new InetSocketAddress("remote-address", port));

        try (socketChannel) {
            PdfDocument pdfDoc = new PdfDocument(new PdfWriter(outputFile));
            Document doc = new Document(pdfDoc);

            ExecutorService executor = Executors.newCachedThreadPool();
            List<Future<Integer>> futures = new ArrayList<>();

            int currentIndex = 0;
            for (File imageFile : imageFiles) {
                int finalCurrentIndex = currentIndex++;
                Runnable runnableTask = () -> {
                    try {
                        BufferedImage image = ImageIO.read(new FileImageInputStream(imageFile));
                        Thumbnails.of(imageFile)
                            .size(Thumbnails.ofWidth(dpi), Thumbnails.onlyOfType(Thumbnails.JPEG))
                            .toBufferedImage();

                        pdfDoc.addNewPage();
                        ImageIO.write(image, "jpg", pdfDoc.getOutputStream());
                    } catch (Exception e) {
                        LOGGER.error("Error converting image: {}", e.getMessage());
                        return 1;
                    } finally {
                        progressCallback.onProgress((double) finalCurrentIndex / imageFiles.size());
                    }
                    return 0;
                };

                Future<Integer> future = executor.submit(runnableTask);
                futures.add(future);
            }

            for (Future<Integer> future : futures) {
                int result = future.get();
                if (result > 0) {
                    return result;
                }
            }

            pdfDoc.close();
            doc.close();
            executor.shutdownNow();
        } catch (Exception e) {
            LOGGER.error("Error establishing connection: {}", e.getMessage());
        }

        return 0;
    }

    private List<File> findMatchingFiles(String inputDir, String pattern) {
        File directory = new File(inputDir);
        File[] files = directory.listFiles((dir, name) -> (name != null) && name.toLowerCase().matches(pattern));
        return Arrays.asList(files);
    }

    // Define ProgressCallback interface and implementation here...
}
```

