```csharp
using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace SecureMessageHandler
{
    public abstract class CspAdapter
    {
        protected readonly HttpClient _httpClient;

        protected CspAdapter(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public abstract Task<KeyAndIv> GetDecryptionKeysAndIvAsync(string contextId);
    }

    public class SecureMessageHandler
    {
        private readonly CspAdapter _cspAdapter;
        private readonly ConcurrentDictionary<string, KeyAndIv> _decryptionContexts = new ConcurrentDictionary<string, KeyAndIv>();

        public SecureMessageHandler(CspAdapter cspAdapter)
        {
            _cspAdapter = cspAdapter;
        }

        public async Task DecryptMessageAsync(string base64EncodedMessage, string contextId)
        {
            var decryptionContext = await GetOrCreateDecryptionContextAsync(contextId);
            var plainText = Decrypt(base64EncodedMessage, decryptionContext.Key, decryptionContext.Iv);
            Console.WriteLine($"Decrypted message: {plainText}");
        }

        public async Task DecryptMessagesAsync(List<string> base64EncodedMessages, string contextId)
        {
            var tasks = base64EncodedMessages.Select(DecryptMessageAsync).ToList();
            await Task.WhenAll(tasks);
        }

        private KeyAndIv GetOrCreateDecryptionContextAsync(string contextId)
        {
            return _decryptionContexts.GetOrAdd(contextId, async keyId =>
            {
                var decryptionKeysAndIv = await _cspAdapter.GetDecryptionKeysAndIvAsync(keyId);
                return decryptionKeysAndIv;
            });
        }

        private static string Decrypt(string cipherText, RSA rsa, byte[] iv)
        {
            var decryptedBytes = rsa.Decrypt(Convert.FromBase64String(cipherText), RSAEncryptionPadding.Pkcs1);
            var decryptedText = Encoding.UTF8.GetString(decryptedBytes);
            return DecryptWithIv(decryptedText, iv);
        }

        private static string DecryptWithIv(string encryptedData, byte[] iv)
        {
            using (var aes = Aes.Create())
            {
                using (var decrytor = aes.CreateDecryptor(aes.Key, iv))
                {
                    var plainTextBytes = decrytor.TransformFinalBlock(Convert.FromBase64String(encryptedData), 0, encryptedData.Length);
                    return Encoding.UTF8.GetString(plainTextBytes);
                }
            }
        }
    }

    public class KeyAndIv
    {
        public RSA Key { get; set; }
        public byte[] Iv { get; set; }
    }
}
```

This code provides a starting point for the SecureMessageHandler. The class implements an abstract `CspAdapter` base class, which serves as an adapter pattern to support different CSPs. The `SecureMessageHandler` uses this adapter to decrypt messages in an asynchronous manner. To complete the implementation, you will need to extend the `CspAdapter` for each supported CSP and implement their unique APIs and authentication mechanisms. Additionally, you should handle key management strategies, error handling, concurrency, scalability, and configuration flexibility as specified.

