```python
import json
import datetime
import uuid
from decimal import Decimal
from typing import Any, Callable, Dict, Type

class JSONSerializable:
    _factories: Dict[str, Callable[[Any], Type]] = {}

    def to_json(self) -> str:
        # Perform custom serialization for specific data types
        if isinstance(self, datetime.datetime):
            return self.isoformat()
        elif isinstance(self, uuid.UUID):
            return str(self)
        elif isinstance(self, Decimal):
            return str(self)

        # Serialize basic Python types and custom objects using json's default function
        return json.dumps(self, default=self.__getnewargs__())

    @classmethod
    def from_json(cls, json_string: str) -> 'JSONSerializable':
        obj = json.loads(json_string)
        if isinstance(obj, dict):
            id_ = obj.pop('__type__')
            factory = cls._factories[id_]
            return factory(**obj)
        else:
            # Handle basic Python types and custom objects using json's default function
            return json.JSONDecoder().decode(json_string)

    @classmethod
    def add_factory_function(cls, id_: str, factory: Callable[[Any], Type]) -> None:
        cls._factories[id_] = factory

    @classmethod
    def create_instance_from_id(cls, id_: str, **kwargs) -> 'JSONSerializable':
        factory = cls._factories.get(id_)
        if factory:
            return factory(**kwargs)
        else:
            raise ValueError(f"No factory function found for ID '{id_}'")

# Example usage:
class MyCustomClass(JSONSerializable):
    def __init__(self, value: int):
        self.value = value

JSONSerializable.add_factory_function('MyCustomClass', MyCustomClass)
obj = MyCustomClass(42)
json_str = obj.to_json()  # '{"__type__": "MyCustomClass", "value": 42}'
new_obj = JSONSerializable.from_json(json_str)  # <MyCustomClass object: value=42>
```
This code defines a `JSONSerializable` class that can be extended to create custom classes which support serialization and deserialization of JSON strings. The `to_json` method handles basic Python types, custom objects, and specific data types like `datetime`, `UUID`, and `Decimal`. The `from_json` method is used for creating instances from JSON strings. The `add_factory_function` function adds new factory functions to the registry, while `create_instance_from_id` creates an instance using the factory function associated with a given ID.

The code also includes an example of a custom class called `MyCustomClass`. This class demonstrates how to extend the base `JSONSerializable` class for custom serialization and deserialization logic.

