2. Semaphore Management System (source)

```c
#include "semaphore.h"

void semaphore_init(Semaphore* sem, int initial_value) {
    sem->count = initial_value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
}

bool semaphore_wait(Semaphore* sem) {
    bool success = true;
    pthread_mutex_lock(&sem->mutex);
    while (sem->count <= 0 && success) {
        success = pthread_cond_wait(&sem->cond, &sem->mutex) == 0;
    }

    if (success) sem->count--;
    pthread_mutex_unlock(&sem->mutex);

    return success;
}

void semaphore_signal(Semaphore* sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->count++;
    pthread_mutex_unlock(&sem->mutex);

    if (pthread_cond_broadcast(&sem->cond) != 0) {
        fprintf(stderr, "Error broadcasting condition variable.\n");
    }
}

void semaphore_destroy(Semaphore* sem) {
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
}
