4. Cryptographic Function (source)

```c
#include "crypto.h"
#include <openssl/err.h>
#include <openssl/evp.h>
#include <openssl/pkey.h>
#include <openssl/x509.h>
#include <string.h>

Cipher* cipher_create(const char* algorithm, const char* key) {
    Cipher* cipher = malloc(sizeof(Cipher));
    if (!cipher) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    EVP_CIPHER_CTX_init(cipher->ctx);
    int rc = EVP_EncryptInit_ex(cipher->ctx, EVP_by_name(algorithm), NULL, (unsigned char*)key, NULL);
    if (rc <= 0) {
        ERR_print_errors_fp(stderr);
        free(cipher);
        return NULL;
    }

    return cipher;
}

void cipher_destroy(Cipher* cipher) {
    EVP_CIPHER_CTX_cleanup(cipher->ctx);
    free(cipher);
}

int cipher_encrypt(Cipher* cipher, unsigned char* input, size_t length) {
    int len;
    int rc = EVP_EncryptUpdate(cipher->ctx, NULL, &len, input, length);
    if (rc <= 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    rc = EVP_EncryptFinal_ex(cipher->ctx, input + len, NULL);
    if (rc <= 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    return length + len;
}

int cipher_decrypt(Cipher* cipher, unsigned char* input, size_t length) {
    int len;
    int rc = EVP_DecryptUpdate(cipher->ctx, NULL, &len, input, length);
    if (rc <= 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    rc = EVP_DecryptFinal_ex(cipher->ctx, input + len, NULL);
    if (rc <= 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    return length - len;
}
