```java
import java.nio.channels.*;
import java.util.*;
import java.net.InetSocketAddress;
import org.apache.kafka.clients.producer.*;

public class ConnectionPool {
    private final SelectorGroup group;
    private final Map<Integer, SelectionKey> connections;
    private final ExecutorService executor;
    private final Producer<String, String> kafkaProducer;
    private static final int CONNECTION_TIMEOUT = 5000;
    private static final int RETRY_INTERVAL = 1000;

    public ConnectionPool(List<String> remoteAddresses) throws IOException {
        group = Selector.openSelect();
        connections = new HashMap<>();
        executor = Executors.newCachedThreadPool();
        kafkaProducer = createKafkaProducer();

        for (String address : remoteAddresss) {
            SocketChannel socketChannel = SocketChannel.open();
            socketChannel.configureBlocking(false);
            socketChannel.connect(new InetSocketAddress(address, 80));
            connections.put(socketChannel.hashCode(), socketChannel.register(group, SelectionKey.OP_CONNECT));
        }
    }

    private Producer<String, String> createKafkaProducer() {
        // Configure and create a Kafka producer instance here
    }

    public void sendMessage(String message) {
        executor.submit(() -> {
            try {
                group.select();
                Iterator<SelectionKey> iter = group.selectedKeys().iterator();
                while (iter.hasNext()) {
                    SelectionKey key = iter.next();
                    iter.remove();

                    if (key.isConnectable()) {
                        SocketChannel socketChannel = (SocketChannel) key.channel();
                        socketChannel.finishConnect();
                        sendData(socketChannel, message);
                    }
                }
            } catch (Exception e) {
                logError(e);
            }
        });
    }

    private void sendData(SocketChannel socketChannel, String message) throws IOException {
        ByteBuffer buffer = ByteBuffer.wrap(message.getBytes());
        while (buffer.hasRemaining()) {
            socketChannel.write(buffer);
        }
        buffer.clear();
    }

    public void handleConnections() throws IOException {
        while (!Thread.currentThread().isInterrupted()) {
            group.select(CONNECTION_TIMEOUT);
            Iterator<SelectionKey> iter = group.selectedKeys().iterator();
            while (iter.hasNext()) {
                SelectionKey key = iter.next();
                iter.remove();

                if (key.isAcceptable()) {
                    SocketChannel socketChannel = ((ServerSocketChannel) key.channel()).accept();
                    socketChannel.configureBlocking(false);
                    connections.put(socketChannel.hashCode(), socketChannel.register(group, SelectionKey.OP_READ));
                }

                if (key.isReadable()) {
                    SocketChannel socketChannel = (SocketChannel) key.channel();
                    handleRead(socketChannel);
                }

                if (key.isConnectFailed()) {
                    SocketChannel socketChannel = (SocketChannel) key.channel();
                    socketChannel.close();
                    int delay = RETRY_INTERVAL;
                    if (!connections.containsKey(socketChannel.hashCode())) {
                        addToConnectionPool(socketChannel.toString(), delay);
                    }
                    try {
                        Thread.sleep(delay);
                    } catch (InterruptedException e) {}
                }
            }
        }
    }

    private void addToConnectionPool(String remoteAddress, int delay) {
        SocketChannel socketChannel = SocketChannel.open();
        socketChannel.configureBlocking(false);
        socketChannel.connect(new InetSocketAddress(remoteAddress, 80));
        connections.put(socketChannel.hashCode(), socketChannel.register(group, SelectionKey.OP_CONNECT));
    }

    private void handleRead(SocketChannel socketChannel) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocateDirect(1024);
        int bytesRead = socketChannel.read(buffer);
        if (bytesRead > 0) {
            // Process the data and send it to Kafka here
        }
    }

    private void logError(Exception e) {
        // Log error details here for debugging purposes
    }
}
```
