import jwt from 'jsonwebtoken';
import axios from 'axios';
import cache from 'lru-cache';
import expressJWT from 'express-oauth2-jwt-bearer';

// Define custom claims
interface CustomClaims {
  roles: string[];
  exp: number;
}

// Configure OAuth providers and their endpoints
const oauthProviders = {
  google: {
    clientID: process.env.GOOGLE_CLIENT_ID,
    clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    scope: 'profile email',
    authUrl: 'https://accounts.google.com/o/oauth2/auth',
    tokenUrl: 'https://oauth2.googleapis.com/token'
  },
  facebook: {
    clientID: process.env.FACEBOOK_CLIENT_ID,
    clientSecret: process.env.FACEBOOK_CLIENT_SECRET,
    scope: 'email',
    authUrl: 'https://www.facebook.com/v12.0/dialog/oauth',
    tokenUrl: 'https://graph.facebook.com/v12.0/me/access_token'
  }
};

const jwtSecret = process.env.JWT_SECRET;
const userProfileCache = cache({ max: 100, maxAge: 60 * 60 }); // Cache user profiles for 1 hour

async function authenticateUser(req) {
  const provider = req.query.provider;
  const oauthConfig = oauthProviders[provider];

  if (!oauthConfig) {
    return { status: 400, message: 'Invalid OAuth provider' };
  }

  // Use express-oauth2-jwt-bearer middleware to validate the access token
  const oauthMiddleware = expressJWT({
    clientID: oauthConfig.clientID,
    clientSecret: oauthConfig.clientSecret,
    scope: oauthConfig.scope,
    authUrl: oauthConfig.authUrl,
    tokenUrl: oauthConfig.tokenUrl,
  });

  const validatedReq = await oauthMiddleware(req);

  try {
    // Fetch the user's profile information from an external API using the validated OAuth token
    let userProfile = userProfileCache.get(validatedReq.accessToken.rawToken.sub);

    if (!userProfile) {
      const response = await axios.get(`https://graph.facebook.com/v12.0/${validatedReq.accessToken.rawToken.sub}`, { headers: { Authorization: `Bearer ${validatedReq.accessToken.rawToken.token}` } });
      userProfile = response.data;
      userProfileCache.set(validatedReq.accessToken.rawToken.sub, userProfile, 60 * 60); // Cache user profile for 1 hour
    }

    // Generate a JWT with the user's profile information, including custom claims like roles and expiration time
    const payload: any = {
      sub: userProfile.id,
      email: userProfile.email,
      iat: Math.floor(Date.now() / 1000), // Issued at
      exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 7, // Expiration time (1 week)
      roles: ['user'], // Custom claim example
      ...userProfile
    };

    const jwt = jwt.sign(payload, jwtSecret);

    return { status: 200, data: { jwt } };
  } catch (error) {
    console.error(error);
    return { status: error.response ? error.response.status : 500, message: error.message || 'An error occurred during authentication' };
  }
}
