using System;
using System.Text;
using System.Security.Cryptography;
using System.IO;
using Newtonsoft.Json;
using RestSharp;

namespace EncryptionService
{
    public class EncryptionService
    {
        private const string ConfigurationFilePath = "appsettings.json";
        private readonly EncryptionSettings _settings;
        private readonly HMACSHA256 _hmac;

        public EncryptionService()
        {
            _settings = JsonConvert.DeserializeObject<EncryptionSettings>(File.ReadAllText(ConfigurationFilePath));
            using (var hmacKey = new SHA256Managed())
            {
                _hmac = new HMACSHA256(hmacKey.ComputeHash(_settings.DecryptionKey));
            }
        }

        public string DecryptMessage(string encryptedMessage)
        {
            if (!IsBase64Encoded(encryptedMessage))
            {
                throw new ArgumentException("Invalid Base64 encoding");
            }

            var decryptedBytes = DecodeBase64(encryptedMessage);

            try
            {
                using (var tripleDes = TripleDES.Create())
                {
                    tripleDes.Key = _settings.DecryptionKey;
                    tripleDes.IV = GetIV(_settings.IvType, decryptedBytes.Length);

                    var decryptor = new ICryptoTransformDecoder(tripleDes.CreateDecryptor(), null);
                    using (var ms = new MemoryStream(decryptedBytes))
                    {
                        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Buffer))
                        {
                            cs.CopyTo(ms);
                            var decryptedData = ms.ToArray();

                            if (!ValidateHMAC(decryptedData))
                            {
                                throw new AuthenticationException("Invalid authentication");
                            }

                            return GetMessageContent(decryptedData);
                        }
                    }
                }
            }
            catch (CryptographicException ex)
            {
                throw new AuthenticationException($"Decryption failed: {ex.Message}", ex);
            }
        }

        private static byte[] DecodeBase64(string base64EncodedData)
        {
            return Convert.FromBase64String(base64EncodedData);
        }

        private byte[] GetIV(IvType ivType, int length)
        {
            switch (ivType)
            {
                case IvType.Random:
                    return RandomNumberGenerator.GetBytes(length);
                case IvType.CounterBased:
                    // Implement counter-based IV generation here
                    throw new NotImplementedException();
                default:
                    throw new ArgumentOutOfRangeException(nameof(ivType), ivType, null);
            }
        }

        private bool ValidateHMAC(byte[] data)
        {
            var hmac = _hmac.ComputeHash(data);
            return AreByteArraysEqual(hmac, Array.Empty<byte>()); // Empty array should contain the HMAC value from the encrypted message
        }

        private static bool AreByteArraysEqual(byte[] a, byte[] b)
        {
            if (ReferenceEquals(a, b)) return true;
            if (ReferenceEquals(a, null)) return ReferenceEquals(b, null);
            if (a.Length != b.Length) return false;
            for (int i = 0; i < a.Length; ++i)
            {
                if (a[i] != b[i]) return false;
            }
            return true;
        }

        private string GetMessageContent(byte[] data)
        {
            var messageType = Encoding.ASCII.GetString(BitConverter.GetBytes(data[0])); // First byte indicates the message type (e.g., JSON, XML)
            var deserializer = messageType switch
            {
                "JSON" => JsonConvert.DeserializeObject<dynamic>,
                "XML" => // Implement XML deserialization here, using a library like Newtonsoft's XmlSerializer or an alternative approach like Linq to XML
                    throw new NotImplementedException(),
                _ => throw new InvalidOperationException($"Unsupported message type: {messageType}")
            };

            return deserializer(data.AsMemory()).ToString();
        }

        private static readonly Random _random = new Random();

        public void LogDecryptedMessage(string decryptedMessage)
        {
            var client = new RestClient(_settings.LoggingServiceUrl);
            var request = new RestRequest("log", DataFormat.Json)
                .AddParameter("decryptedMessage", decryptedMessage);

            client.ExecuteAsync(request, response =>
            {
                if (response.IsSuccessful)
                {
                    Console.WriteLine($"Logged decrypted message: {decryptedMessage}");
                }
                else
                {
                    Console.WriteLine($"Failed to log decrypted message: {response.ErrorMessage}");
                }
            });
        }

        public void LogError(Exception exception)
        {
            var client = new RestClient(_settings.LoggingServiceUrl);
            var request = new RestRequest("error", DataFormat.Json)
                .AddParameter("exceptionMessage", exception.Message)
                .AddParameter("stackTrace", exception.StackTrace);

            client.ExecuteAsync(request, response =>
            {
                if (response.IsSuccessful)
                {
                    Console.WriteLine($"Logged error: {exception.Message}");
                }
                else
                {
                    Console.WriteLine($"Failed to log error: {response.ErrorMessage}");
                }
            });
        }

        public void SaveEncryptionKeyAndIV(string key, string iv)
        {
            // Implement secure storage of encryption keys and IVs here, using a key management service or HSM
            throw new NotImplementedException();
        }
    }

    public class EncryptionSettings
    {
        public byte[] DecryptionKey { get; set; }
        public string LoggingServiceUrl { get; set; }
        public IvType IvType { get; set; }
    }

    public enum IvType
    {
        Random,
        CounterBased
    }

    public class AuthenticationException : Exception
    {
        public AuthenticationException() {}
        public AuthenticationException(string message) : base(message) {}
        public AuthenticationException(string message, Exception innerException) : base(message, innerException) {}
    }
}
