```javascript
const async = require('async');
const crypto = require('crypto');
const fs = require('fs');
const https = require('https');
const path = require('path');

class ProcessedTransactionResult {
  constructor(weightedSum, transactionId) {
    this.weightedSum = weightedSum;
    this.transactionId = transactionId;
  }
}

function asyncReduceArray(array, initialValue, callback) {
  return new Promise((resolve, reject) => {
    let accumulator = initialValue;
    const tasks = array.map((number, index, self) => {
      return cb => async ((), cb)(accumulator, number).then(result => {
        accumulator = result;
        if (index === self.length - 1) resolve(accumulator);
      });
    });

    async.series(tasks, err => {
      if (err) return reject(err);
      resolve(accumulator);
    });
  });
}

async function fetchAndProcessData(url, callback) {
  let options = {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${process.env.API_KEY}`
    }
  };

  let retries = 5;
  let backoffTimeout = 1000;

  while (retries > 0) {
    try {
      const response = await https.request(url, options, res => {
        if (res.statusCode !== 200) throw new Error(`Unexpected status code: ${res.statusCode}`);
        let body = '';
        res.on('data', data => body += data);
        res.on('end', () => callback(null, JSON.parse(body)));
      });
      response.on('error', err => {
        console.error(`Error fetching data from ${url}:`, err.message);
        retries--;
        backoffTimeout *= 2;
      });
      await new Promise(resolve => response.on('end', resolve));
    } catch (err) {
      if (retries === 0) throw err;
      console.error(`Failed to fetch data from ${url}. Retrying in ${backoffTimeout}ms...`);
      await new Promise(resolve => setTimeout(resolve, backoffTimeout));
    }
  }
}

