async function combineCertificates(certificates) {
  certificates = certificates.filter(validateCertificate);

  const combinedCert = [];
  let uniqueConcat = (arr, mapFn) => [...new Set(arr.map(mapFn))];
  const uniqueKeys = uniqueConcat(Object.keys(certificates[0]), key => key).sort();

  for (let key of uniqueKeys) {
    combinedCert[key] = {};
    combinedCert[key]['combined'] = [];
  }

  for (let cert of certificates) {
    let index = combinedCert.findIndex(obj => obj.publicKey.pem === cert.publicKey.pem);
    if (index !== -1) combinedCert[index].certificate.push(cert.certificate);
  }

  const finalCombinedCertPem = crypto.createCertificate({
    serialNumber: crypto.randomBytes(16),
    subject: {
      countryName: 'US',
      organizationName: 'My Company',
      organizationalUnitName: 'IT',
      commonName: 'My Server',
      localityName: 'City',
      stateOrProvinceName: 'State'
    },
    issuer: {
      countryName: 'US',
      organizationName: 'My Company',
      organizationalUnitName: 'IT',
      commonName: 'My Server',
      localityName: 'City',
      stateOrProvinceName: 'State'
    },
