        let text = response.text().await?;
        serde_json::from_str::<JsonObject>(&text)
    }

    async fn create_from_json<T: JsonCreatable>(&self, id: &str, json: serde_json::Value) -> Result<T, Box<dyn std::error::Error>> {
        let registry = self.registry.lock().unwrap();
        let creatable = registry.get(id).ok_or("Invalid ID")?;
