from threading import Thread, Lock
from queue import Queue
from collections import namedtuple
from aiohttp import ClientSession, WSMsgType, WSProtocolError
from cachelib import LRUCache
from dotenv import load_dotenv

load_dotenv()  # Load environment variables from .env file
API_KEYS = {
    'apn': os.getenv('APN_API_KEY'),
    'fcm': os.getenv('FCM_API_KEY'),
    'onesignal': os.getenv('ONESIGNAL_API_KEY')
}
PROTOCOLS = {
    'apn': 'apns',
    'fcm': 'fcm',
    'onesignal': 'rest'
}
CACHE = LRUCache((int(os.getenv('CACHE_SIZE')) if os.getenv('CACHE_SIZE') else 100) )

NotificationPayload = namedtuple('NotificationPayload', ['title', 'body', 'device_type'])

class PushNotificationManager:
    def __init__(self):
        self.sessions = {protocol: ClientSession() for protocol in API_KEYS}
        self._lock = Lock()
        self.queue = Queue()

    async def send(self, payload: NotificationPayload):
        with self._lock:
            self.queue.put(payload)
            while not self.queue.empty():
                time.sleep(1)

        for protocol, session in self.sessions.items():
            try:
                await self._send_notification(session, payload, protocol)
            except Exception as e:
                logging.exception(e)

    async def _send_notification(self, session, payload, protocol):
        url = API_URLS[protocol]
        async with session.ws_connect(url) as ws:
            await ws.send_str(self._payload_to_string(payload))
            for msg in ws:
                if msg.type == WSMsgType.TEXT:
                    response = json.loads(msg.data)
                    self._handle_response(response, payload)

    @staticmethod
    def _payload_to_string(payload):
        return json.dumps({
            'aps': payload.title if protocol == 'apn' else None,
            'notification': {
                'title': payload.title,
                'body': payload.body
            },
            'data': {
                'device_type': payload.device_type
            }
        })

    @staticmethod
    def _handle_response(response, payload):
        if response['success']:
            logging.info(f'Successfully sent notification: {payload}')
        else:
            error = response['error']
            logging.warning(f'Failed to send notification: {payload}. Error: {error}')

def run_push_manager():
    manager = PushNotificationManager()
    while True:
        manager.send(next_notification())  # replace next_notification with your function that generates NotificationPayload objects
        time.sleep(1)

if __name__ == "__main__":
    run_push_manager()
