```cpp
#include <iostream>
#include <fstream>
#include <json/json.h>
#include <memory>
#include <vector>
#include <functional>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/json_parser.hpp>

class IObserver {
public:
    virtual void onSettingsChanged() = 0;
};

class Settings {
private:
    std::shared_ptr<Json::Value> m_settings;
    boost::property_tree::ptree pt;

public:
    Settings(const std::string& filePath) {
        loadFromFile(filePath);
    }

    template<typename T>
    T getSetting(const std::string& key, const T& defaultValue, const T& minValue = T(), const T& maxValue = T()) {
        if (!m_settings->isMember(key)) {
            return defaultValue;
        }

        auto value = m_settings->get(key, defaultValue).as<T>();

        if (minValue <= value && value <= maxValue) {
            return value;
        }

        throw std::runtime_error("Invalid setting value");
    }

    void loadFromFile(const std::string& filePath) {
        try {
            std::ifstream ifs(filePath);
            boost::property_tree::read_json(ifs, pt);

            m_settings = std::make_shared<Json::Value>(Json::parse(pt.get<std::string>("settings").data(), nullptr, nullptr));
        } catch (const std::exception& e) {
            std::cerr << "Error loading settings from file: " << e.what() << std::endl;
        }
    }

    void saveToFile(const std::string& filePath) const {
        try {
            boost::property_tree::write_json(std::ofstream(filePath), pt);
        } catch (const std::exception& e) {
            std::cerr << "Error saving settings to file: " << e.what() << std::endl;
        }
    }

    template<typename T>
    void addObserver(const std::string& key, const std::shared_ptr<IObserver>& observer) {
        m_observers[key].push_back(observer);
    }

    void notifyObservers() {
        for (auto& pair : m_observers) {
            for (const auto& observer : pair.second) {
                observer->onSettingsChanged();
            }
        }
    }

    Settings& operator=(Settings&& other) noexcept {
        if (this != &other) {
            m_settings = std::move(other.m_settings);
            pt = std::move(other.pt);
            m_observers = std::move(other.m_observers);
        }
        return *this;
    }

private:
    std::unordered_map<std::string, std::vector<std::shared_ptr<IObserver>>> m_observers;
};
```
