3. TaskExecutor Class:

```java
@Slf4j
public class TaskExecutor implements Runnable {
    private final TaskQueue taskQueue;
    private final JobSchedulerService jobSchedulerService;
    private final RetryPolicy retryPolicy;

    public TaskExecutor(TaskQueue taskQueue, JobSchedulerService jobSchedulerService, RetryPolicy retryPolicy) {
        this.taskQueue = taskQueue;
        this.jobSchedulerService = jobSchedulerService;
        this.retryPolicy = retryPolicy;
    }

    @Override
    public void run() {
        while (true) {
            try {
                Task task = taskQueue.dequeue();
                if (task == null) continue; // no more tasks, sleep and wait for new ones

                log.info("Executing task: {}", task.getId());
                try {
                    task.runnable.run();
                    jobSchedulerService.submitJob(task);
                } catch (Exception e) {
                    int retriesRemaining = retryPolicy.getRetriesRemaining(e);
                    if (retriesRemaining <= 0) {
                        log.error("Failed to execute task {} after all retries", task.getId(), e);
                    } else {
                        log.warn("Task {} failed, retrying in {}", task.getId(), retryPolicy.getRetryInterval());
                        Thread.sleep(retryPolicy.getRetryInterval());
                    }
                }
            } catch (InterruptedException e) {
                log.error("TaskExecutor interrupted", e);
                Thread.currentThread().interrupt();
            }
        }
    }
}
