        public async Task<DecryptionResult> DecryptMessagesAsync(string tenant, List<string> encryptedMessages)
        {
            if (!_tenants.ContainsKey(tenant)) throw new AuthenticationException("Invalid tenant.");

            var hmacKey = SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(_tenants[tenant].Key));
            var decryptedMessages = new List<string>();

            ParallelOptions parallelOptions = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
            await Task.WhenAll(encryptedMessages.AsParallel().WithDegreeOfParallelism(parallelOptions).Select(async message =>
