                {
                    _logger.LogError($"Decryption failed for message: {message}. Error: {ex.Message}");
                }
            }));

            return new DecryptionResult { IsAuthenticated = decryptedMessages.Any(), DecryptedMessage = string.Join("\n", decryptedMessages) };
