import os
import boto3
from botocore.exceptions import NoCredentialsError, ClientError

def upload_file(bucket_name, file_name, file_size, metadata):
    s3 = boto3.client('s3')

    try:
        if not bucket_name or not file_name or file_size <= 0:
            raise ValueError("Bucket name, file name, and file size must be provided.")

        if not os.path.exists(file_name):
            raise FileNotFoundError(f"File '{file_name}' does not exist.")

        user = metadata['user']
        if user not in ['admin', 'developer']:
            raise PermissionError("User does not have permission to upload files.")

        s3.head_bucket(Bucket=bucket_name)  # Check if the bucket exists before uploading
        s3.upload_file(file_name, bucket_name, file_name, ExtraArgs={"Metadata": metadata})
        return {"success": True}
    except NoCredentialsError as e:
        print("AWS credentials not found.")
        return {"success": False, "error": str(e)}
    except ClientError as e:
        print(f"An error occurred: {str(e)}")
        return {"success": False, "error": str(e)}
