```javascript
const axios = require('axios');
const async = require('async');

function asyncArrayReduce(arr, initVal, callback, config) {
    let currentVal = initVal;
    const chunkSize = Math.ceil(arr.length / config.maxParallel);
    const tasks = [];

    for (let i = 0; i < arr.length; i += chunkSize) {
        tasks.push((callback, resultCallback) => {
            async.waterfall([
                (cb) => cb(null, arr.slice(i, i + chunkSize)),
                // Implement caching, throttling, error handling, etc. using axios and async functions
            ], (err, results) => resultCallback(err, results.reduce(callback, currentVal)));
        });
    }

    const taskRunner = (done) => {
        let index = 0;
        function next() {
            if (index < tasks.length) {
                tasks[index++](async.apply(asyncArrayReduce, this, arguments), next);
            } else {
                done();
            }
        }
        next();
    };

    async.series([
        () => { config.authToken && axios.defaults.headers.Authorization = `Bearer ${config.authToken}`; },
        (cb) => cb(null, currentVal),
        taskRunner,
        // Implement progress reporting using the callback function provided in the configuration object
    ], (err, finalResult) => {
        if (err) throw err;
        // Return the final reduced value
    });
}
