use std::env;
use std::fs::{create_dir_all, remove_dir_all};
use std::io::{Write, BufReader};
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, Duration};
use std::thread;
use log::{error, info};
use simplelog::{ConfigBuilder, TermLogger, LevelFilter};
use tempfile::NamedTempFile;

const CACHE_DIR_ENV: &str = "CACHE_DIR";
const CLEANUP_INTERVAL: Duration = Duration::hours(24);

struct CacheManager {
    cache_dir: Arc<Mutex<Path>>,
    log: Arc<log::Logger>,
}

impl CacheManager {
    fn new(cache_dir: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let cache_dir = Self::ensure_cache_dir(cache_dir)?;
        set_env(cache_dir.as_path());
        Ok(CacheManager {
            cache_dir: Arc::new(Mutex::new(cache_dir)),
            log: Arc::new(log::Logger::root(LevelFilter::Info, ConfigBuilder::new().build())),
        })
    }

    fn ensure_cache_dir(cache_dir: &str) -> Result<Path, Box<dyn std::error::Error>> {
        let cache_path = Path::new(cache_dir);
        if !cache_path.exists() {
            create_dir_all(cache_path)?;
        }
        Ok(cache_path)
    }

    fn set_env(path: &Path) {
        dotenv::from_path(path).ok();
        env::set_var("CACHE_DIR", path.to_str().unwrap());
    }

    fn get_cache_dir(&self) -> &Path {
        self.cache_dir.lock().unwrap()
    }

    fn clean_up(&self) {
        let mut cache_path = self.get_cache_dir().to_owned();
        remove_dir_all(cache_path)?;
        info!(self.log, "Cache cleaned up");
        thread::spawn(|| {
            let interval = CLEANUP_INTERVAL;
            loop {
                thread::sleep(interval);
                Self::clean_up(self).unwrap();
            }
        });
    }

    fn create_file(&self) -> Result<NamedTempFile, Box<dyn std::error::Error>> {
        NamedTempFile::new("cache")?.into_temp_path()
    }
}

fn main() {
    let cache_manager = CacheManager::new(CACHE_DIR_ENV)?;
    cache_manager.clean_up();

    // Your concurrent file handling, logging, and resource management code here...
}
```

