public class ThreadSafeFileUploadManager
{
    private readonly ConcurrentDictionary<string, CryptoServiceProvider> _cspPool = new ConcurrentDictionary<string, CryptoServiceProvider>();
    private readonly SemaphoreSlim _rateLimiter;
    private readonly JsonSerializer _serializer;
    private readonly string _configurationFilePath;

    public ThreadSafeFileUploadManager(string configurationFilePath)
    {
        _configurationFilePath = configurationFilePath;
        _rateLimiter = new SemaphoreSlim(int.Parse(LoadConfiguration()["RateLimit"]));
        _serializer = new JsonSerializer
        {
            ContractResolver = new CamelCasePropertyNamesContractResolver(),
            Formatting = Formatting.Indented
        };
    }

    public void DecryptMessage(string message, string clearanceLevel, Action<string> onComplete)
    {
        var validationResult = ValidateMessage(message);
        if (!validationResult.Success)
        {
            onComplete($"Error: {validationResult.ErrorMessage}");
            return;
        }

        _rateLimiter.Wait();
        Task.Run(() =>
        {
            try
            {
                using var keyAndIv = FetchKeysAndIVs(clearanceLevel);
                var decryptedMessage = DecryptMessageWithTripleDES(message, keyAndIv.Key, keyAndIv.Iv)
                    .DecryptWithAES(keyAndIv.RsaKey)
                    .DecryptWithRSA(keyAndIv.SymmetricKey);
                onComplete(decryptedMessage);
            }
            catch (Exception ex)
            {
                onComplete($"Error: {ex.Message}");
            }
            finally
            {
                _rateLimiter.Release();
            }
        });
    }

    private KeyAndIv FetchKeysAndIVs(string clearanceLevel)
    {
        // Implement logic for fetching keys and IVs from CSP dynamically based on availability and performance metrics.
    }

    private TripleDESCryptoServiceProvider DecryptMessageWithTripleDES(string cipherText, ICryptoTransform symmetricKey, ICryptoTransform iv) => symmetricKey.CreateDecryptor().TransformFinalBlock(Convert.FromBase64String(cipherText), 0, cipherText.Length);

    private AesCryptoServiceProvider DecryptMessageWithAES(string cipherText, RSACryptoServiceProvider rsaKey) => RSA.CreateDecrypter(rsaKey).Decrypt(Convert.FromBase64String(cipherText), RSAEncryptionPadding.Pkcs1);

    private string DecryptWithRSA(string cipherText, AesCryptoServiceProvider aes) => Encoding.UTF8.GetString(aes.CreateDecryptor().TransformFinalBlock(Convert.FromBase64String(cipherText), 0, cipherText.Length));

    private ValidationResult ValidateMessage(string message)
    {
        try
        {
            var messageObject = _serializer.Deserialize<ValidationMessage>(new MemoryStream(Encoding.UTF8.GetBytes(message)));
            return new ValidationResult { Success = true };
        }
        catch (JsonReaderException)
        {
            return new ValidationResult { Success = false, ErrorMessage = "Invalid message structure." };
        }
    }

    private ValidationMessage LoadConfiguration() => _serializer.Deserialize<ValidationMessage>(File.ReadAllText(_configurationFilePath));
}

public class KeyAndIv
{
    public ICryptoTransform SymmetricKey { get; set; }
    public RSACryptoServiceProvider RsaKey { get; set; }
    public byte[] Iv { get; set; }
}

public class ValidationMessage
{
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }
}
