```javascript
// Import required modules
const async = require('async');
const Bluebird = require('bluebird');
const _ = require('lodash');
const Database = require('./Database'); // Custom Database module

/**
 * Asynchronous hierarchical reduce function for an array of numbers with support for nested arrays.
 * @param {Array} arr - The array to be reduced.
 * @param {Function} callback - The reduction operation function, accepting four arguments: (accumulator, currentValue, currentIndex, array)
 * @returns {Promise<mixed>} A Promise that resolves with the final reduced value or rejects with an error.
 */
async function asyncHierarchicalReduce(arr, callback, options = {}) {
  // Default options
  const { maxConcurrency = 4, database } = options;

  // Fetch array data from the database if necessary
  let data = arr;
  if (database) {
    try {
      data = await Database.fetchArray(arr);
    } catch (error) {
      return Bluebird.reject(error);
    }
  }

  // Check for empty array and return early
  if (!data.length) return Bluebird.resolve(0);

  // Initialize accumulator with the first value of the array or initialValue, whichever is provided
  let accumulator = data[0] || options.initialValue;

  // Create a function to handle processing a chunk of items
  const processChunk = (items) => {
    return new Bluebird((resolve, reject) => {
      async.reduce(
        items,
        accumulator,
        (memo, currentValue, currentIndex, array) => {
          // Perform the reduction operation using the provided callback
          try {
            return callback(memo, currentValue, currentIndex, array);
          } catch (error) {
            reject(error);
          }
        },
        (err, result) => err ? reject(err) : resolve(result)
      );
    });
  };

  // Use async.eachOf to process each value in the array and handle nested arrays recursively
  return new Bluebird((resolve, reject) => {
    async.eachOf(data, (value, key, next) => {
      if (_.isArray(value)) {
        // If it's a nested array, recurse to process its contents
        const chunk = value;
        return processChunk(chunk)
          .then((result) => {
            accumulator = result;
            next();
          })
          .catch(next);
      } else if (typeof value !== 'number') {
        // If it's a non-numeric value, skip it and continue with the next item
        next();
      } else {
        // Otherwise, process the current item using processChunk function
        return processChunk([value])
          .then((result) => {
            accumulator = result;
            next();
          })
          .catch(next);
      }
    }, (err) => err ? reject(err) : resolve(accumulator));
  });
}

// Example usage:
asyncHierarchicalReduce([1, [2, [3], 4]], (acc, currentValue, currentIndex, array) => acc + currentValue, { initialValue: 0 })
  .then((result) => console.log(result)) // Output: 10
  .catch(console.error);
```

