    public class XmlDocumentLoader
    {
        private readonly IConnectionMultiplexer _redis;
        private readonly IDictionary<string, Func<Task<XmlDocument>>> _sources;
        private readonly ConcurrentDictionary<string, XmlDocument> _cache;
        private static readonly ILog _logger = LogManager.GetLogger(typeof(XmlDocumentLoader));

        public XmlDocumentLoader()
        {
            var redisConfiguration = new ConfigurationElementCollection();
            redisConfiguration.Add(new ConnectionMultiplexerConfiguration("localhost"));
            var redisSettings = redisConfiguration[0] as ConnectionMultiplexerConfiguration;
            _redis = ConnectionMultiplexer.Connect(redisSettings);

            var sourceConfigurations = new Dictionary<string, SourceConfiguration>();
            foreach (var section in ConfigurationManager.GetSection("sources"))
            {
                sourceConfigurations[((SourceConfiguration)section).Name] = (SourceConfiguration)section;
            }

            _cache = new ConcurrentDictionary<string, XmlDocument>();
            _sources = sourceConfigurations.ToDictionary(k => k.Key, v => CreateSourceLoaderAsync(v.Priorities, v.LoadBalancing));
        }

        private static Func<Task<XmlDocument>> CreateSourceLoaderAsync(PriorityQueue<string> priorities, bool loadBalance)
        {
            var sourceType = Type.GetType($"{v.TypeName}, {v.AssemblyName}");
            var constructor = sourceType.GetConstructors().First();
            return () => Task.Run(() => (XmlDocument)((Source)constructor.Invoke(new object[] { v.Config })).LoadAsync());
        }

        public async Task<XmlDocument> LoadAndCacheAsync(string key, string xpathQuery)
        {
            var cachedDoc = _cache.GetOrAdd(key, async _ =>
            {
                foreach (var source in _sources[key])
                {
                    try
                    {
                        var document = await source();
                        return document;
                    }
                    catch (Exception ex)
                    {
                        _logger.Error(ex);
                    }
                }
                throw new Exception($"No data found for key: {key}");
            });

            var result = cachedDoc.XPathSelectElements(xpathQuery);
            // Handle exceptions, logging, caching eviction, query timeout, and performance tuning here...
            return cachedDoc;
        }
    }

