    id: u32,
}

static CONNECTION_POOL: Mutex<Option<Client>> = Mutex::new(None);
const MAX_CONCURRENT_CONNECTIONS: usize = env::var("MAX_CONCURRENT_CONNECTIONS")
    .unwrap_or_else(|_| "10".to_string())
    .parse::<usize>()
    .unwrap();

async fn init_pool() -> Result<(), Box<dyn std::error::Error>> {
    let db_url = env::var("DB_URL").expect("DB_URL must be set");
    let pool = Client::connect(&db_url).await?;
    *CONNECTION_POOL.lock().await = Some(pool);
    Ok(())
}

pub async fn get_user(id: u32) -> Result<(), Box<dyn std::error::Error>> {
    let pool = CONNECTION_POOL.lock().await;
    if let Some(ref mut pool) = *pool {
        let client = pool.acquire().await?;
        let res = client.query_row("SELECT name FROM users WHERE id=$1", &[&id], |(name,)| Ok((name,)))
            .await??;
        println!("User: {}", res);
    } else {
        eprintln!("No pool available!");
    }
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let opts = Opts::parse();
    init_pool().await?;
    get_user(opts.id).await?;
    Ok(())
}
