```python
# database_connector/__init__.py
import abc
import os
import re
import threading
import typing as ty
from sqlalchemy import create_engine, pools
from sqlalchemy.exceptions import DatabaseError

Lock = threading.RLock()
REGISTRY = {}

class DatabaseConnector(metaclass=abc.ABCMeta):
    @staticmethod
    @abc.abstractmethod
    def create_engine(**kwargs) -> create_engine:
        pass

    @abc.abstractmethod
    async def connect() -> None:
        pass

    @abc.abstractmethod
    async def disconnect() -> None:
        pass

    @abc.abstractmethod
    async def execute(query: str) -> ty.Union[None, list]:
        pass

    @abc.abstractmethod
    async def transaction(func: ty.Callable) -> None:
        pass

@DatabaseConnector.register_factory
def _create_registry(config):
    from .subclasses import registry as subclass_registry

    for cls in subclass_registry.values():
        REGISTRY[cls.TYPE] = cls.from_config

    return REGISTRY

class Registry:
    def __init__(self):
        self._data = {}
        self._lock = Lock()

    async def register(self, name: str, factory) -> None:
        with self._lock:
            if name in self._data:
                raise ValueError(f"Registry already contains a factory for '{name}'.")
            self._data[name] = factory

    def get_factory(self, name):
        with self._lock:
            return self._data.get(name)

class RegistryLoader:
    def __init__(self, directory: str):
        self.directory = directory

    async def load(self, registry: Registry) -> None:
        for path in os.listdir(self.directory):
            if not re.match(r"^[a-zA-Z0-9_]+\.py$", path):
                continue

            module_name = path.replace(".py", "").lower()
            __import__(f"{self.directory}.{module_name}", fromlist=[".", ".registry"])

def discover_subclasses(directory) -> None:
    import importlib.util

    for path, subdirs, files in importlib.util.walk_files(directory):
        if not any(file.endswith(".py") for file in files):
            continue

        module = importlib.util.module_from_spec(importlib.util.spec_from_file_location(path, path))
        sys.modules[module.__name__] = module

        if hasattr(module, "registry"):
            for name, factory in getattr(module, "registry").values():
                REGISTRY[name] = factory

# Example of subclass registration and usage
from database_connector import RegistryLoader, DatabaseConnector

class CustomDBConnector(DatabaseConnector):
    TYPE = "custom"
    DIALECT = "sqlite"

    def __init__(self, config: dict):
        super().__init__(**config)
        self.engine = create_engine(
            f"{self.DIALECT}+aiollowsqlite:///{config['db_name']}",
            poolclass=pools.QueuePool,
            pool_size=config["pool_size"] or 5,
            max_overflow=0,
        )

    async def connect(self):
        await self.engine.connect()

    async def disconnect(self):
        await self.engine.dispose()

    async def execute(self, query: str) -> ty.Union[None, list]:
        with self.engine.connect() as conn:
            return await conn.execute(query)

    async def transaction(self, func: ty.Callable) -> None:
        async with self.engine.connect() as conn:
            await conn.begin()
            try:
                await func(conn)
                await conn.commit()
            except DatabaseError:
                await conn.rollback()
                raise

# Usage
config = {"type": "custom", "db_name": "example.db", "pool_size": 10}
