            throw new ArgumentOutOfRangeException(nameof(input), "Input length exceeds the maximum allowed.");

        var lines = input.Split('\n');
        var lineTasks = lines.Select(ProcessLine).ToList();

        await Task.WhenAll(lineTasks, cancellationToken);
    }

