    private byte[] ComputeHash(string input)
    {
        if (_trimInput && input.Length > _maxInputLength)
            input = input.Substring(0, _maxInputLength);

        if (_capitalizeInput)
            input = input.ToUpper();

        using var sha = GetHashFunction("SHA1"); // Replace with the appropriate hash function...
        return sha.ComputeHash(Encoding.UTF8.GetBytes(input));
    }

    private Func<byte[], byte[]> GetHashFunction(string algorithm)
    {
        if (_hashFunctions.TryGetValue(algorithm, out var hashFunction))
            return hashFunction;

        throw new KeyNotFoundException($"No such hash function: '{algorithm}'.");
    }
