class Registry:
    _registry = {}
    _lock = Lock()

    @staticmethod
    def register_factory(func):
        wraps(func)(func)  # Maintain original function metadata (e.g., docstring)
        func.__factory_id__ = Registry._generate_id()
        Registry._registry[func.__factory_id__] = func

    @staticmethod
    def discover_subclasses(directory: str):
        for file in os.listdir(directory):
            if not file.endswith(".py"):
                continue

            module_name = f"{directory.replace('/', '.')}.{file[:-3]}"
            __import__(module_name)
            for name, obj in sys.modules[module_name].__dict__.items():
                if not isinstance(obj, type) or not issubclass(obj, JSONBase):
                    continue

                Registry.register_factory(obj)

    @staticmethod
    def get_factory(factory_id: str) -> Any:
        with Registry._lock:
            if factory_id not in Registry._registry:
                raise KeyError(f"Factory ID '{factory_id}' not found")
            return Registry._registry[factory_id]

