        self.retry_backoff = 2 ** self.max_retries
        self.cache = {}
        self.cancel_event = Event()

    def get_or_cache_credentials(self, key: str) -> Any:
        if key in self.cache:
            return self.cache[key]
        credentials = self.session.get_credentials().get_frozen_credentials()
        self.cache[key] = {
            'access_key': credentials.access_key,
            'secret_key': credentials.secret_key,
            'session_token': credentials.token,
        }
        return self.cache[key]

    def upload_chunk(self, file_id: str, chunk_num: int, chunk_data: bytes):
        key = f"{file_id}/part-{chunk_num}"
        credentials = self.get_or_cache_credentials('upload')
        while True:
            try:
                self.s3.put_object(
                    Bucket=self.bucket,
                    Key=key,
                    Body=chunk_data,
                    ACL='private',
                    ServerSideEncryption='AES256'
                )
                break
            except Exception as e:
                if self.cancel_event.is_set():
                    raise ValueError("Upload canceled.")
                if self.max_retries > 0:
                    self.max_retries -= 1
                    wait_time = int(self.retry_backoff / 2) * min(self.max_retries, len(str(e).split('\n')))
                    print(f"Retrying upload in {wait_time} seconds due to error: {e}")
                    time.sleep(wait_time)
                else:
                    raise e

    def start_upload(self, file_id: str, chunk_generator, priority=0):
        self.cancel_event.clear()
        thread = Thread(target=self._upload_thread, args=(file_id, chunk_generator, priority))
        thread.start()
        return thread

    def _upload_thread(self, file_id: str, chunk_generator, priority: int):
        for i, chunk_data in enumerate(chunk_generator):
            self.upload_chunk(file_id, i, chunk_data)

    def cancel_all_uploads(self):
        self.cancel_event.set()

class FileChunkUploaderTests:
    # Add unit tests for various scenarios such as file upload with retries, canceling uploads, and edge cases
```

This code creates a `FileChunkUploader` class that handles asynchronous file chunk uploads to AWS S3 using multipart upload. The class has methods for initiating uploads synchronously or asynchronously, cancelling ongoing uploads, and handling retries with exponential backoff. It caches frequently used credentials for improved performance and supports multiple sets of upload credentials through a configurable settings object or environment variables.

