class TransactionQueue {
    std::queue<Transaction> transactions_;
    std::mutex mtx_;
public:
    void enqueue(const Transaction& tx) {
        std::unique_lock lock(mtx_);
        transactions_.push(tx);
    }

    bool try_dequeue(Transaction& tx) {
        std::unique_lock lock(mtx_);
        if (transactions_.empty()) return false;
        tx = std::move(transactions_.front());
        transactions_.pop();
        return true;
    }
};

