static log4cxx::LoggerPtr logger(log4cxx::Logger::getLogger("main"));

typedef struct {
    char *input_file;
    char *output_file;
    int verbose;
} options_t;

options_t opts;
pid_t current_pid;
int lines_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void sigint_handler(int signum) {
    logger->info("Received SIGINT. Gracefully exiting...");
    exit(0);
}

void* count_lines(void *arg) {
    FILE *fp = fopen(opts.input_file, "r");
    if (!fp) {
        perror("Error opening input file");
        return NULL;
    }

    char c;
    while ((c = fgetc(fp)) != EOF) {
        pthread_mutex_lock(&mutex);
        lines_count++;
        pthread_mutex_unlock(&mutex);
    }

    fclose(fp);
    return NULL;
}

int parse_arguments(int argc, char *argv[]) {
    current_pid = getpid();
    int opt = 0;
    while ((opt = getopt(argc, argv, "hvcs:o:")) != -1) {
        switch (opt) {
            case 'h':
                print_usage();
                return 0;
            case 'v':
                opts.verbose++;
                break;
            case 'c':
                // Add code to set opts.cs here
                break;
            case 's':
                // Add code to set opts.input_file here
                if (opts.input_file) {
                    fprintf(stderr, "Error: More than one input file provided\n");
                    return 1;
                }
                opts.input_file = optarg;
                break;
            case 'o':
                // Add code to set opts.output_file here
                opts.output_file = optarg;
                break;
            case '?':
                fprintf(stderr, "Error: Invalid option '%c'\n", optopt);
                return 1;
            default:
                print_usage();
                return 1;
        }
    }

    if (!opts.input_file) {
        print_usage();
        return 1;
    }

    return 0;
}

void print_usage() {
    printf("Usage: [program] [-h|--help] [-v|--verbose] [-s input_file] [-o output_file]\n");
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error installing SIGINT handler");
        return 1;
    }

    if (parse_arguments(argc, argv))
        return 1;

    // Configure log4cxx here

    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, count_lines, NULL)) {
            perror("Error creating thread");
            return 1;
        }
    }

    // Wait for all threads to finish here

    printf("Number of lines in the input file: %d\n", lines_count);

    return 0;
}
```

