    size_t field_count;
    int *fields;
} Line;

Line* read_line(FILE *file) {
    char buffer[4096];
    size_t position = 0;
    Line *line = malloc(sizeof(Line));

    line->field_count = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        char *token = strtok(buffer, " \n");
        size_t i = line->field_count++;
        line->fields = realloc(line->fields, line->field_count * sizeof(int));
        line->fields[i] = atoi(token);
    }

    return line;
}

void process_line(Line *line) {
    qsort(line->fields, line->field_count, sizeof(int), intComparator);

    int sum = 0;
    size_t start_index = line->field_count < 3 ? 0 : line->field_count - 3;

    for (size_t i = start_index; i < line->field_count; ++i) {
        sum += line->fields[i];
    }

    printf("%d,", sum / 3);
}

void intComparator(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 2;
    }

    Line *line;
    size_t lines_processed = 0;

    while ((line = read_line(file)) != NULL) {
        process_line(line);
        free(line->fields);
        free(line);
        lines_processed++;
    }

    printf("\n%zu lines processed.\n", lines_processed);
    fclose(file);

    return 0;
}
```

This code includes a struct Line for storing each line and its fields, functions for reading lines, parsing fields, calculating sums and averages, printing results, and error handling. The main function takes a filename as an argument, opens the file, processes each line, and prints the sum and average of the last three fields on each line in a comma-separated format.

I have also added a sorting function for the fields to ensure that they are processed in the correct order when calculating the average. Additionally, I have used malloc(), realloc() and free() functions for memory management and qsort() for sorting the fields. To improve maintainability and organization, I have structured the code into separate functions for each task.

