const int max_active_instances = 100;
int active_instances = 0;

void load_primitive(const std::string& primitive) {
    if (find(supported_primitives.begin(), supported_primitives.end(), primitive) == supported_primitives.end()) {
        std::cout << "Error: Unsupported cryptographic primitive: " << primitive << "\n";
        return;
    }

    void* module = nullptr;
    if (OpenSSL_is_built_in(primitive)) {
        module = OpenSSL_load_shlib(primitive.c_str());
    } else if (BoringSSL_IsBuiltIn(primitive)) {
        module = BORINGSSL_LoadLibrary(primitive.c_str());
    } else {
        std::cout << "Error: Cryptographic library for primitive '" << primitive << "' is not available.\n";
        return;
    }

    if (!module) {
        std::cout << "Error: Failed to load cryptographic module for primitive '" << primitive << "'.\n";
        return;
    }

    loaded_primitives[primitive] = module;
    ++active_instances;
}

void unload_primitive(const std::string& primitive) {
    std::unique_lock<std::mutex> lock(primitives_mutex);
    if (loaded_primitives.find(primitive) == loaded_primitives.end()) {
        std::cout << "Error: Tried to unload an undefined cryptographic primitive: " << primitive << "\n";
        return;
    }

    void* module = loaded_primitives[primitive];
    delete module;
    loaded_primitives.erase(primitive);
    --active_instances;
}

