    if (command == "update") {
        update_cryptographic_library();
    } else if (command == "load" || command == "unload") {
        if (argc < 3) {
            std::cout << "Error: Missing primitive argument.\n";
            return -1;
        }

        const std::string primitive = argv[2];
        if (command == "load") {
