#include <stdlib.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    EVP_CIPHER_CTX *aes_ctx;
    EVP_CIPHER_CTX *camellia_ctx;
    EVP_MD_CTX *md5_ctx;
    EVP_MD_CTX *sha1_ctx;
    EVP_MD_CTX *sha256_ctx;
    RSA *rsa;
    char *key_store_path;
    pthread_mutex_t lock;
} CryptoContext;

static CryptoContext* global_crypto_context = NULL;

static void crypto_cleanup(CryptoContext *ctx) {
    if (ctx->rsa != NULL) {
        RSA_free(ctx->rsa);
        ctx->rsa = NULL;
    }

    if (ctx->aes_ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->aes_ctx);
        ctx->aes_ctx = NULL;
    }

    if (ctx->camellia_ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->camellia_ctx);
        ctx->camellia_ctx = NULL;
    }

    if (ctx->md5_ctx != NULL) {
        EVP_MD_CTX_free(ctx->md5_ctx);
        ctx->md5_ctx = NULL;
    }

    if (ctx->sha1_ctx != NULL) {
        EVP_MD_CTX_free(ctx->sha1_ctx);
        ctx->sha1_ctx = NULL;
    }

    if (ctx->sha256_ctx != NULL) {
        EVP_MD_CTX_free(ctx->sha256_ctx);
        ctx->sha256_ctx = NULL;
    }

    if (ctx->key_store_path != NULL) {
        free(ctx->key_store_path);
        ctx->key_store_path = NULL;
    }

    pthread_mutex_destroy(&ctx->lock);
    free(ctx);
}

static CryptoContext* crypto_context_create() {
    CryptoContext *ctx = mmap(NULL, sizeof(CryptoContext), PROT_READ | PROT_WRITE | PROT_EXEC, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ctx == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    memset(ctx, 0, sizeof(CryptoContext));
    pthread_mutex_init(&ctx->lock, NULL);

    return ctx;
}

static void crypto_register_functions() {
    const char *aes_alias = "AES-256-CBC";
    const char *camellia_alias = "Camellia-128-CBC";
    const char *md5_alias = "MD5";
    const char *sha1_alias = "SHA1";
    const char *sha256_alias = "SHA256";

    EVP_add_cipher(aes_alias, EVP_aes_256_cbc());
    EVP_add_cipher(camellia_alias, EVP_camellia_128_cbc());
    EVP_add_digest(MD5, EVP_md5());
    EVP_add_digest(SHA1, SHA1_DIGEST);
    EVP_add_digest(SHA256, SHA256_DIGEST);

    // Add RSA with SHA1
    const char *rsa_alias = "RSA-SHA1";
    RSA* rsa_key;
    int key_size = RSA_F4; // 2048 bits (F4 in OpenSSL)

    if (!(rsa_key = RSA_generate_key(RSA_F4, RSA_F4, NULL, NULL))) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    EVP_PKEY* pkey = EVP_PKEY_new();
    if (!pkey) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    if (!EVP_PKEY_assign_RSA(pkey, rsa_key)) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    EVP_add_digest_alias(rsa_alias, EVP_sha1(), NULL);
    EVP_add_encrypt_alias(rsa_alias, EVP_RSA_encrypt, NULL);
    EVP_add_decrypt_alias(rsa_alias, EVP_RSA_decrypt, NULL);
}

static void crypto_load_keys() {
    // Implement a secure key store loading mechanism here
    // This could involve reading keys from a file, environment variables, etc.
    // Make sure to handle missing or invalid keys gracefully
}

static void* crypto_init(void *arg) {
    CryptoContext *ctx = (CryptoContext *) arg;

    ctx->key_store_path = "/path/to/your/key/store"; // Set your key store path here

    pthread_mutex_lock(&ctx->lock);
    crypto_load_keys();
    crypto_register_functions();
    pthread_mutex_unlock(&ctx->lock);

    return NULL;
}

void init_cryptographic_primitives() {
    if (global_crypto_context == NULL) {
        global_crypto_context = crypto_context_create();
        pthread_t thread_id;

        pthread_create(&thread_id, NULL, crypto_init, global_crypto_context);
        pthread_detach(thread_id);
    }
}
