```java
import redis.clients.jedis.Jedis;
import akka.actor.ActorSystem;
import akka.stream.Materializer;
import okhttp3.*;
import java.time.Duration;

public class WeatherService {
    private static final String REDIS_HOST = "localhost";
    private static final int REDIS_PORT = 6379;
    private Jedis redisClient;
    private OkHttpClient httpClient;

    public WeatherService(ActorSystem system) {
        this.redisClient = new Jedis(REDIS_HOST, REDIS_PORT);
        this.httpClient = new OkHttpClient();
        // Configure rate limiting, authentication and other security aspects here
    }

    public void fetchWeatherData(String location, Callback<JsonElement> callback) {
        // Check if data is in cache
        String data = redisClient.get(location);
        if (data != null) {
            callback.onResponse(new JsonParser().parse(data));
        } else {
            Request request = new Request.Builder()
                    .url("http://api.openweathermap.org/data/2.5/weather?q=" + location + "&appid=YOUR_API_KEY")
                    .build();

            Call call = httpClient.newCall(request);
            call.enqueue(new Callback<Response>() {
                @Override
                public void onFailure(Call call, IOException e) {
                    // Handle error and retry here
                }

                @Override
                public void onResponse(Call call, Response response) throws IOException {
                    if (!response.isSuccessful()) {
                        // Handle error and retry here
                    } else {
                        JsonElement jsonElement = new JsonParser().parse(response.body().string());
                        redisClient.setex(location, 600, response.body().toString());
                        callback.onResponse(jsonElement);
                    }
                }
            });
        }
    }

    // Invalidate cache based on geographical alerts or weather changes
    public void invalidateCache(String location) {
        redisClient.del(location);
    }
}
```

