    if resp.status().is_success() {
        let last_modified = resp.headers()
            .get("last-modified")
            .and_then(|h| h.to_str())
            .ok_or(io::Error::new(io::ErrorKind::InvalidData, "invalid header value"))?
            .parse::<i64>()?;
        let local_mod_time = fs::metadata("config")?.created().unwrap().duration_since(std::time::SystemTime::UNIX_EPOCH)?.as_secs() as i64;
        if last_modified > local_mod_time {
            // Sync remote config directory with local one and return the path
            let dir_path = sync_config_dir(CONFIG_REPO_URL).map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
            return Ok(dir_path);
        }
    }

    // Directory not found or stale; create a new one locally and sync it
    let mut dir_lock = CONCURRENT_DIR_LOCK.lock().unwrap();
    let mut existing_dir = dir_lock.entry(env::current_exe().unwrap().file_name().unwrap().to_str().unwrap().to_owned()).or_insert_with(|| {
        let home_dir = env::var("HOME").unwrap_or_else(|_| ".".to_string());
        PathBuf::new(&home_dir).join("config")
    });
    *existing_dir = sync_config_dir(CONFIG_REPO_URL).map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
    Ok(existing_dir)
}

