Registry = type('Registry', (object,), {})

@Registry.register_factory
def _json_base_factory(cls: Type[JSONBase]):
    return cls

def discover_subclasses(directory: str) -> None:
    for file in os.listdir(directory):
        if file.endswith('.py'):
            __import__(f'{__package__}.subclasses.{file[:-3]}', fromlist=['*'])

def load_from_yaml(yaml_path: str) -> None:
    with open(yaml_path, 'r') as yamlfile:
        data = yaml.safe_load(yamlfile)
        for factory, metadata in data.items():
            modname, className = metadata['module'], metadata['class']
            mod = __import__(f'{__package__}.{modname}', fromlist=['*'])
            cls = getattr(mod, className)
            _json_base_factory(cls)

def save_to_file(file_path: str) -> None:
