    def __init__(self, config_file='config.ini', log_dir=None):
        self.config_file = config_file
        self.log_dir = log_dir
        self._setup_logging()

    def _setup_logging(self):
        if self.log_dir:
            self.log_path = os.path.join(self.log_dir, f"logs_run_{time.strftime('%Y-%m-%d_%H-%M-%S')}")
        else:
            self.log_path = _create_unique_log_directory("/var/log/myapp/")

        file_handler = TimedRotatingFileHandler(self.log_path, when='D', interval=1, backupCount=5)
        console_handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        file_handler.setFormatter(formatter)
        console_handler.setFormatter(formatter)

        root_logger = logging.getLogger()
        root_logger.handlers = [file_handler, console_handler]
        root_logger.setLevel(self._get_log_level())

    @staticmethod
    def _create_unique_log_directory(default_path):
        unique_dirs = set()
        lock = threading.Lock()

        def create_and_add_to_set(path):
            if not os.path.exists(path) or os.listdir(path) == []:
                os.makedirs(path)
                return path
            else:
                with lock:
                    for dir in unique_dirs:
                        if dir == path:
                            return path

                    new_path = create_and_add_to_set(f"{path}_{time.strftime('%Y-%m-%d_%H-%M-%S')}")
                    return new_path

        return create_and_add_to_set(default_path)

    @staticmethod
    def _get_log_level():
        log_level = os.environ.get('LOGGING_LEVEL', 'INFO').upper()
        valid_levels = {'DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL'}
        if not log_level in valid_levels:
            raise ValueError(f"Invalid logging level '{log_level}'")
        return log_level

