import json
import datetime
from decimal import Decimal
from uuid import UUID

class JSONSerializable:
    @staticmethod
    def _deserialize(data, cls):
        return cls.from_json(data)

    @staticmethod
    def _serialize(obj):
        return obj.to_json()

    @classmethod
    def register_factory(cls, name, factory_function):
        cls._factories[name] = factory_function

    @classmethod
    def from_json(cls, json_str):
        try:
            data = json.loads(json_str)
            factory_function = cls._factories.get(data['__type__'])
            if not factory_function:
                raise ValueError(f"Unsupported type: {data['__type__']}")
            return factory_function(**data)
        except json.JSONDecodeError as e:
            raise ValueError("Invalid JSON input.") from e

    @classmethod
    def to_json(cls, obj):
        data = cls._serializer.dumps(obj)
        data['__type__'] = cls.__name__
        return data

    class Serializer:
        @staticmethod
        def dumps(obj):
            raise NotImplementedError("Subclasses must implement this method.")

        @staticmethod
        def loads(json_str):
            raise NotImplementedError("Subclasses must implement this method.")

    # Define serializers for datetime, UUID, Decimal, and other custom data types here.

# Example of a FinancialDataModel that inherits from JSONSerializable:
class StockPrice(JSONSerializable):
    def __init__(self, timestamp, price):
        self.timestamp = datetime.datetime.fromisoformat(timestamp)
        self.price = Decimal(price)

    @classmethod
    def _deserialize(cls, data, **kwargs):
        return StockPrice(data['timestamp'], data['price'])

    @classmethod
    def _serialize(cls, obj):
        return {
            'timestamp': obj.timestamp.isoformat(),
            'price': str(obj.price)
        }
