class Character {
public:
    explicit Character(int initialEnergy) : energy(initialEnergy), energyMutex() {}

    void addAttack(const Attack& attack) { availableAttacks.push_back(attack); }
    const std::vector<Attack>& getAvailableAttacks() const { return availableAttacks; }

    int getEnergy() const { std::unique_lock<std::mutex> lock(energyMutex); return energy; }
    void setEnergy(int newEnergy) {
