// External logging function
void log_structure_creation(int log_level, const char *message);

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int log_level) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety
    if (!num_structures || !crc_flag_rules) return -1; // Invalid input

    *nfalist = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*nfalist) return -2; // Allocation failure

    pthread_mutex_lock(&lock); // Lock for thread safety

    int tag = 1, rnti = 1000;
    int *used_crc_flags = calloc(num_structures, sizeof(int));
    if (!used_crc_flags) {
        free(*nfalist); // Deallocate memory if allocation failure
        pthread_mutex_unlock(&lock); // Unlock for thread safety
        return -2; // Allocation failure
    }

    for (int i = 0; i < num_structures; ++i) {
        (*nfalist)[i].tag = tag++;
        (*nfalist)[i].rnti = rnti++;
        (*nfalist)[i].crc_indication.crcFlag = crc_flag_rules[used_crc_flags[i] ^= 1]; // Set CRC flag based on the rule
        log_structure_creation(log_level, "Created structure with tag: %d, RNTI: %d, CRC Flag: %d", (*nfalist)[i].tag, (*nfalist)[i].rnti, (*nfalist)[i].crc_indication.crcFlag);
    }

    free(used_crc_flags); // Deallocate memory for used_crc_flags
    pthread_mutex_unlock(&lock); // Unlock for thread safety

    // Validate the populated structures against the crc_flag_rules and report any mismatches
    int mismatches = 0;
    for (int i = 0; i < num_structures; ++i) {
        if ((*nfalist)[i].crc_indication.crcFlag != crc_flag_rules[i]) ++mismatches;
    }
    if (mismatches) printf("Warning: %d structures do not match the provided CRC flag rules.\n", mismatches);

    return 0; // Success
}
