using System.Collections.Generic;

namespace CustomDataLoader
{
    public struct Checksum
    {
        public byte[] CalculatedChecksum;
        public byte[] ExpectedChecksum;
    }

    [Serializable]
    public class DataContainer
    {
        // Add your custom data structure properties here
    }

    public static class BinaryFileLoader
    {
        private const int ChecksumSize = 16;

        public static T LoadData<T>(string filePath) where T : new()
        {
            try
            {
                using (FileStream fs = File.OpenRead(filePath))
                {
                    // Read the checksum first to ensure data integrity
                    byte[] checksum = new byte[ChecksumSize];
                    fs.Read(checksum, 0, ChecksumSize);

                    // Calculate the checksum of the binary file content
                    using (SHA256 sha256 = SHA256.Create())
                    {
                        byte[] dataChecksum = sha256.ComputeHash(fs);

                        // Compare calculated checksum with expected checksum to ensure data integrity
                        Checksum loadedChecksum = new Checksum { CalculatedChecksum = dataChecksum, ExpectedChecksum = Array.Clone(checksum, ChecksumSize) };
                        if (!loadedChecksum.CalculatedChecksum.SequenceEqual(loadedChecksum.ExpectedChecksum))
                            throw new InvalidDataException("Invalid checksum, file might be corrupted.");
                    }

                    // Deserialize the data from the binary stream
                    BinaryFormatter formatter = new BinaryFormatter();
                    object deserializedData = formatter.Deserialize(fs);

                    if (deserializedData is not T castedData)
                        throw new InvalidCastException($"Deserialized data could not be cast to {typeof(T).Name}.");

                    return castedData as T;
                }
            }
            catch (FileNotFoundException ex)
            {
                throw new FileNotFoundException("The specified file does not exist.", ex);
            }
            catch (IOException ex)
            {
                throw new IOException("An error occurred while reading the file.", ex);
            }
            catch (SerializationException ex)
            {
                throw new SerializationException("An error occurred during deserialization of the binary data.", ex);
            }
            catch (InvalidDataException ex)
            {
                throw ex;
            }
            catch (InvalidCastException ex)
            {
                throw ex;
            }
        }
    }
}
```

