```javascript
const MAX_CONCURRENT_REQUESTS = 3;
let activeRequests = 0;

function loadDynamicContent(content) {
    return new Promise((resolve, reject) => {
        const footer = document.querySelector('footer');
        const scriptElements = [];
        let totalRequests = content.length;
        let timedOutRequests = 0;

        function loadScript(scriptObject) {
            if (activeRequests >= MAX_CONCURRENT_REQUESTS) return;
            activeRequests++;

            const script = document.createElement('script');
            script.async = true;

            if (scriptObject.url) {
                script.src = scriptObject.url;
                script.onerror = () => {
                    timedOutRequests++;
                    activeRequests--;
                    if (!scriptObject.fallback) {
                        console.error(`Script ${scriptObject.key} failed to load`);
                        reject(new Error(`Script ${scriptObject.key} failed to load`));
                    }
                }
                script.ontimeout = () => {
                    timedOutRequests++;
                    activeRequests--;
                    if (!scriptObject.fallback) {
                        console.error(`Script ${scriptObject.key} timed out`);
                        reject(new Error(`Script ${scriptObject.key} timed out`));
                    }
                }
            } else {
                script.innerHTML = scriptObject.code;
            }

            if (scriptObject.fallback) {
                script.onload = () => {
                    activeRequests--;
                    footer.innerHTML += scriptObject.fallback;
                }
            }

            scriptElements.push(script);

            document.head.appendChild(script);
        }

        content.forEach(loadScript);

        // Load scripts in parallel but not block the main thread for more than 5 seconds per request
        setTimeout(() => {
            if (totalRequests - activeRequests - timedOutRequests > 0) {
                resolve(footer.innerHTML);
            } else {
                reject(new Error('Script loading timeout'));
            }
        }, 5000);
    });
}
```

