struct NFCP {
    int crcFlag;
    sem_t lock;
};

static struct NFCP* pool = NULL;
static size_t numElems = 0;
static const size_t minPoolSize = 100000;
static sem_t poolSemaphore;

void initPool() {
    if (numElems > 0) return;
    pool = malloc(minPoolSize * sizeof(struct NFCP));
    for (size_t i = 0; i < minPoolSize; ++i) {
        pool[i].crcFlag = i + 1;
        sem_init(&pool[i].lock, 0, 1);
    }
    numElems = minPoolSize;
}

int getNFCP(struct NFCP** nfcp) {
    sem_wait(&poolSemaphore);
    if (numElems == 0) initPool();
    size_t index = --numElems;
    *nfcp = &pool[index];
    sem_post(&poolSemaphore);
    return index + 1;
}

void freeNFCP(struct NFCP* nfcp) {
    sem_destroy(&nfcp->lock);
}

