    private readonly XmlDocument _document;
    private readonly XmlNamespaceManager _namespaceManager;
    private readonly Dictionary<string, object> _cache = new Dictionary<string, object>();
    private readonly ILogger<XmlParser> _logger;

    public XmlParser(Stream xmlStream, ILogger<XmlParser> logger)
    {
        _document = new XmlDocument();
        _document.Load(xmlStream);
        _namespaceManager = CreateNamespaceManager(_document);
        _logger = logger;
    }

    public XmlParser(string xmlString, ILogger<XmlParser> logger) : this(new MemoryStream(System.Text.Encoding.UTF8.GetBytes(xmlString)), logger) { }

    private XmlNamespaceManager CreateNamespaceManager(XmlDocument document)
    {
        var manager = new XmlNamespaceManager(document.NameTable);
        foreach (var ns in document.LookupNamespace("*"))
            manager.AddNamespace("ns", ns.Value);
        return manager;
    }

    public object GetSingleElementValue(string xpathExpression) => GetElementsValues(xpathExpression).FirstOrDefault();

    public List<object> GetElementsValues(string xpathExpression)
    {
        lock (_cache)
        {
            if (_cache.TryGetValue(xpathExpression, out var result)) return (List<object>)result;
        }

        var nodes = _document.SelectNodes(xpathExpression, _namespaceManager);

        if (nodes == null || nodes.Count == 0) return new List<object>();

        if (nodes.Count > 1)
            throw new MultipleElementException($"Multiple elements found for XPath expression: {xpathExpression}");

        var result = new List<object> { nodes[0].InnerText };
        _cache.Add(xpathExpression, result);

        return result;
    }

