void *parseLog(Worker* worker);
void reportStatistics();
void handleRequest(int sockfd);
void recoverFromError(char* errorMessage, size_t messageLength);

int main() {
    // Initialize global variables and structures
    int serverSocket;
    struct sockaddr_in serverAddr;
    fd_set masterFds, readFds;
    pthread_mutex_t statsLock;
    Worker* workerPool; // Dynamically allocate memory for worker pool
    int numWorkers = 16; // Number of threads to handle concurrent requests

    // Initialize and bind the server socket
    serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &serverAddr.sin_addr);
    bind(serverSocket, (struct sockaddr*)&serverAddr, sizeof(serverAddr));
    listen(serverSocket, 5);

    // Initialize the worker pool and other data structures

    while (1) {
        FD_ZERO(&masterFds);
        FD_ZERO(&readFds);
        FD_SET(serverSocket, &masterFds);

        // Poll for new connections and handle worker requests

        if (!FD_ISSET(serverSocket, &masterFds)) continue;

        int clientSockfd = accept(serverSocket, NULL, NULL);
        handleRequest(clientSockfd);
    }

    free(workerPool); // Free memory when done with worker pool
    close(serverSocket);
    return 0;
}
