import importlib

class ConfigurationManager:
    def __init__(self, data: Dict[str, Any]):
        self.data = data

    # Define your custom configuration manager methods here

def load_config(config_file: str) -> ConfigurationManager:
    logging.basicConfig(level=logging.DEBUG)

    mimetype = get_mimetype(config_file)
    if not is_valid_config_mimetype(mimetype):
        raise ValueError("Invalid configuration file format")

    with open(config_file, "r") as f:
        config_data = parse_config_file(f.read(), mimetype)

    try:
        ConfigurationManager_class = get_configuration_manager_class(config_data["type"])
    except (AttributeError, KeyError):
        raise ValueError("Invalid or missing configuration manager class")

    if not issubclass(ConfigurationManager_class, ConfigurationManager):
        raise ValueError("Specified configuration manager class is not a valid ConfigurationManager subclass")

    try:
        config = ConfigurationManager_class(config_data)
    except Exception as e:
        logging.error(f"Error creating instance of {ConfigurationManager_class.__name__}: {str(e)}")
        raise ValueError("Failed to create configuration manager instance")

    return config

def get_mimetype(filepath: str) -> str:
    mime = None
    try:
        with open(filepath, "rb") as f:
            mime = mimetypes.guess_type(filepath)[0]
    except Exception as e:
        logging.warning(f"Failed to get mimetype of {filepath}: {str(e)}")
    return mime if mime else "application/unknown"

def is_valid_config_mimetype(mimetype: str) -> bool:
    # Add your condition for valid configuration file MIME types here, e.g.:
    # return mimetype in ["application/json", "application/x-yaml"]
    pass

def parse_config_file(data: str, mimetype: str) -> Dict[str, Any]:
    if mimetype == "application/json":
        return json.loads(data)
    elif mimetype == "application/x-yaml":
        return yaml.safe_load(data)
    else:
        raise ValueError("Invalid configuration file format")

def get_configuration_manager_class(class_name: str) -> Type[ConfigurationManager]:
    if class_name in sys.modules:
        return sys.module_type[class_name]
    try:
        module_name, _ = class_name.rsplit(".", 1)
        module = importlib.import_module(module_name)
        return getattr(module, class_name)
    except Exception as e:
        logging.warning(f"Failed to load configuration manager class {class_name}: {str(e)}")
        raise ValueError("Failed to load configuration manager class")
