    FILE *log_file;
    pthread_mutex_t mutex;
} LogConfig;

void logConditionalMessage(bool condition, const LogConfig *config, const char *format, ...) {
    if (!condition || config->log_threshold <= 0) return;

    va_list args;
    char buffer[4096]; // Maximum character limit for a message
    size_t bytes_written = snprintf(buffer, sizeof(buffer), "%s", format);

    if (bytes_written >= sizeof(buffer)) {
        // Handle overflow here by logging an error or truncating the message.
    }

    va_start(args, format);
    size_t bytes_available = sizeof(buffer) - bytes_written;
    bytes_written += vsnprintf(&buffer[bytes_written], bytes_available, format, args);

    if (bytes_written >= sizeof(buffer)) {
        // Handle overflow here by logging an error or truncating the message.
    }

    va_end(args);

    pthread_mutex_lock(&config->mutex);
    if (!config->log_file || !ferror(config->log_file) || fseeko64(config->log_file, 0, SEEK_END) < 0) {
        // If log file is not writable or an error occurred during seeking, handle the error gracefully.
    } else if (ftello64(config->log_file) > config->log_threshold) {
        // If the total number of characters logged exceeds the threshold, handle it appropriately.
    } else {
        fputs(buffer, config->log_file);
        fflush(config->log_file);
    }
    pthread_mutex_unlock(&config->mutex);
}
