async function fetchScripts(scriptObjects) {
  const fetchedScriptObjects = [];
  const priorityQueue = getPriorityQueue(scriptObjects);

  while (priorityQueue.length) {
    const scriptObject = priorityQueue.shift();

    try {
      const [validatedScript, metadata] = await validateAndFetchScriptMetadata(scriptObject);
      if (isScriptInCache(validatedScript.src)) {
        fetchedScriptObjects.push(cacheScriptToMemoryAndLocalStorage(validatedScript));
        continue;
      }

      const scriptTag = createScriptTag(validatedScript, metadata);
      fetchedScriptObjects.push(scriptTag);

      // Load scripts in parallel up to 4 at a time
      if (fetchedScriptObjects.length === 4) {
        await loadScriptsInParallel(fetchedScriptObjects);
        fetchedScriptObjects = [];
      }
    } catch (error) {
      if (shouldRetryError(error)) {
        priorityQueue.unshift(scriptObject); // Retry with higher priority
      } else {
        throw error; // Propagate the error for logging and handling
      }
    }
  }

  return fetchedScriptObjects;
}

// Helper function to create script tags based on script object and metadata
function createScriptTag(script, metadata) {
  const inlineScriptContent = metadata.inline || '';
  const scriptTag = `<script${metadata.attributes}>${inlineScriptContent}${script.content}</script>`;
  return scriptTag;
}

