public void InsertAfter(ConcurrentQueue<string> queue, string searchString, string insertString)
{
    int position = queue.FindIndex(x => x == searchString);
    if (position < 0)
    {
        queue.Enqueue(insertString);
    }
    else
    {
        queue.Insert(position + 1, insertString);
    }
}
