use std::env;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

static DIRECTORY_ENV_VAR: Mutex<Option<PathBuf>> = Mutex::new(None);

pub fn create_and_set_directory(directory_name: &str) -> Result<(), Box<dyn std::error::Error> {
    let mut guard = DIRECTORY_ENV_VAR.lock().unwrap();
    if *guard == None {
        let current_dir = env::current_dir()?;
        let new_dir = current_dir.join(directory_name);
        std::fs::create_dir_all(&new_dir)?;
        *guard = Some(new_dir);
    }

    let dir_path = match *guard {
        Some(path) => path,
        None => return Err(Box::new(std::io::Error::new(std::io::ErrorKind::NotFound, "Environment variable not found"))),
    };

    env::set_var("MYAPP_DIR", dir_path.to_str().unwrap());

    Ok(())
}
```

