    ciphers = sorted([line.strip() for line in lines], key=str.lower)
    return ciphers

def get_cipher(name):
    if name not in CACHE:
        try:
            mod = __import__(name, fromlist=[f"{name}.{name}"])
            func = getattr(mod, 'Fernet')
            CACHE[name] = func()
        except (ModuleNotFoundError, AttributeError):
            raise ValueError(f'Cipher module {name} not found or missing Fernet function.')
    return CACHE[name]

def encrypt_data(data, ciphers):
    with ProcessPoolExecutor(max_workers=4) as executor:
        results = list(executor.map(lambda x: x[1](x[0]), enumerate(ciphers)))
    return b''.join(results)

