```rust
use std::env;
use std::fs::File;
use std::io::{BufWriter, Write};
use std::process::{Command, Stdio};
use std::sync::OnceLock;
use rustc_driver::{Config, Cargo Toml, EarlyError, Error, ErrorDiagnosticField, ExitCode, RustcDriver};
use std::time::Instant;

static LOGGER: OnceLock<Box<dyn Fn(&String) + Send + Sync> = OnceLock::new();

fn start_logger(f: Box<dyn Fn(&String) + Send + Sync>) {
    *LOGGER.get_or_init(|| f)
}

fn compile() -> Result<ExitCode, Error> {
    let start = Instant::now();
    let rss_max = std::process::Pid::current().peak_rss();

    // Initialize the logger only once and share among multiple compilation processes.
    let logger = LOGGER.get();

    // Configure the Rust compiler with custom logging and memory usage hooks.
    let config = Config::new()
        .std(Stdio::inherit())
        .env_callback(|key, value| {
            if key == "RUSTC_LOG" || key == "RUSTDOCTOOL_LOG" {
                Some(value.to_owned() + ",log_target=log")
            } else {
                None
            }
        })
        .diagnostic_field(|field| match field {
            ErrorDiagnosticField::Message(_, msg) => {
                logger(&format!("Compilation error: {}", msg))
            }
            _ => (),
        });

    // Create a temporary Cargo.toml file to specify the target crate and version.
    let cargo_toml = tempfile::NamedTempFile::new("Cargo.toml")?;
    {
        let mut f = BufWriter::new(cargo_toml);
        writeln!(f, "[package]")?;
        writeln!(f, "name = \"my-crate\"")?;
        writeln!(f, "version = \"1.0.0\"")?;
        writeln!(f, "edition = \"2018\"")?;
        writeln!(f, "[lib]")?;
        writeln!(f, "name = \"my_crate\"")?;
        writeln!(f, "path = \"src/lib.rs\"")?;
    }

    let cargo_manifest_dir = cargo_toml.path().parent().unwrap();
    let rustc = RustcDriver::new(config, Cargo Toml::from_path(cargo_manifest_dir))?;

    // Run the Rust compiler and catch any errors.
    let exit_code = rustc_driver::catch_with_exit_code(rustc, &["src/lib.rs"])?;

    // Log the duration of compilation, peak RSS, and exit code.
    logger(&format!(
        "Compilation complete in {}s (peak RSS: {})",
        start.elapsed().as_secs_f64(),
        rss_max
    ));

    Ok(exit_code)
}

fn main() {
    // Initialize the logger and start logging the compilation process.
    let _logger = start_logger(|msg| println!("{}", msg));

    if let Err(error) = compile() {
        early_panic!(error);
    }
}
```

This Rust function takes no arguments, runs the Rust compiler with custom logging and memory usage hooks installed, measures the time taken for the compilation and peak resident set size (RSS), and integrates with an external logging system. The code handles errors robustly using `rustc_driver::catch_with_exit_code` and `early_error`. It initializes the logger only once to improve performance and scalability, and logs detailed messages about the compilation process, including start and end times, and peak RSS. The function is organized in a way that allows for easy maintenance and extension, considering future requirements such as adding support for different compiler versions or custom logging formats.

