use url::Url;

mod json_processor {
    pub trait JsonProcessor {
        async fn process(&self, data: serde_json::Value) -> Result<(), Box<dyn std::error::Error>>;
    }
}

#[derive(Serialize, Deserialize, Debug)]
struct Config {
    processors: Vec<ProcessorConfig>,
    config_url: Url,
    root_dir: String,
}

#[derive(Serialize, Deserialize, Debug)]
struct ProcessorConfig {
    name: String,
    klass: String,
}

pub struct JsonParser {
    config: Arc<RwLock<Config>>,
    processors: HashMap<String, Box<dyn json_processor::JsonProcessor + Send + Sync + 'static>>,
}

impl JsonParser {
    pub async fn new(config_url: Url) -> Result<Self, Box<dyn std::error::Error>> {
        let config = load_and_parse_config(config_url).await?;
        Ok(JsonParser {
            config: Arc::new(RwLock::new(config)),
            processors: HashMap::new(),
        })
    }

    pub async fn register(&mut self, name: String, processor: Box<dyn json_processor::JsonProcessor + Send + Sync + 'static>) {
        let mut config = self.config.write().await;
        self.processors.insert(name, processor);
        drop(config);
    }

    pub async fn parse(&self, file_path: impl AsRef<Path>) -> Result<(), Box<dyn std::error::Error>> {
        let config = self.config.read().await;
        let mut data = serde_json::from_reader(BufReader::new(File::open(file_path)?));
        data.next_value().ok_or("Unexpected end of file")?;
        if let Some(processors) = config.as_vec() {
            for processor in &self.processors {
                for processor_config in processors {
                    if processor_config.name == processor.0 {
                        let result = spawn_blocking(move || {
                            processor.1.process(data.clone()).map(|_| ())
                        });
                        match result {
                            Ok(_) => (),
                            Err(e) => eprintln!("Error processing file {}: {}", file_path.as_ref().display(), e),
                        }
                    }
                }
            }
        }
        Ok(())
    }

    async fn load_and_parse_config(config_url: Url) -> Result<Config, Box<dyn std::error::Error>> {
        let mut data = Vec::new();
        let mut file = File::open(&config_url)?;
        file.read_to_end(&mut data)?;
        Ok(serde_json::from_slice(&data)?)
    }
}
