typedef struct {
    sem_t sem;
    int concurrency_limit;
} Semaphore;

void create_semaphore(Semaphore *sem, int value, int concurrency_limit) {
    if (sem_init(&(sem->sem), 0, value) != 0) {
        perror("Failed to initialize semaphore");
        exit(1);
    }
    sem->concurrency_limit = concurrency_limit;
}

void delete_semaphore(Semaphore *sem) {
    if (sem_destroy(&(sem->sem)) != 0) {
        perror("Failed to destroy semaphore");
        exit(1);
    }
}

int wait_and_take(Semaphore *sem) {
    int ret = sem_wait(&(sem->sem));
    if (ret == -1 && errno != EINTR) {
        perror("Failed to wait on semaphore");
        return 1;
    }
    return 0;
}

int signal_and_give(Semaphore *sem) {
    int ret = sem_post(&(sem->sem));
    if (ret == -1) {
        perror("Failed to post on semaphore");
        return 1;
    }
    return 0;
}

void log_error(const char *message, int error_code = 0) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    std::cout << timestamp << ": Error: " << message;
    if (error_code != 0) {
