void storeOptimizedImages(const std::string& outputDir, const std::unordered_set<std::string>& imageFiles) {
  std::filesystem::path optimizedPath(outputDir + "/optimized_images");
  if (!std::filesystem::exists(optimizedPath)) {
    std::filesystem::create_directory(optimizedPath);
