    soup = BeautifulSoup(requests.get(url).content, 'html.parser')
    for link in soup.findAll('a', href=True):
        if re.match(r'\.(jpg|jpeg|png)$', link['href']):
            img = get_image(link['href'])
            img = resize_and_compress(img, width, height, quality)
            images.append(img)
    for img in images:
        img.save('downloaded_images/' + img.filename)

