<?php

class PasswordManager {
    private $hashedPassword;
    private $characterSet;
    private $saltRoundCount = 12;

    public function __construct($characterSet) {
        $this->validateCharacterSet($characterSet);
        $this->characterSet = $characterSet;
    }

    public function generateRandomString($length, $characterSet) {
        $randomString = '';
        $characters = array_merge(
            range('A', 'Z'),
            range('a', 'z'),
            range(0, 9),
            array('!', '@', '#', '$', '%', '^', '&', '*', '-', '_', '+')
        );
        $characters = array_merge($characterSet, $characters);
        $max = strlen($characters) - 1;
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characters[rand(0, $max)];
        }
        return $randomString;
    }

    public function hashPassword($password) {
        return password_hash($password, PASSWORD_BCRYPT, array('cost' => $this->saltRoundCount));
    }

    public function checkPassword($providedPassword, $hashedPassword) {
        return password_verify($providedPassword, $hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        $regex = '/(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&_-+])/';
        if (!preg_match($regex, $characterSet)) {
            throw new Exception('Invalid character set');
        }
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 8 || $rounds > 31) {
            throw new Exception('Invalid salt round count');
        }
        $this->saltRoundCount = $rounds;
    }

    public function externalPolicyCheck($characterSet) {
        // Implement a call to your external password policy service here.
        // Return a boolean indicating whether the character set complies with the policy.
