using System.Threading;
using Imagemagick;
using OctoPrint.Core.Extensions;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Kernel.Utils;
using Newtonsoft.Json.Linq;

namespace ImageToPDF
{
    public class ConvertImagesToPdf
    {
        private const int MaxConcurrency = 10;
        private const string SemaphoreName = "ImageToPDF_Semaphore";
        private const string DefaultOutputFormat = "PDF";
        private const int ThumbnailInterval = 5;

        public void Execute(string directoryPath, string outputFileName, List<string> imageFileNames, JObject configuration)
        {
            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");

            var semaphore = CreateSemaphore(MaxConcurrency);

            try
            {
                using (var writer = new PdfWriter(outputFileName))
                {
                    var pdfDocument = new PdfDocument(writer);
                    var page = pdfDocument.AddNewPage();

                    var imageFilePaths = GetImageFilePaths(imageFileNames, configuration);
                    var imagesToProcess = imageFilePaths.Distinct().ToList();

                    Parallel.ForEach(imagesToProcess, imagePath =>
                    {
                        semaphore.WaitOne();

                        try
                        {
                            ProcessImageAndAddToPdf(imagePath, page, configuration);
                        }
                        catch (Exception ex)
                        {
                            LogError($"Failed to process image '{imagePath}': {ex.Message}", ex);
                        }
                        finally
                        {
                            semaphore.Release();
                        }
                    });
                }

                DeleteSemaphore(SemaphoreName);
            }
            catch (Exception exception)
            {
                LogError($"An error occurred while converting images to PDF: {exception.Message}", exception);
            }
        }

        private static Semaphore CreateSemaphore(int initialCount)
        {
            var semaphore = new Semaphore(initialCount, initialCount);
            SetNamedSemaphore(SemaphoreName, semaphore.CurrentState.MaximumCount);
            return semaphore;
        }

        private static void DeleteSemaphore(string name)
        {
            if (IsSemaphoreExists(name))
                ResetNamedSemaphore(name);
        }

        [DllImport("kernel32.dll")]
        private static extern bool SetNamedSemaphore(string name, int releaseCount);

        [DllImport("kernel32.dll")]
        private static extern bool ResetNamedSemaphore(string name);

        [DllImport("kernel32.dll", CharSet = CharSet.Auto)]
        private static extern bool IsSemaphoreExists(string name);

        private List<string> GetImageFilePaths(List<string> imageFileNames, JObject configuration)
        {
            var imageExtensions = configuration["image_extensions"]?.ToString().Split(';') ?? new[] { ".jpg", ".jpeg", ".png", ".gif" };
            return imageFileNames.Select(FileNameUtils.GetPath).Where(file => imageExtensions.Contains(Path.GetExtension(file))).ToList();
        }

        private void ProcessImageAndAddToPdf(string imageFilePath, DocumentPage page, JObject configuration)
        {
            // Embed metadata, optimize PDF generation, generate thumbnails, etc...
        }

        private void LogError(string message, Exception exception = null)
        {
            var timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
            Console.WriteLine($"[{timestamp}] {message}");

            if (exception != null)
                Console.WriteLine($"[{timestamp}] Error Code: {exception.GetType().FullName}\n[{timestamp}] Message: {exception.Message}\n[{timestamp}] Stack Trace: {exception.StackTrace}");
        }
    }
}
```

