use std::fs::File;
use std::io::{BufRead, BufReader};
use serde_json::from_reader;

fn load_configuration(path: &str) -> Result<Configuration, Box<dyn std::error::Error>> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    from_reader::<Configuration>(reader).map_err(|e| e.into())
}
```

