struct Word { char *word; size_t length; };
typedef struct Word Word;

// External data source API callback
void fetchWordsCallback(Word **words, int *numWords, void *userdata) {
    // Implement your API call here, handle errors, caching, etc.
}

void dynamicTrimAndCapitalize(char **input, size_t *length) {
    // ... (initialize variables, check for valid pointers, etc.)

    Word *wordList = NULL;
    int numWords = 0;

    fetchWordsCallback(&wordList, &numWords, NULL); // Fetch the word list

    if (!wordList) {
        // Handle error during data fetching
        return;
    }

    size_t averageWordLength = numWords ? (size_t)(*length / numWords) : 0;
    size_t newLength = (*length > numWords * averageWordLength ? (*length) : numWords * averageWordLength);

    char *result = malloc(newLength + 1); // Allocate memory for the result string
    if (!result) {
        // Handle out of memory error
        return;
    }

    size_t currentPos = 0;
    for (int i = 0; i < numWords; ++i) {
        const char *wordStart = wordList[i].word;
        const char *wordEnd = memchr(wordList[i].word, '\0', wordList[i].length);

        // Trim the word and move the result string pointer accordingly
        memmove(&result[currentPos], wordStart + 1, wordEnd - (wordStart + 1));
        currentPos += (wordEnd - (wordStart + 1));

        // Capitalize the first letter of the word
        result[currentPos] = toupper(*(wordStart + 0));
        ++currentPos;
    }

    // Ensure the total length does not exceed the adjusted size limit
    if (currentPos >= newLength) {
        free(result);
        return NULL;
    }

    result[currentPos] = '\0';
    *length = currentPos;

    // Free the allocated memory for the word list and individual words
    for (int i = 0; i < numWords; ++i) {
        free(wordList[i].word);
    }
    free(wordList);

    return result;
}
