```javascript
async function asyncArrayReduce(arr, initialValue, callback, options) {
    let accumulator = options ? options.initialValue || initialValue : initialValue;
    const semaphore = new Semaphore(options ? options.concurrencyLevel || 4 : 4);

    return new Promise((resolve, reject) => {
        function reducer(accumulator, currentValue, callbackFn) {
            callbackFn((err, result) => {
                if (err) {
                    return reject(err);
                }
                accumulator = callback(accumulator, currentValue, result);

                if (!options || !options.throttle) {
                    semaphore.release();
                }
            });
        }

        function processNextOperation() {
            const currentIndex = arr.length ? Math.min(arr.length - 1, semaphore.acquire()) : undefined;
            if (currentIndex !== undefined) {
                reducer(accumulator, arr[currentIndex], callback);
            } else {
                resolve(accumulator);
            }
        }

        processNextOperation();
    });
}
