```rust
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::process::Command;
use std::sync::mpsc::channel;
use std::time::Instant;
use walkdir::{DirEntry, WalkDir};

fn summaryCompilation(path: &str) {
    let (tx, rx) = channel::<Result<(), Box<dyn std::error::Error>>>();

    let start_time = Instant::now();
    let mut peak_memory = 0;
    walkdir::WalkDir::new(path)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| if e.file_type().is_file() {
            e.path().extension().and_then(|ext| ext.to_str()). filter(|s| s == "rs")
        } else {
            false
        })
        .for_each(|entry| {
            let path = entry.into_path();
            let mut cmd = Command::new("rustc");
            cmd.arg(&path);
            cmd.stdout(Stdio::piped());
            cmd.stderr(Stdio::piped());
            let mut child = cmd.spawn().expect("Failed to spawn process");
            let stdout = child.stdout.unwrap();
            let mut stderr = child.stderr.unwrap();
            let output = BufReader::new(stdout).lines();
            let error = BufReader::new(stderr).lines();
            let (tx_send, tx_recv) = channel::<String>();
            let thread = thread::spawn(move || {
                for line in output.filter_map(|l| l.ok()) {
                    println!("{}", line);
                }
                tx_send.send("".to_string()).unwrap();
            });
            let mut errors = String::new();
            for line in error.filter_map(|l| l.ok()) {
                errors += &format!("{}\n", line);
            }
            drop(thread);
            if !errors.is_empty() {
                tx.send(Err(Box::new(errors)))
                    .expect("Failed to send error message");
                return;
            }
            let time = Instant::now();
            child.wait().unwrap();
            let elapsed = time.duration_since(start_time).as_millis() as u64;
            tx.send(Ok(()))
                .expect("Failed to send result");
            if elapsed > peak_memory {
                peak_memory = elapsed;
            }
        });

    let elapsed = start_time.elapsed().as_secs() as u64;
    println!("Compilation time: {} seconds", elapsed);
    println!(
        "Peak memory usage: {} megabytes",
        (peak_memory as f64 / 1024f64 / 1024f64).round()
    );
}
