class CryptoModule:
    def __init__(self, config_file):
        self.config = self._read_config(config_file)

    @staticmethod
    def _read_config(filename):
        with open(filename, encoding='utf-8') as f:
            lines = [line.strip() for line in f]
            entries = sorted([entry.split('=') for entry in lines if re.match(r'^[a-zA-Z0-9]+=[^#]+$', entry)], key=lambda x: x[0])
            cryptos = {name: (hmac.new(key.encode(), digestmod=hashlib.sha256).digest(), int(params.split('_')[-1])) for name, key, params in entries}
        return cryptos

    def get_cipher(self, cipher_name: str) -> Tuple[bytes, int]:
        if cipher_name not in self.config:
            raise KeyError(f"Cipher '{cipher_name}' not found in the configuration.")
        return self.config[cipher_name]

    def get_hash_function(self, hash_name: str) -> hashlib.sha256:
        if hash_name not in self.config:
            raise KeyError(f"Hash '{hash_name}' not found in the configuration.")
