class ConfigManager {
public:
    ConfigManager(const std::vector<std::string>& filePaths) : ioService_(new boost::asio::io_service), mutex_(), filePaths_(filePaths) {}

    ConfigManager(const ConfigManager&) = delete;
    ConfigManager& operator=(const ConfigManager&) = delete;

    ConfigManager(ConfigManager&& other) noexcept {
        swap(*this, other);
    }

    ConfigManager& operator=(ConfigManager&& other) noexcept {
        swap(*this, other);
    }

    template<typename T>
    const T& getSetting(const std::string& key) {
        boost::lock_guard<boost::mutex> lock(mutex_);
        auto it = settings_.find(key);
        if (it != settings_.end()) {
            return it->second.get();
        }
        throw std::runtime_error("Setting not found");
    }

    void loadSettings() {
        for (const auto& filePath : filePaths_) {
            try {
                nlohmann::json settings;
                std::ifstream ifs(filePath);
                if (!ifs.is_open()) {
                    continue;
                }
                ifs >> settings;
                for (const auto& [key, value] : settings.items()) {
                    validateSetting<T>(key, value);
                    settings_.emplace(key, std::make_unique<T>(value));
                }
            } catch (std::exception& e) {
                std::cerr << "Error loading settings from file: " << filePath << ": " << e.what() << std::endl;
            }
        }
    }

    void saveSettings() {
        for (const auto& [key, setting] : settings_) {
            try {
                nlohmann::json settings;
                settings[key] = setting->to_json();
                std::ofstream ofs(filePaths_[key]);
                if (!ofs.is_open()) {
                    continue;
                }
                ofs << settings.dump() << std::endl;
            } catch (std::exception& e) {
                std::cerr << "Error saving settings to file: " << filePaths_[key] << ": " << e.what() << std::endl;
            }
        }
    }

    void addObserver(const std::function<void()>& observer) {
        observers_.insert(observer);
    }

private:
    template<typename T>
    static void validateSetting(const std::string& key, const nlohmann::json& value) {
        if (!value.is<T>()) {
            throw std::invalid_argument("Invalid setting type for key: " + key);
        }
        auto typedValue = value.get<T>();
        // Add your range constraint checks here
    }

    void swap(ConfigManager& other) noexcept {
        using std::swap;
        swap(ioService_, other.ioService_);
        swap(mutex_, other.mutex_);
        swap(filePaths_, other.filePaths_);
        swap(settings_, other.settings_);
        swap(observers_, other.observers_);
    }

    boost::asio::io_service& ioService_;
    boost::mutex mutex_;
    std::vector<std::string> filePaths_;
    std::map<std::string, std::unique_ptr<T>> settings_;
