    create_logger();
    match get_remote_directory()? {
        path @ Some(ref p) => {
            log::info!("Using existing remote configuration directory: {}", p.display());
            if !config_dir.exists() {
                log::debug!("Creating local configuration directory");
                create_local_directory(&config_dir)?;
            }
            let repository = Repository::discover(path).map_err(|e| e.into())?;
            sync_with_remote(&repository, &config_dir)?;
        }
        None => {
            log::info!("No remote configuration directory found");
            if !config_dir.exists() {
                log::debug!("Creating local configuration directory");
                create_local_directory(&config_dir)?;
                let temp_dir = TempDir::new().unwrap();
                sync_with_remote(temp_dir.path(), &config_dir)?;
            } else {
                log::warn!("Local configuration directory exists but not synced with remote");
            }
        }
    }

    let config = get_current_config()?;
    store_config(&config)?;

    Ok(())
}
