using System.Xml.XPath;
using System.IO;
using System.Threading.Tasks;
using System.Runtime.Caching;
using log4net;

public class DynamicXmlProcessor
{
    private static readonly ILog _log = LogManager.GetLogger(typeof(DynamicXmlProcessor));
    private ObjectCache _cache;
    private XmlDocument _document;
    private object _syncLock = new object();

    public DynamicXmlProcessor(ObjectCache cache)
    {
        _cache = cache;
    }

    public async Task<XmlDocument> LoadDocumentAsync(string filePath)
    {
        if (_cache.Get(filePath) is XmlDocument cachedDoc)
            return cachedDoc;

        _document = new XmlDocument();
        using (var reader = XmlReader.Create(filePath))
        {
            _document.Load(reader);
        }

        await Task.Run(() => CacheDocument());

        return _document;
    }

    private void CacheDocument()
    {
        _cache.Add(new CacheItem("DynamicXmlProcessor_" + _document.OuterXml.GetHashCode(), _document),
            new CacheItemPolicy
            {
                AbsoluteExpiration = DateTimeOffset.Now.AddMinutes(5),
                SlidingExpiration = TimeSpan.FromSeconds(30)
            });
    }

    public IEnumerable<XNode> ParseXPathExpression(string xpathExpression)
    {
        lock (_syncLock)
        {
            var nodes = _document.SelectNodes(xpathExpression);
            return nodes?.Cast<XNode>();
        }
    }

    // Implement other methods as specified in the task description
}
