use std::env;
use std::fs;
use std::path::{Path, PathBuf};

pub fn create_directory_and_set_env(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let dir_path = Path::new(&dir_name);
    if env::var("PATH").ok().map(|v| v.contains(dir_path)).unwrap_or(false) {
        println!("Directory already exists and is in the environment path.");
        return Ok(());
    }

    if !fs::create_dir_all(dir_path).is_ok() {
        return Err("Failed to create directory.".into());
    }

    let dir_path_str = dir_path.to_str().unwrap();
    env::set_var("MY_DIRECTORY", dir_path_str);
    println!("Created new directory: {}", dir_path_str);
    Ok(())
}
