import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CommandManager {

    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final List<String> nodes = Arrays.asList("node1", "node2", "node3"); // Update this list with your node information

    public void executeCommand(String command, String filePath) {
        if (Files.exists(Path.of(filePath))) {
            try {
                Files.deleteIfExists(Path.of(filePath));
            } catch (Exception e) {
                System.err.println("Error deleting the file: " + e.getMessage());
            }
        }

        CommandTask commandTask = new CommandTask(command, filePath);
        executor.submit(commandTask);
    }

    private class CommandTask implements Runnable {
        private final String command;
        private final String filePath;

        public CommandTask(String command, String filePath) {
            this.command = command;
            this.filePath = filePath;
        }

        @Override
        public void run() {
            Process process;
            try {
                List<String> cmd = Arrays.asList("bash", "-c", command); // Use 'sh' or another shell depending on your system
                process = Runtime.getRuntime().exec(cmd, null, getNode());

                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                Thread inputThread = new Thread(() -> {
                    try {
                        String line;
                        while ((line = reader.readLine()) != null) {
                            System.out.println(line);
                        }
                    } catch (IOException e) {
                        System.err.println("Error reading command output: " + e.getMessage());
                    }
                });

                Thread errorThread = new Thread(() -> {
                    try {
                        String line;
                        while ((line = errorReader.readLine()) != null) {
                            System.err.println("Error: " + line);
                        }
                    } catch (IOException e) {
                        System.err.println("Error reading command error: " + e.getMessage());
                    }
                });

                inputThread.start();
                errorThread.start();

                int exitValue = process.waitFor(60, TimeUnit.SECONDS); // Adjust the timeout as needed

                if (exitValue != 0) {
                    System.err.println("Command execution failed with exit value: " + exitValue);
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Error executing command: " + e.getMessage());
            }
        }

        private Process getNode() {
            // Use the nodes list to determine the appropriate node for execution, depending on your implementation
            return null; // Update this with your logic for choosing a suitable node for command execution
        }
    }
}
