    void establishDbConnection(const DatabaseConfig& config, std::function<void()> callback) {
        if (config.getDatabaseURL().empty()) {
            logError("Empty database URL.");
            throw std::runtime_error("Empty database URL.");
        }
        if (config.getUsername().empty()) {
            logError("Empty username.");
            throw std::runtime_error("Empty username.");
        }
        if (config.getPassword().empty()) {
            logError("Empty password.");
            throw std::runtime_error("Empty password.");
        }
        if (config.getConnectionTimeout() <= 0) {
            logError("Invalid connection timeout.");
            throw std::runtime_error("Invalid connection timeout.");
        }
        if (config.getMaxRetries() <= 0) {
            logError("Invalid max retries.");
            throw std::runtime_error("Invalid max retries.");
        }
        std::unique_lock<std::mutex> lock(*mutex);
        connectionCount++;
        auto timeout = config.getConnectionTimeout();
        auto maxRetries = config.getMaxRetries();

        auto connection = DatabaseDriver::createConnection(config);
        bool success = false;
        for (int retry = 0; retry < maxRetries && !success; ++retry) {
            if (connection->connect()) {
                success = true;
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(timeout));
            }
        }
        if (!success) {
            logError("Failed to establish a database connection.");
            throw std::runtime_error("Failed to establish a database connection.");
        }
        callback();
        lock.unlock();
    }
private:
    int connectionCount = 0;
    std::unique_ptr<std::mutex> mutex = std::make_unique<std::mutex>();
};
