        var bestCsp = _cspProviders.Find(csp => csp.PerformsBestUnder(networkConditions));
        return bestCsp ?? _cspProviders[0]; // Fallback to default CSP when no suitable CSP is found
    }

    private byte[] Decrypt(byte[] encryptedMessage, ICryptoTransform decryptor)
    {
        using (var ms = new MemoryStream(encryptedMessage))
        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
        {
            var decryptedBytes = new byte[cs.ReadByte()];
            cs.Read(decryptedBytes, 0, decryptedBytes.Length);
            return decryptedBytes;
        }
    }
}
