#include <stdio.h>
#include <jansson.h>
#include <openssl/md5.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <time.h>

// Global variables and structures for data storage and synchronization
typedef struct Record {
    char key[MAX_KEY_LENGTH];
    int value;
    long offset;
} Record;

Record *records;
long num_records;
pthread_mutex_t records_mutex;

// Hashing function to generate MD5 hash
char *md5_hash(const char *data) {
    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data, strlen(data));
    MD5_Final(md5, &ctx);

    // Convert the binary digest into a hexadecimal string
    char md5_str[MD5_DIGEST_LENGTH * 2 + 1];
    for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        snprintf(md5_str + i * 2, sizeof(md5_str), "%02x", md5[i]);
    }

    return strdup(md5_str);
}

// Function to parse JSON configuration string and perform range-based key assignment
void assign_values(const char *json_config, char **keys, size_t num_keys) {
    // Parse the JSON configuration string
    json_t *root = json_loads(json_config, 0, NULL);

    // Extract the range and other necessary details from the parsed JSON
    double start, end;
    json_object_foreach(root, key, value) {
        if (strcmp(key, "start") == 0) {
            start = json_number_value(value);
        } else if (strcmp(key, "end") == 0) {
            end = json_number_value(value);
        }
    }

    // Distribute values across the provided keys based on the specified range
    for (size_t i = 0; i < num_keys; ++i) {
        double current = (start + end) / 2.0 - ((end - start) / num_keys * i);

        // Use the MD5 hash of the JSON configuration string as a key for load balancing
        char *config_hash = md5_hash(json_config);
        int storage_node_index = hash(config_hash) % NUM_STORAGE_NODES;

        // Interact with the selected storage service and perform range-based assignment
        store_value((char *)keys[i], current, storage_node_index);
    }
}

// Implement a retry mechanism for transient failures when interacting with the storage services
void store_value(const char *key, double value, int storage_node_index) {
    // Define maximum number of retries and backoff multiplier
    #define MAX_RETRIES 5
    #define BACKOFF_MULTIPLIER 2

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        bool success = interact_with_storage_service(key, value, storage_node_index);
        if (success) return;

        // Exponential backoff before retrying
        usleep(attempt * BACKOFF_MULTIPLIER * BACKOFF_DURATION);
    }
}

// Helper functions to optimize memory allocation and ensure thread safety
void init_data_structures() {
    records = malloc((num_records + 1) * sizeof(Record));
    pthread_mutex_init(&records_mutex, NULL);
}

void cleanup_data_structures() {
    free(records);
    pthread_mutex_destroy(&records_mutex);
}

// ... (missing: integration with specific APIs, load balancing, efficient use of system resources)

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <JSON configuration string> <key1> <key2> ...\n", argv[0]);
        return 1;
    }

    const char *json_config = argv[1];
    char **keys = &argv[2];
    size_t num_keys = argc - 3;

    init_data_structures();

    assign_values(json_config, keys, num_keys);

    cleanup_data_structures();

    return 0;
}
