    public class Deserializer
    {
        private readonly IDbConnection _dbConnection;
        private readonly Func<string, HashAlgorithm> _hashAlgorithmFactory;
        private readonly long _maxFileSize;

        public Deserializer(IDbConnection dbConnection, Func<string, HashAlgorithm> hashAlgorithmFactory, long maxFileSize)
        {
            _dbConnection = dbConnection;
            _hashAlgorithmFactory = hashAlgorithmFactory;
            _maxFileSize = maxFileSize;
        }

        public async Task DeserializeAsync(Stream fileStream)
        {
            if (fileStream.Length > _maxFileSize)
                throw new InvalidDataException("File is too large to deserialize.");

            using var checksumStream = new HashStream(fileStream, _hashAlgorithmFactory("SHA256"));
            var fileChecksum = checksumStream.GetHash();

            if (ShouldValidateChecksum() && !DoesChecksumMatch(fileChecksum))
                throw new InvalidDataException("File has an invalid checksum.");

            using var binaryReader = new BinaryReader(fileStream);

            int version;
            while (binaryReader.PeekChar() != 0) // Stream reading with PeekChar ensures efficient memory usage
            {
                version = binaryReader.ReadInt32();
                DeserializeVersion(version, binaryReader);
            }
        }

        private void DeserializeVersion(int version, BinaryReader reader)
        {
            // Implement deserialization for each supported version here
            // Use a switch statement or factory method to handle multiple versions gracefully
        }

        private byte[] GetHash(byte[] data) => _hashAlgorithmFactory("SHA256").ComputeHash(data);

        private bool ShouldValidateChecksum() => _hashAlgorithmFactory != null;

        private bool DoesChecksumMatch(byte[] fileChecksum)
        {
            // Retrieve the stored checksum from the database, if applicable
            var storedChecksum = _dbConnection.QueryFirstOrDefault<byte[]>("SELECT Checksum FROM FileHashes WHERE FileId = @FileId", new { FileId = GetFileId() });

            return storedChecksum?.SequenceEqual(fileChecksum) ?? false;
        }

        private int GetFileId() => // Implement logic to get the file id here, e.g., based on filename or path
        {
            throw new NotImplementedException();
        }
    }

    public class HashStream : Stream
    {
        private readonly Stream _innerStream;
        private readonly HashAlgorithm _hashAlgorithm;
        private byte[] _buffer;

        public HashStream(Stream innerStream, Func<string, HashAlgorithm> hashAlgorithmFactory)
        {
            _innerStream = innerStream;
            _hashAlgorithm = hashAlgorithmFactory("SHA256");
        }

        public override void Write(byte[] buffer)
        {
            if (_buffer == null || _buffer.Length < _buffer.LongLength)
                _buffer = new byte[_buffer.LongLength];

            buffer.AsMemory().CopyTo(_buffer.AsMemory());
            _innerStream.Write(_buffer);

            _hashAlgorithm.TransformBlock(_buffer, 0, _buffer.Length, null, 0);
        }

        public override void Flush() => _innerStream.Flush();

        public byte[] GetHash()
        {
            _hashAlgorithm.TransformFinalBlock(new byte[0], 0, 0);
            return _hashAlgorithm.Hash;
        }
    }
}
