#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <curl/curl.h>
#include <string.h>

typedef struct {
    int rxi;
    int rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

static CURL *g_curl = NULL;
static size_t g_memory_usage = 0;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

int processNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int log_level, const char *external_data_source_url, int max_memory_usage_kb) {
    if (max_memory_usage_kb <= 0 || num_structures <= 0) {
        return -1; // Invalid input parameters
    }

    if (!g_curl) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        g_curl = curl_easy_init();
    }

    *nfalist = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*nfalist) {
        return -2; // Memory allocation failure
    }

    pthread_mutex_lock(&g_mutex);
    g_memory_usage += num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (g_memory_usage > max_memory_usage_kb * 1024) {
        free(*nfalist);
        return -3; // Memory usage exceeded the limit
    }
    pthread_mutex_unlock(&g_mutex);

    for (int i = 0; i < num_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &(*nfalist)[i];

        if (curl_easy_perform(g_curl, external_data_source_url) != CURLE_OK) {
            log_structure_creation(log_level, "Failed to fetch data from the URL.");
            continue;
        }

        curl_easy_getinfo(g_curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &entry->rxi);
        if (entry->rxi <= 0 || entry->rxi > INT_MAX) {
            log_structure_creation(log_level, "Invalid RX_UE_INFORMATION_TAG value.");
            continue;
        }

        curl_easy_getinfo(g_curl, CURLINFO_HEADER_CONTENT_LENGTH, &entry->rnti);
        if (entry->rnti <= 0 || entry->rnti > INT_MAX) {
            log_structure_creation(log_level, "Invalid RNTI value.");
            continue;
        }

        entry->crcflag = crc_flag_rules[i % sizeof(crc_flag_rules)];
        log_structure_creation(log_level, "Created structure with RX_UE_INFORMATION_TAG=%d and RNTI=%d.", entry->rxi, entry->rnti);
    }

    return 0; // Success
}
