        {"case-sensitive", no_argument, NULL, 'c'},
        {"output-file", required_argument, NULL, 'o'},
        {0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "hc:o:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                usage();
                return 0;
            case 'c':
                config->case_sensitive = true;
                break;
            case 'o':
                config->output_file = optarg;
                break;
