```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <log4cxx/logger.h> // External logging system

// Define log4cxx logger
log4cxx::LoggerPtr logger(log4cxx::Logger::getLogger("filename_modifier"));

char* ParseFilename(const char* filename) {
    size_t lastDot = strlen(filename) - 1;
    for (; lastDot > 0 && filename[lastDot] != '.'; --lastDot);
    return strdup(filename < lastDot ? filename : filename + 1);
}

int DetermineDigits(const char* fileType) {
    // Implement mapping between file types and digit counts here
    static const int digits[] = {3, 5};
    for (size_t i = 0; i < sizeof(fileTypes) / sizeof(*fileTypes); ++i) {
        if (!strcasecmp(fileType, fileTypes[i])) return digits[i];
    }
    return -1; // Unsupported file type
}

bool ValidateFileType(const char* fileType) {
    static const char* fileTypes[] = {"txt", "jpg", "png", "pdf"};
    for (size_t i = 0; i < sizeof(fileTypes) / sizeof(*fileTypes); ++i) {
        if (!strcasecmp(fileType, fileTypes[i])) return true;
    }
    return false;
}

void SetFileType(char* filename, const char* newExt) {
    size_t extLen = strlen(newExt);
    memmove(filename + strlen(filename), newExt, extLen + 1);
    filename[strlen(filename)] = '.';
    filename[strlen(filename) + 1] = '\0';
}

char* CreateNewFilename(const char* baseName, int digits) {
    // Implement string manipulation for creating new filenames here
    static const char* zero = "0";
    size_t len = strlen(baseName);
    char* result = malloc(len + digits + 2);
    memset(result, 0, len + digits + 2);
    strcpy(result, baseName);
    for (size_t i = len; i < len + digits; ++i) {
        result[i] = zero[(len + digits - i - 1) % 3];
    }
    return result;
}

int ModifyFilename(const char* filename, const char* newExt) {
    if (!filename || !*filename || strlen(newExt) < 2) return EINVAL; // Invalid arguments

    char* baseName = ParseFilename(filename);
    if (!baseName) {
        logger->error("Unable to parse filename: " + std::string(filename));
        free(baseName);
        return ENOMEM; // Memory allocation error
    }

    int digits = DetermineDigits(newExt);
    if (digits < 0) {
        logger->error("Unsupported file type: " + std::string(newExt));
        free(baseName);
        return ENOTSUP; // Unsupported file type
    }

    if (!ValidateFileType(newExt)) {
        logger->error("Invalid file extension: " + std::string(newExt));
        free(baseName);
        return EINVAL; // Invalid extension
    }

    char* newFilename = CreateNewFilename(baseName, digits);
    if (!newFilename) {
        logger->error("Failed to create new filename");
        free(baseName);
        return ENOMEM; // Memory allocation error
    }

    SetFileType(newFilename, newExt);

    int fd = open(newFilename, O_WRONLY | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR | S_IXUSR);
    if (fd < 0) {
        logger->error("Unable to create new file: " + std::string(newFilename));
        free(baseName);
        free(newFilename);
        return errno; // System error
    }

    close(fd); // Close the file descriptor

    unlink(filename); // Delete the original file
    free(baseName); // Free base name

    logger->info("Modified filename: " + std::string(newFilename));
    return 0; // Success
}
```

