```python
import os
import sys
import time
import shutil
import signal
import errno
import logging
import contextlib
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
from configargparse import ArgumentParser, configure_argparse_apiserver_from_envvar

class LogRotationManager:
    def __init__(self, log_dir='logs', rotation_criteria='daily', backup_count=5):
        self.log_dir = log_dir
        self.rotation_criteria = rotation_criteria
        self.backup_count = backup_count
        self.create_directory()
        self.set_env()
        self.rotator = Rotator(self.log_dir, self.rotation_criteria, self.backup_count)
        self.monitor = Monitor(self.log_dir)

    def create_directory(self):
        if not os.path.exists(self.log_dir):
            os.makedirs(self.log_dir, exist_ok=True)

    def set_env(self):
        os.environ['LOG_DIR'] = self.log_dir

    @contextlib.contextmanager
    def log_file(self):
        filename = f"{os.path.join(self.log_dir, '{time.strftime(%Y-%m-%d)}-app.log')}"
        try:
            self.rotator.rotate()
            yield open(filename, 'a')
        except Exception as e:
            print(f"Error during log writing: {e}")

    class Rotator:
        def __init__(self, log_dir, rotation_criteria, backup_count):
            self.log_dir = log_dir
            self.rotation_criteria = rotation_criteria
            self.backup_count = backup_count
            self.previous_files = []

        def rotate(self):
            current_files = [f for f in os.listdir(self.log_dir) if f.endswith(".log")]
            to_remove = current_files[:len(current_files) - self.backup_count]
            for file in to_remove:
                try:
                    os.remove(os.path.join(self.log_dir, file))
                except OSError as e:
                    if e.errno != errno.ENOENT:
                        raise e

            if self.rotation_criteria == 'size-based':
                self._rotate_by_size()
            else:
                self._rotate_daily()
            self.previous_files = current_files

        def _rotate_daily(self):
            for file in self.previous_files:
                new_file = f"{os.path.join(self.log_dir, f'{time.strftime("%Y-%m-%d")}-{file}')}"
                os.rename(os.path.join(self.log_dir, file), new_file)

        def _rotate_by_size(self):
            largest = max([os.path.getsize(os.path.join(self.log_dir, f)) for f in self.previous_files], default=0)
            files_to_rename = [f for f in self.previous_files if os.path.getsize(os.path.join(self.log_dir, f)) == largest]
            for file in files_to_rename:
                new_file = f"{os.path.join(self.log_dir, f'{largest}.{file}')}"
                os.rename(os.path.join(self.log_dir, file), new_file)

    class Monitor:
        def __init__(self, log_dir):
            self.observer = Observer()
            self.event_handler = RotationEventHandler(log_dir)
            self.observer.schedule(self.event_handler, path=log_dir, recursive=False)
            self.observer.start()

class RotationEventHandler(FileSystemEventHandler):
    def on_modified(self, event):
        if not event.is_directory:
            logging.info(f"Log file modified, rotating...")
            self._rotate_logfile(event.src_path)

    @staticmethod
    def _rotate_logfile(logfile):
        log_manager = LogRotationManager()
        with log_manager.log_file() as f:
            pass  # write the log here
        log_manager.rotator.rotate()

if __name__ == "__main__":
    parser = ArgumentParser()
    configure_argparse_apiserver_from_envvar(parser, 'logging')
    args = parser.parse_args()
    if args.log_dir:
        log_manager = LogRotationManager(args.log_dir)
    else:
        log_manager = LogRotationManager()
```

This code uses `watchdog` library for monitoring the log files and handling events when they are modified. It also takes advantage of context managers for efficient resource management. The `rotate_logfile` function can be replaced with your custom logging logic.

