function traverseDOM(selector, callback) {
    let elementFinder = new ElementFinder(selector);
    let elements = elementFinder.getElements();

    let pendingPromises = [];

    function visitNode(node) {
        if (callback(node)) {
            return;
        }

        if (node.childNodes && node.childNodes.length > 0) {
            for (let i = 0; i < node.childNodes.length; i++) {
                pendingPromises.push(visitNode(node.childNodes[i]));
            }
        }
    }

    elements.forEach(element => {
        pendingPromises.push(visitNode(element));
    });

    return Promise.all(pendingPromises);
}
