void init_database() {
    int rc = sqlite3_open("database.db", &db);
    if (rc) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        exit(1);
    }
}

int count_records() {
    char *error_message = nullptr;
    sqlite3_stmt* stmt;
    int rc = sqlite3_prepare_v2(db, "SELECT COUNT(*) FROM records;", -1, &stmt, &error_message);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", error_message);
        sqlite3_free(error_message);
        return 0;
    }

    rc = sqlite3_step(stmt);
    if (rc != SQLITE_ROW) {
        fprintf(stderr, "Failed to step statement: %s\n", error_message);
        sqlite3_finalize(stmt);
        return 0;
    }

    int count = sqlite3_column_int(stmt, 0);
    sqlite3_finalize(stmt);
    return count;
}

void allocate_memory(int count) {
    records = (record*) malloc(count * sizeof(record));
    keys = (int*) malloc(count * sizeof(int));
    timestamps = (long*) malloc(count * sizeof(long));
    descriptions = (char**) calloc(count, 256);
    values = (double*) calloc(count, sizeof(double));
}

void set_random_values() {
    for (int i = 0; i < count; ++i) {
        keys[i] = rand() % 10000;
        timestamps[i] = time(NULL) + rand() % 31536000; // up to 1 year ahead
        descriptions[i][0] = '\0'; // initialize string to empty
        strncat(descriptions[i], generate_random_string(), 255);
        values[i] = (double) ((rand() % 20000) - 10000.0);
    }
}

void init_records() {
    int count = count_records();
    allocate_memory(count);
    set_random_values();
}

