class ConfigManager:
    def __init__(self, remote_endpoint, local_config_file, cache_expiration=600):
        self.remote_endpoint = remote_endpoint
        self.local_config_file = local_config_file
        self.cache_expiration = timedelta(seconds=cache_expiration)
        self.ssm = boto3.client('ssm')
        self.last_fetched = 0

    @lru_cache()
    def get_config(self):
        if time.time() - self.last_fetched > self.cache_expiration:
            remote_data = self.ssm.get_parameters_by_path(Path=self.remote_endpoint)['Parameters']
            if remote_data:
                config = json.loads(remote_data[0]['Value'])
                self.last_fetched = time.time()
                return config

        if os.path.exists(self.local_config_file):
            with open(self.local_config_file) as f:
                try:
                    local_config = json.load(f)
                except Exception as e:
                    print(f'Error loading local configuration file: {e}')
                    return self.get_config()
                if self.validate_config(local_config):
                    return local_config
        return self.get_config()

    def validate_config(self, config):
