    public class ConfigurationManager
    {
        private readonly ILogger<ConfigurationManager> _logger;
        private readonly IConfiguration _config;
        private readonly IMongoDatabase _db;
        private readonly ConnectionPool _connectionPool;
        private readonly IModel _rabbitMQChannel;
        private readonly object _cacheLock = new object();
        private readonly ConcurrentDictionary<string, CachedConfiguration> _cache;
        private readonly TimeSpan _cacheTimeToLive;
        private readonly int _throttleLimit;
        private readonly SemaphoreSlim _throttleSemaphore;

        public ConfigurationManager(ILogger<ConfigurationManager> logger, IConfiguration config, IMongoDatabase db, ConnectionPool connectionPool, IModel rabbitMQChannel, TimeSpan cacheTimeToLive, int throttleLimit)
        {
            _logger = logger;
            _config = config;
            _db = db;
            _connectionPool = connectionPool;
            _rabbitMQChannel = rabbitMQChannel;
            _cacheTimeToLive = cacheTimeToLive;
            _throttleLimit = throttleLimit;
            _throttleSemaphore = new SemaphoreSlim(throttleLimit);
            _cache = new ConcurrentDictionary<string, CachedConfiguration>();
        }

        public async Task UpdateUserConfigAsync(string userId, string configName, string configValue)
        {
            if (!_throttleSemaphore.WaitAsync(TimeSpan.Zero).Result)
                throw new Exception("Throttling limit exceeded.");

            var user = await GetUserAsync(userId);
            if (user == null)
                throw new ArgumentException($"User '{userId}' not found.", nameof(userId));

            ValidateConfigValue(configName, configValue);

            using (var connection = _connectionPool.CreateConnection())
            {
                var tenantDb = connection.GetTenantDatabase(user.TenantId);
                using (var transaction = await tenantDb.BeginTransactionAsync())
                {
                    try
                    {
                        var configCollection = tenantDb.GetCollection<Configuration>("Configurations");
                        var encryptedConfigValue = EncryptData(configValue);
                        var config = configCollection.Find(c => c.Name == configName).FirstOrDefault();

                        if (config != null)
                        {
                            config.Value = encryptedConfigValue;
                            await configCollection.ReplaceOneAsync(c => c._id == config._id, config, new UpdateOptions { IsUpsert = true });
                        }
                        else
                        {
                            config = new Configuration { Name = configName, Value = encryptedConfigValue };
                            await configCollection.InsertOneAsync(config);
                        }

                        var logConfigChange = new ConfigChangeLog
                        {
                            UserId = userId,
                            TenantId = user.TenantId,
                            ConfigurationName = configName,
                            OldValue = config != null ? DecryptData(config.Value) : null,
                            NewValue = encryptedConfigValue,
                            Timestamp = DateTimeOffset.UtcNow
                        };

                        await tenantDb.GetCollection<ConfigChangeLog>("ConfigChangeLogs").InsertOneAsync(logConfigChange);

                        CacheUpdate(configName, configValue);

                        // Trigger real-time notifications and cache synchronization here using RabbitMQ.

                        transaction.Commit();
                    }
                    catch
                    {
                        transaction.Rollback();
                        throw;
                    }
                }
            }
        }

        // Methods for GetUserAsync, ValidateConfigValue, EncryptData, DecryptData, CacheUpdate, etc.
    }
}
