class DataAggregator:
    def __init__(self):
        self.streams = defaultdict(Stream)
        self.consolidated_stream = []
        self.executor = ThreadPoolExecutor()

    def add_stream(self, api_name, priority, func):
        stream = self.streams[api_name]
        stream.priority = priority
        getattr(self, f'fetch_{api_name}')(func)

    def fetch_api(self, func):
        while True:
            try:
                data = func()
                if data is not None:
                    self.consolidate(data)
            except Exception as e:
                print(f'API Error for {func.__name__}: {e}')

    def consolidate(self, data):
        if not isinstance(data, int):
            return
        heapq.heappush(self.consolidated_stream, data)
