3. Fault Tolerance Mechanism (FaultToleranceMechanism.py)

```python
import time
from functools import wraps

def retry(max_attempts=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while True:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempts >= max_attempts:
                        raise e
                    print(f'API error, retrying after {5 * (attempts + 1)} seconds...')
                    time.sleep(5 * (attempts + 1))
                    attempts += 1
        return wrapper
    return decorator
```

