public JsonNode extractJsonData(String jsonPath) {
  String cacheKey = calculateCacheKey(jsonPath);
  JsonNode result = cache.getIfPresent(cacheKey);
  if (result == null) {
    result = parseJson(jsonPath, objectMapper);
    cache.put(cacheKey, result); // handle cache evictions as needed
  }
  // Recursively extract nested child nodes
  return findChildNode(result, jsonPath);
}

private JsonNode findChildNode(JsonNode rootNode, String jsonPath) {
  if (jsonPath.contains(".")) {
    String[] parts = jsonPath.split("\\.");
    return rootNode.get(parts[0])
        .findValue(parts.subList(1, parts.length));
  } else {
    return rootNode.get(jsonPath);
  }
}
