        if (preg_match('~[A-Z]~', $characterSet) && preg_match('~[a-z]~', $characterSet) && preg_match('~\d~', $characterSet) && preg_match('~[!@#$%^&*()$~', $characterSet)) {
            return true;
        }
        return false;
    }

