```rust
use tempfile::TempDir;
use std::env;
use std::fs;
use std::path::Path;
use std::sync::{Arc, Mutex};
use env_logger::{Builder as LoggerBuilder, Target};
use tokio::task::spawn;
use chrono::Local;
use reqwest::Client;
use serde_json::{Value, Map};

type DirectoryManager = Arc<Mutex<DirectoryInfo>>;

struct DirectoryInfo {
    dir: TempDir,
    usage_map: Map<String, i64>,
    last_access: chrono::DateTime<chrono::Local>,
}

async fn create_directory(name: &str, retention: usize, manager: &DirectoryManager) -> Result<(), Box<dyn std::error::Error> {
    // Check if the directory already exists
    let dir = TempDir::new(format!("{}/{}", name, Local::now().format("%Y-%m-%d_%H-%M-%S").to_string())).unwrap();

    // If it doesn't exist, create it and add to the manager
    let mut manager = manager.lock().unwrap();
    if !dir.path().exists() {
        fs::create_dir_all(dir.path()).unwrap();
    }

    // Store directory information in the manager
    let usage = 0;
    let last_access = Local::now();
    manager.usage_map.insert(dir.path().to_str().unwrap().to_owned(), usage);
    manager.last_access = last_access;

    // Set environment variable if it doesn't exist or update if it does
    let var_name = format!("DIRECTORY_{}", name.to_uppercase());
    if env::var(&var_name).is_err() {
        env::set_var(var_name, dir.path().to_str().unwrap());
    }

    Ok(())
}

async fn clean_old_directories(manager: &DirectoryManager) -> Result<(), Box<dyn std::error::Error> {
    let mut manager = manager.lock().unwrap();
    let current_time = Local::now();
    for (path, usage) in manager.usage_map.drain() {
        if (current_time - manager.last_access).num_seconds() > retention * 60 {
            fs::remove_dir_all(Path::new(path)).unwrap();
        }
    }
    Ok(())
}

// Add periodic cleanup, REST API endpoint, authentication, rate limiting, metadata store integration, retry mechanism, and distributed coordination as per your requirements.

fn main() {
    let logger = LoggerBuilder().filter_level(log::LevelFilter::Info).init();
    let manager = Arc::new(Mutex::new(DirectoryInfo {
        dir: TempDir::new("my_directory").unwrap(),
        usage_map: Map::new(),
        last_access: Local::now(),
    }));

    // Spawn periodic cleanup task
    spawn(clean_old_directories(&manager));

    // Start listening for REST API requests here
}
