```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using System.IO;
using System.Threading;
using SevenZip;

public class RandomValueGenerator
{
    private float _minValue;
    private float _maxValue;
    private int _seed;
    private readonly List<Random> _randomGenerators = new List<Random>();
    private string _logFilePath;

    public RandomValueGenerator(float minValue, float maxValue, int seed, string logFilePath)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _seed = seed;
        _logFilePath = logFilePath;
        InitializeRandomGenerators();
    }

    private void InitializeRandomGenerators()
    {
        for (int i = 0; i < Environment.ProcessorCount * 2; i++)
        {
            var rng = new Random(Interlocked.Increment(ref _seed));
            rng.Next(); // consume the initial value to make it thread-safe
            _randomGenerators.Add(rng);
        }
    }

    public float GetRandomFloat() => _randomGenerators[Thread.CurrentThread.ManagedThreadId % _randomGenerators.Count].NextSingle(_minValue, _maxValue + 1e-6f) - _minValue;

    public int GetRandomInt() => (int)(GetRandomFloat() * (_maxValue - _minValue + 1)) + (int)_minValue;

    public Vector3 GetRandomVector3(float min, float max) => new Vector3(GetRandomFloat(min, max), GetRandomFloat(min, max), GetRandomFloat(min, max));

    public Quaternion GetRandomQuaternion(float angle, Vector3 axis) => Quaternion.AngleAxis(GetRandomFloat(-angle, angle), axis);

    public override string ToString() => $"Min: {_minValue}, Max: {_maxValue}";

    public void LogRandomValue(string message)
    {
        if (string.IsNullOrEmpty(_logFilePath)) return;

        try
        {
            using (var writer = new StreamWriter(_logFilePath, true))
            {
                writer.WriteLine($"{DateTime.Now}: {message}");
            }

            CompressLogFile();
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
        }
    }

    private void CompressLogFile()
    {
        using (var ms = new MemoryStream())
        using (var archiver = new ArchiveInStream(new DeflateCompressionStrategy(), File.OpenRead(_logFilePath)))
            archiver.CopyTo(ms);

        File.WriteAllBytes(_logFilePath, ms.ToArray());
    }
}
