```c
#include <openssl/aes.h>
#include <openssl/pkcs5.h>
#include <openssl/rand.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    AES_KEY cipher;
    unsigned char *salt;
    size_t salt_len;
} aes_context;

aes_context *aes_init(const char *password, size_t key_len, size_t iv_len, const unsigned char *iv) {
    if (!password || !key_len || !iv_len) {
        return NULL;
    }

    unsigned char salt[PKCS5_SALTBYTES];
    RAND_bytes(salt, PKCS5_SALTBYTES);

    aes_context *ctx = malloc(sizeof(aes_context));
    if (!ctx) {
        return NULL;
    }

    ctx->salt = malloc(PKCS5_SALTBYTES);
    if (!ctx->salt) {
        free(ctx);
        return NULL;
    }
    memcpy(ctx->salt, salt, PKCS5_SALTBYTES);

    unsigned char key[AES_BLOCK_SIZE + PKCS5_SALTBYTES];
    unsigned int key_len = AES_KEYGEN_LEN(key_len);
    PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), salt, PKCS5_SALTBYTES, 0x01 /*iterations*/, key_len, key);

    AES_set_encrypt_key((const unsigned char *)key, key_len * 8, &ctx->cipher.encrypt);
    ctx->cipher.iv = iv;
    ctx->salt_len = PKCS5_SALTBYTES;

    return ctx;
}

void aes_cleanup(aes_context *ctx) {
    if (ctx) {
        free(ctx->salt);
        free(ctx);
    }
}
```
