    private static final String SECRET_KEY = "your-secret-key";
    private static final String ENCRYPTION_KEY = "your-encryption-key";
    private static final String IV = "your-initialization-vector";
    private static final List<String> ALLOWED_ITEMS = Arrays.asList("item1", "item2");

    // Retrofit instance and service interface for payment gateway API
    private Retrofit retrofit;
    private PaymentGatewayService service;

