        retrofit = new Retrofit.Builder()
                .baseUrl(API_URL)
                .addConverterFactory(GsonConverterFactory.create())
                .build();
        service = retrofit.create(PaymentGatewayService.class);
    }

    public void processTransactions(List<Transaction> transactions) {
        for (Transaction transaction : transactions) {
            // Validate payment token using HMAC SHA256 algorithm with the secret key
            String hmac = calculateHmacSha256(transaction.getPaymentToken(), SECRET_KEY);
            if (!hmac.equals(transaction.getHmac())) {
                LOGGER.error("Invalid payment token: {} (HMAC mismatch)", transaction.getPaymentToken());
                continue;
            }

            // Decrypt the payload using AES encryption with the provided key and IV
            byte[] decryptedPayload = decryptAes(transaction.getCipherText(), ENCRYPTED_KEY, IV);

            // Parse and validate the decrypted payload against predefined rules
            JsonObject jsonPayload = new Gson().fromJson(new String(decryptedPayload, StandardCharsets.UTF_8), JsonObject.class);
            if (!validatePayload(jsonPayload)) {
                LOGGER.error("Invalid transaction payload: {}", jsonPayload);
                continue;
            }

            // Process the validated transaction asynchronously with retry logic and parallel processing
            CompletableFuture.runAsync(() -> processTransactionAsync(jsonPayload), executorService)
                    .exceptionally(ex -> {
                        if (ex instanceof RetrofitException) {
                            handleRetrofitException((RetrofitException) ex);
                        } else {
                            LOGGER.error("Failed to process transaction: {}", ex.getMessage());
                        }
                        return null;
                    });
        }
    }

    // Implement the remaining methods for HMAC SHA256 calculation, AES decryption, payload validation, Retrofit exception handling, and more...
}
