```javascript
/**
 * @typedef {import('fs').ReadStream} ReadStream
 * @typedef {import('stream').Transform} Transform
 * @typedef {import('child_process').ChildProcess} ChildProcess
 */

const stream = require('stream');
const fs = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');

/**
 * Configurable options for reading directory files.
 */
class ReadDirectoryFilesOptions {
  /**
   * Directory to read from.
   * @type {string}
   */
  directory;

  /**
   * File extensions to include in the result.
   * @type {string[]}
   */
  extensions = [];

  /**
   * Maximum buffer size for reading file contents.
   * @type {number}
   */
  bufferSize = 1024;

  /**
   * Maximum number of concurrent file reads.
   * @type {number}
   */
  maxConcurrentReads = 5;

  /**
   * Number of retries for failed file reads before giving up.
   * @type {number}
   */
  retryLimit = 3;

  /**
   * Logging function to log messages during processing.
   * @type {function(string): void}
   */
  log;

  constructor({ directory, extensions, bufferSize, maxConcurrentReads, retryLimit, log }) {
    this.directory = directory;
    this.extensions = extensions || [];
    this.bufferSize = bufferSize || 1024;
    this.maxConcurrentReads = maxConcurrentReads || 5;
    this.retryLimit = retryLimit || 3;
    this.log = log || (() => {});
  }
}

/**
 * Function to read files asynchronously within a specified directory, filter them based on an extension, and return their combined content.
 * @param {ReadDirectoryFilesOptions} options - Configuration object for the file reading process.
 */
async function readDirectoryFiles(options) {
  const { directory, extensions, bufferSize, maxConcurrentReads, retryLimit, log } = options;
  let processedFilesCount = 0;
  let currentReadingTasks = new Set();
  let currentFailedTasks = new Set();

  // Create a stream to concatenate file contents.
  const concatStream = new stream.Transform({
    transform(chunk, encoding, callback) {
      this.push(chunk);
      callback();
    },
    final(callback) {
      callback(null, this.toString());
    }
  });

  async function readFile(filePath) {
    if (currentReadingTasks.has(filePath)) return;

    let currentRead = new Promise((resolve, reject) => {
      const readStream = fs.createReadStream(filePath, { encoding: 'utf8', highWaterMark: bufferSize });
      let retriesLeft = retryLimit;

      function handleReadError() {
        if (!retriesLeft--) return reject(new Error(`Failed to read file "${filePath}" after ${retryLimit} attempts.`));
        log(`Retrying to read failed file "${filePath}"...`);
        currentRead = readFile(filePath);
      }

      readStream.on('error', handleReadError);
      readStream.on('end', () => {
        if (currentReadingTasks.delete(filePath)) {
          log(`Finished reading file "${filePath}" (${readStream._writableState.highWaterMark} bytes).`);
        }
        readStream.removeListener('error', handleReadError);
      });

      currentReadingTasks.add(filePath);

      concatStream.on('finish', () => {
        if (currentReadingTasks.size === 0 && currentFailedTasks.size === 0) {
          log(`Completed processing all files.`);
        }
      });

      readStream.pipe(concatStream, { end: false });
    });

    try {
      await currentRead;
    } catch (error) {
      if (!currentFailedTasks.has(filePath)) {
        currentFailedTasks.add(filePath);
        log(`Error reading file "${filePath}": ${error.message}.`);
      }
    }
  }

  function processDirectory() {
    const files = fs.readdirSync(directory, { withFileTypes: true });

    for (const file of files) {
      if (!file.isDirectory()) continue;

      const filePath = path.join(directory, file.name);
      if (!fs.existsSync(filePath)) continue;

      processDirectory(filePath);

      for (const ext of extensions) {
        if (path.extname(filePath) === `.${ext}`) {
          processedFilesCount++;

          if (currentReadingTasks.size < maxConcurrentReads) {
            readFile(filePath);
          } else {
            log(`Queueing file "${filePath}" for processing...`);
          }
        }
      }
    }
  }

  processDirectory();

  // Handle cross-origin file reading in browser environment.
  if (typeof self !== 'undefined' && self.cors) {
    const cors = new self.cors.CORS(directory);
    cors.onerror = function (err, request, response) {
      log(`Error with CORS configuration: ${err.message}`);
    };
  }

  return new Promise((resolve, reject) => {
    concatStream.once('error', reject);
    concatStream.once('finish', resolve);
  });
}
```

This JavaScript function `readDirectoryFiles` asynchronously reads all files within a specified directory, filters out files based on a given extension (e.g., `.txt`), concatenates their contents into a single string, and returns this string. It supports reading large directories efficiently by implementing a configurable buffer size for reading file contents and managing file reading in parallel while not exceeding a specified maximum limit to avoid overwhelming the file system. The function handles errors gracefully, logs file names and their content lengths during processing, and retries failed file reads up to a configurable number of times before giving up. It also manages cross-origin file reading where necessary through CORS configuration.

