class RenderScriptsFooter {
  constructor() {
    this.scripts = [];
  }

  // Validate input array and handle errors gracefully
  validateArray(arr) {
    if (!Array.isArray(arr)) throw new Error("Invalid input: scripts must be an Array");

    for (const script of arr) {
      if (typeof script !== "object" || !('src' in script && 'code' in script)) {
        throw new Error("Invalid script object format");
      }
    }
  }

  // Remove all previously rendered scripts
  clearScripts() {
    this.scripts = [];
  }

  // Load scripts asynchronously and add them to the scripts array
  async loadScripts(scripts) {
    await Promise.all(scripts.map(async (script) => {
      const scriptElement = document.createElement('script');

      if ('src' in script) {
        scriptElement.src = script.src;
        scriptElement.onload = () => this.scripts.push(scriptElement);
      } else {
        scriptElement.innerHTML = script.code;
        this.scripts.push(scriptElement);
      }

      return new Promise((resolve) => document.head.appendChild(scriptElement).onload = resolve);
    }));
  }

  // Render the footer with the current scripts array
  render() {
    return this.scripts.map((script, index) => `<script key="${index}">${script.innerHTML}</script>`).join('');
  }

  // Renders and returns the footer HTML string based on the current scripts array and optionally clears previously rendered scripts.
  async renderScriptsFooter(scripts, clear = true) {
    this.validateArray(scripts);

    if (clear) this.clearScripts();

    await this.loadScripts(scripts);

    return this.render();
  }
}
```

