const axios = require('axios');
const _ = require('lodash');

// Constants and helper functions
const POKEAPI_URL = 'https://pokeapi.co/api/v2/pokemon';
const MAX_PARALLEL_REQUESTS = 10; // Adjust this based on your system resources
const TIMEOUT = 5000; // API request timeout in milliseconds

async function getPokemonDetails(pokemonId) {
  try {
    const response = await axios.get(`${POKEAPI_URL}/${pokemonId}`);
    if (!response.data || !response.data.types) {
      throw new Error('Invalid Pokemon data');
    }
    return response.data;
  } catch (error) {
    console.error(`Error fetching Pokemon details: ${error.message}`);
    return null;
  }
}

function getWeaknesses(pokemon) {
  const { type } = pokemon;
  switch (type.name.toLowerCase()) {
    case 'normal':
      return ['Fighting'];
    case 'fire':
      return ['Water', 'Ground'];
    // Add more cases for other types here...
    default:
      return [];
  }
}

async function asyncReduce(array, callback, initialValue) {
  let accumulator = initialValue;
  const chunkSize = Math.min(array.length, MAX_PARALLEL_REQUESTS);
  for (let i = 0; i < array.length; i += chunkSize) {
    const chunk = array.slice(i, i + chunkSize);
    // Concurrently process each chunk using Promise.all and await the result
    const promises = chunk.map(pokemon => callback(getPokemonDetails(pokemon.id), pokemon));
    const results = await Promise.all(promises);
    accumulator = results.reduce((acc, result) => {
      if (result) {
        acc.push(...result);
      }
      return acc;
    }, []);
  }
  return accumulator;
}

async function getPokemonWeaknesses(pokemons) {
  try {
    return await asyncReduce(pokemons, (details, pokemon) => {
      if (!details) {
        return []; // Skip processing if no details were fetched
      }
      const weaknesses = getWeaknesses(details);
      // Consider level when determining additional weaknesses (edge case)
      // ...
      return [...weaknesses];
    }, []);
  } catch (error) {
    console.error(`Error getting Pokemon weaknesses: ${error.message}`);
    return [];
  }
}
```

