import asyncio
import aiohttp
import json
from collections import namedtuple, OrderedDict
from functools import lru_cache
from typing import Dict, Any, Callable, Tuple
import logging

class CacheEntry:
    def __init__(self, data: dict, timestamp: float, expires_in: int):
        self.data = data
        self.timestamp = timestamp
        self.expires_in = expires_in

CacheItem = namedtuple('CacheItem', 'location, cache')

async def _fetch_weather(session: aiohttp.ClientSession, location: str) -> CacheEntry:
    try:
        async with session.get(f'https://api.openweathermap.org/data/2.5/weather', params={'q': location, 'appid': '<your_api_key>'}) as response:
            if response.status != 200:
                raise Exception(f'Error fetching weather data for {location}: {response.status}')

            response_json = await response.json()
            cache_entry = CacheEntry(data=response_json, timestamp=time.time(), expires_in=(response_json['dt'] + 60 * 60) - time.time())
            return cache_entry
    except Exception as e:
        logging.error(f'Error fetching weather data for {location}: {str(e)}')
        raise e

@lru_cache(maxsize=128, typed=True)
def get_cache_item(location: str) -> CacheItem:
    cache = OrderedDict()
    for item in _CACHE.items():
        if time.time() > item[1].timestamp + item[1].expires_in or len(_CACHE) >= 128:
            del _CACHE[item[0]]
        else:
            cache[item[0]] = item[1]
    return CacheItem(location=location, cache=cache) if location in cache else CacheItem(location=location, cache={})

def fetch_weather_data(location: str, callback: Callable[[Dict[str, Any]], Tuple[bool, Dict[str, Any]]]):
    def wrapper(location: str):
        cache_item = get_cache_item(location)
        if location in cache_item.cache:
            return True, cache_item.cache[location]

        async def fetch_and_update():
            async with aiohttp.get('https://aiohttp.readthedocs.io/en/stable/', timeout=10) as response:
                if response.status == 200:
                    data = await response.json()
                    cache_entry = CacheEntry(data=data, timestamp=time.time(), expires_in=60 * 60)
                    _CACHE[location] = cache_entry
                    return True, data
                else:
                    logging.error(f'Error fetching weather data for {location}: {response.status}')
            return False, {}

        loop = asyncio.get_event_loop()
        result = loop.run_until_complete(asyncio.wait_for(fetch_and_update(), timeout=10))
        if result[0]:
            callback(result[1])
        else:
            callback({'error': 'Network error'})

    return wrapper(location)
