```python
import requests
import json
from datetime import datetime, timedelta
from jinja2 import Template
from cachetools import TTLCache
import smtplib
import ssl
import hashlib
from sqlalchemy import create_engine, event
from sqlalchemy.orm import sessionmaker
from zope.interface import implementer

# Payment gateway API settings
PAYMENT_GATEWAY_API_URL = "https://api.example-payment-gateway.com"
OAUTH_TOKEN_URL = f"{PAYMENT_GATEWAY_API_URL}/oauth/token"
TRANSACTION_URL = f"{PAYMENT_GATEWAY_API_URL}/transactions"

# Database settings
DATABASE_URI = "sqlite:///db.sqlite3"

# Rate limiting settings
RATE_LIMIT_PERIOD = timedelta(minutes=15)
RATE_LIMIT_MAX_CALLS = 100

# Cache settings
CACHE = TTLCache(maxsize=1000, ttl=timedelta(minutes=5))

# OAuth 2.0 credentials (Store these securely!)
CLIENT_ID = "your-client-id"
CLIENT_SECRET = "your-client-secret"
REFRESH_TOKEN = "your-refresh-token"

class PaymentGatewayAPI(object):
    def __init__(self):
        self.access_token = None
        self.refresh_token = REFRESH_TOKEN

    @property
    def auth(self):
        if not self.access_token or datetime.now() > self.access_token_expires:
            response = requests.post(OAUTH_TOKEN_URL, data={"grant_type": "refresh_token", "refresh_token": self.refresh_token}, auth=(CLIENT_ID, CLIENT_SECRET))
            access_token = response.json()["access_token"]
            self.access_token = access_token
            self.access_token_expires = datetime.now() + timedelta(minutes=access_token_expires)
        return (CLIENT_ID, self.access_token)

    def make_transaction(self, customer_id, amount, currency, payment_method, metadata):
        # Use cache if available
        key = f"payment:gateway:{customer_id}:{amount}:{currency}:{payment_method}"
        if key in CACHE and not datetime.now() > CACHE[key]["expires"]:
            response = CACHE[key]["response"]
        else:
            headers = {"Authorization": "Basic {0}".format(hashlib.sha256((CLIENT_ID + ":" + self.access_token).encode()).hexdigest())}
            response = requests.post(TRANSACTION_URL, headers=headers, data={"customer_id": customer_id, "amount": amount, "currency": currency, "payment_method": payment_method, "metadata": metadata})
            if response.status_code == 201:
                CACHE[key] = {"response": response.json(), "expires": datetime.now() + timedelta(minutes=response.json()["expires_in"])}
            else:
                CACHE[key] = {"response": response.json()}

        return response.json()

@implementer(DBSession)
class DBSession(object):
    def __init__(self, expire_on_commit=True):
        self._engine = create_engine(DATABASE_URI)
        self._SessionClass = sessionmaker(bind=self._engine)
        self.session = None
        if expire_on_commit:
            event.listen(self._SessionClass(), "after_transaction_commit", self.expire_session)

    def __enter__(self):
        self.session = self._SessionClass()
        return self.session

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.session is not None:
            self.session.close()

    @staticmethod
    def expire_session(mapper, connection, session):
        session.expunge_all()

def process_transaction(customer_id, amount, currency, payment_method, metadata, **kwargs):
    with DBSession() as session:
        transaction = session.query(Transaction).filter_by(customer_id=customer_id).first()
        if transaction is None:
            transaction = Transaction(customer_id=customer_id)
            session.add(transaction)

        payment_gateway = PaymentGatewayAPI()
        response = payment_gateway.make_transaction(customer_id, amount, currency, payment_method, metadata)

        if "error" in response:
            raise Exception(response["error"])

        transaction.amount = response["amount"]
        transaction.currency = response["currency"]
        transaction.payment_method = response["payment_method"]
        transaction.metadata = json.dumps(response["metadata"])
        transaction.status = "pending"

        try:
            session.commit()
            send_email(transaction)
            return {"success": True}
        except Exception as e:
            transaction.status = "error"
            session.commit()
            raise e

def send_email(transaction):
    message = Template("Subject: Your Transaction Receipt\n\nYour transaction #{{ transaction_id }} was processed for {{ amount }} {{ currency }}.\nTransaction Details:\n{{ metadata }}").render({"transaction_id": transaction.id, "amount": transaction.amount, "currency": transaction.currency, "metadata": transaction.metadata})
    mailserver = smtplib.SMTP("smtp.example.com", 587)
    mailserver.starttls()
    mailserver.login("your-email@example.com", "your-password")
    msg = f"Subject: {message}\n\n{message}"
    mailserver.sendmail("your-email@example.com", transaction.customer.email, msg)
