const MAX_CONCURRENT_REQUESTS = 3;
let scriptQueue = [];
let themeCache = {};
let themeBitmap;
let currentTheme;
let imageProcessingService;
let db; // Assuming a local database is already initialized
let logger; // Assuming a logging function is already defined

function renderScriptsFooter(scriptArray) {
  const footerHTML = `<footer id="scripts-footer"></footer>`;
  document.body.innerHTML += footerHTML;
  const scriptsFooter = document.getElementById("scripts-footer");

  scriptArray.forEach((script, index) => {
    const uniqueKey = `script_${index}`;
    const scriptTag = document.createElement('script');
    scriptTag.setAttribute('key', uniqueKey);
    scriptTag.innerHTML = script.code;
    scriptsFooter.appendChild(scriptTag);

    if (script.url) {
      scriptQueue.push({ url: script.url, onloadCallback: () => scriptsFooter.appendChild(scriptTag) });
    }
  });
}

function loadScripts() {
  if (!scriptQueue.length) return;

  const numQueued = scriptQueue.length;
  let activeRequests = 0;

  (function loadNextScript() {
    if (!scriptQueue.length || activeRequests >= MAX_CONCURRENT_REQUESTS) return;

    const { url, onloadCallback } = scriptQueue.shift();
    activeRequests++;

    const scriptTag = document.createElement('script');
    scriptTag.onload = () => {
      activeRequests--;
      onloadCallback(scriptTag);
      loadNextScript();
    };

    scriptTag.src = url;
    document.head.appendChild(scriptTag);
  })();
}

