```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct ResourceBundle {
    size_t size;
    json_object *items;
} ResourceBundle;

ResourceBundle *loadResourceBundle(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    json_object *obj = json_tokener_parse_ex((char *)file, strlen(path), 0, NULL);
    fclose(file);

    if (json_object_get_type(obj) != JSON_OBJECT) {
        fprintf(stderr, "Invalid resource file format\n");
        json_object_put(obj);
        return NULL;
    }

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        perror("Memory allocation failure");
        json_object_put(obj);
        return NULL;
    }

    bundle->items = obj;
    bundle->size = json_object_get_array_length(obj);

    return bundle;
}

int getResourceValue(ResourceBundle *bundle, const char *key, int *value) {
    json_object *item = json_object_object_get(bundle->items, key);
    if (!item) {
        fprintf(stderr, "Key '%s' not found in resource bundle\n", key);
        return -1;
    }

    if (json_object_is_type(item, json_type_int)) {
        *value = json_object_get_int(item);
    } else if (json_object_is_type(item, json_type_double)) {
        *value = (int)json_object_get_double(item);
    } else if (json_object_is_type(item, json_type_string)) {
        const char *str_val = json_object_get_string(item);
        sscanf(str_val, "%d", value);
        if (*value == 0 && strcmp(str_val, "0") != 0) {
            fprintf(stderr, "Invalid integer value for key '%s'\n", key);
            return -1;
        }
    } else {
        fprintf(stderr, "Unsupported data type for key '%s' in resource bundle\n", key);
        return -1;
    }

    return 0;
}

// Implement cache mechanism, error handling, configuration system integration, and other required functions

void freeResourceBundle(ResourceBundle *bundle) {
    json_object_put(bundle->items);
    free(bundle);
}
```

