use std::fs::File;
use std::io::{BufReader, Write};
use std::path::PathBuf;
use std::error::Error;
use std::env;

fn create_config_dir_and_set_env_var(config_dir: &str) -> Result<(), Box<dyn Error>> {
    let config_path = env::current_exe()?.parent().unwrap().join(config_dir);

    if !config_path.exists() {
        fs::create_dir_all(&config_path)?;

        let mut out = Vec::new();
        writeln!(out, "export XDG_CONFIG_DIR={}", config_path.to_str().unwrap())?;
        env::set_var("XDG_CONFIG_DIR", &config_path.to_str().unwrap())?;

        let _ = File::create(format!("{}/environment_vars.sh", config_path.to_str().unwrap()))
            .and_then(|file| write!(file, "{}", out))?;
    } else if env::var("XDG_CONFIG_DIR").is_err() {
        env::set_var("XDG_CONFIG_DIR", &config_path.to_str().unwrap())?;
    }

    Ok(())
}
