    size_t formatted_size = strlen(format) + 1 + strftime(nullptr, 0, "%Y-%m-%d", &result->tm);
    result->formatted_string = (char *)malloc(formatted_size);
    if (!result->formatted_string) {
        log(LOG_ERROR, "Memory allocation error");
        free(result);
        return nullptr;
    }
    snprintf(result->formatted_string, formatted_size, format, &result->tm);

    return result;
