struct Line {
    char* data;
    size_t len;
};

// Function to read a line from the file and return it as a dynamically allocated string.
struct Line *readLine(FILE *file) {
    size_t cap = 0, len = 0;
    char *line = NULL;
    ssize_t bytesRead;

    while ((bytesRead = getdelim(&line, &cap, '\n', file)) != EOF && bytesRead > 0) {
        len += bytesRead;
        cap *= 2; // Double the capacity if necessary.
    }

    if (bytesRead == -1) {
        free(line);
        return NULL;
    }

    line = realloc(line, len + 1);
    line[len] = '\0';
    return (struct Line*) { .data = line, .len = len };
}

// Function to split a line into fields and return an array of pointers to the numeric ones.
