}

void* processLineThread(void *arg) {
    struct Line *line = arg;
    char **fields;

    if (!(fields = extractNumericFields(line->data))) {
        free(line->data);
        free(line);
        return NULL;
    }

    processLine(fields, line->len / sizeof(char*) + 1);

    for (size_t i = 0; i < line->len / sizeof(char*); ++i) {
        free(fields[i]);
    }
    free(fields);
    free(line->data);
    free(line);

    return NULL;
}

int main(int argc, char *argv[]) {
