class LazyRegistry(Registry):
    _registry = {}

    @staticmethod
    def _register_factory(cls: Type[JsonBase], data: Dict[str, Any]) -> None:
        if not hasattr(cls, '__registration__'):
            cls.__registration__ = True
            LazyRegistry._registry[cls.__name__] = cls

    @classmethod
    def get_factory(cls, name: str) -> JsonBase:
        if cls.__name__ in LazyRegistry._registry:
            return LazyRegistry._registry[cls.__name__]
        try:
            module_name, _, _ = name.rpartition('.')
            module = __import__(module_name, fromlist=[f'{name}.{module_name}' for f in ['*', '_']])
            return getattr(module, name)
        except ImportError as e:
            raise ImportError(f"Unable to import subclass {name}: {e}")
        except AttributeError as e:
            raise AttributeError(f"Subclass {name} not found in the provided module.")

