import json
import yaml
import boto3
import os
import time
from concurrent.futures import ThreadPoolExecutor
from functools import lru_cache
from cryptography.fernet import Fernet

class ConfigManager:
    def __init__(self, config_file='config.json', ssm_prefix='my-app/config'):
        self.config_file = config_file
        self.ssm_prefix = ssm_prefix
        self.cache = {}
        self.ssm_client = boto3.client('ssm')
        self.encryption_key = Fernet(os.environ['ENCRYPTION_KEY'])
        self.rules = self._load_validation_rules()
        self.last_checked_time = 0

    def _load_validation_rules(self):
        with open('validation_rules.yaml') as f:
            return yaml.safe_load(f)

    @lru_cache(maxsize=128)
    def _get_ssm_parameter(self, name):
        try:
            response = self.ssm_client.get_parameters_by_name(Name=[name], WithDecryption=True)[0]
            if 'Value' in response and response['Value']:
                return response['Value']
            else:
                raise KeyError(f"SSM parameter '{name}' not found or empty value.")
        except Exception as e:
            print(f"Error while fetching SSM parameter {name}: {e}")
            return None

    def _validate_config(self, config):
        for rule in self.rules:
            if not self._validate_rule(config[rule['key']], rule):
                raise ValueError("Configuration does not meet validation rules.")

    def _validate_rule(self, value, rule):
        if 'type' in rule and value != type(rule['type']):
            return False
        if 'range' in rule:
            min_val = rule['range']['min']
            max_val = rule['range']['max']
            if not (isinstance(value, (int, float)) and min_val <= value <= max_val):
                return False
        if 'depends_on' in rule:
            for dep_key in rule['depends_on']:
                if dep_key not in config or config[dep_key] != rule['depends_on'][dep_key]:
                    return False
        return True

    def _load_config(self):
        local_config = {}
        try:
            with open(self.config_file) as f:
                local_config = json.load(f)
        except Exception as e:
            print(f"Error while loading local configuration file: {e}")
            return None

        ssm_config = {}
        for name, encrypted in self._get_ssm_parameters(self.ssm_prefix).items():
            try:
                decrypted = self.encryption_key.decrypt(encrypted.encode()).decode()
                ssm_config[name] = json.loads(decrypted)
            except Exception as e:
                print(f"Error while decrypting SSM configuration parameter {name}: {e}")
                continue

        merged_config = {**local_config, **ssm_config}
        self._validate_config(merged_config)
        return merged_config

    def _get_ssm_parameters(self, prefix):
        params = {}
        for name in self.ssm_client.list_parameters_by_path(Path=prefix)[0]['Parameters']:
            param = self._get_ssm_parameter(prefix + '/' + name['Name'])
            if param:
                params[name['Name']] = param
        return params

    def get_config(self, version='latest', cache_ttl=60):
        current_time = int(time.time())
        if (current_time - self.last_checked_time) > cache_ttl:
            self.cache.clear()
            self.cache = {key: val for key, val in self._load_config().items()}
            self.last_checked_time = current_time
        return self.cache

    def update_config(self, new_config):
        if isinstance(new_config, dict) and set(new_config.keys()) <= set(self.rules):
            for key, value in new_config.items():
                if key not in self.cache:
                    self.cache[key] = value
                else:
                    self.cache[key] = value
        else:
            raise TypeError("Invalid configuration update format.")

    # Additional methods for dynamic updates, secure configuration management, etc.
