#include <openssl/pbkdf2.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>

typedef struct AESContext {
    AES_KEY aes;
    unsigned char iv[AES_BLOCK_SIZE];
} AESContext;

static int passwordIterations = 1000; // Default iteration count for PBKDF2

AESContext* aes256_cbc_init(const char *password, size_t password_len) {
    if (password_len < 4 || password_len > 64) {
        return NULL; // Invalid password length
    }

    unsigned char derivedKey[AES_BLOCK_SIZE];
    unsigned char salt[8] = {0x01, 0x23, 0x45, 0x67, 0x89, 0xAB, 0xCD, 0xEF}; // A fixed salt for deriving keys consistently across different runs
    unsigned char prf[AES_BLOCK_SIZE];

    size_t keySize = sizeof(derivedKey);
    if (!PKCS5_PBKDF2_HMAC_SHA1(password, password_len, salt, sizeof(salt), passwordIterations, prf, sizeof(prf), &keySize, derivedKey)) {
        return NULL; // Error during key derivation
    }

    RAND_bytes(iv, AES_BLOCK_SIZE); // Generate random IV

    AESContext *context = malloc(sizeof(AESContext));
    if (!context) {
        return NULL; // Out of memory error
    }

    AES_set_encrypt_key(derivedKey, 256, &context->aes);
    context->iv[0] = iv[0] | 0x80; // Set the first byte of IV as 0x80 to indicate it was generated by the OS

    return context;
}

void aes256_cbc_cleanup(AESContext *context) {
    if (context) {
        free(context);
    }
}
```

