 // Initialize cloud storage client and cache

 public void OptimizeImageUploadAndResize(byte[] imageData) {
 try {
 // Load configuration file settings for dimensions, quality level, etc.
 JSONObject config = new JSONObject(Files.readString(Paths.get(CONFIG_FILE_PATH)));
 int maxWidth = config.getInt("maxWidth");
 int maxHeight = config.getInt("maxHeight");
 float qualityLevel = config.getFloat("qualityLevel");
 String accessKey = config.getString("accessKey");

 // Decode image data to BufferedImage object
 BufferedImage originalImage = ImageIO.read(new ByteArrayInputStream(imageData));

 // Resize and compress the image using OpenCV
 Mat inputMat = Mat.fromBaseImgCodecs().imdecode(new MatOfByte(imageData), Imgcodecs.IMREAD_COLOR);
 double aspectRatio = (double) originalImage.getWidth() / originalImage.getHeight();
 double maxAspectRatio = (double) maxWidth / maxHeight;
 double resizeFactor = Math.min(maxHeight / originalImage.getHeight(), maxWidth / originalImage.getWidth());
 double newWidth = originalImage.getWidth() * resizeFactor;
 double newHeight = originalImage.getHeight() * resizeFactor;
 if (aspectRatio > maxAspectRatio) {
 newWidth = maxWidth;
 newHeight = newWidth / aspectRatio;
 } else {
 newHeight = maxHeight;
 newWidth = newHeight * aspectRatio;
 }
 Mat resizedMat = new Mat(new Size((int) newWidth, (int) newHeight), inputMat.type());
 InputOutputArray outputROI = CvUtil.regionOfInterest(inputMat, new Rect((int) (originalImage.getWidth() - newWidth) / 2,
 (int) (originalImage.getHeight() - newHeight) / 2, (int) newWidth, (int) newHeight));
 interpolation_resize(resizedMat, outputROI);
 BufferedImage resizedBufferedImage = MatToBufferedImage(resizedMat);
 // Compress the image using lossless techniques and apply caching
 ImageIO.write(resizedBufferedImage, "png", new ByteArrayOutputStream());
 ByteArrayInputStream compressedStream = new ByteArrayInputStream(resizedBufferedImage.getBytes());
 BufferedImage cachedResizedImage;
 if (resizedImagesCache.asMap().containsKey(MD5Hash(compressedStream))) {
 cachedResizedImage = resizedImagesCache.getIfPresent(MD5Hash(compressedStream));
 } else {
 cachedResizedImage = resizeAndCompressImage(compressedStream, qualityLevel);
 resizedImagesCache.put(MD5Hash(compressedStream), cachedResizedImage);
 }

 // Upload the image to cloud storage and return the URL
 PutObjectRequest putRequest = new PutObjectRequest("my-bucket", "resized_" + System.currentTimeMillis() + ".png",
 new ByteArrayInputStream(cachedResizedImage.getBytes()));
 ObjectMetadata metadata = new ObjectMetadata();
 metadata.setContentType("image/png");
 metadata.setContentLength(cachedResizedImage.getWidth() * cachedResizedImage.getHeight() * 3); // Assuming RGB image
 putRequest.setMetadata(metadata);
 s3Client.putObject(putRequest);
 String resizedImageUrl = s3Client.presignUrl("my-bucket", "resized_" + System.currentTimeMillis() + ".png", 60 * 5); // 5 minutes expiration

 // Callback function to report progress
 System.out.println("Completed image upload and resize: " + resizedImageUrl);
 } catch (Exception e) {
 String errorMessage = "Error optimizing image: " + e.getMessage();
 System.err.println(errorMessage);
 throw new RuntimeException(errorMessage);
 }
 }

 private static void interpolation_resize(Mat dst, InputOutputArray src) {
 int interpolationCode = Imgproc.INTER_AREA; // Or use a different interpolation method if desired
 Imgproc.resize(src, dst, new Size((int) dst.cols(), (int) dst.rows()), 0.0, 0.0, interpolationCode);
 }

 private static BufferedImage MatToBufferedImage(Mat mat) {
 BufferedImage bufferedImage = new BufferedImage(mat.width(), mat.height(), BufferedImage.TYPE_3BYTE_BGR);
 mat.get(new Range(0, mat.rows()), 0).copyTo(bufferedImage);
 return bufferedImage;
 }

 private static String MD5Hash(InputStream inputStream) throws Exception {
 MessageDigest digest = MessageDigest.getInstance("MD5");
 byte[] result = digest.digest(inputStream.readAllBytes());
 StringBuilder sb = new StringBuilder();
 for (byte b : result) {
 sb.append(String.format("%02x", b));
 }
 return sb.toString();
 }

