import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import okhttp3.*;
import java.io.IOException;
import java.util.ConcurrentHashMap;
import java.util.Map;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class JsonParser {
    private final ObjectMapper objectMapper = new ObjectMapper();
    private final OkHttpClient httpClient = new OkHttpClient();
    private final SchemaValidator schemaValidator;
    private final Cache cache;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    public JsonParser(SchemaValidator schemaValidator, Cache cache) {
        this.schemaValidator = schemaValidator;
        this.cache = cache;
    }

    public JsonNode getJsonPath(String json, String path) throws IOException {
        lock.readLock().lock();
        try {
            // Check if the result is already in the cache
            JsonNode cachedResult = cache.get(json + "_" + path);
            if (cachedResult != null) {
                return cachedResult;
            }

            // Validate JSON document against schema
            validateJsonDocument(json);

            // Parse and extract data from the JSON document
            JsonNode node = objectMapper.readTree(json).at(path);

            if (node == null) {
                throw new JsonPathNotFoundException("No data found at path: " + path);
            } else if (!node.isNull() && node.size() > 1) {
                throw new MultipleJsonPathMatchesException("Multiple matching nodes found at path: " + path);
            }

            // Cache the result for future use
