from flask import Flask, request, jsonify
from kubernetes import client, config
import time
from queue import Queue
import threading
import requests

app = Flask(__name__)
deployment_queue = Queue()
rate_limiter = {}
connection_pool = {}

def init_k8s():
    config.load_kube_config()
    vs = client.CoreV1Api()
    return vs

@app.route('/deploy', methods=['POST'])
def deploy():
    if request.json['namespace'] in rate_limiter:
        delay = int((time.time() - rate_limiter[request.json['namespace']]) / 60)
        if delay < 60:
            return jsonify({"error": f"Rate limited for {delay} minutes"}), 429
    rate_limiter[request.json['namespace']] = time.time()

    container_name = request.json['container_name']
    namespace = request.json['namespace']
    if check_existing_deployment(container_name, namespace):
        return jsonify({"message": f"Container '{container_name}' already exists in namespace '{namespace}'"}), 200

    try:
        k8s = init_k8s()
        deployment = create_deployment(k8s, container_name, namespace)
        deployment_queue.put((deployment, namespace))
        return jsonify({"message": f"Container '{container_name}' deployment request submitted for namespace '{namespace}'"}), 202
    except Exception as e:
        print(e)
        return jsonify({"error": str(e)}), 500

def check_existing_deployment(container_name, namespace):
    # Implement this function to check if a deployment for the given container and namespace already exists
    pass

def create_deployment(k8s, container_name, namespace):
    # Implement this function to create a deployment object using kubernetes python client library
    pass

def process_queue():
    while not deployment_queue.empty():
        (deployment, namespace), = deployment_queue.get()
        try:
            if check_existing_deployment(container_name, namespace):
                continue

            k8s = connection_pool.get(namespace)
            if not k8s:
                k8s = init_k8s()
                connection_pool[namespace] = k8s

            creation = k8s.create_namespaced_deployment(body=deployment, namespace=namespace)
            print(f"Deployment '{creation.metadata.name}' created in namespace '{namespace}'")
        except Exception as e:
            print(e)

threading.Thread(target=process_queue).start()

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')
```

