public abstract class WeatherDataProvider {
    private String apiKey;
    private Cache<String, WeatherData> cache;

    public WeatherDataProvider(String apiKey) {
        this.apiKey = apiKey;
        this.cache = new Cache<>();
    }

    // Abstract methods for making requests and handling responses
    protected abstract Future<WeatherData> fetchWeatherData(String location);

    public WeatherData getWeatherData(String location) throws ExecutionException, InterruptedException {
        String cacheKey = createCacheKey(location);
        WeatherData weatherData = cache.get(cacheKey);
        if (weatherData != null) return weatherData;

        Future<WeatherData> future = fetchWeatherData(location);
        weatherData = future.get();
        cache.put(cacheKey, weatherData);
        return weatherData;
    }

    private String createCacheKey(String location) {
        // Create a unique key using the location and some random value
        // To ensure data consistency across different providers
        // Replace this with a proper hash function or similar
        return "weather_data_" + location + System.nanoTime();
    }
}
