import okhttp3.*;

public class OpenWeatherMapProvider extends WeatherDataProvider {
    private OkHttpClient client;

    public OpenWeatherMapProvider(String apiKey) {
        super(apiKey);
        this.client = new OkHttpClient();
    }

    @Override
    protected Future<WeatherData> fetchWeatherData(String location) {
        Request request = new Request.Builder()
                .url("http://api.openweathermap.org/data/2.5/weather?q=" + location + "&appid=" + apiKey)
                .build();

        return Futures.future(() -> {
            try (Response response = client.newCall(request).execute()) {
                if (!response.isSuccessful()) throw new RuntimeException("Failed : " + response.code());
                WeatherData weatherData = JsonUtils.parseWeatherData(response.body().string());
                return weatherData;
            } catch (IOException e) {
                System.err.println("Error getting response from OpenWeatherMap API");
                throw new RuntimeException(e);
            }
        });
    }
}
