<?php

class UpdateService {
    private $oauthClient;
    private $db;
    private $apiClient;
    private $cache;
    private $geolocationApi;
    private $notificationService;
    private $rateLimiter;

    public function __construct(OAuth2Client $oauthClient, Database $db, APIClient $apiClient, Cache $cache, GeolocationAPI $geolocationApi, NotificationService $notificationService, RateLimiter $rateLimiter) {
        $this->oauthClient = $oauthClient;
        $this->db = $db;
        $this->apiClient = $apiClient;
        $this->cache = $cache;
        $this->geolocationApi = $apiLocationApi;
        $this->notificationService = $notificationService;
        $this->rateLimiter = $rateLimiter;
    }

    public function updateClinicStatuses(array $userData, array $clinicIds, array $updateParams) {
        if (!$this->rateLimiter->allow($userData['id'])) {
            return 'Rate limit exceeded.';
        }

        $accessToken = $this->oauthClient->authenticate($userData);
        $session = $_SESSION[$accessToken];

        try {
            $activeClinics = $this->apiClient->getActiveClinics();
            if (!array_intersect($clinicIds, array_column($activeClinics, 'id'))) {
                return 'Invalid clinic IDs.';
            }

            $ipAddress = $_SERVER['REMOTE_ADDR'];
            if (!$this->validateIp($ipAddress)) {
                return 'IP address not allowed.';
            }

            $geoLocation = $this->geolocationApi->getLocationByIp($ipAddress);
            if ($geoLocation['country'] !== $clinicIds[0]['country']) {
                return 'IP address geographic region does not match the clinic location.';
            }

            // Start transaction
            $this->db->beginTransaction();

            foreach ($clinicIds as $clinicId) {
                $uniqueIdentifier = uniqid();
                $statusVersion = $updateParams[$clinicId]['status_version']++;

                // Validate and update the clinic status, last modified IP and date, store unique identifier
                $this->db->updateClinic(
                    $clinicId,
                    [
                        'status' => $updateParams[$clinicId]['status'],
                        'status_version' => $statusVersion,
                        'last_modified_ip' => $ipAddress,
                        'last_modified_date' => new DateTime(),
                        'update_identifier' => $uniqueIdentifier
                    ]
                );

                // Log the authentication and update operations
                $this->db->logAuthentication($accessToken);
                $this->db->logUpdate($clinicId, $uniqueIdentifier);
            }

            // Commit transaction
            $this->db->commit();

            // Send notifications to clinic administrators
            foreach ($clinicIds as $clinicId) {
                $this->notificationService->sendNotification($clinicId, $uniqueIdentifier, $updateParams[$clinicId]['status']);
            }

            return 'Success';
        } catch (\Exception $e) {
            // Rollback transaction and log the error
            $this->db->rollBack();
            $this->db->logError($e->getMessage());

            return 'Error: ' . $e->getMessage();
        }
    }
}
