```javascript
/**
 * Copies specified bytes from buffered data chunks into a new buffer, handling large datasets and managing resources effectively.
 * @param {Buffer[]} inputChunks - Array of input data chunks in buffers
 * @param {number} startByte - Optional starting byte index for the copy operation (defaults to 0)
 * @param {number} endByte - Optional ending byte index for the copy operation (defaults to the length of the input data)
 * @returns {Promise<Buffer>} A new buffer containing the copied data or an error object if an error occurs during the process.
 */
async function copyDataChunks(inputChunks, startByte = 0, endByte = inputChunks[0].length) {
    // Validate input parameters
    if (!Array.isArray(inputChunks)) throw new TypeError('Input data must be an array of Buffer objects.');
    if (endByte < startByte || endByte > inputChunks.reduce((acc, val) => acc + val.length, 0)) throw new RangeError('Invalid byte range provided.');

    // Create an empty buffer to store the copied data
    const outputBuffer = Buffer.alloc(endByte - startByte);

    let totalCopied = 0;
    let offset = startByte;

    for (const chunk of inputChunks) {
        // Check if the end of the current chunk is reached or exceeded
        const remainingInChunk = chunk.length - offset;
        const amountToCopyFromThisChunk = Math.min(remainingInChunk, endByte - totalCopied);

        // Copy data from the input chunk to the output buffer
        chunk.copy(outputBuffer, totalCopied, offset, offset + amountToCopyFromThisChunk);
        totalCopied += amountToCopyFromThisChunk;

        // Reset offset for the next iteration
        offset = 0;

        // If the current chunk doesn't contain enough data to fulfill the request, skip it and move on to the next one.
        if (amountToCopyFromThisChunk < remainingInChunk) offset = amountToCopyFromThisChunk;
    }

    return outputBuffer;
}
```

Note that this function is designed as a building block for integration with an external data streaming API. It does not handle errors from the API itself but ensures efficient handling of buffered data chunks within its scope.

To integrate with an API, you can create a higher-order function that manages the asynchronous calls and error handling based on the specifics of your data streaming API.

