class Octree final {
public:
    explicit Octree(size_t featureSize, size_t initialLeafNodes, size_t maxDataCapacity, const std::string& authKey)
        : _featureSize(featureSize), _initialLeafNodes(initialLeafNodes), _maxDataCapacity(maxDataCapacity), _authKey(authKey),
          _rootNode(nullptr), _prefixLeafNodes(), _data(), _cache(), _syncMutex(), _cacheSize(0) {}

    void initializeSpatialCache() {
        // Allocate memory for root node and leaf nodes
        allocateMemory(_rootNode, new Node());
        for (size_t i = 0; i < _initialLeafNodes; ++i)
            allocateMemory(prefixLeafNodes[i], new Node());

        if (!_rootNode || !prefixLeafNodes.empty() && std::any_of(prefixLeafNodes.begin(), prefixLeafNodes.end(), [](const auto& node) { return !node; }))
            throw std::runtime_error("Failed to allocate memory for octree nodes.");

        // Initialize root node and leaf nodes
        _rootNode->initialize(_featureSize, this);
        for (auto& node : prefixLeafNodes)
            node->initialize(_featureSize, this);

        // Initialize caching mechanism and cache synchronization
        _cache.emplace(_authKey, std::make_unique<Cache>());
        _syncThread = std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(_syncMutex);
                _syncCondition.wait(lock, [this]() { return _cacheSize > 0 || !isUpToDate(); });

                if (_cacheSize > 0 && isUpToDate()) {
                    syncCache();
                    _cacheSize = 0;
