#include <stdio.h>
#include <stdarg.h>
#include <curl/curl.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    CURL *handle;
    size_t size;
} LogRequestData;

static size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    LogRequestData *data = (LogRequestData *)userp;
    data->size += size * nmemb;
    return size * nmemb;
}

static int LogCallback(CURL *curl, CURLMcode res, void *userp) {
    if (res != CURLE_OK && res != CURLE_OPERATION_TIMEDOUT) {
        // Handle error and implement retry mechanism here
        printf("Logging failed: %s\n", curl_easy_strerror(res));
        return 0;
    }
    return 1;
}

void log_to_server(const char *url, int level, const char *message, ...) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        printf("Failed to initialize cURL.\n");
        return;
    }

    LogRequestData data = { .handle = curl, .size = 0 };

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, ""); // Set up form data here for customizable headers and message

    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &data);
    curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, NULL);

    curl_easy_perform(curl); // Perform the HTTP POST request

    char *log_response = malloc(data.size + 1);
    if (!log_response) {
        printf("Failed to allocate memory for log response.\n");
        return;
    }
    log_response[data.size] = '\0';
    memcpy(log_response, data.handle->receivedstring, data.size);

    // Format the message based on the logging level and print it to stdout or a file here

    free(data.handle->receivedstring);
    curl_easy_cleanup(curl);
}
```

This code provides a basic structure for implementing the `log_to_server()` function using libcurl. The provided code initializes a cURL session, sets the URL, and configures the write callback to handle the response data. The log message formatting and error handling should be added according to your requirements.

