class ImageConverter {
public:
    ImageConverter(const std::string& logFilePath, int numThreads = 4)
        : logger_(logFilePath), numThreads_(numThreads) {}

    void convertImages(const std::vector<std::pair<std::string, std::string>>& imagePathsAndFormats) {
        for (auto [inputPath, outputPathAndFormat] : imagePathsAndFormats) {
            auto outputPathAndFormatPair = splitOutputPathAndFormat(outputPathAndFormat);
            convertImage(imagePathsAndFormats, inputPath, outputPathAndFormatPair.first, outputPathAndFormatPair.second);
        }
    }

private:
    void convertImage(const std::vector<std::pair<std::string, std::string>>& imagePathsAndFormats,
                      const std::string& inputPath, const std::string& outputPath, ImageFormat outputFormat) {
        auto startTime = std::chrono::high_resolution_clock::now();

        try {
            // Dynamic library loading (replace with the actual code for loading the conversion library)
            libimage_convertor::Library* lib = new libimage_convertor::Library();
            auto convertFunction = lib->getSymbol<decltype(&libimage_convertor::convertImage)>("convertImage");

            // Initialize the conversion parameters (quality level, etc.)
            ImageConverterParams params;
            // Set quality level if necessary

            // Perform the image conversion using the loaded library function
            convertFunction(inputPath.c_str(), outputPath.c_str(), outputFormat, &params);

            lib->release();

            auto endTime = std::chrono::high_resolution_clock::now();
            auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();
            logConversionDetails(inputPath, outputPath, duration);
        } catch (const std::exception& e) {
            logger_.error("Error converting image {}: {}", inputPath, e.what());
        }
    }

    void logConversionDetails(const std::string& inputPath, const std::string& outputPath, uint64_t durationMs) {
        // Configure the logging output (console, file, etc.)
        logger_.info("Converted image {} to {} in {} ms", inputPath, outputPath, durationMs);
    }

    struct OutputPathAndFormat {
        std::string path;
        ImageFormat format;
    };

    OutputPathAndFormat splitOutputPathAndFormat(const std::string& outputPathAndFormat) {
        auto separatorPos = outputPathAndFormat.find('.');
        return {outputPathAndFormat.substr(0, separatorPos), ImageFormatFromString(outputPathAndFormat.substr(separatorPos))};
    }

    std::string logFilePath_;
    int numThreads_;
    boost::log::sources::logger logger_{"ImageConverter"};
};

